/*
 * core.h - central definitions for the interpreter
 */
#ifndef CORE_H
#define CORE_H

#include <stddef.h>
#include <stdint.h>
#include <stdarg.h>
#include <setjmp.h>
#include <string.h>
#include <limits.h>
#include <ucontext.h>

#define VERSION_MAJOR "5"
#define VERSION_MINOR "5"
#define VERSION_RELEASE "1"
#define VERSION_STRING "Lua 5.5"
#define COPYRIGHT_LINE "Lua 5.5.1  Copyright (C) 1994-2026 Lua.org, PUC-Rio"

typedef int64_t Integer;
typedef uint64_t UInteger;
typedef double Number;
typedef uint32_t Instruction;

#define MAXSTACK_SLOTS 1000000
#define MAX_CCALLS 200
#define EXTRA_SLOTS 5
#define BASIC_STACK 40
#define MAXSHORTLEN 40
#define IDSIZE 60
#define MULTRET (-1)
#define REGISTRYINDEX (-1000000 - 1000)

/* status codes */
enum { ST_OK = 0, ST_YIELD, ST_ERRRUN, ST_ERRSYNTAX, ST_ERRMEM, ST_ERRERR };

/* basic types */
enum {
  T_NONE = -1, T_NIL = 0, T_BOOLEAN, T_LIGHTUD, T_NUMBER, T_STRING, T_TABLE,
  T_FUNCTION, T_USERDATA, T_THREAD, T_NUMTYPES,
  T_UPVAL = T_NUMTYPES, T_PROTO, T_DEADKEY
};

#define makevariant(t, v) ((t) | ((v) << 4))
#define V_NIL       makevariant(T_NIL, 0)
#define V_EMPTY     makevariant(T_NIL, 1)   /* empty table slot */
#define V_ABSTKEY   makevariant(T_NIL, 2)   /* absent key marker */
#define V_FALSE     makevariant(T_BOOLEAN, 0)
#define V_TRUE      makevariant(T_BOOLEAN, 1)
#define V_INT       makevariant(T_NUMBER, 0)
#define V_FLT       makevariant(T_NUMBER, 1)
#define V_SHRSTR    makevariant(T_STRING, 0)
#define V_LNGSTR    makevariant(T_STRING, 1)
#define V_LCL       makevariant(T_FUNCTION, 0)  /* Lua closure */
#define V_LCF       makevariant(T_FUNCTION, 1)  /* light C function */
#define V_CCL       makevariant(T_FUNCTION, 2)  /* C closure */
#define V_TABLE     makevariant(T_TABLE, 0)
#define V_USERDATA  makevariant(T_USERDATA, 0)
#define V_THREAD    makevariant(T_THREAD, 0)
#define V_LIGHTUD   makevariant(T_LIGHTUD, 0)
#define V_UPVAL     makevariant(T_UPVAL, 0)
#define V_PROTO     makevariant(T_PROTO, 0)
#define V_DEADKEY   makevariant(T_DEADKEY, 0)

#define BIT_COLLECTABLE (1 << 6)
#define ctb(t) ((t) | BIT_COLLECTABLE)

struct State;
typedef struct State State;
typedef int (*CFunction)(State *L);

typedef struct GCHeader {
  struct GCHeader *next;
  uint8_t tt;
  uint8_t marked;
} GCHeader;

typedef union ValueU {
  GCHeader *gc;
  void *p;
  CFunction f;
  Integer i;
  Number n;
} ValueU;

typedef struct Value {
  ValueU v;
  uint8_t tt;
} Value;

typedef Value *StkId;

/* ---- value access macros ---- */
#define rawtt(o)      ((o)->tt)
#define novariant(t)  ((t) & 0x0F)
#define ttype(o)      novariant(rawtt(o))
#define ttypetag(o)   (rawtt(o) & 0x3F)
#define checktag(o,t) (rawtt(o) == (t))
#define checktype(o,t) (ttype(o) == (t))

#define ttisnil(o)      checktype(o, T_NIL)
#define ttisstrictnil(o) checktag(o, V_NIL)
#define ttisboolean(o)  checktype(o, T_BOOLEAN)
#define ttisfalse(o)    checktag(o, V_FALSE)
#define ttistrue(o)     checktag(o, V_TRUE)
#define ttisnumber(o)   checktype(o, T_NUMBER)
#define ttisinteger(o)  checktag(o, V_INT)
#define ttisfloat(o)    checktag(o, V_FLT)
#define ttisstring(o)   checktype(o, T_STRING)
#define ttisshrstring(o) checktag(o, ctb(V_SHRSTR))
#define ttislngstring(o) checktag(o, ctb(V_LNGSTR))
#define ttistable(o)    checktag(o, ctb(V_TABLE))
#define ttisfunction(o) checktype(o, T_FUNCTION)
#define ttisLclosure(o) checktag(o, ctb(V_LCL))
#define ttislcf(o)      checktag(o, V_LCF)
#define ttisCclosure(o) checktag(o, ctb(V_CCL))
#define ttisclosure(o)  (ttisLclosure(o) || ttisCclosure(o))
#define ttisfulluserdata(o) checktag(o, ctb(V_USERDATA))
#define ttislightuserdata(o) checktag(o, V_LIGHTUD)
#define ttisthread(o)   checktag(o, ctb(V_THREAD))
#define ttisdeadkey(o)  checktag(o, V_DEADKEY)
#define iscollectable(o) (rawtt(o) & BIT_COLLECTABLE)
#define isempty(o)      ttisnil(o)
#define l_isfalse(o)    (ttisfalse(o) || ttisnil(o))

#define ivalue(o)   ((o)->v.i)
#define fltvalue(o) ((o)->v.n)
#define nvalue(o)   (ttisinteger(o) ? (Number)ivalue(o) : fltvalue(o))
#define gcvalue(o)  ((o)->v.gc)
#define pvalue(o)   ((o)->v.p)
#define fvalue(o)   ((o)->v.f)
#define tsvalue(o)  ((TString *)gcvalue(o))
#define hvalue(o)   ((Table *)gcvalue(o))
#define clLvalue(o) ((LClosure *)gcvalue(o))
#define clCvalue(o) ((CClosure *)gcvalue(o))
#define uvalue(o)   ((Udata *)gcvalue(o))
#define thvalue(o)  ((State *)gcvalue(o))
#define bvalue(o)   (ttistrue(o))

#define settt(o,t)  ((o)->tt = (t))
#define setnilvalue(o) settt(o, V_NIL)
#define setempty(o) settt(o, V_EMPTY)
#define setfltvalue(o,x) { Value *io_ = (o); io_->v.n = (x); settt(io_, V_FLT); }
#define setivalue(o,x)   { Value *io_ = (o); io_->v.i = (x); settt(io_, V_INT); }
#define setbfvalue(o)    settt(o, V_FALSE)
#define setbtvalue(o)    settt(o, V_TRUE)
#define setbvalue(o,b)   settt(o, (b) ? V_TRUE : V_FALSE)
#define setpvalue(o,x)   { Value *io_ = (o); io_->v.p = (x); settt(io_, V_LIGHTUD); }
#define setfvalue(o,x)   { Value *io_ = (o); io_->v.f = (x); settt(io_, V_LCF); }
#define setgcovalue(o,x) { Value *io_ = (o); GCHeader *g_ = (GCHeader *)(x); io_->v.gc = g_; settt(io_, ctb(g_->tt)); }
#define setsvalue(o,x)   setgcovalue(o, x)
#define sethvalue(o,x)   setgcovalue(o, x)
#define setclLvalue(o,x) setgcovalue(o, x)
#define setclCvalue(o,x) setgcovalue(o, x)
#define setuvalue(o,x)   setgcovalue(o, x)
#define setthvalue(o,x)  setgcovalue(o, x)
#define setobj(o1,o2)    { const Value *s_ = (o2); Value *d_ = (o1); d_->v = s_->v; d_->tt = s_->tt; }

/* ---- strings ---- */
typedef struct TString {
  GCHeader hdr;
  uint8_t extra;      /* reserved word index for short strings; has-hash flag for long */
