/* ---- upvalues & closures ---- */
typedef struct UpVal {
  GCHeader hdr;
  uint8_t tbc;
  Value *v;              /* points to stack or to own value */
  union {
    struct { struct UpVal *next; struct UpVal **previous; } open;
    Value value;
  } u;
} UpVal;

typedef struct CClosure {
  GCHeader hdr;
  uint8_t nupvalues;
  CFunction f;
  Value upvalue[1];
} CClosure;

typedef struct LClosure {
  GCHeader hdr;
  uint8_t nupvalues;
  Proto *p;
  UpVal *upvals[1];
} LClosure;

#define upisopen(up) ((up)->v != &(up)->u.value)

/* ---- tables ---- */
typedef struct Node {
  Value val;        /* value */
  uint8_t keytt;    /* key type tag */
  int next;         /* offset to next node in chain */
  ValueU keyval;    /* key value */
} Node;

typedef struct Table {
  GCHeader hdr;
  uint8_t flags;       /* 1<<p means tagmethod(p) is not present */
  uint8_t lsizenode;   /* log2 of size of node array */
  unsigned int asize;  /* size of array part */
  unsigned int lenhint;/* hint for length operator */
  Value *array;
  Node *node;
  Node *lastfree;
  struct Table *metatable;
} Table;

#define sizenode(t) (1 << (t)->lsizenode)
#define gnode(t,i)  (&(t)->node[i])
#define gval(n)     (&(n)->val)
#define gnext(n)    ((n)->next)
#define keytt(n)    ((n)->keytt)
#define keyval(n)   ((n)->keyval)
#define keyisnil(n) (keytt(n) == V_NIL)
#define keyisinteger(n) (keytt(n) == V_INT)
#define keyival(n)  (keyval(n).i)
#define keyisshrstr(n) (keytt(n) == ctb(V_SHRSTR))
#define keystrval(n) ((TString *)keyval(n).gc)
#define keyiscollectable(n) (keytt(n) & BIT_COLLECTABLE)
#define gckey(n)    (keyval(n).gc)
#define keyisdead(n) (keytt(n) == V_DEADKEY)
#define setdeadkey(n) (keytt(n) = V_DEADKEY)
#define getnodekey(L,obj,node) { Value *io_=(obj); const Node *n_=(node); io_->v = n_->keyval; io_->tt = n_->keytt; }
#define setnodekey(L,node,obj) { Node *n_=(node); const Value *io_=(obj); n_->keyval = io_->v; n_->keytt = io_->tt; }

/* ---- metamethod events ---- */
typedef enum {
  TM_INDEX, TM_NEWINDEX, TM_GC, TM_MODE, TM_LEN, TM_EQ,
  TM_ADD, TM_SUB, TM_MUL, TM_MOD, TM_POW, TM_DIV, TM_IDIV,
  TM_BAND, TM_BOR, TM_BXOR, TM_SHL, TM_SHR, TM_UNM, TM_BNOT,
  TM_LT, TM_LE, TM_CONCAT, TM_CALL, TM_CLOSE, TM_N
} TMS;

#define maskflags (~(~0u << (TM_EQ + 1)))
#define invalidateTMcache(t) ((t)->flags &= ~maskflags)

/* ---- call info ---- */
typedef struct CallInfo {
  StkId func;
  StkId top;
  struct CallInfo *previous, *next;
  union {
    struct {
      const Instruction *savedpc;
      int nextraargs;
    } l;
    struct {
      int dummy;
    } c;
  } u;
  short nresults;
  unsigned short callstatus;
} CallInfo;

#define CIST_C       (1 << 0)   /* call is running a C function */
#define CIST_FRESH   (1 << 1)   /* call is on a fresh "execute" frame */
#define CIST_TAIL    (1 << 2)   /* call was tail called */
#define CIST_FIN     (1 << 3)   /* function is running a finalizer */
#define CIST_HOOKED  (1 << 4)
#define CIST_CLSRET  (1 << 5)   /* function is closing tbc variables */
#define CIST_YPCALL  (1 << 6)

#define isLua(ci)  (!((ci)->callstatus & CIST_C))

/* ---- global state ---- */
typedef struct StringTable {
  TString **hash;
  int nuse;
  int size;
} StringTable;

typedef struct GlobalState {
  size_t totalbytes;      /* bytes currently allocated */
  size_t gcthreshold;
  size_t gcestimate;
  int gcpause;            /* percentage */
  int gcstepmul;
  int gcrunning;
  int gcstopped;          /* stopped by user */
  int gckind;             /* 0 incremental, 1 generational (cosmetic) */
  int gcemergency;
  StringTable strt;
  Value l_registry;
  Value nilvalue;
  unsigned int seed;
  GCHeader *allgc;        /* list of all collectable objects */
  GCHeader *finobj;       /* objects with finalizers */
  GCHeader *tobefnz;      /* objects to be finalized */
  GCHeader *fixedgc;      /* objects not to be collected */
  struct State *mainthread;
  struct State *running;   /* currently running coroutine */
  TString *memerrmsg;
  TString *tmname[TM_N];
  struct Table *mt[T_NUMTYPES];
  TString *strcache[53][2];
  void (*warnf)(void *ud, const char *msg, int tocont);
  void *ud_warn;
  int warnstate;          /* 0 off, 1 on, 2 continuing */
  int gccount;            /* number of collections done */
  int inGC;
} GlobalState;

/* ---- thread state ---- */
typedef struct LongJmp {
  struct LongJmp *previous;
  jmp_buf b;
  volatile int status;
} LongJmp;

struct State {
  GCHeader hdr;
  uint8_t status;
  uint8_t allowhook;
  unsigned short nci;
  StkId top;
  GlobalState *g;
  CallInfo *ci;
  StkId stack_last;      /* end of usable stack */
  StkId stack;
  UpVal *openupval;
  StkId tbclist;
  GCHeader *gclist;
  struct State *twups;
  LongJmp *errorJmp;
  CallInfo base_ci;
  volatile CFunction hook;
  ptrdiff_t errfunc;
  uint32_t nCcalls;
  int oldpc;
  int basehookcount;
  int hookcount;
  int hookmask;
  /* coroutine support */
  ucontext_t ctx;
  void *cstack;
  size_t cstacksize;
  struct State *resumer;
  int costarted;         /* has the coroutine body started? */
  int cofinished;        /* body finished (dead) */
  int transfer;          /* number of values transferred by yield/resume */
  int coerrstatus;       /* error status when body ended with error */
  CFunction hookf;       /* debug hook function placeholder */
};

#define G(L) ((L)->g)
#define stacksize(th) ((int)((th)->stack_last - (th)->stack))
#define savestack(L,p) ((char *)(p) - (char *)(L)->stack)
#define restorestack(L,n) ((StkId)((char *)(L)->stack + (n)))

