/* ======================= memory ======================= */

static void *tryagain(State *L, void *block, size_t osize, size_t nsize) {
  if (L != NULL && G(L)->mainthread != NULL && !G(L)->inGC) {
    gc_fullcollect(L, 1);
    return realloc(block, nsize);
  }
  return NULL;
}

void *mem_realloc(State *L, void *block, size_t osize, size_t nsize) {
  void *newblock;
  GlobalState *g = L ? G(L) : NULL;
  if (nsize == 0) {
    free(block);
    if (g) g->totalbytes -= osize;
    return NULL;
  }
  newblock = realloc(block, nsize);
  if (newblock == NULL) {
    newblock = tryagain(L, block, osize, nsize);
    if (newblock == NULL) {
      if (L) do_throw(L, ST_ERRMEM);
      return NULL;
    }
  }
  if (g) g->totalbytes = g->totalbytes - osize + nsize;
  return newblock;
}

void *mem_alloc(State *L, size_t size) {
  return mem_realloc(L, NULL, 0, size);
}

void mem_free(State *L, void *block, size_t osize) {
  if (block == NULL) return;
  mem_realloc(L, block, osize, 0);
}

void *mem_growvector(State *L, void *block, int nelems, int *size, int elemsize, int limit, const char *what) {
  int newsize;
  if (nelems + 1 <= *size) return block;
  if (*size >= limit / 2) {
    if (*size >= limit)
      err_runerror(L, "too many %s (limit is %d)", what, limit);
    newsize = limit;
  } else {
    newsize = (*size) * 2;
    if (newsize < 4) newsize = 4;
  }
  block = mem_realloc(L, block, (size_t)(*size) * elemsize, (size_t)newsize * elemsize);
  *size = newsize;
  return block;
}

void *mem_shrinkvector(State *L, void *block, int *size, int final, int elemsize) {
  block = mem_realloc(L, block, (size_t)(*size) * elemsize, (size_t)final * elemsize);
  *size = final;
  return block;
}

/* ======================= strings ======================= */

unsigned int str_hash(const char *s, size_t l, unsigned int seed) {
  unsigned int h = seed ^ (unsigned int)l;
  for (; l > 0; l--)
    h ^= ((h << 5) + (h >> 2) + (unsigned char)(s[l - 1]));
  return h;
}

unsigned int str_hashlong(TString *ts) {
  if (ts->extra == 0) {
    size_t len = ts->u.lnglen;
    ts->hash = str_hash(getstr(ts), len, ts->hash);
    ts->extra = 1;
  }
  return ts->hash;
}

int str_eqlng(TString *a, TString *b) {
  size_t len = a->u.lnglen;
  return (a == b) || ((len == b->u.lnglen) && (memcmp(getstr(a), getstr(b), len) == 0));
}

void str_resize(State *L, int newsize) {
  StringTable *tb = &G(L)->strt;
  int i;
  TString **newhash = mem_newvector(L, newsize, TString *);
  for (i = 0; i < newsize; i++) newhash[i] = NULL;
  for (i = 0; i < tb->size; i++) {
    TString *p = tb->hash[i];
    while (p) {
      TString *hnext = p->u.hnext;
      unsigned int h = p->hash & (newsize - 1);
      p->u.hnext = newhash[h];
      newhash[h] = p;
      p = hnext;
    }
  }
  mem_freearray(L, tb->hash, tb->size);
  tb->hash = newhash;
  tb->size = newsize;
}

void str_clearcache(GlobalState *g) {
  int i, j;
  for (i = 0; i < 53; i++)
    for (j = 0; j < 2; j++) {
      if (g->strcache[i][j] && (g->strcache[i][j]->hdr.marked & 3) == 0 && 0)
        g->strcache[i][j] = g->memerrmsg;
    }
}

void str_init(State *L) {
  GlobalState *g = G(L);
  int i, j;
  g->strt.hash = NULL;
  g->strt.size = 0;
  g->strt.nuse = 0;
  str_resize(L, 128);
  g->memerrmsg = str_new(L, "not enough memory");
  gc_fix(L, (GCHeader *)g->memerrmsg);
  for (i = 0; i < 53; i++)
    for (j = 0; j < 2; j++)
      g->strcache[i][j] = g->memerrmsg;
}

static TString *createstrobj(State *L, size_t l, int tag, unsigned int h) {
  size_t totalsize = offsetof(TString, data) + l + 1;
  TString *ts = (TString *)gc_newobj(L, tag, totalsize);
  ts->hash = h;
  ts->extra = 0;
  ts->contents = ts->data;
  ts->contents[l] = '\0';
  return ts;
}

TString *str_createlng(State *L, size_t l) {
  TString *ts = createstrobj(L, l, V_LNGSTR, G(L)->seed);
  ts->u.lnglen = l;
  ts->shrlen = 0xFF;
  return ts;
}

void str_remove(State *L, TString *ts) {
  StringTable *tb = &G(L)->strt;
  TString **p = &tb->hash[ts->hash & (tb->size - 1)];
  while (*p != ts) p = &(*p)->u.hnext;
  *p = (*p)->u.hnext;
  tb->nuse--;
}

static TString *internshrstr(State *L, const char *str, size_t l) {
  TString *ts;
  GlobalState *g = G(L);
  StringTable *tb = &g->strt;
  unsigned int h = str_hash(str, l, g->seed);
  TString **list = &tb->hash[h & (tb->size - 1)];
  for (ts = *list; ts != NULL; ts = ts->u.hnext) {
    if (l == ts->shrlen && (memcmp(str, getstr(ts), l) == 0)) {
      /* found; may be dead during a sweep */
      if (ts->hdr.marked & 4) ts->hdr.marked &= ~4; /* resurrect if marked dead */
      return ts;
    }
  }
  if (tb->nuse >= tb->size) {
    str_resize(L, tb->size * 2);
    list = &tb->hash[h & (tb->size - 1)];
  }
  ts = createstrobj(L, l, V_SHRSTR, h);
  ts->shrlen = (uint8_t)l;
  memcpy(ts->contents, str, l);
  ts->u.hnext = *list;
  *list = ts;
  tb->nuse++;
  return ts;
}

TString *str_newlstr(State *L, const char *str, size_t l) {
  if (l <= MAXSHORTLEN)
    return internshrstr(L, str, l);
  else {
    TString *ts;
    if (l >= (MAX_SIZE - sizeof(TString)) / sizeof(char))
      err_runerror(L, "string length overflow");
    ts = str_createlng(L, l);
    memcpy(ts->contents, str, l);
    return ts;
  }
}

TString *str_new(State *L, const char *str) {
  unsigned int i = point2uint(str) % 53;
  int j;
  TString **p = G(L)->strcache[i];
  for (j = 0; j < 2; j++) {
    if (strcmp(str, getstr(p[j])) == 0)
      return p[j];
  }
  for (j = 2 - 1; j > 0; j--)
    p[j] = p[j - 1];
  p[0] = str_newlstr(L, str, strlen(str));
  return p[0];
}

