static int isneg(const char **s) {
  if (**s == '-') { (*s)++; return 1; }
  else if (**s == '+') (*s)++;
  return 0;
}

static const char *l_str2dloc(const char *s, Number *result, int mode) {
  char *endptr;
  *result = (mode == 'x') ? strtod(s, &endptr) : strtod(s, &endptr);
  if (endptr == s) return NULL;
  while (isspace((unsigned char)*endptr)) endptr++;
  return (*endptr == '\0') ? endptr : NULL;
}

static const char *l_str2d(const char *s, Number *result) {
  const char *endptr;
  const char *pmode = strpbrk(s, ".xXnN");
  int mode = pmode ? ((unsigned char)*pmode | 0x20) : 0;
  if (mode == 'n') return NULL;  /* reject 'inf' and 'nan' */
  endptr = l_str2dloc(s, result, mode);
  if (endptr == NULL) {
    /* maybe a locale issue with the decimal point: try replacing '.' */
    char buff[201];
    const char *pdot = strchr(s, '.');
    if (pdot == NULL || strlen(s) > 200) return NULL;
    strcpy(buff, s);
    buff[pdot - s] = localeconv()->decimal_point[0];
    endptr = l_str2dloc(buff, result, mode);
    if (endptr != NULL) endptr = s + (endptr - buff);
  }
  return endptr;
}

#define MAXBY10 ((UInteger)(INT64_MAX / 10))
#define MAXLASTD ((int)(INT64_MAX % 10))

static const char *l_str2int(const char *s, Integer *result) {
  UInteger a = 0;
  int empty = 1;
  int neg;
  while (isspace((unsigned char)*s)) s++;
  neg = isneg(&s);
  if (s[0] == '0' && (s[1] == 'x' || s[1] == 'X')) {
    s += 2;
    for (; isxdigit((unsigned char)*s); s++) {
      a = a * 16 + obj_hexavalue(*s);
      empty = 0;
    }
  } else {
    for (; isdigit((unsigned char)*s); s++) {
      int d = *s - '0';
      if (a >= MAXBY10 && (a > MAXBY10 || d > MAXLASTD + neg))
        return NULL;  /* overflow: do not accept as integer */
      a = a * 10 + d;
      empty = 0;
    }
  }
  while (isspace((unsigned char)*s)) s++;
  if (empty || *s != '\0') return NULL;
  else {
    *result = l_castU2S((neg) ? 0u - a : a);
    return s;
  }
}

int obj_str2num(const char *s, Value *o) {
