    buff[len] = '\0';
  }
  return len;
}

int obj_tostringbuff(const Value *obj, char *buff) {
  if (ttisinteger(obj))
    return snprintf(buff, MAXNUMBER2STR, "%lld", (long long)ivalue(obj));
  else
    return tostringbuff_flt(fltvalue(obj), buff);
}

void obj_tostring(State *L, Value *obj) {
  char buff[MAXNUMBER2STR];
  int len = obj_tostringbuff(obj, buff);
  setsvalue(obj, str_newlstr(L, buff, len));
}

/* ---- formatted string building (pushfstring) ---- */
typedef struct BuffFS {
  State *L;
  int pushed;
  size_t blen;
  char space[200];
} BuffFS;

static void pushstr(BuffFS *buff, const char *str, size_t lstr) {
  State *L = buff->L;
  setsvalue(L->top, str_newlstr(L, str, lstr));
  L->top++;
  if (!buff->pushed)
    buff->pushed = 1;
  else
    vm_concat(L, 2);
}

static void clearbuff(BuffFS *buff) {
  pushstr(buff, buff->space, buff->blen);
  buff->blen = 0;
}

static char *getbuff(BuffFS *buff, size_t sz) {
  if (sz > sizeof(buff->space) - buff->blen)
    clearbuff(buff);
  return buff->space + buff->blen;
}

static void addstr2buff(BuffFS *buff, const char *str, size_t slen) {
  if (slen <= sizeof(buff->space)) {
    char *bf = getbuff(buff, slen);
    memcpy(bf, str, slen);
    buff->blen += slen;
  } else {
    clearbuff(buff);
    pushstr(buff, str, slen);
  }
}

static void addnum2buff(BuffFS *buff, Value *num) {
  char *numbuff = getbuff(buff, MAXNUMBER2STR);
  int len = obj_tostringbuff(num, numbuff);
  buff->blen += len;
}

const char *obj_pushvfstring(State *L, const char *fmt, va_list argp) {
  BuffFS buff;
  const char *e;
  buff.pushed = 0; buff.blen = 0; buff.L = L;
  while ((e = strchr(fmt, '%')) != NULL) {
    addstr2buff(&buff, fmt, e - fmt);
    switch (*(e + 1)) {
      case 's': {
        const char *s = va_arg(argp, char *);
        if (s == NULL) s = "(null)";
        addstr2buff(&buff, s, strlen(s));
        break;
      }
      case 'c': {
        char c = (char)va_arg(argp, int);
        addstr2buff(&buff, &c, 1);
        break;
      }
      case 'd': {
        Value num;
        setivalue(&num, va_arg(argp, int));
        addnum2buff(&buff, &num);
        break;
      }
      case 'I': {
        Value num;
        setivalue(&num, (Integer)va_arg(argp, long long));
        addnum2buff(&buff, &num);
        break;
      }
      case 'f': {
        Value num;
        setfltvalue(&num, va_arg(argp, double));
        addnum2buff(&buff, &num);
        break;
      }
      case 'p': {
        const int sz = 3 * sizeof(void *) + 8;
        char *bf = getbuff(&buff, sz);
        void *p = va_arg(argp, void *);
        int len = snprintf(bf, sz, "%p", p);
        buff.blen += len;
        break;
      }
      case 'U': {
        char bf[8];
        int len = obj_utf8esc(bf, va_arg(argp, long));
        addstr2buff(&buff, bf + 8 - len, len);
        break;
      }
      case '%': {
        addstr2buff(&buff, "%", 1);
        break;
      }
      default: {
        err_runerror(L, "invalid option '%%%c' to 'pushfstring'", *(e + 1));
      }
    }
    fmt = e + 2;
  }
  addstr2buff(&buff, fmt, strlen(fmt));
  clearbuff(&buff);
  return svalue(L->top - 1);
}

const char *obj_pushfstring(State *L, const char *fmt, ...) {
  const char *msg;
  va_list argp;
  va_start(argp, fmt);
  msg = obj_pushvfstring(L, fmt, argp);
  va_end(argp);
  return msg;
}

#define RETS "..."
#define PRE "[string \""
#define POS "\"]"
#define addstr(a,b,l) ( memcpy(a,b,(l) * sizeof(char)), a += (l) )

void obj_chunkid(char *out, const char *source, size_t srclen) {
  size_t bufflen = IDSIZE;
  if (*source == '=') {
    if (srclen <= bufflen)
      memcpy(out, source + 1, srclen * sizeof(char));
    else {
      addstr(out, source + 1, bufflen - 1);
      *out = '\0';
    }
  } else if (*source == '@') {
    if (srclen <= bufflen)
      memcpy(out, source + 1, srclen * sizeof(char));
    else {
      addstr(out, RETS, strlen(RETS));
      bufflen -= strlen(RETS);
      memcpy(out, source + 1 + srclen - bufflen, bufflen * sizeof(char));
    }
  } else {
    const char *nl = strchr(source, '\n');
    addstr(out, PRE, strlen(PRE));
    bufflen -= strlen(PRE RETS POS) + 1;
    if (srclen < bufflen && nl == NULL) {
      addstr(out, source, srclen);
    } else {
      if (nl != NULL) srclen = nl - source;
      if (srclen > bufflen) srclen = bufflen;
      addstr(out, source, srclen);
      addstr(out, RETS, strlen(RETS));
    }
    memcpy(out, POS, (strlen(POS) + 1) * sizeof(char));
  }
}

/* ---- raw arithmetic ---- */

Integer obj_arith_int(State *L, int op, Integer v1, Integer v2) {
  switch (op) {
    case OPR_ADD: return aux_intop_add(v1, v2);
    default: return 0;
  }
}

#define intop(op,v1,v2) l_castU2S(l_castS2U(v1) op l_castS2U(v2))

static Integer intarith(State *L, int op, Integer v1, Integer v2) {
  switch (op) {
    case OPR_ADD: return intop(+, v1, v2);
    case OPR_SUB: return intop(-, v1, v2);
    case OPR_MUL: return intop(*, v1, v2);
    case OPR_MOD: return vm_mod(L, v1, v2);
    case OPR_IDIV: return vm_idiv(L, v1, v2);
    case OPR_BAND: return intop(&, v1, v2);
    case OPR_BOR: return intop(|, v1, v2);
    case OPR_BXOR: return intop(^, v1, v2);
    case OPR_SHL: return vm_shiftl(v1, v2);
    case OPR_SHR: return vm_shiftl(v1, intop(-, 0, v2));
    case OPR_UNM: return intop(-, 0, v1);
    case OPR_BNOT: return intop(^, ~l_castS2U(0), v1);
    default: return 0;
  }
}

static Number numarith(State *L, int op, Number v1, Number v2) {
  switch (op) {
    case OPR_ADD: return v1 + v2;
    case OPR_SUB: return v1 - v2;
    case OPR_MUL: return v1 * v2;
    case OPR_DIV: return v1 / v2;
    case OPR_POW: return (v2 == 2) ? v1 * v1 : pow(v1, v2);
    case OPR_IDIV: return floor(v1 / v2);
    case OPR_UNM: return -v1;
    case OPR_MOD: return vm_modf(L, v1, v2);
    default: return 0;
  }
}

int obj_rawarith(State *L, int op, const Value *p1, const Value *p2, Value *res) {
  switch (op) {
    case OPR_BAND: case OPR_BOR: case OPR_BXOR:
    case OPR_SHL: case OPR_SHR: case OPR_BNOT: {
      Integer i1; Integer i2;
      if (tointegerns(p1, &i1) && tointegerns(p2, &i2)) {
        setivalue(res, intarith(L, op, i1, i2));
        return 1;
      }
      return 0;
    }
    case OPR_DIV: case OPR_POW: {
      Number n1; Number n2;
      if (tonumber(p1, &n1) && tonumber(p2, &n2)) {
        setfltvalue(res, numarith(L, op, n1, n2));
        return 1;
      }
      return 0;
    }
    default: {
      Number n1; Number n2;
      if (ttisinteger(p1) && ttisinteger(p2)) {
        setivalue(res, intarith(L, op, ivalue(p1), ivalue(p2)));
        return 1;
      } else if (tonumber(p1, &n1) && tonumber(p2, &n2)) {
        setfltvalue(res, numarith(L, op, n1, n2));
        return 1;
      }
      return 0;
    }
  }
}

void obj_arith(State *L, int op, const Value *p1, const Value *p2, StkId res) {
  if (!obj_rawarith(L, op, p1, p2, res)) {
    tm_trybin(L, p1, p2, res, (TMS)(op + TM_ADD));
  }
}
