CClosure *cclosure_new(State *L, int nupvals) {
  size_t sz = offsetof(CClosure, upvalue) + sizeof(Value) * (size_t)nupvals;
  CClosure *c = (CClosure *)gc_newobj(L, V_CCL, sz);
  c->nupvalues = (uint8_t)nupvals;
