LClosure *lclosure_new(State *L, int nupvals) {
  size_t sz = offsetof(LClosure, upvals) + sizeof(UpVal *) * (size_t)nupvals;
  LClosure *c = (LClosure *)gc_newobj(L, V_LCL, sz);
  int i;
  c->p = NULL;
  c->nupvalues = (uint8_t)nupvals;
  for (i = 0; i < nupvals; i++) c->upvals[i] = NULL;
  return c;
}

void lclosure_initupvals(State *L, LClosure *cl) {
  int i;
  for (i = 0; i < cl->nupvalues; i++) {
    UpVal *uv = (UpVal *)gc_newobj(L, V_UPVAL, sizeof(UpVal));
    uv->tbc = 0;
    uv->v = &uv->u.value;
    setnilvalue(uv->v);
    cl->upvals[i] = uv;
  }
}

static UpVal *newupval(State *L, StkId level, UpVal **prev) {
  UpVal *uv = (UpVal *)gc_newobj(L, V_UPVAL, sizeof(UpVal));
  UpVal *next = *prev;
  uv->tbc = 0;
  uv->v = level;
  uv->u.open.next = next;
  uv->u.open.previous = prev;
  if (next) next->u.open.previous = &uv->u.open.next;
  *prev = uv;
  return uv;
}

UpVal *upval_find(State *L, StkId level) {
  UpVal **pp = &L->openupval;
  UpVal *p;
  while ((p = *pp) != NULL && p->v >= level) {
    if (p->v == level) return p;
    pp = &p->u.open.next;
  }
  return newupval(L, level, pp);
}

void upval_unlinkupval(UpVal *uv) {
  *uv->u.open.previous = uv->u.open.next;
  if (uv->u.open.next)
    uv->u.open.next->u.open.previous = uv->u.open.previous;
}

void upval_free(State *L, UpVal *uv) {
  if (upisopen(uv)) upval_unlinkupval(uv);
  mem_free(L, uv, sizeof(UpVal));
}

/* close all open upvalues at or above level (no tbc handling here) */
void upval_close(State *L, StkId level) {
  UpVal *uv;
  while ((uv = L->openupval) != NULL && uv->v >= level) {
    upval_unlinkupval(uv);
    setobj(&uv->u.value, uv->v);
    uv->v = &uv->u.value;
  }
}

