/* ---- formatted string building (pushfstring) ---- */
typedef struct BuffFS {
  State *L;
  int pushed;
  size_t blen;
  char space[200];
} BuffFS;

static void pushstr(BuffFS *buff, const char *str, size_t lstr) {
  State *L = buff->L;
  setsvalue(L->top, str_newlstr(L, str, lstr));
  L->top++;
  if (!buff->pushed)
    buff->pushed = 1;
  else
    vm_concat(L, 2);
}

static void clearbuff(BuffFS *buff) {
  pushstr(buff, buff->space, buff->blen);
  buff->blen = 0;
}

static char *getbuff(BuffFS *buff, size_t sz) {
  if (sz > sizeof(buff->space) - buff->blen)
    clearbuff(buff);
  return buff->space + buff->blen;
}

static void addstr2buff(BuffFS *buff, const char *str, size_t slen) {
  if (slen <= sizeof(buff->space)) {
    char *bf = getbuff(buff, slen);
    memcpy(bf, str, slen);
    buff->blen += slen;
  } else {
    clearbuff(buff);
    pushstr(buff, str, slen);
  }
}

static void addnum2buff(BuffFS *buff, Value *num) {
  char *numbuff = getbuff(buff, MAXNUMBER2STR);
  int len = obj_tostringbuff(num, numbuff);
  buff->blen += len;
}

const char *obj_pushvfstring(State *L, const char *fmt, va_list argp) {
  BuffFS buff;
  const char *e;
  buff.pushed = 0; buff.blen = 0; buff.L = L;
  while ((e = strchr(fmt, '%')) != NULL) {
    addstr2buff(&buff, fmt, e - fmt);
    switch (*(e + 1)) {
      case 's': {
        const char *s = va_arg(argp, char *);
        if (s == NULL) s = "(null)";
        addstr2buff(&buff, s, strlen(s));
        break;
      }
      case 'c': {
        char c = (char)va_arg(argp, int);
        addstr2buff(&buff, &c, 1);
        break;
      }
      case 'd': {
        Value num;
        setivalue(&num, va_arg(argp, int));
        addnum2buff(&buff, &num);
        break;
      }
      case 'I': {
        Value num;
        setivalue(&num, (Integer)va_arg(argp, long long));
        addnum2buff(&buff, &num);
        break;
      }
      case 'f': {
        Value num;
        setfltvalue(&num, va_arg(argp, double));
        addnum2buff(&buff, &num);
        break;
      }
      case 'p': {
        const int sz = 3 * sizeof(void *) + 8;
        char *bf = getbuff(&buff, sz);
        void *p = va_arg(argp, void *);
        int len = snprintf(bf, sz, "%p", p);
        buff.blen += len;
        break;
      }
      case 'U': {
        char bf[8];
        int len = obj_utf8esc(bf, va_arg(argp, long));
        addstr2buff(&buff, bf + 8 - len, len);
        break;
      }
      case '%': {
        addstr2buff(&buff, "%", 1);
        break;
      }
      default: {
        err_runerror(L, "invalid option '%%%c' to 'pushfstring'", *(e + 1));
      }
    }
    fmt = e + 2;
  }
  addstr2buff(&buff, fmt, strlen(fmt));
  clearbuff(&buff);
  return svalue(L->top - 1);
}

const char *obj_pushfstring(State *L, const char *fmt, ...) {
  const char *msg;
  va_list argp;
  va_start(argp, fmt);
  msg = obj_pushvfstring(L, fmt, argp);
  va_end(argp);
  return msg;
}

#define RETS "..."
#define PRE "[string \""
#define POS "\"]"
#define addstr(a,b,l) ( memcpy(a,b,(l) * sizeof(char)), a += (l) )

void obj_chunkid(char *out, const char *source, size_t srclen) {
  size_t bufflen = IDSIZE;
  if (*source == '=') {
    if (srclen <= bufflen)
      memcpy(out, source + 1, srclen * sizeof(char));
    else {
      addstr(out, source + 1, bufflen - 1);
      *out = '\0';
    }
  } else if (*source == '@') {
    if (srclen <= bufflen)
      memcpy(out, source + 1, srclen * sizeof(char));
    else {
      addstr(out, RETS, strlen(RETS));
      bufflen -= strlen(RETS);
      memcpy(out, source + 1 + srclen - bufflen, bufflen * sizeof(char));
    }
  } else {
    const char *nl = strchr(source, '\n');
    addstr(out, PRE, strlen(PRE));
    bufflen -= strlen(PRE RETS POS) + 1;
    if (srclen < bufflen && nl == NULL) {
      addstr(out, source, srclen);
    } else {
      if (nl != NULL) srclen = nl - source;
      if (srclen > bufflen) srclen = bufflen;
      addstr(out, source, srclen);
      addstr(out, RETS, strlen(RETS));
    }
    memcpy(out, POS, (strlen(POS) + 1) * sizeof(char));
  }
}

