    case OPR_DIV: return v1 / v2;
    case OPR_POW: return (v2 == 2) ? v1 * v1 : pow(v1, v2);
    case OPR_IDIV: return floor(v1 / v2);
    case OPR_UNM: return -v1;
    case OPR_MOD: return vm_modf(L, v1, v2);
