  Integer ni;
  n = frexp(n, &i) * -cast_num(INT_MIN);
  if (!vm_flttointns(n, &ni, F2Ieq)) {
    return 0;
  } else {
    unsigned int u = cast_uint(i) + cast_uint(ni);
    return cast_int(u <= cast_uint(INT_MAX) ? u : ~u);
  }
}

static Node *mainpositionTV(const Table *t, const Value *key) {
  switch (ttypetag(key)) {
    case V_INT: return hashint(t, ivalue(key));
