    case V_SHRSTR: return hashstr(t, tsvalue(key));
    case V_LNGSTR: return hashpow2(t, str_hashlong(tsvalue(key)));
    case V_FALSE: return hashboolean(t, 0);
    case V_TRUE: return hashboolean(t, 1);
    case V_LIGHTUD: return hashpointer(t, pvalue(key));
    case V_LCF: return hashpointer(t, (void *)fvalue(key));
    default: return hashpointer(t, gcvalue(key));
