static int equalkey(const Value *k1, const Node *n2, int deadok) {
  if ((rawtt(k1) != keytt(n2)) &&
      !(deadok && keyisdead(n2) && iscollectable(k1)))
    return 0;
  switch (keytt(n2)) {
    case V_NIL: case V_FALSE: case V_TRUE: return 1;
    case V_INT: return (ivalue(k1) == keyival(n2));
    case V_FLT: return fltvalue(k1) == keyval(n2).n;
    case V_LIGHTUD: return pvalue(k1) == keyval(n2).p;
    case V_LCF: return fvalue(k1) == keyval(n2).f;
