/*
 * table.c - Lua tables (array part + chained scatter hash part)
 */
#include <math.h>
#include <limits.h>
#include "core.h"

#define MAXABITS 31
#define MAXASIZE (1u << MAXABITS)
#define MAXHBITS 30

const Value absentkey_value = { {NULL}, V_ABSTKEY };

static Node dummynode_ = {
  { {NULL}, V_EMPTY },  /* value */
  V_NIL, 0, {NULL}      /* key tt, next, key val */
};
#define dummynode (&dummynode_)
#define isdummy(t) ((t)->lastfree == NULL)

#define hashpow2(t,n)   (gnode(t, ((n) & (sizenode(t) - 1))))
#define hashmod(t,n)    (gnode(t, ((n) % ((sizenode(t) - 1) | 1))))
#define hashstr(t,str)  hashpow2(t, (str)->hash)
#define hashboolean(t,p) hashpow2(t, p)
#define hashpointer(t,p) hashmod(t, point2uint(p))

static Node *hashint(const Table *t, Integer i) {
  UInteger ui = l_castS2U(i);
  if (ui <= (UInteger)INT_MAX)
    return hashmod(t, cast_int(ui));
  else
    return gnode(t, (ui % ((sizenode(t) - 1) | 1)));
}

static int l_hashfloat(Number n) {
  int i;
  Integer ni;
  n = frexp(n, &i) * -cast_num(INT_MIN);
  if (!vm_flttointns(n, &ni, F2Ieq)) {
    return 0;
  } else {
    unsigned int u = cast_uint(i) + cast_uint(ni);
    return cast_int(u <= cast_uint(INT_MAX) ? u : ~u);
  }
}

static Node *mainpositionTV(const Table *t, const Value *key) {
  switch (ttypetag(key)) {
    case V_INT: return hashint(t, ivalue(key));
    case V_FLT: return hashmod(t, l_hashfloat(fltvalue(key)));
    case V_SHRSTR: return hashstr(t, tsvalue(key));
    case V_LNGSTR: return hashpow2(t, str_hashlong(tsvalue(key)));
    case V_FALSE: return hashboolean(t, 0);
    case V_TRUE: return hashboolean(t, 1);
    case V_LIGHTUD: return hashpointer(t, pvalue(key));
    case V_LCF: return hashpointer(t, (void *)fvalue(key));
    default: return hashpointer(t, gcvalue(key));
  }
}

static Node *mainpositionfromnode(const Table *t, Node *nd) {
  Value key;
  getnodekey(NULL, &key, nd);
  return mainpositionTV(t, &key);
}

static int equalkey(const Value *k1, const Node *n2, int deadok) {
  if ((rawtt(k1) != keytt(n2)) &&
      !(deadok && keyisdead(n2) && iscollectable(k1)))
    return 0;
  switch (keytt(n2)) {
    case V_NIL: case V_FALSE: case V_TRUE: return 1;
    case V_INT: return (ivalue(k1) == keyival(n2));
    case V_FLT: return fltvalue(k1) == keyval(n2).n;
    case V_LIGHTUD: return pvalue(k1) == keyval(n2).p;
    case V_LCF: return fvalue(k1) == keyval(n2).f;
    case ctb(V_LNGSTR): return str_eqlng(tsvalue(k1), (TString *)keyval(n2).gc);
    default: return gcvalue(k1) == keyval(n2).gc;
  }
}

unsigned int tbl_realasize(const Table *t) { return t->asize; }

size_t tbl_totalsize(const Table *t) {
  size_t sz = sizeof(Table) + (size_t)t->asize * sizeof(Value);
  if (!isdummy(t)) sz += (size_t)sizenode(t) * sizeof(Node);
  return sz;
}

/* ---- traversal ---- */

static unsigned int arrayindex(Integer k) {
  if (l_castS2U(k) - 1u < MAXASIZE) return cast_uint(k);
  return 0;
}

static const Value *getgeneric(Table *t, const Value *key, int deadok) {
  Node *n = mainpositionTV(t, key);
  for (;;) {
    if (equalkey(key, n, deadok))
      return gval(n);
    else {
      int nx = gnext(n);
      if (nx == 0) return &absentkey_value;
      n += nx;
    }
  }
}

static unsigned int findindex(State *L, Table *t, Value *key, unsigned int asize) {
  unsigned int i;
  if (ttisnil(key)) return 0;
  i = ttisinteger(key) ? arrayindex(ivalue(key)) : 0;
  if (i - 1u < asize)
    return i;
  else {
    const Value *n = getgeneric(t, key, 1);
    if (unlikely(isabstkey(n)))
      err_runerror(L, "invalid key to 'next'");
    i = cast_int((Node *)((char *)n - offsetof(Node, val)) - gnode(t, 0));
    return (i + 1) + asize;
  }
}

int tbl_next(State *L, Table *t, StkId key) {
  unsigned int asize = t->asize;
  unsigned int i = findindex(L, t, key, asize);
  for (; i < asize; i++) {
    if (!isempty(&t->array[i])) {
      setivalue(key, i + 1);
      setobj(key + 1, &t->array[i]);
      return 1;
    }
  }
  for (i -= asize; cast_int(i) < sizenode(t); i++) {
    if (!isempty(gval(gnode(t, i)))) {
      Node *n = gnode(t, i);
      getnodekey(L, key, n);
      setobj(key + 1, gval(n));
      return 1;
    }
  }
  return 0;
}

/* ---- rehash ---- */

static unsigned int computesizes(unsigned int nums[], unsigned int *pna) {
  int i;
  unsigned int twotoi;
  unsigned int a = 0;
  unsigned int na = 0;
  unsigned int optimal = 0;
  for (i = 0, twotoi = 1;
       twotoi > 0 && *pna * 3 > twotoi;
       i++, twotoi *= 2) {
    a += nums[i];
    if (a * 3 > twotoi) {
      optimal = twotoi;
      na = a;
    }
  }
  *pna = na;
  return optimal;
}

static int countint(Integer key, unsigned int *nums) {
  unsigned int k = arrayindex(key);
  if (k != 0) {
    nums[obj_ceillog2(k)]++;
    return 1;
  }
  return 0;
}

static unsigned int numusearray(const Table *t, unsigned int *nums) {
  int lg;
  unsigned int ttlg;
  unsigned int ause = 0;
  unsigned int i = 1;
  unsigned int asize = t->asize;
  for (lg = 0, ttlg = 1; lg <= MAXABITS; lg++, ttlg *= 2) {
    unsigned int lc = 0;
    unsigned int lim = ttlg;
    if (lim > asize) {
      lim = asize;
      if (i > lim) break;
    }
    for (; i <= lim; i++) {
      if (!isempty(&t->array[i - 1])) lc++;
    }
    nums[lg] += lc;
    ause += lc;
  }
  return ause;
}

static int numusehash(const Table *t, unsigned int *nums, unsigned int *pna) {
  int totaluse = 0;
  int ause = 0;
  int i = sizenode(t);
  while (i--) {
    Node *n = &t->node[i];
    if (!isempty(gval(n))) {
      if (keyisinteger(n))
        ause += countint(keyival(n), nums);
      totaluse++;
    }
  }
  *pna += ause;
  return totaluse;
}

static void setnodevector(State *L, Table *t, unsigned int size) {
  if (size == 0) {
    t->node = dummynode;
    t->lsizenode = 0;
    t->lastfree = NULL;
  } else {
    int i;
    int lsize = obj_ceillog2(size);
    if (lsize > MAXHBITS || (1u << lsize) > (1u << MAXHBITS))
      err_runerror(L, "table overflow");
    size = 1u << lsize;
    t->node = mem_newvector(L, size, Node);
    for (i = 0; i < (int)size; i++) {
      Node *n = gnode(t, i);
      gnext(n) = 0;
      keytt(n) = V_NIL;
      setempty(gval(n));
    }
    t->lsizenode = cast_byte(lsize);
    t->lastfree = gnode(t, size);
  }
}

static void reinsert(State *L, Table *ot, Table *t) {
  int j;
  int size = sizenode(ot);
  for (j = 0; j < size; j++) {
    Node *old = gnode(ot, j);
    if (!isempty(gval(old))) {
      Value k;
      getnodekey(L, &k, old);
      tbl_set(L, t, &k, gval(old));
    }
  }
}

static void exchangehashpart(Table *t1, Table *t2) {
  uint8_t lsizenode = t1->lsizenode;
  Node *node = t1->node;
  Node *lastfree = t1->lastfree;
  t1->lsizenode = t2->lsizenode;
  t1->node = t2->node;
  t1->lastfree = t2->lastfree;
  t2->lsizenode = lsizenode;
  t2->node = node;
  t2->lastfree = lastfree;
}

void tbl_resize(State *L, Table *t, unsigned int newasize, unsigned int nhsize) {
  unsigned int i;
  Table newt;
  unsigned int oldasize = t->asize;
  Value *newarray;
  newt.flags = 0;
  setnodevector(L, &newt, nhsize);
  if (newasize < oldasize) {
    t->asize = newasize;  /* pretend array has new size... */
    exchangehashpart(t, &newt);
    for (i = newasize; i < oldasize; i++) {
      if (!isempty(&t->array[i]))
        tbl_setint(L, t, i + 1, &t->array[i]);
    }
    t->asize = oldasize;
    exchangehashpart(t, &newt);
  }
  newarray = (Value *)mem_realloc(L, t->array, (size_t)oldasize * sizeof(Value), (size_t)newasize * sizeof(Value));
  if (unlikely(newarray == NULL && newasize > 0)) {
    /* error: free new hash part and raise */
    if (!isdummy(&newt)) mem_freearray(L, newt.node, sizenode(&newt));
    do_throw(L, ST_ERRMEM);
  }
  exchangehashpart(t, &newt);
  t->array = newarray;
  t->asize = newasize;
  for (i = oldasize; i < newasize; i++)
    setempty(&t->array[i]);
  reinsert(L, &newt, t);
  if (!isdummy(&newt)) mem_freearray(L, newt.node, sizenode(&newt));
  t->lenhint = newasize / 2;
}

void tbl_resizearray(State *L, Table *t, unsigned int nasize) {
  int nsize = isdummy(t) ? 0 : sizenode(t);
  tbl_resize(L, t, nasize, nsize);
}

static void rehash(State *L, Table *t, const Value *ek) {
  unsigned int asize;
  unsigned int na;
  unsigned int nums[MAXABITS + 1];
  int i;
  int totaluse;
  for (i = 0; i <= MAXABITS; i++) nums[i] = 0;
  na = numusearray(t, nums);
  totaluse = na;
  totaluse += numusehash(t, nums, &na);
  if (ttisinteger(ek))
    na += countint(ivalue(ek), nums);
  totaluse++;
  asize = computesizes(nums, &na);
  tbl_resize(L, t, asize, totaluse - na);
}

/* ---- creation / destruction ---- */

Table *tbl_new(State *L) {
  Table *t = (Table *)gc_newobj(L, V_TABLE, sizeof(Table));
  t->metatable = NULL;
  t->flags = cast_byte(maskflags);
  t->array = NULL;
  t->asize = 0;
  t->lenhint = 0;
  setnodevector(L, t, 0);
  return t;
}

void tbl_free(State *L, Table *t) {
  if (!isdummy(t)) mem_freearray(L, t->node, sizenode(t));
  mem_freearray(L, t->array, t->asize);
  mem_free(L, t, sizeof(Table));
}

static Node *getfreepos(Table *t) {
  if (!isdummy(t)) {
    while (t->lastfree > t->node) {
      t->lastfree--;
      if (keyisnil(t->lastfree))
        return t->lastfree;
    }
  }
  return NULL;
}

void tbl_newkey(State *L, Table *t, const Value *key, const Value *value) {
  Node *mp;
  Value aux;
  if (unlikely(ttisnil(key)))
    err_runerror(L, "table index is nil");
  else if (ttisfloat(key)) {
    Number f = fltvalue(key);
    Integer k;
    if (vm_flttointns(f, &k, F2Ieq)) {
      setivalue(&aux, k);
      key = &aux;
    } else if (unlikely(isnan(f)))
      err_runerror(L, "table index is NaN");
  }
  if (ttisnil(value))
    return;
  mp = mainpositionTV(t, key);
  if (!isempty(gval(mp)) || isdummy(t)) {
    Node *othern;
    Node *f = getfreepos(t);
    if (f == NULL) {
      rehash(L, t, key);
      tbl_set(L, t, key, value);
      return;
    }
    othern = mainpositionfromnode(t, mp);
    if (othern != mp) {
      /* move colliding node into free position */
      while (othern + gnext(othern) != mp)
