      gnext(othern) = cast_int(f - othern);
      *f = *mp;
      if (gnext(mp) != 0) {
        gnext(f) += cast_int(mp - f);
        gnext(mp) = 0;
      }
      setempty(gval(mp));
    } else {
      /* new node will go into free position */
      if (gnext(mp) != 0)
        gnext(f) = cast_int((mp + gnext(mp)) - f);
      gnext(mp) = cast_int(f - mp);
      mp = f;
    }
  }
  setnodekey(L, mp, key);
  setobj(gval(mp), value);
}

/* ---- search ---- */

const Value *tbl_getint(Table *t, Integer key) {
  if (l_castS2U(key) - 1u < t->asize)
    return &t->array[key - 1];
  else {
    Node *n = hashint(t, key);
    for (;;) {
      if (keyisinteger(n) && keyival(n) == key)
        return gval(n);
      else {
        int nx = gnext(n);
        if (nx == 0) break;
        n += nx;
      }
    }
    return &absentkey_value;
  }
}

const Value *tbl_getshortstr(Table *t, TString *key) {
  Node *n = hashstr(t, key);
  for (;;) {
    if (keyisshrstr(n) && eqshrstr(keystrval(n), key))
      return gval(n);
    else {
      int nx = gnext(n);
      if (nx == 0) return &absentkey_value;
      n += nx;
    }
  }
}

const Value *tbl_getstr(Table *t, TString *key) {
  if (isshrstr(key))
    return tbl_getshortstr(t, key);
  else {
    Value ko;
    setsvalue(&ko, key);
    return getgeneric(t, &ko, 0);
  }
}

const Value *tbl_get(Table *t, const Value *key) {
  switch (ttypetag(key)) {
    case ctb(V_SHRSTR): return tbl_getshortstr(t, tsvalue(key));
    case V_INT: return tbl_getint(t, ivalue(key));
    case V_NIL: return &absentkey_value;
    case V_FLT: {
      Integer k;
      if (vm_flttointns(fltvalue(key), &k, F2Ieq))
        return tbl_getint(t, k);
    }
    /* FALLTHROUGH */
    default:
      return getgeneric(t, key, 0);
  }
}

void tbl_finishset(State *L, Table *t, const Value *key, const Value *slot, const Value *value) {
  if (isabstkey(slot))
    tbl_newkey(L, t, key, value);
  else
    setobj((Value *)slot, value);
}

void tbl_set(State *L, Table *t, const Value *key, const Value *value) {
  const Value *slot = tbl_get(t, key);
  tbl_finishset(L, t, key, slot, value);
}

void tbl_setint(State *L, Table *t, Integer key, const Value *value) {
  const Value *p = tbl_getint(t, key);
  if (isabstkey(p)) {
    Value k;
    setivalue(&k, key);
    tbl_newkey(L, t, &k, value);
  } else
    setobj((Value *)p, value);
}

/* ---- length ---- */

static int present(Table *t, UInteger i) {
  return !isempty(tbl_getint(t, (Integer)i));
}

static UInteger binsearch_gen(Table *t, UInteger i, UInteger j) {
  /* t[i] present (or i == 0), t[j] absent */
  while (j - i > 1u) {
    UInteger m = (i + j) / 2;
    if (!present(t, m)) j = m;
    else i = m;
  }
  return i;
}

static UInteger unbound_search(Table *t, UInteger j) {
  UInteger i;
  if (j == 0) j++;
  do {
    i = j;
    if (j <= l_castS2U(INT64_MAX) / 2)
      j *= 2;
    else {
      j = INT64_MAX;
      if (!present(t, j)) break;
      else return j;
    }
  } while (present(t, j));
  return binsearch_gen(t, i, j);
}

UInteger tbl_getn(Table *t) {
  unsigned int asize = t->asize;
  UInteger h = t->lenhint;
  UInteger result;
  if (h > 0 && !present(t, h)) {
    /* border is below h: probe downward a few steps */
