    UInteger lim = (h > 4) ? h - 4 : 0;
    result = (UInteger)-1;
    for (k = h - 1; k > lim; k--) {
      if (present(t, k)) { result = k; break; }
    }
    if (result == (UInteger)-1) {
      if (lim == 0) result = 0;
      else if (present(t, lim)) result = lim;
      else result = binsearch_gen(t, 0, lim);
    }
  } else {
    UInteger k;
    UInteger p = h;
    result = (UInteger)-1;
    for (k = h + 1; k <= h + 4; k++) {
      if (!present(t, k)) { result = k - 1; break; }
      p = k;
    }
    if (result == (UInteger)-1) {
      /* t[p] present */
      if (p < asize) {
        if (!isempty(&t->array[asize - 1])) {
          /* array full at the end: continue into the hash part */
          if (!present(t, (UInteger)asize + 1))
            result = asize;
          else
            result = unbound_search(t, asize);
        } else
          result = binsearch_gen(t, p, asize);
      } else {
        result = unbound_search(t, p);
      }
    }
  }
  t->lenhint = (unsigned int)((result <= 0xFFFFFFFFu) ? result : 0xFFFFFFFFu);
  return result;
}
