  };
  int i;
  for (i = 0; i < TM_N; i++) {
    G(L)->tmname[i] = str_new(L, eventnames[i]);
    gc_fix(L, (GCHeader *)G(L)->tmname[i]);
  }
}

const Value *tm_get(Table *events, TMS event, TString *ename) {
  const Value *tm = tbl_getshortstr(events, ename);
  if (ttisnil(tm)) {
    if (event <= TM_EQ)
      events->flags |= cast_byte(1u << event);
    return NULL;
  } else
    return tm;
}

const Value *tm_getbyobj(State *L, const Value *o, TMS event) {
  Table *mt;
  switch (ttype(o)) {
    case T_TABLE: mt = hvalue(o)->metatable; break;
    case T_USERDATA: mt = uvalue(o)->metatable; break;
    default: mt = G(L)->mt[ttype(o)];
  }
  return (mt ? tbl_getshortstr(mt, G(L)->tmname[event]) : &absentkey_value);
}

const char *tm_objtypename(State *L, const Value *o) {
  Table *mt;
  if ((ttistable(o) && (mt = hvalue(o)->metatable) != NULL) ||
      (ttisfulluserdata(o) && (mt = uvalue(o)->metatable) != NULL)) {
    const Value *name = tbl_getshortstr(mt, str_new(L, "__name"));
    if (ttisstring(name))
      return getstr(tsvalue(name));
  }
  return ttypename(ttype(o));
}

void tm_call(State *L, const Value *f, const Value *p1, const Value *p2, const Value *p3) {
  StkId func = L->top;
  setobj(func, f);
  setobj(func + 1, p1);
  setobj(func + 2, p2);
  setobj(func + 3, p3);
  L->top = func + 4;
  do_callnoyield(L, func, 0);
}

void tm_callres(State *L, const Value *f, const Value *p1, const Value *p2, StkId res) {
  ptrdiff_t result = savestack(L, res);
  StkId func = L->top;
  setobj(func, f);
  setobj(func + 1, p1);
  setobj(func + 2, p2);
  L->top += 3;
  do_callnoyield(L, func, 1);
  res = restorestack(L, result);
  L->top--;
  setobj(res, L->top);
}

int tm_callbinres(State *L, const Value *p1, const Value *p2, StkId res, TMS event) {
  const Value *tm = tm_getbyobj(L, p1, event);
  if (ttisnil(tm))
    tm = tm_getbyobj(L, p2, event);
  if (ttisnil(tm)) return 0;
  tm_callres(L, tm, p1, p2, res);
  return 1;
}

void tm_trybin(State *L, const Value *p1, const Value *p2, StkId res, TMS event) {
  if (unlikely(!tm_callbinres(L, p1, p2, res, event))) {
    switch (event) {
      case TM_BAND: case TM_BOR: case TM_BXOR:
      case TM_SHL: case TM_SHR: case TM_BNOT: {
        if (ttisnumber(p1) && ttisnumber(p2))
          err_tointerror(L, p1, p2);
        else
          err_opinterror(L, p1, p2, "perform bitwise operation on");
      }
      /* FALLTHROUGH */
      default:
        err_opinterror(L, p1, p2, "perform arithmetic on");
    }
  }
}

int tm_callorder(State *L, const Value *p1, const Value *p2, TMS event) {
  if (tm_callbinres(L, p1, p2, L->top, event))
    return !l_isfalse(L->top);
  err_ordererror(L, p1, p2);
  return 0;
}
