cat > src/gc.c <<'EOF'
/*
 * gc.c - stop-the-world mark & sweep collector with weak tables and finalizers
 */
#include <stdlib.h>
#include <stdio.h>
#include <sys/mman.h>
#include "core.h"
#include "api.h"

#define MARKBIT    1   /* reachable in current cycle */
#define FIXEDBIT   2   /* never collected */
#define FINBIT     4   /* object is in 'finobj' list (has finalizer) */
#define TOBEFNZBIT 8   /* object is in 'tobefnz' list */

#define ismarked(o) ((o)->marked & (MARKBIT | FIXEDBIT))
#define setmark(o)  ((o)->marked |= MARKBIT)

/* simple pointer vectors used as work lists */
typedef struct PtrVec {
  GCHeader **items;
  size_t n, cap;
} PtrVec;

static void pv_push(PtrVec *v, GCHeader *o) {
  if (v->n >= v->cap) {
    size_t ncap = v->cap ? v->cap * 2 : 256;
    GCHeader **ni = (GCHeader **)realloc(v->items, ncap * sizeof(GCHeader *));
    if (ni == NULL) { fprintf(stderr, "out of memory during GC\n"); abort(); }
    v->items = ni;
    v->cap = ncap;
  }
  v->items[v->n++] = o;
}

static void pv_free(PtrVec *v) { free(v->items); v->items = NULL; v->n = v->cap = 0; }

typedef struct GCState {
  GlobalState *g;
  PtrVec gray;        /* objects to traverse */
  PtrVec weakvals;    /* tables with weak values (strong keys) */
  PtrVec ephemerons;  /* tables with weak keys */
  PtrVec allweak;     /* tables with weak keys and values */
} GCState;

GCHeader *gc_newobj(State *L, int tt, size_t sz) {
  GlobalState *g = G(L);
  GCHeader *o = (GCHeader *)mem_alloc(L, sz);
  o->marked = 0;
  o->tt = (uint8_t)tt;
  o->next = g->allgc;
  g->allgc = o;
  return o;
}

void gc_fix(State *L, GCHeader *o) {
  GlobalState *g = G(L);
  /* object must be the most recently created one */
  if (g->allgc == o) {
    g->allgc = o->next;
    o->next = g->fixedgc;
    g->fixedgc = o;
  }
  o->marked |= FIXEDBIT;
}

/* ---- marking ---- */

static void markobject(GCState *st, GCHeader *o) {
  if (o == NULL || ismarked(o)) return;
  setmark(o);
  switch (o->tt) {
    case V_SHRSTR: case V_LNGSTR:
      return;  /* no children */
    case V_UPVAL: {
      UpVal *uv = (UpVal *)o;
      if (!upisopen(uv)) {
        if (iscollectable(uv->v)) pv_push(&st->gray, o);
      }
      return;
    }
    default:
      pv_push(&st->gray, o);
  }
}

#define markvalue(st, v) { if (iscollectable(v)) markobject(st, gcvalue(v)); }

static int iscleared(GCState *st, const Value *o) {
  if (!iscollectable(o)) return 0;
  else if (ttisstring(o)) {
    markobject(st, gcvalue(o));  /* strings are 'values', never weak */
    return 0;
  } else
    return !ismarked(gcvalue(o));
}

static void clearkey(Node *n) {
  if (keyiscollectable(n))
    setdeadkey(n);
}

static int getmode(GlobalState *g, Table *h, int *weakkey, int *weakvalue) {
  const Value *mode;
  *weakkey = *weakvalue = 0;
  if (h->metatable == NULL) return 0;
  mode = gfasttm(g, h->metatable, TM_MODE);
  if (mode && ttisstring(mode)) {
    const char *s = svalue(mode);
    *weakkey = (strchr(s, 'k') != NULL);
    *weakvalue = (strchr(s, 'v') != NULL);
    return (*weakkey || *weakvalue);
  }
  return 0;
}

static void traversestrongtable(GCState *st, Table *h) {
  unsigned int i;
  int size = sizenode(h);
  for (i = 0; i < h->asize; i++)
    markvalue(st, &h->array[i]);
  for (i = 0; i < (unsigned)size; i++) {
    Node *n = gnode(h, i);
    if (isempty(gval(n)))
      clearkey(n);
    else {
      if (keyiscollectable(n)) markobject(st, gckey(n));
      markvalue(st, gval(n));
    }
  }
}

static void traverseweakvalue(GCState *st, Table *h) {
  unsigned int i;
  int size = sizenode(h);
  for (i = 0; i < (unsigned)size; i++) {
    Node *n = gnode(h, i);
    if (isempty(gval(n)))
      clearkey(n);
    else {
      if (keyiscollectable(n)) markobject(st, gckey(n));
    }
  }
  pv_push(&st->weakvals, (GCHeader *)h);
}

/* returns 1 if it marked something new */
static int traverseephemeron(GCState *st, Table *h) {
  unsigned int i;
  int marked = 0;
  int size = sizenode(h);
  for (i = 0; i < h->asize; i++) {
    Value *v = &h->array[i];
    if (iscollectable(v) && !ismarked(gcvalue(v))) {
      marked = 1;
      markobject(st, gcvalue(v));
    }
  }
  for (i = 0; i < (unsigned)size; i++) {
    Node *n = gnode(h, i);
    if (isempty(gval(n)))
      clearkey(n);
    else {
      Value k;
      getnodekey(NULL, &k, n);
      if (iscleared(st, &k)) {
        /* key not marked yet: value stays unmarked for now */
      } else if (iscollectable(gval(n)) && !ismarked(gcvalue(gval(n)))) {
        marked = 1;
        markobject(st, gcvalue(gval(n)));
      }
    }
  }
  return marked;
}

static void traversetable(GCState *st, Table *h) {
  int weakkey, weakvalue;
  markobject(st, (GCHeader *)h->metatable);
  if (getmode(st->g, h, &weakkey, &weakvalue)) {
    if (!weakkey) {
      traverseweakvalue(st, h);
    } else if (!weakvalue) {
      traverseephemeron(st, h);
      pv_push(&st->ephemerons, (GCHeader *)h);
    } else {
      /* all weak: only clear dead keys; everything cleared later */
      pv_push(&st->allweak, (GCHeader *)h);
    }
  } else
    traversestrongtable(st, h);
}

static void traverseproto(GCState *st, Proto *f) {
  int i;
  markobject(st, (GCHeader *)f->source);
  for (i = 0; i < f->sizek; i++) markvalue(st, &f->k[i]);
  for (i = 0; i < f->sizeupvalues; i++) markobject(st, (GCHeader *)f->upvalues[i].name);
  for (i = 0; i < f->sizep; i++) markobject(st, (GCHeader *)f->p[i]);
  for (i = 0; i < f->sizelocvars; i++) markobject(st, (GCHeader *)f->locvars[i].varname);
}

static void traverseLclosure(GCState *st, LClosure *cl) {
  int i;
  markobject(st, (GCHeader *)cl->p);
  for (i = 0; i < cl->nupvalues; i++)
    markobject(st, (GCHeader *)cl->upvals[i]);
}

static void traverseCclosure(GCState *st, CClosure *cl) {
  int i;
  for (i = 0; i < cl->nupvalues; i++)
    markvalue(st, &cl->upvalue[i]);
}

static void traverseudata(GCState *st, Udata *u) {
  int i;
  markobject(st, (GCHeader *)u->metatable);
  for (i = 0; i < u->nuvalue; i++)
    markvalue(st, &u->uv[i]);
}

static void traversethread(GCState *st, State *th) {
  StkId o;
  UpVal *uv;
  if (th->stack == NULL) return;
  for (o = th->stack; o < th->top; o++)
    markvalue(st, o);
  for (uv = th->openupval; uv != NULL; uv = uv->u.open.next)
    markobject(st, (GCHeader *)uv);
  if (th->resumer) markobject(st, (GCHeader *)th->resumer);
  if (!st->g->gcemergency) {
    for (; o < th->stack_last + EXTRA_SLOTS; o++)
      setnilvalue(o);
  }
}

static void propagate(GCState *st) {
  while (st->gray.n > 0) {
    GCHeader *o = st->gray.items[--st->gray.n];
    switch (o->tt) {
      case V_TABLE: traversetable(st, (Table *)o); break;
      case V_USERDATA: traverseudata(st, (Udata *)o); break;
      case V_LCL: traverseLclosure(st, (LClosure *)o); break;
      case V_CCL: traverseCclosure(st, (CClosure *)o); break;
      case V_PROTO: traverseproto(st, (Proto *)o); break;
      case V_THREAD: traversethread(st, (State *)o); break;
      case V_UPVAL: {
        UpVal *uv = (UpVal *)o;
        markvalue(st, uv->v);
        break;
      }
      default: break;
    }
  }
}

static void convergeephemerons(GCState *st) {
  int changed;
  do {
    size_t i;
    changed = 0;
    for (i = 0; i < st->ephemerons.n; i++) {
      Table *h = (Table *)st->ephemerons.items[i];
      if (traverseephemeron(st, h)) {
        propagate(st);
        changed = 1;
      }
    }
  } while (changed);
}

static void clearbykeys(GCState *st, PtrVec *list) {
  size_t i;
  for (i = 0; i < list->n; i++) {
    Table *h = (Table *)list->items[i];
    Node *limit = gnode(h, sizenode(h));
    Node *n;
    for (n = gnode(h, 0); n < limit; n++) {
      Value k;
      getnodekey(NULL, &k, n);
      if (!isempty(gval(n)) && iscleared(st, &k))
        setempty(gval(n));
      if (isempty(gval(n)))
        clearkey(n);
    }
  }
}

static void clearbyvalues(GCState *st, PtrVec *list) {
  size_t i;
  for (i = 0; i < list->n; i++) {
    Table *h = (Table *)list->items[i];
    Node *limit = gnode(h, sizenode(h));
    Node *n;
    unsigned int j;
    for (j = 0; j < h->asize; j++) {
      Value *o = &h->array[j];
      if (iscleared(st, o))
        setempty(o);
    }
    for (n = gnode(h, 0); n < limit; n++) {
      if (!isempty(gval(n)) && iscleared(st, gval(n)))
        setempty(gval(n));
      if (isempty(gval(n)))
        clearkey(n);
    }
  }
}

/* ---- finalizers ---- */

void gc_checkfinalizer(State *L, GCHeader *o, Table *mt) {
  GlobalState *g = G(L);
  if ((o->marked & FINBIT) || (o->marked & TOBEFNZBIT) ||
      gfasttm(g, mt, TM_GC) == NULL || (o->marked & FIXEDBIT))
    return;
  else {
    GCHeader **p;
    /* move object from 'allgc' to 'finobj' */
    for (p = &g->allgc; *p != o; p = &(*p)->next) { /* find it */ }
    *p = o->next;
    o->next = g->finobj;
    g->finobj = o;
    o->marked |= FINBIT;
  }
}

/* move unreachable objects with finalizers to 'tobefnz' (appending to its end) */
static void separatetobefnz(GlobalState *g, int all) {
  GCHeader *curr;
  GCHeader **p = &g->finobj;
  GCHeader **lastnext = &g->tobefnz;
  while (*lastnext != NULL) lastnext = &(*lastnext)->next;
  while ((curr = *p) != NULL) {
    if (!(ismarked(curr) || all)) {
      p = &curr->next;
    } else if (!all && ismarked(curr)) {
      p = &curr->next;
    } else {
      *p = curr->next;
      curr->next = *lastnext;
      *lastnext = curr;
      lastnext = &curr->next;
      curr->marked &= ~FINBIT;
      curr->marked |= TOBEFNZBIT;
    }
  }
}

static void separateunreached(GlobalState *g, int all) {
  GCHeader *curr;
  GCHeader **p = &g->finobj;
  GCHeader **lastnext = &g->tobefnz;
  while (*lastnext != NULL) lastnext = &(*lastnext)->next;
  while ((curr = *p) != NULL) {
    if (ismarked(curr) && !all) {
      p = &curr->next;
    } else {
      *p = curr->next;
      curr->next = *lastnext;
      *lastnext = curr;
      lastnext = &curr->next;
      curr->marked &= ~FINBIT;
      curr->marked |= TOBEFNZBIT;
    }
  }
}

static void marktobefnz(GCState *st) {
  GCHeader *o;
  for (o = st->g->tobefnz; o != NULL; o = o->next)
    markobject(st, o);
}

static void dothecall(State *L, void *ud) {
  UNUSED(ud);
  do_callnoyield(L, L->top - 2, 0);
}

static void GCTM(State *L) {
  GlobalState *g = G(L);
  const Value *tm;
  Value v;
  GCHeader *o = g->tobefnz;
  g->tobefnz = o->next;
  o->next = g->allgc;
  g->allgc = o;
  o->marked &= ~TOBEFNZBIT;
  setgcovalue(&v, o);
  tm = tm_getbyobj(L, &v, TM_GC);
  if (!ttisnil(tm)) {
    int status;
    uint8_t oldah = L->allowhook;
    int oldgcstp = g->gcstopped;
    g->gcstopped |= 2;  /* avoid GC steps */
    L->allowhook = 0;
    setobj(L->top++, tm);
    setobj(L->top++, &v);
    L->ci->callstatus |= CIST_FIN;
    status = do_pcall(L, dothecall, NULL, savestack(L, L->top - 2), 0);
    L->ci->callstatus &= ~CIST_FIN;
    L->allowhook = oldah;
    g->gcstopped = oldgcstp;
    if (unlikely(status != ST_OK)) {
      warn_error(L, "__gc");
      L->top--;
    }
  }
}

void gc_callallpendingfinalizers(State *L) {
  GlobalState *g = G(L);
  while (g->tobefnz)
    GCTM(L);
}

/* ---- sweep ---- */

static void freeupval(State *L, UpVal *uv) {
  if (upisopen(uv)) upval_unlinkupval(uv);
  mem_free(L, uv, sizeof(UpVal));
}

static void freeobj(State *L, GCHeader *o) {
  switch (o->tt) {
    case V_PROTO: proto_free(L, (Proto *)o); break;
    case V_UPVAL: freeupval(L, (UpVal *)o); break;
    case V_LCL: {
      LClosure *cl = (LClosure *)o;
      mem_free(L, cl, offsetof(LClosure, upvals) + sizeof(UpVal *) * cl->nupvalues);
      break;
    }
    case V_CCL: {
      CClosure *cl = (CClosure *)o;
      mem_free(L, cl, offsetof(CClosure, upvalue) + sizeof(Value) * cl->nupvalues);
      break;
    }
    case V_TABLE: tbl_free(L, (Table *)o); break;
    case V_THREAD: co_freethread(L, (State *)o); break;
    case V_USERDATA: {
      Udata *u = (Udata *)o;
      mem_free(L, o, sizeof(Udata) + u->len + (size_t)u->nuvalue * sizeof(Value));
      break;
    }
    case V_SHRSTR: {
      TString *ts = (TString *)o;
      str_remove(L, ts);
      mem_free(L, ts, offsetof(TString, data) + ts->shrlen + 1);
      break;
    }
    case V_LNGSTR: {
      TString *ts = (TString *)o;
      mem_free(L, ts, offsetof(TString, data) + ts->u.lnglen + 1);
      break;
    }
    default: break;
  }
}

static void sweeplist(State *L, GCHeader **p) {
  GCHeader *curr;
  while ((curr = *p) != NULL) {
    if (ismarked(curr)) {
      curr->marked &= ~MARKBIT;
      p = &curr->next;
    } else {
      *p = curr->next;
      freeobj(L, curr);
    }
  }
}

static void clearmarks(GCHeader *list) {
  for (; list; list = list->next) list->marked &= ~MARKBIT;
}

static void markroots(GCState *st, State *L) {
  GlobalState *g = st->g;
  int i;
  markobject(st, (GCHeader *)g->mainthread);
  markvalue(st, &g->l_registry);
  for (i = 0; i < T_NUMTYPES; i++) markobject(st, (GCHeader *)g->mt[i]);
  if (g->running) markobject(st, (GCHeader *)g->running);
  markobject(st, (GCHeader *)L);
  /* threads in the resume chain */
  {
    State *th = g->running;
    while (th) { markobject(st, (GCHeader *)th); th = th->resumer; }
  }
}

static void atomic_collect(State *L, int isemergency) {
  GlobalState *g = G(L);
  GCState st;
  size_t i;
  memset(&st, 0, sizeof(st));
  st.g = g;
  g->gcemergency = isemergency;
  markroots(&st, L);
  propagate(&st);
  convergeephemerons(&st);
  /* clear weak tables (first pass: values that are already dead) */
  clearbyvalues(&st, &st.weakvals);
  clearbyvalues(&st, &st.allweak);
  /* resurrect objects to be finalized */
  separateunreached(g, 0);
  marktobefnz(&st);
  propagate(&st);
  convergeephemerons(&st);
  /* clear weak keys from resurrected / dead objects */
  clearbykeys(&st, &st.ephemerons);
  clearbykeys(&st, &st.allweak);
  clearbyvalues(&st, &st.weakvals);
  clearbyvalues(&st, &st.allweak);
  /* clear string cache entries pointing to dead strings */
  for (i = 0; i < 53; i++) {
    int j;
    for (j = 0; j < 2; j++) {
      TString *ts = g->strcache[i][j];
      if (!ismarked(&ts->hdr)) g->strcache[i][j] = g->memerrmsg;
    }
  }
  /* sweep */
  sweeplist(L, &g->allgc);
  sweeplist(L, &g->finobj);
  clearmarks(g->tobefnz);
  clearmarks(g->fixedgc);
  pv_free(&st.gray);
  pv_free(&st.weakvals);
  pv_free(&st.ephemerons);
  pv_free(&st.allweak);
  g->gcemergency = 0;
  g->gccount++;
}

static void setthreshold(GlobalState *g) {
  size_t est = g->totalbytes;
  size_t th = (est / 100) * (size_t)g->gcpause;
  if (th < est + 64 * 1024) th = est + 64 * 1024;
  g->gcthreshold = th;
  g->gcestimate = est;
}

void gc_fullcollect(State *L, int isemergency) {
  GlobalState *g = G(L);
  if (g->inGC) return;
  g->inGC = 1;
  atomic_collect(L, isemergency);
  g->inGC = 0;
  setthreshold(g);
  if (!isemergency) {
    /* call pending finalizers */
    gc_callallpendingfinalizers(L);
  }
}

void gc_check(State *L) {
  GlobalState *g = G(L);
  if (g->gcstopped || g->inGC || !g->gcrunning) {
    /* keep threshold moving so we do not test on every allocation */
    if (g->totalbytes >= g->gcthreshold)
      g->gcthreshold = g->totalbytes + (g->totalbytes / 2) + 1024;
    return;
  }
  gc_fullcollect(L, 0);
}

void gc_step(State *L) {
  gc_fullcollect(L, 0);
}

void gc_runtilstate(State *L) {
  gc_fullcollect(L, 0);
}

static void freelist(State *L, GCHeader *list) {
  while (list) {
    GCHeader *next = list->next;
    freeobj(L, list);
    list = next;
  }
}

void gc_freeallobjects(State *L) {
  GlobalState *g = G(L);
  g->gcstopped = 1;
  separateunreached(g, 1);
  gc_callallpendingfinalizers(L);
  g->inGC = 1;
  freelist(L, g->allgc);
  g->allgc = NULL;
  freelist(L, g->finobj);
  g->finobj = NULL;
  freelist(L, g->fixedgc);
  g->fixedgc = NULL;
  g->inGC = 0;
}
