      do_throw(g->mainthread, errcode);
    } else {
      const char *msg = ttisstring(L->top - 1) ? svalue(L->top - 1) : "error object is not a string";
      fprintf(stderr, "PANIC: unprotected error in call to Lua API (%s)\n", msg);
      fflush(stderr);
      abort();
    }
  }
}

int do_rawrunprotected(State *L, Pfunc f, void *ud) {
  uint32_t oldnCcalls = L->nCcalls;
  LongJmp lj;
  lj.status = ST_OK;
  lj.previous = L->errorJmp;
  L->errorJmp = &lj;
  if (setjmp(lj.b) == 0) {
    (*f)(L, ud);
  }
  L->errorJmp = lj.previous;
  L->nCcalls = oldnCcalls;
  return lj.status;
}

/* ======================= stack ======================= */

static void relstack(State *L) {
  CallInfo *ci;
  UpVal *up;
  int i;
  L->top = (StkId)savestack(L, L->top);
  for (up = L->openupval; up != NULL; up = up->u.open.next)
    up->v = (Value *)savestack(L, up->v);
  for (ci = L->ci; ci != NULL; ci = ci->previous) {
    ci->top = (StkId)savestack(L, ci->top);
    ci->func = (StkId)savestack(L, ci->func);
  }
  UNUSED(i);
}

static void correctstack(State *L) {
  CallInfo *ci;
  UpVal *up;
  L->top = restorestack(L, (ptrdiff_t)L->top);
  for (up = L->openupval; up != NULL; up = up->u.open.next)
    up->v = restorestack(L, (ptrdiff_t)up->v);
  for (ci = L->ci; ci != NULL; ci = ci->previous) {
    ci->top = restorestack(L, (ptrdiff_t)ci->top);
    ci->func = restorestack(L, (ptrdiff_t)ci->func);
  }
}

void do_reallocstack(State *L, int newsize, int raiseerror) {
  int oldsize = stacksize(L);
  int i;
  StkId newstack;
  int oldgcstop = G(L)->gcstopped;
  relstack(L);
  G(L)->gcstopped |= 4;
  newstack = (StkId)realloc(L->stack, ((size_t)newsize + EXTRA_SLOTS) * sizeof(Value));
  G(L)->gcstopped = oldgcstop;
  if (unlikely(newstack == NULL)) {
    correctstack(L);
    if (raiseerror) do_throw(L, ST_ERRMEM);
    else return;
  }
  G(L)->totalbytes += ((size_t)newsize - (size_t)oldsize) * sizeof(Value);
  L->stack = newstack;
  correctstack(L);
  L->stack_last = L->stack + newsize;
  for (i = oldsize + EXTRA_SLOTS; i < newsize + EXTRA_SLOTS; i++)
    setnilvalue(newstack + i);
}

void do_growstack(State *L, int n, int raiseerror) {
  int size = stacksize(L);
  if (unlikely(size > MAXSTACK_SLOTS)) {
    /* already using the extra space for error handling */
    if (raiseerror)
      do_throw(L, ST_ERRERR);
    return;
  } else if (n < MAXSTACK_SLOTS) {
    int newsize = 2 * size;
    int needed = cast_int(L->top - L->stack) + n;
    if (newsize > MAXSTACK_SLOTS) newsize = MAXSTACK_SLOTS;
    if (newsize < needed) newsize = needed;
    if (likely(newsize <= MAXSTACK_SLOTS)) {
      do_reallocstack(L, newsize, raiseerror);
      return;
    }
  }
  do_reallocstack(L, ERRORSTACKSIZE, raiseerror);
  if (raiseerror)
    err_runerror(L, "stack overflow");
}

static int stackinuse(State *L) {
  CallInfo *ci;
  int res;
  StkId lim = L->top;
  for (ci = L->ci; ci != NULL; ci = ci->previous) {
    if (lim < ci->top) lim = ci->top;
  }
  res = cast_int(lim - L->stack) + 1;
  if (res < LUA_MINSTACK) res = LUA_MINSTACK;
  return res;
}

void do_shrinkstack(State *L) {
  int inuse = stackinuse(L);
  int max = (inuse > MAXSTACK_SLOTS / 3) ? MAXSTACK_SLOTS : inuse * 3;
  if (inuse <= MAXSTACK_SLOTS && stacksize(L) > max) {
    int nsize = (inuse > MAXSTACK_SLOTS / 2) ? MAXSTACK_SLOTS : inuse * 2;
    do_reallocstack(L, nsize, 0);
  }
  do_freeci(L);
}

void do_inctop(State *L) {
  checkstack(L, 1);
  L->top++;
}

void do_checkstackaux(State *L, int n) {
  checkstack(L, n);
}

CallInfo *do_extendci(State *L) {
  CallInfo *ci = mem_new(L, CallInfo);
  L->ci->next = ci;
  ci->previous = L->ci;
  ci->next = NULL;
  L->nci++;
  return ci;
}

void do_freeci(State *L) {
  CallInfo *ci = L->ci;
  CallInfo *next = ci->next;
  ci->next = NULL;
  while ((ci = next) != NULL) {
    next = ci->next;
    mem_free(L, ci, sizeof(CallInfo));
    L->nci--;
  }
}

void state_freeCI(State *L) {
  CallInfo *ci = &L->base_ci;
  CallInfo *next = ci->next;
  ci->next = NULL;
  while ((ci = next) != NULL) {
    next = ci->next;
    mem_free(L, ci, sizeof(CallInfo));
    L->nci--;
  }
}

/* ======================= to-be-closed variables ======================= */

void upval_newtbc(State *L, StkId level) {
  if (l_isfalse(level)) return;  /* false/nil are ignored */
  {
    const Value *tm = tm_getbyobj(L, level, TM_CLOSE);
    if (unlikely(ttisnil(tm))) {
      int idx = cast_int(level - L->ci->func) - 1;
      const char *vname = dbg_getlocalname(clLvalue(L->ci->func)->p, idx + 1,
                                           cast_int(L->ci->u.l.savedpc - clLvalue(L->ci->func)->p->code) - 1);
      if (vname == NULL) vname = "?";
      err_runerror(L, "variable '%s' got a non-closable value", vname);
    }
  }
  if (L->ntbc >= L->sizetbc) {
    int ns = L->sizetbc ? L->sizetbc * 2 : 8;
    L->tbc = (ptrdiff_t *)mem_realloc(L, L->tbc, L->sizetbc * sizeof(ptrdiff_t), ns * sizeof(ptrdiff_t));
    L->sizetbc = ns;
  }
  L->tbc[L->ntbc++] = savestack(L, level);
}

static void callclosemethod(State *L, Value *obj, Value *err, int yy) {
  Value tmv;
  const Value *tm = tm_getbyobj(L, obj, TM_CLOSE);
  StkId top = L->top;
  setobj(&tmv, tm);
  setobj(top, &tmv);
  setobj(top + 1, obj);
  setobj(top + 2, err);
  L->top = top + 3;
  if (yy) do_call(L, top, 0);
  else do_callnoyield(L, top, 0);
}

static void prepcallclosemth(State *L, StkId level, int status, int yy) {
  Value *uv = level;
  Value *errobj;
  Value nilv;
  if (status == CLOSEKTOP) {
    setnilvalue(&nilv);
    errobj = &nilv;
  } else {
    errobj = L->top - 1;  /* error object is on top */
    /* make room for a copy of the object being closed */
    setobj(L->top, uv);
    L->top++;
    uv = L->top - 1;
    errobj = L->top - 2;
  }
  callclosemethod(L, uv, errobj, yy);
  if (status != CLOSEKTOP) {
    /* remove the copy of the object */
    L->top--;
  }
}

void func_close(State *L, StkId level, int status, int yy) {
  ptrdiff_t lvl = savestack(L, level);
  upval_close(L, level);
  while (L->ntbc > 0 && L->tbc[L->ntbc - 1] >= lvl) {
    ptrdiff_t off = L->tbc[--L->ntbc];
    StkId tbc = restorestack(L, off);
    prepcallclosemth(L, tbc, status, yy);
  }
}

/* ======================= calls ======================= */

static StkId tryfuncTM(State *L, StkId func) {
  const Value *tm;
  StkId p;
  checkstack(L, 1);  /* may need space for metamethod */
  tm = tm_getbyobj(L, func, TM_CALL);
  if (unlikely(ttisnil(tm)))
    err_callerror(L, func);
  for (p = L->top; p > func; p--)
    setobj(p, p - 1);
  L->top++;
  setobj(func, tm);
  return func;
}

static void moveresults(State *L, StkId res, int nres, int wanted) {
  StkId firstresult;
  int i;
  switch (wanted) {
    case 0:
      L->top = res;
      return;
    case 1:
      if (nres == 0) setnilvalue(res);
      else setobj(res, L->top - nres);
      L->top = res + 1;
      return;
    case MULTRET:
      wanted = nres;
      break;
    default:
      break;
  }
  firstresult = L->top - nres;
  if (nres > wanted) nres = wanted;
  for (i = 0; i < nres; i++)
    setobj(res + i, firstresult + i);
  for (; i < wanted; i++)
    setnilvalue(res + i);
  L->top = res + wanted;
}

void do_poscall(State *L, CallInfo *ci, int nres) {
  int wanted = ci->nresults;
  L->ci = ci->previous;
  moveresults(L, ci->func, nres, wanted);
}

static CallInfo *prepCallInfo(State *L, StkId func, int nret, int mask, StkId top) {
  CallInfo *ci = L->ci = next_ci(L);
  ci->func = func;
  ci->nresults = (short)nret;
  ci->callstatus = (unsigned short)mask;
  ci->top = top;
  return ci;
}

static void checkstackp(State *L, int n, StkId *func) {
  if (L->stack_last - L->top <= n) {
    ptrdiff_t t = savestack(L, *func);
    do_growstack(L, n, 1);
    *func = restorestack(L, t);
  }
  if (G(L)->totalbytes >= G(L)->gcthreshold) {
    ptrdiff_t t = savestack(L, *func);
    gc_check(L);
    *func = restorestack(L, t);
  }
}

static int precallC(State *L, StkId func, int nresults, CFunction f) {
  int n;
  CallInfo *ci;
  checkstackp(L, LUA_MINSTACK, &func);
  L->ci = ci = prepCallInfo(L, func, nresults, CIST_C, L->top + LUA_MINSTACK);
  n = (*f)(L);
  do_poscall(L, ci, n);
  return n;
}

CallInfo *do_precall(State *L, StkId func, int nresults) {
 retry:
  switch (ttypetag(func)) {
    case ctb(V_CCL):
      precallC(L, func, nresults, clCvalue(func)->f);
      return NULL;
    case V_LCF:
      precallC(L, func, nresults, fvalue(func));
      return NULL;
    case ctb(V_LCL): {
      CallInfo *ci;
      Proto *p = clLvalue(func)->p;
      int narg = cast_int(L->top - func) - 1;
      int nfixparams = p->numparams;
      int fsize = p->maxstacksize;
      checkstackp(L, fsize, &func);
      L->ci = ci = prepCallInfo(L, func, nresults, 0, func + 1 + fsize);
      ci->u.l.savedpc = p->code;
      ci->u.l.nextraargs = 0;
      for (; narg < nfixparams; narg++)
        setnilvalue(L->top++);
      return ci;
    }
    default:
      func = tryfuncTM(L, func);
      goto retry;
  }
}

/* prepare a tail call: move function and args down to ci->func */
void do_pretailcall(State *L, CallInfo *ci, StkId func, int narg1, int delta) {
  int i;
  UNUSED(delta);
  for (i = 0; i < narg1; i++)
    setobj(ci->func + i, func + i);
  L->top = ci->func + narg1;
}

static void ccall(State *L, StkId func, int nResults, int inc) {
  CallInfo *ci;
  L->nCcalls += inc;
  if (unlikely(L->nCcalls >= MAX_CCALLS)) {
    checkstackp(L, 0, &func);
    if (L->nCcalls == MAX_CCALLS)
      err_runerror(L, "C stack overflow");
    else if (L->nCcalls >= (MAX_CCALLS / 10 * 11))
      do_throw(L, ST_ERRERR);
  }
  if ((ci = do_precall(L, func, nResults)) != NULL) {
    ci->callstatus = CIST_FRESH;
    vm_execute(L, ci);
  }
  L->nCcalls -= inc;
}

void do_call(State *L, StkId func, int nResults) {
  ccall(L, func, nResults, 1);
}

void do_callnoyield(State *L, StkId func, int nResults) {
  ccall(L, func, nResults, 1);
}

/* ======================= protected calls ======================= */

struct CloseP {
  StkId level;
  int status;
};

static void closepaux(State *L, void *ud) {
  struct CloseP *pcl = (struct CloseP *)ud;
  func_close(L, pcl->level, pcl->status, 0);
}

int do_closeprotected(State *L, ptrdiff_t level, int status) {
  CallInfo *old_ci = L->ci;
  uint8_t old_allowhooks = L->allowhook;
  for (;;) {
    struct CloseP pcl;
    pcl.level = restorestack(L, level);
    pcl.status = status;
    status = do_rawrunprotected(L, &closepaux, &pcl);
    if (likely(status == ST_OK))
      return pcl.status;
    else {
      L->ci = old_ci;
      L->allowhook = old_allowhooks;
    }
  }
}

int do_pcall(State *L, Pfunc func, void *u, ptrdiff_t old_top, ptrdiff_t ef) {
  int status;
  CallInfo *old_ci = L->ci;
  uint8_t old_allowhooks = L->allowhook;
  ptrdiff_t old_errfunc = L->errfunc;
  L->errfunc = ef;
  status = do_rawrunprotected(L, func, u);
  if (unlikely(status != ST_OK)) {
    L->ci = old_ci;
    L->allowhook = old_allowhooks;
    status = do_closeprotected(L, old_top, status);
    do_seterrorobj(L, status, restorestack(L, old_top));
    do_shrinkstack(L);
  }
  L->errfunc = old_errfunc;
  return status;
}

/* ======================= parser entry ======================= */

struct SParser {
  Zio *z;
  Mbuffer buff;
  const char *mode;
  const char *name;
};

static void checkmode(State *L, const char *mode, const char *x) {
  if (strchr(mode, x[0]) == NULL) {
    obj_pushfstring(L, "attempt to load a %s chunk (mode is '%s')", x, mode);
    do_throw(L, ST_ERRSYNTAX);
  }
}

static void f_parser(State *L, void *ud) {
  LClosure *cl;
  struct SParser *p = (struct SParser *)ud;
  const char *mode = p->mode ? p->mode : "bt";
  int c = zgetc(p->z);
  if (c == 0x1B) {
    checkmode(L, mode, "binary");
    cl = undump_chunk(L, p->z, p->name);
  } else {
    checkmode(L, mode, "text");
    cl = parse_chunk(L, p->z, p->name, c);
  }
  UNUSED(cl);
}

int do_protectedparser_z(State *L, Zio *z, const char *name, const char *mode) {
  struct SParser p;
  int status;
  L->nCcalls++;  /* parser is not reentrant in a sense; count C level */
  p.z = z; p.name = name; p.mode = mode;
  p.buff.buffer = NULL; p.buff.n = 0; p.buff.buffsize = 0;
  status = do_pcall(L, f_parser, &p, savestack(L, L->top), L->errfunc);
  mem_free(L, p.buff.buffer, p.buff.buffsize);
  L->nCcalls--;
  return status;
}

int do_protectedparser(State *L, const char *chunkname, const char *mode, int fromfile) {
  UNUSED(L); UNUSED(chunkname); UNUSED(mode); UNUSED(fromfile);
  return ST_OK;
}

/* ======================= zio ======================= */

void zio_init(State *L, Zio *z, Reader reader, void *data) {
  z->L = L;
  z->reader = reader;
  z->data = data;
  z->n = 0;
  z->p = NULL;
}

int zio_fill(Zio *z) {
  size_t size;
  State *L = z->L;
  const char *buff;
  buff = z->reader(L, z->data, &size);
  if (buff == NULL || size == 0)
    return EOZ;
  z->n = size - 1;
  z->p = buff;
  return (unsigned char)(*(z->p++));
}

size_t zio_read(Zio *z, void *b, size_t n) {
  while (n) {
    size_t m;
    if (z->n == 0) {
      if (zio_fill(z) == EOZ)
        return n;
      else {
        z->n++;
        z->p--;
      }
    }
    m = (n <= z->n) ? n : z->n;
    memcpy(b, z->p, m);
    z->n -= m;
    z->p += m;
    b = (char *)b + m;
    n -= m;
  }
  return 0;
}
