#define op_order(L,opi,opn,other) {  \
  int cond;  \
  Value *rb = RB(i);  \
  if (ttisinteger(s2v_(ra)) && ttisinteger(rb)) {  \
    Integer ia = ivalue(ra);  \
    Integer ib = ivalue(rb);  \
    cond = opi(ia, ib);  \
