  else if (ttisnumber(ra) && ttisnumber(rb))  \
    cond = opn(ra, rb);  \
  else  \
    Protect(cond = other(L, ra, rb));  \
  docondjump(); }

#define op_orderI(L,opi,opf,inv,tm) {  \
  int cond;  \
  int im = GETARG_sB(i);  \
