static int orderI_other(State *L, Value *ra, int im, int inv, int isf, TMS tm) {
  Value aux;
  const Value *p1, *p2;
  if (isf) { setfltvalue(&aux, cast_num(im)); }
  else { setivalue(&aux, im); }
  if (inv) { p1 = &aux; p2 = ra; }
  else { p1 = ra; p2 = &aux; }
  return tm_callorder(L, p1, p2, tm);
}

static void trybinTM_VM(State *L, Value *p1, Value *p2, StkId res, TMS tm) {
  tm_trybin(L, p1, p2, res, tm);
}

void vm_execute(State *L, CallInfo *ci) {
  LClosure *cl;
  Value *k;
  StkId base;
  const Instruction *pc;
 startfunc:
 returning:
  cl = clLvalue(ci->func);
  k = cl->p->k;
  pc = ci->u.l.savedpc;
  base = ci->func + 1;
  for (;;) {
    Instruction i;
