      case OP_SETTABLE: {
        const Value *slot;
        Value *rb = RB(i);
        Value *rc = RKC(i);
        if (ttistable(ra)) {
          if (ttisinteger(rb)) slot = tbl_getint(hvalue(ra), ivalue(rb));
          else slot = tbl_get(hvalue(ra), rb);
          if (!isempty(slot)) {
            setobj((Value *)slot, rc);
            invalidateTMcache(hvalue(ra));
