          }
        } else slot = NULL;
        Protect(vm_finishset(L, ra, rb, rc, slot));
        break;
      }
      case OP_SETI: {
        const Value *slot;
        int c = GETARG_B(i);
        Value *rc = RKC(i);
        if (ttistable(ra) && !isempty(slot = tbl_getint(hvalue(ra), c))) {
          setobj((Value *)slot, rc);
          invalidateTMcache(hvalue(ra));
        } else {
          Value key;
          setivalue(&key, c);
          Protect(vm_finishset(L, ra, &key, rc, ttistable(ra) ? slot : NULL));
        }
        break;
      }
      case OP_SETFIELD: {
        const Value *slot;
        Value *rb = KB(i);
        Value *rc = RKC(i);
        TString *key = tsvalue(rb);
        if (ttistable(ra) && !isempty(slot = tbl_getshortstr(hvalue(ra), key))) {
          setobj((Value *)slot, rc);
          invalidateTMcache(hvalue(ra));
        } else {
          Protect(vm_finishset(L, ra, rb, rc, ttistable(ra) ? slot : NULL));
        }
        break;
      }
      case OP_NEWTABLE: {
        int b = GETARG_B(i);
        int c = GETARG_C(i);
