      }
      case OP_ADDK: { op_arithK(L, l_addi, luai_numadd); break; }
      case OP_SUBK: { op_arithK(L, l_subi, luai_numsub); break; }
      case OP_MULK: { op_arithK(L, l_muli, luai_nummul); break; }
      case OP_MODK: {
        savestate(L, ci);
