      }
      case OP_POWK: { op_arithfK(L, luai_numpow2); break; }
      case OP_DIVK: { op_arithfK(L, luai_numdiv2); break; }
      case OP_IDIVK: {
        savestate(L, ci);
        op_arithK(L, vm_idiv, luai_numidiv);
