      }
      case OP_BANDK: { op_bitwiseK(L, l_band); break; }
      case OP_BORK: { op_bitwiseK(L, l_bor); break; }
      case OP_BXORK: { op_bitwiseK(L, l_bxor); break; }
      case OP_SHRI: {
