      }
      case OP_ADD: { op_arith(L, l_addi, luai_numadd); break; }
      case OP_SUB: { op_arith(L, l_subi, luai_numsub); break; }
      case OP_MUL: { op_arith(L, l_muli, luai_nummul); break; }
      case OP_MOD: {
        savestate(L, ci);
