      case OP_POW: { op_arithf(L, luai_numpow2); break; }
      case OP_DIV: { op_arithf(L, luai_numdiv2); break; }
      case OP_IDIV: {
        savestate(L, ci);
        op_arith(L, vm_idiv, luai_numidiv);
