        if (ttisinteger(ra + 2)) {
          UInteger count = l_castS2U(ivalue(ra + 1));
          if (count > 0) {
            Integer step = ivalue(ra + 2);
            Integer idx = ivalue(ra);
            setivalue(ra + 1, l_castU2S(count - 1));
            idx = intop(+, idx, step);
            setivalue(ra, idx);
            setivalue(ra + 3, idx);
