          pc -= GETARG_Bx(i);
        break;
      }
      case OP_FORPREP: {
        savestate(L, ci);
        if (forprep(L, ra))
          pc += GETARG_Bx(i) + 1;
        break;
      }
      case OP_TFORPREP: {
        halfProtect(upval_newtbc(L, ra + 3));
        pc += GETARG_Bx(i);
        i = *(pc++);
        ra = RA(i);
        goto l_tforcall;
      }
      case OP_TFORCALL: {
       l_tforcall:
