        break;
      }
      case OP_VARARG: {
        int n = GETARG_C(i) - 1;
        Protect(vm_vararg(L, ci, ra, n));
        break;
      }
      case OP_VARARGPREP: {
        ProtectNT(vm_adjustvarargs(L, GETARG_A(i), ci, cl->p));
        break;
      }
      case OP_EXTRAARG: {
        break;
      }
      default:
        break;
    }
  }
}
