actions.command:
cd /workspace && cat > src/vm.c <<'EOF'
/*
 * vm.c - the bytecode interpreter
 */
#include <stdlib.h>
#include <stdio.h>
#include <math.h>
#include <float.h>
#include <limits.h>
#include "core.h"
#include "opcodes.h"
#include "api.h"

#define MAXTAGLOOP 2000

/* ======================= conversions ======================= */

static int l_strton(const Value *obj, Value *result) {
  if (!cvt2num(obj)) return 0;
  else {
    TString *st = tsvalue(obj);
    return (obj_str2num(getstr(st), result) == tsslen(st) + 1);
  }
}

int vm_tonumber_(State *L, const Value *obj, Number *n) {
  Value v;
  UNUSED(L);
  if (ttisinteger(obj)) {
    *n = cast_num(ivalue(obj));
    return 1;
  } else if (l_strton(obj, &v)) {
    *n = nvalue(&v);
    return 1;
  } else
    return 0;
}

int vm_flttointns(Number n, Integer *p, int mode) {
  Number f = floor(n);
  if (n != f) {
    if (mode == F2Ieq) return 0;
    else if (mode == F2Iceil) f += 1;
  }
  if (f >= -9223372036854775808.0 && f < 9223372036854775808.0) {
    *p = (Integer)f;
    return 1;
  }
  return 0;
}

int vm_tointegerns(const Value *obj, Integer *p, int mode) {
  Value v;
  if (l_strton(obj, &v)) obj = &v;
  if (ttisinteger(obj)) {
    *p = ivalue(obj);
    return 1;
  } else if (ttisfloat(obj))
    return vm_flttointns(fltvalue(obj), p, mode);
  else
    return 0;
}

int vm_tointeger(const Value *obj, Integer *p, int mode) {
  return vm_tointegerns(obj, p, mode);
}

int vm_tostring_(State *L, Value *obj) {
  if (!cvt2str(obj)) return 0;
  obj_tostring(L, obj);
  return 1;
}

/* ======================= arithmetic helpers ======================= */

Integer vm_idiv(State *L, Integer m, Integer n) {
  if (unlikely(l_castS2U(n) + 1u <= 1u)) {  /* n == 0 or n == -1 */
    if (n == 0)
      err_runerror(L, "attempt to perform 'n//0'");
    return l_castU2S(0u - l_castS2U(m));  /* avoid overflow with -1 */
  } else {
    Integer q = m / n;
    if ((m ^ n) < 0 && m % n != 0)
      q -= 1;
    return q;
  }
}

Integer vm_mod(State *L, Integer m, Integer n) {
  if (unlikely(l_castS2U(n) + 1u <= 1u)) {
    if (n == 0)
      err_runerror(L, "attempt to perform 'n%%0'");
    return 0;
  } else {
    Integer r = m % n;
    if (r != 0 && (r ^ n) < 0)
      r += n;
    return r;
  }
}

Number vm_modf(State *L, Number m, Number n) {
  Number r;
  UNUSED(L);
  r = fmod(m, n);
  if ((r > 0) ? n < 0 : (r < 0 && n != r))
    r += n;
  return r;
}

#define NBITS 64

Integer vm_shiftl(Integer x, Integer y) {
  if (y < 0) {
    if (y <= -NBITS) return 0;
    else return l_castU2S(l_castS2U(x) >> l_castS2U(-y));
  } else {
    if (y >= NBITS) return 0;
    else return l_castU2S(l_castS2U(x) << l_castS2U(y));
  }
}

/* ======================= comparisons ======================= */

static int l_strcmp(const TString *ls, const TString *rs) {
  const char *l = getstr(ls);
  size_t ll = tsslen(ls);
  const char *r = getstr(rs);
  size_t lr = tsslen(rs);
  for (;;) {
    int temp = strcoll(l, r);
    if (temp != 0)
      return temp;
    else {
      size_t len = strlen(l);
      if (len == lr)
        return (len == ll) ? 0 : 1;
      else if (len == ll)
        return -1;
      len++;
      l += len; ll -= len; r += len; lr -= len;
    }
  }
}

#define l_intfitsf(i) ((l_castS2U(i) + (1ull << 53)) <= (2ull << 53))

static int LTintfloat(Integer i, Number f) {
  if (l_intfitsf(i))
    return cast_num(i) < f;
  else {
    Integer fi;
    if (vm_flttointns(f, &fi, F2Iceil))
      return i < fi;
    else
      return f > 0;
  }
}

static int LEintfloat(Integer i, Number f) {
  if (l_intfitsf(i))
    return cast_num(i) <= f;
  else {
    Integer fi;
    if (vm_flttointns(f, &fi, F2Ifloor))
      return i <= fi;
    else
      return f > 0;
  }
}

static int LTfloatint(Number f, Integer i) {
  if (l_intfitsf(i))
    return f < cast_num(i);
  else {
    Integer fi;
    if (vm_flttointns(f, &fi, F2Ifloor))
      return fi < i;
    else
      return f < 0;
  }
}

static int LEfloatint(Number f, Integer i) {
  if (l_intfitsf(i))
    return f <= cast_num(i);
  else {
    Integer fi;
    if (vm_flttointns(f, &fi, F2Iceil))
      return fi <= i;
    else
      return f < 0;
  }
}

static int LTnum(const Value *l, const Value *r) {
  if (ttisinteger(l)) {
    Integer li = ivalue(l);
    if (ttisinteger(r)) return li < ivalue(r);
    else return LTintfloat(li, fltvalue(r));
  } else {
    Number lf = fltvalue(l);
    if (ttisfloat(r)) return lf < fltvalue(r);
    else return LTfloatint(lf, ivalue(r));
  }
}

static int LEnum(const Value *l, const Value *r) {
  if (ttisinteger(l)) {
    Integer li = ivalue(l);
    if (ttisinteger(r)) return li <= ivalue(r);
    else return LEintfloat(li, fltvalue(r));
  } else {
    Number lf = fltvalue(l);
    if (ttisfloat(r)) return lf <= fltvalue(r);
    else return LEfloatint(lf, ivalue(r));
  }
}

static int lessthanothers(State *L, const Value *l, const Value *r) {
  if (ttisstring(l) && ttisstring(r))
    return l_strcmp(tsvalue(l), tsvalue(r)) < 0;
  else
    return tm_callorder(L, l, r, TM_LT);
}

int vm_lessthan(State *L, const Value *l, const Value *r) {
  if (ttisnumber(l) && ttisnumber(r))
    return LTnum(l, r);
  else return lessthanothers(L, l, r);
}

static int lessequalothers(State *L, const Value *l, const Value *r) {
  if (ttisstring(l) && ttisstring(r))
    return l_strcmp(tsvalue(l), tsvalue(r)) <= 0;
  else
    return tm_callorder(L, l, r, TM_LE);
}

int vm_lessequal(State *L, const Value *l, const Value *r) {
  if (ttisnumber(l) && ttisnumber(r))
    return LEnum(l, r);
  else return lessequalothers(L, l, r);
}

int vm_equalobj(State *L, const Value *t1, const Value *t2) {
  const Value *tm;
  if (ttypetag(t1) != ttypetag(t2)) {
    if (ttype(t1) != ttype(t2) || ttype(t1) != T_NUMBER)
      return 0;
    else {
      Integer i1, i2;
      return (vm_tointegerns(t1, &i1, F2Ieq) &&
              vm_tointegerns(t2, &i2, F2Ieq) && i1 == i2);
    }
  }
  switch (ttypetag(t1)) {
    case V_NIL: case V_FALSE: case V_TRUE: return 1;
    case V_INT: return (ivalue(t1) == ivalue(t2));
    case V_FLT: return fltvalue(t1) == fltvalue(t2);
    case V_LIGHTUD: return pvalue(t1) == pvalue(t2);
    case V_LCF: return fvalue(t1) == fvalue(t2);
    case ctb(V_SHRSTR): return eqshrstr(tsvalue(t1), tsvalue(t2));
    case ctb(V_LNGSTR): return str_eqlng(tsvalue(t1), tsvalue(t2));
    case ctb(V_USERDATA): {
      if (uvalue(t1) == uvalue(t2)) return 1;
      else if (L == NULL) return 0;
      tm = fasttm(L, uvalue(t1)->metatable, TM_EQ);
      if (tm == NULL)
        tm = fasttm(L, uvalue(t2)->metatable, TM_EQ);
      break;
    }
    case ctb(V_TABLE): {
      if (hvalue(t1) == hvalue(t2)) return 1;
      else if (L == NULL) return 0;
      tm = fasttm(L, hvalue(t1)->metatable, TM_EQ);
      if (tm == NULL)
        tm = fasttm(L, hvalue(t2)->metatable, TM_EQ);
      break;
    }
    default:
      return gcvalue(t1) == gcvalue(t2);
  }
  if (tm == NULL)
    return 0;
  else {
    tm_callres(L, tm, t1, t2, L->top);
    return !l_isfalse(L->top);
  }
}

/* ======================= table access ======================= */

void vm_finishget(State *L, const Value *t, Value *key, StkId val, const Value *slot) {
  int loop;
  const Value *tm;
  for (loop = 0; loop < MAXTAGLOOP; loop++) {
    if (slot == NULL) {
      tm = tm_getbyobj(L, t, TM_INDEX);
      if (unlikely(ttisnil(tm)))
        err_typeerror(L, t, "index");
    } else {
      tm = fasttm(L, hvalue(t)->metatable, TM_INDEX);
      if (tm == NULL) {
        setnilvalue(val);
        return;
      }
    }
    if (ttisfunction(tm)) {
      tm_callres(L, tm, t, key, val);
      return;
    }
    t = tm;
    if (ttistable(t)) {
      slot = tbl_get(hvalue(t), key);
      if (!isempty(slot)) {
        setobj(val, slot);
        return;
      }
    } else
      slot = NULL;
  }
  err_runerror(L, "'__index' chain too long; possibly a loop");
}

void vm_finishset(State *L, const Value *t, Value *key, Value *val, const Value *slot) {
  int loop;
  for (loop = 0; loop < MAXTAGLOOP; loop++) {
    const Value *tm;
    if (slot != NULL) {
      Table *h = hvalue(t);
      tm = fasttm(L, h->metatable, TM_NEWINDEX);
      if (tm == NULL) {
        tbl_finishset(L, h, key, slot, val);
        invalidateTMcache(h);
        return;
      }
    } else {
      tm = tm_getbyobj(L, t, TM_NEWINDEX);
      if (unlikely(ttisnil(tm)))
        err_typeerror(L, t, "index");
    }
    if (ttisfunction(tm)) {
      tm_call(L, tm, t, key, val);
      return;
    }
    t = tm;
    if (ttistable(t)) {
      slot = tbl_get(hvalue(t), key);
      if (!isempty(slot)) {
        setobj((Value *)slot, val);
        invalidateTMcache(hvalue(t));
        return;
      }
    } else
      slot = NULL;
  }
  err_runerror(L, "'__newindex' chain too long; possibly a loop");
}

void vm_gettable(State *L, const Value *t, Value *key, StkId val) {
  const Value *slot;
  if (ttistable(t)) {
    slot = tbl_get(hvalue(t), key);
    if (!isempty(slot)) { setobj(val, slot); return; }
  } else slot = NULL;
  vm_finishget(L, t, key, val, slot);
}

void vm_settable(State *L, const Value *t, Value *key, Value *val) {
  const Value *slot;
  if (ttistable(t)) {
    slot = tbl_get(hvalue(t), key);
    if (!isempty(slot)) {
      setobj((Value *)slot, val);
      invalidateTMcache(hvalue(t));
      return;
    }
  } else slot = NULL;
  vm_finishset(L, t, key, val, slot);
}

/* ======================= length & concat ======================= */

void vm_objlen(State *L, StkId ra, const Value *rb) {
  const Value *tm;
  switch (ttypetag(rb)) {
    case ctb(V_TABLE): {
      Table *h = hvalue(rb);
      tm = fasttm(L, h->metatable, TM_LEN);
      if (tm) break;
      setivalue(ra, (Integer)tbl_getn(h));
      return;
    }
    case ctb(V_SHRSTR): {
      setivalue(ra, tsvalue(rb)->shrlen);
      return;
    }
    case ctb(V_LNGSTR): {
      setivalue(ra, (Integer)tsvalue(rb)->u.lnglen);
      return;
    }
    default: {
      tm = tm_getbyobj(L, rb, TM_LEN);
      if (unlikely(ttisnil(tm)))
        err_typeerror(L, rb, "get length of");
      break;
    }
  }
  tm_callres(L, tm, rb, rb, ra);
}

#define tostring(L,o) (ttisstring(o) || (cvt2str(o) && (vm_tostring_(L, o) != 0)))
#define isemptystr(o) (ttisshrstring(o) && tsvalue(o)->shrlen == 0)

static void copy2buff(StkId top, int n, char *buff) {
  size_t tl = 0;
  do {
    size_t l = vslen(top - n);
    memcpy(buff + tl, svalue(top - n), l * sizeof(char));
    tl += l;
  } while (--n > 0);
}

void vm_concat(State *L, int total) {
  if (total == 1) return;
  do {
    StkId top = L->top;
    int n = 2;
    if (!(ttisstring(top - 2) || cvt2str(top - 2)) || !tostring(L, top - 1)) {
      if (!tm_callbinres(L, top - 2, top - 1, top - 2, TM_CONCAT))
        err_concaterror(L, top - 2, top - 1);
    } else if (isemptystr(top - 1)) {
      tostring(L, top - 2);
    } else if (isemptystr(top - 2)) {
      setobj(top - 2, top - 1);
    } else {
      size_t tl = vslen(top - 1);
      TString *ts;
      for (n = 1; n < total && tostring(L, top - n - 1); n++) {
        size_t l = vslen(top - n - 1);
        if (unlikely(l >= (MAX_SIZE / sizeof(char)) - tl)) {
          L->top = top - total;
          err_runerror(L, "string length overflow");
        }
        tl += l;
      }
      if (tl <= MAXSHORTLEN) {
        char buff[MAXSHORTLEN];
        copy2buff(top, n, buff);
        ts = str_newlstr(L, buff, tl);
      } else {
        ts = str_createlng(L, tl);
        copy2buff(top, n, getstr(ts));
      }
      setsvalue(top - n, ts);
    }
    total -= n - 1;
    L->top -= n - 1;
  } while (total > 1);
}

/* ======================= for loop ======================= */

static int forlimit(State *L, Integer init, const Value *lim, Integer *p, Integer step) {
  if (!vm_tointegerns(lim, p, (step < 0 ? F2Iceil : F2Ifloor))) {
    Number flim;
    if (!tonumber(lim, &flim))
      err_forerror(L, lim, "limit");
    if (0 < flim) {
      if (step < 0) return 1;
      *p = INT64_MAX;
    } else {
      if (step > 0) return 1;
      *p = INT64_MIN;
    }
  }
  return (step > 0 ? init > *p : init < *p);
}

static int forprep(State *L, StkId ra) {
  Value *pinit = ra;
  Value *plimit = ra + 1;
  Value *pstep = ra + 2;
  if (ttisinteger(pinit) && ttisinteger(pstep)) {
    Integer init = ivalue(pinit);
    Integer step = ivalue(pstep);
    Integer limit;
    if (step == 0)
      err_runerror(L, "'for' step is zero");
    setivalue(ra + 3, init);
    if (forlimit(L, init, plimit, &limit, step))
      return 1;
    else {
      UInteger count;
      if (step > 0) {
        count = l_castS2U(limit) - l_castS2U(init);
        if (step != 1)
          count /= l_castS2U(step);
      } else {
        count = l_castS2U(init) - l_castS2U(limit);
        count /= (l_castS2U(-(step + 1)) + 1u);
      }
      setivalue(plimit, l_castU2S(count));
    }
  } else {
    Number init; Number flimit; Number step;
    if (unlikely(!tonumber(plimit, &flimit)))
      err_forerror(L, plimit, "limit");
    if (unlikely(!tonumber(pstep, &step)))
      err_forerror(L, pstep, "step");
    if (unlikely(!tonumber(pinit, &init)))
      err_forerror(L, pinit, "initial value");
    if (step == 0)
      err_runerror(L, "'for' step is zero");
    if (step > 0 ? (flimit < init) : (init < flimit))
      return 1;
    else {
      setfltvalue(plimit, flimit);
      setfltvalue(pstep, step);
      setfltvalue(ra, init);
      setfltvalue(ra + 3, init);
    }
  }
  return 0;
}

static int floatforloop(StkId ra) {
  Number step = fltvalue(ra + 2);
  Number limit = fltvalue(ra + 1);
  Number idx = fltvalue(ra);
  idx = idx + step;
  if (step > 0 ? (idx <= limit) : (limit <= idx)) {
    setfltvalue(ra, idx);
    setfltvalue(ra + 3, idx);
    return 1;
  } else
    return 0;
}

/* ======================= closures ======================= */

static void pushclosure(State *L, Proto *p, UpVal **encup, StkId base, StkId ra) {
  int nup = p->sizeupvalues;
  Upvaldesc *uv = p->upvalues;
  int i;
  LClosure *ncl = lclosure_new(L, nup);
  ncl->p = p;
  setclLvalue(ra, ncl);
  for (i = 0; i < nup; i++) {
    if (uv[i].instack)
      ncl->upvals[i] = upval_find(L, base + uv[i].idx);
    else
      ncl->upvals[i] = encup[uv[i].idx];
  }
}

