static int orderI_other(State *L, Value *ra, int im, int inv, int isf, TMS tm) {
  Value aux;
  const Value *p1, *p2;
  if (isf) { setfltvalue(&aux, cast_num(im)); }
  else { setivalue(&aux, im); }
  if (inv) { p1 = &aux; p2 = ra; }
  else { p1 = ra; p2 = &aux; }
  return tm_callorder(L, p1, p2, tm);
}

