void vm_execute(State *L, CallInfo *ci) {
  LClosure *cl;
  Value *k;
  StkId base;
  const Instruction *pc;
 startfunc:
 returning:
  cl = clLvalue(ci->func);
  k = cl->p->k;
  pc = ci->u.l.savedpc;
  base = ci->func + 1;
  for (;;) {
    Instruction i;
    StkId ra;
    vmfetch();
    ra = RA(i);
    switch (GET_OPCODE(i)) {
      case OP_MOVE: {
        setobj(ra, RB(i));
        break;
      }
      case OP_LOADI: {
        Integer b = GETARG_sBx(i);
        setivalue(ra, b);
        break;
      }
      case OP_LOADF: {
        int b = GETARG_sBx(i);
        setfltvalue(ra, cast_num(b));
        break;
      }
      case OP_LOADK: {
        Value *rb = k + GETARG_Bx(i);
        setobj(ra, rb);
        break;
      }
      case OP_LOADKX: {
        Value *rb;
        rb = k + GETARG_Ax(*pc); pc++;
        setobj(ra, rb);
        break;
      }
      case OP_LOADFALSE: {
        setbfvalue(ra);
        break;
      }
      case OP_LFALSESKIP: {
        setbfvalue(ra);
        pc++;
        break;
      }
      case OP_LOADTRUE: {
        setbtvalue(ra);
        break;
      }
      case OP_LOADNIL: {
        int b = GETARG_B(i);
        do {
          setnilvalue(ra++);
        } while (b--);
        break;
      }
      case OP_GETUPVAL: {
        int b = GETARG_B(i);
        setobj(ra, cl->upvals[b]->v);
        break;
      }
      case OP_SETUPVAL: {
        UpVal *uv = cl->upvals[GETARG_B(i)];
        setobj(uv->v, ra);
        break;
      }
      case OP_GETTABUP: {
        const Value *slot;
