/*
 * lexer.c - tokenizer
 */
#include <ctype.h>
#include <locale.h>
#include <stdlib.h>
#include <stdio.h>
#include "core.h"
#include "lexer.h"
#include "api.h"

#define next(ls) (ls->current = zgetc(ls->z))
#define currIsNewline(ls) (ls->current == '\n' || ls->current == '\r')
#define MAXLEXBUF 2147483647

static const char *const token_names[] = {
  "and", "break", "do", "else", "elseif",
  "end", "false", "for", "function", "goto", "if",
  "in", "local", "nil", "not", "or", "repeat",
  "return", "then", "true", "until", "while",
  "//", "..", "...", "==", ">=", "<=", "~=",
  "<<", ">>", "::", "<eof>",
  "<number>", "<integer>", "<name>", "<string>"
};

static void lexerror(LexState *ls, const char *msg, int token);

static void buff_reset(Mbuffer *b) { b->n = 0; }

static void buff_resize(State *L, Mbuffer *b, size_t newsize) {
  b->buffer = (char *)mem_realloc(L, b->buffer, b->buffsize, newsize);
  b->buffsize = newsize;
}

static void save(LexState *ls, int c) {
  Mbuffer *b = ls->buff;
  if (b->n + 1 > b->buffsize) {
    size_t newsize;
    if (b->buffsize >= MAXLEXBUF / 2)
      lexerror(ls, "lexical element too long", 0);
    newsize = b->buffsize * 2;
    if (newsize < 32) newsize = 32;
    buff_resize(ls->L, b, newsize);
  }
  b->buffer[b->n++] = (char)c;
}

#define save_and_next(ls) (save(ls, ls->current), next(ls))

void lex_init(State *L) {
  int i;
  TString *e = str_new(L, "_ENV");
  gc_fix(L, (GCHeader *)e);
  for (i = 0; i < NUM_RESERVED; i++) {
    TString *ts = str_new(L, token_names[i]);
    gc_fix(L, (GCHeader *)ts);
    ts->extra = (uint8_t)(i + 1);
  }
}

const char *lex_token2str(LexState *ls, int token) {
  if (token < FIRST_RESERVED) {
    if (isprint(token))
      return obj_pushfstring(ls->L, "'%c'", token);
    else
      return obj_pushfstring(ls->L, "'<\\%d>'", token);
  } else {
    const char *s = token_names[token - FIRST_RESERVED];
    if (token < TK_EOS)
      return obj_pushfstring(ls->L, "'%s'", s);
    else
      return s;
  }
}

static const char *txtToken(LexState *ls, int token) {
  switch (token) {
    case TK_NAME: case TK_STRING:
    case TK_FLT: case TK_INT:
      save(ls, '\0');
      return obj_pushfstring(ls->L, "'%s'", ls->buff->buffer);
    default:
      return lex_token2str(ls, token);
  }
}

static void lexerror(LexState *ls, const char *msg, int token) {
  char buff[IDSIZE];
  obj_chunkid(buff, getstr(ls->source), tsslen(ls->source));
  msg = obj_pushfstring(ls->L, "%s:%d: %s", buff, ls->linenumber, msg);
  if (token)
    obj_pushfstring(ls->L, "%s near %s", msg, txtToken(ls, token));
  do_throw(ls->L, ST_ERRSYNTAX);
}

void lex_syntaxerror(LexState *ls, const char *msg) {
  lexerror(ls, msg, ls->t.token);
}

TString *lex_newstring(LexState *ls, const char *str, size_t l) {
  State *L = ls->L;
  TString *ts = str_newlstr(L, str, l);
  const Value *o = tbl_getstr(ls->h, ts);
  if (!ttisnil(o))
    ts = tsvalue(o);  /* reuse existing copy */
  else {
    Value key, val;
    setsvalue(&key, ts);
    setbtvalue(&val);
    setsvalue(L->top, ts);
    L->top++;
    tbl_set(L, ls->h, &key, &val);
    gc_checkGC(L);
    L->top--;
  }
  return ts;
}

static void inclinenumber(LexState *ls) {
  int old = ls->current;
  next(ls);
  if (currIsNewline(ls) && ls->current != old)
    next(ls);
  if (++ls->linenumber >= INT_MAX)
    lexerror(ls, "chunk has too many lines", 0);
}

void lex_setinput(State *L, LexState *ls, Zio *z, TString *source, int firstchar) {
  ls->t.token = 0;
  ls->L = L;
  ls->current = firstchar;
  ls->lookahead.token = TK_EOS;
  ls->z = z;
  ls->fs = NULL;
  ls->linenumber = 1;
  ls->lastline = 1;
  ls->source = source;
  ls->envn = str_new(L, "_ENV");
  buff_resize(L, ls->buff, 32);
}

static int check_next1(LexState *ls, int c) {
  if (ls->current == c) {
    next(ls);
    return 1;
  }
  return 0;
}

static int check_next2(LexState *ls, const char *set) {
  if (ls->current == set[0] || ls->current == set[1]) {
    save_and_next(ls);
    return 1;
  }
  return 0;
}

static int read_numeral(LexState *ls, SemInfo *seminfo) {
  Value obj;
  const char *expo = "Ee";
  int first = ls->current;
  save_and_next(ls);
  if (first == '0' && check_next2(ls, "xX"))
    expo = "Pp";
  for (;;) {
    if (check_next2(ls, expo))
      check_next2(ls, "-+");
    else if (isxdigit(ls->current) || ls->current == '.')
      save_and_next(ls);
    else break;
  }
  if (isalpha(ls->current) || ls->current == '_')
    save_and_next(ls);  /* force an error */
  save(ls, '\0');
  if (obj_str2num(ls->buff->buffer, &obj) == 0)
    lexerror(ls, "malformed number", TK_FLT);
  ls->buff->n--;  /* remove '\0' */
  if (ttisinteger(&obj)) {
    seminfo->i = ivalue(&obj);
    return TK_INT;
  } else {
    seminfo->r = fltvalue(&obj);
    return TK_FLT;
  }
}

static size_t skip_sep(LexState *ls) {
  size_t count = 0;
  int s = ls->current;
  save_and_next(ls);
  while (ls->current == '=') {
    save_and_next(ls);
    count++;
  }
  return (ls->current == s) ? count + 2
         : (count == 0) ? 1
         : 0;
}

static void read_long_string(LexState *ls, SemInfo *seminfo, size_t sep) {
  int line = ls->linenumber;
  save_and_next(ls);
  if (currIsNewline(ls))
    inclinenumber(ls);
  for (;;) {
    switch (ls->current) {
      case EOZ: {
        const char *what = (seminfo ? "string" : "comment");
        const char *msg = obj_pushfstring(ls->L, "unfinished long %s (starting at line %d)", what, line);
        lexerror(ls, msg, TK_EOS);
        break;
      }
      case ']': {
        if (skip_sep(ls) == sep) {
          save_and_next(ls);
          goto endloop;
        }
        break;
      }
      case '\n': case '\r': {
        save(ls, '\n');
        inclinenumber(ls);
        if (!seminfo) buff_reset(ls->buff);
        break;
      }
      default: {
        if (seminfo) save_and_next(ls);
        else next(ls);
      }
    }
  } endloop:
  if (seminfo)
    seminfo->ts = lex_newstring(ls, ls->buff->buffer + sep, ls->buff->n - 2 * sep);
}

static void esccheck(LexState *ls, int c, const char *msg) {
  if (!c) {
    if (ls->current != EOZ)
      save_and_next(ls);
    lexerror(ls, msg, TK_STRING);
  }
}

static int gethexa(LexState *ls) {
  save_and_next(ls);
  esccheck(ls, isxdigit(ls->current), "hexadecimal digit expected");
  return obj_hexavalue(ls->current);
}

static int readhexaesc(LexState *ls) {
  int r = gethexa(ls);
  r = (r << 4) + gethexa(ls);
  ls->buff->n -= 2;
  return r;
}

static unsigned long readutf8esc(LexState *ls) {
  unsigned long r;
  int i = 4;
  save_and_next(ls);
  esccheck(ls, ls->current == '{', "missing '{'");
  r = gethexa(ls);
  while ((void)save_and_next(ls), isxdigit(ls->current)) {
    i++;
    esccheck(ls, r <= (0x7FFFFFFFu >> 4), "UTF-8 value too large");
    r = (r << 4) + obj_hexavalue(ls->current);
  }
  esccheck(ls, ls->current == '}', "missing '}'");
  next(ls);
  ls->buff->n -= i;
  return r;
}

static void utf8esc(LexState *ls) {
  char buff[8];
  int n = obj_utf8esc(buff, readutf8esc(ls));
  for (; n > 0; n--)
    save(ls, buff[8 - n]);
}

static int readdecesc(LexState *ls) {
  int i;
  int r = 0;
  for (i = 0; i < 3 && isdigit(ls->current); i++) {
    r = 10 * r + ls->current - '0';
    save_and_next(ls);
  }
  esccheck(ls, r <= UCHAR_MAX, "decimal escape too large");
  ls->buff->n -= i;
  return r;
}

static void read_string(LexState *ls, int del, SemInfo *seminfo) {
  save_and_next(ls);
  while (ls->current != del) {
    switch (ls->current) {
      case EOZ:
        lexerror(ls, "unfinished string", TK_EOS);
        break;
      case '\n':
      case '\r':
        lexerror(ls, "unfinished string", TK_STRING);
        break;
      case '\\': {
        int c;
        save_and_next(ls);
        switch (ls->current) {
          case 'a': c = '\a'; goto read_save;
          case 'b': c = '\b'; goto read_save;
          case 'f': c = '\f'; goto read_save;
          case 'n': c = '\n'; goto read_save;
          case 'r': c = '\r'; goto read_save;
          case 't': c = '\t'; goto read_save;
          case 'v': c = '\v'; goto read_save;
          case 'x': c = readhexaesc(ls); goto read_save;
          case 'u': utf8esc(ls); goto no_save;
          case '\n': case '\r':
            inclinenumber(ls); c = '\n'; goto only_save;
          case '\\': case '\"': case '\'':
            c = ls->current; goto read_save;
          case EOZ: goto no_save;
          case 'z': {
            ls->buff->n--;
            next(ls);
            while (isspace(ls->current)) {
              if (currIsNewline(ls)) inclinenumber(ls);
              else next(ls);
            }
            goto no_save;
          }
          default: {
            esccheck(ls, isdigit(ls->current), "invalid escape sequence");
            c = readdecesc(ls);
            goto only_save;
          }
        }
       read_save:
         next(ls);
       only_save:
         ls->buff->n--;
         save(ls, c);
       no_save: break;
      }
      default:
        save_and_next(ls);
    }
  }
  save_and_next(ls);
  seminfo->ts = lex_newstring(ls, ls->buff->buffer + 1, ls->buff->n - 2);
}

static int llex(LexState *ls, SemInfo *seminfo) {
  buff_reset(ls->buff);
  for (;;) {
    switch (ls->current) {
      case '\n': case '\r': {
        inclinenumber(ls);
        break;
      }
      case ' ': case '\f': case '\t': case '\v': {
        next(ls);
        break;
      }
      case '-': {
        next(ls);
        if (ls->current != '-') return '-';
        next(ls);
        if (ls->current == '[') {
          size_t sep = skip_sep(ls);
          buff_reset(ls->buff);
          if (sep >= 2) {
            read_long_string(ls, NULL, sep);
            buff_reset(ls->buff);
            break;
          }
        }
        while (!currIsNewline(ls) && ls->current != EOZ)
          next(ls);
        break;
      }
      case '[': {
        size_t sep = skip_sep(ls);
        if (sep >= 2) {
          read_long_string(ls, seminfo, sep);
          return TK_STRING;
        } else if (sep == 0)
          lexerror(ls, "invalid long string delimiter", TK_STRING);
        return '[';
      }
      case '=': {
        next(ls);
        if (check_next1(ls, '=')) return TK_EQ;
        else return '=';
      }
      case '<': {
        next(ls);
        if (check_next1(ls, '=')) return TK_LE;
        else if (check_next1(ls, '<')) return TK_SHL;
        else return '<';
      }
      case '>': {
        next(ls);
        if (check_next1(ls, '=')) return TK_GE;
        else if (check_next1(ls, '>')) return TK_SHR;
        else return '>';
      }
      case '/': {
        next(ls);
        if (check_next1(ls, '/')) return TK_IDIV;
        else return '/';
      }
      case '~': {
        next(ls);
        if (check_next1(ls, '=')) return TK_NE;
        else return '~';
      }
      case ':': {
        next(ls);
        if (check_next1(ls, ':')) return TK_DBCOLON;
        else return ':';
      }
      case '"': case '\'': {
        read_string(ls, ls->current, seminfo);
        return TK_STRING;
      }
      case '.': {
        save_and_next(ls);
        if (check_next1(ls, '.')) {
          if (check_next1(ls, '.'))
            return TK_DOTS;
          else return TK_CONCAT;
        } else if (!isdigit(ls->current)) return '.';
        else return read_numeral(ls, seminfo);
      }
      case '0': case '1': case '2': case '3': case '4':
      case '5': case '6': case '7': case '8': case '9': {
        return read_numeral(ls, seminfo);
      }
      case EOZ: {
        return TK_EOS;
      }
      default: {
        if (isalpha(ls->current) || ls->current == '_') {
          TString *ts;
          do {
            save_and_next(ls);
          } while (isalnum(ls->current) || ls->current == '_');
          ts = lex_newstring(ls, ls->buff->buffer, ls->buff->n);
          seminfo->ts = ts;
          if (isshrstr(ts) && ts->extra > 0)
            return ts->extra - 1 + FIRST_RESERVED;
          else
            return TK_NAME;
        } else {
          int c = ls->current;
          next(ls);
          return c;
        }
      }
    }
  }
}

void lex_next(LexState *ls) {
  ls->lastline = ls->linenumber;
  if (ls->lookahead.token != TK_EOS) {
    ls->t = ls->lookahead;
    ls->lookahead.token = TK_EOS;
  } else
    ls->t.token = llex(ls, &ls->t.seminfo);
}

int lex_lookahead(LexState *ls) {
  ls->lookahead.token = llex(ls, &ls->lookahead.seminfo);
  return ls->lookahead.token;
}
