      fixjump(fs, list, vtarget);
    else
      fixjump(fs, list, dtarget);
    list = next;
  }
}

void cg_patchlist(FuncState *fs, int list, int target) {
  patchlistaux(fs, list, target, NO_REG, target);
}

void cg_patchtohere(FuncState *fs, int list) {
  int hr = cg_getlabel(fs);
  cg_patchlist(fs, list, hr);
}

/* ---- line info ---- */

static void savelineinfo(FuncState *fs, Proto *f, int line) {
  int pc = fs->pc - 1;
  mem_growvec(fs->ls->L, f->lineinfo, pc, f->sizelineinfo, int, INT_MAX, "opcodes");
  f->lineinfo[pc] = line;
  fs->previousline = line;
}

static void removelastinstruction(FuncState *fs) {
  fs->pc--;
}

int cg_code(FuncState *fs, Instruction i) {
  Proto *f = fs->f;
  mem_growvec(fs->ls->L, f->code, fs->pc, f->sizecode, Instruction, INT_MAX, "opcodes");
  f->code[fs->pc++] = i;
  savelineinfo(fs, f, fs->ls->lastline);
  return fs->pc - 1;
}

int cg_codeABCk(FuncState *fs, OpCode o, int a, int b, int c, int k) {
  return cg_code(fs, CREATE_ABCk(o, a, b, c, k));
}

int cg_codeABx(FuncState *fs, OpCode o, int a, unsigned int bc) {
  return cg_code(fs, CREATE_ABx(o, a, bc));
}

static int codeAsBx(FuncState *fs, OpCode o, int a, int bc) {
  unsigned int b = bc + OFFSET_sBx;
  return cg_code(fs, CREATE_ABx(o, a, b));
}

static int codesJ(FuncState *fs, OpCode o, int sj, int k) {
  unsigned int j = sj + OFFSET_sJ;
  return cg_code(fs, CREATE_sJ(o, j, k));
}

static int codeextraarg(FuncState *fs, int a) {
  return cg_code(fs, CREATE_Ax(OP_EXTRAARG, a));
}

static int codek(FuncState *fs, int reg, int k) {
  if (k <= MAXARG_Bx)
    return cg_codeABx(fs, OP_LOADK, reg, k);
  else {
    int p = cg_codeABx(fs, OP_LOADKX, reg, 0);
    codeextraarg(fs, k);
    return p;
  }
}

void cg_checkstack(FuncState *fs, int n) {
  int newstack = fs->freereg + n;
  if (newstack > fs->f->maxstacksize) {
    if (newstack >= MAXREGS_)
      lex_syntaxerror(fs->ls, "function or expression needs too many registers");
    fs->f->maxstacksize = cast_byte(newstack);
  }
}

void cg_reserveregs(FuncState *fs, int n) {
  cg_checkstack(fs, n);
  fs->freereg += n;
}

static void freereg(FuncState *fs, int reg) {
  if (reg >= parser_nvarstack(fs)) {
    fs->freereg--;
  }
}

static void freeregs(FuncState *fs, int r1, int r2) {
  if (r1 > r2) {
    freereg(fs, r1);
    freereg(fs, r2);
  } else {
    freereg(fs, r2);
    freereg(fs, r1);
  }
}

static void freeexp(FuncState *fs, expdesc *e) {
  if (e->k == VNONRELOC)
    freereg(fs, e->u.info);
}

static void freeexps(FuncState *fs, expdesc *e1, expdesc *e2) {
  int r1 = (e1->k == VNONRELOC) ? e1->u.info : -1;
  int r2 = (e2->k == VNONRELOC) ? e2->u.info : -1;
  freeregs(fs, r1, r2);
}

/* ---- constants ---- */

static int addk(FuncState *fs, Value *key, Value *v) {
  Value val;
  State *L = fs->ls->L;
  Proto *f = fs->f;
  const Value *idx = tbl_get(fs->ls->h, key);
  int k, oldsize;
  if (ttisinteger(idx)) {
    k = cast_int(ivalue(idx));
    if (k < fs->nk && ttypetag(&f->k[k]) == ttypetag(v) &&
        vm_rawequalobj(&f->k[k], v))
      return k;
  }
  oldsize = f->sizek;
  k = fs->nk;
  setivalue(&val, k);
  tbl_set(L, fs->ls->h, key, &val);
  mem_growvec(L, f->k, k, f->sizek, Value, MAXARG_Ax, "constants");
  while (oldsize < f->sizek) setnilvalue(&f->k[oldsize++]);
  setobj(&f->k[k], v);
  fs->nk++;
  return k;
}

int cg_stringK(FuncState *fs, TString *s) {
  Value o;
  setsvalue(&o, s);
  return addk(fs, &o, &o);
}

static int intK(FuncState *fs, Integer n) {
  Value o;
  setivalue(&o, n);
  return addk(fs, &o, &o);
}

static int numberK(FuncState *fs, Number r) {
  Value o;
  Integer ik;
  setfltvalue(&o, r);
  if (!vm_flttointns(r, &ik, F2Ieq))
    return addk(fs, &o, &o);
  else {
    /* use a different key to avoid collision with the integer */
    const int nbm = DBL_MANT_DIG;
    const Number q = ldexp(1.0, -nbm + 1);
    const Number k = (ik == 0) ? q : r + r * q;
    Value kv;
    setfltvalue(&kv, k);
    return addk(fs, &kv, &o);
  }
}

static int boolF(FuncState *fs) {
  Value o;
  setbfvalue(&o);
  return addk(fs, &o, &o);
}

static int boolT(FuncState *fs) {
  Value o;
  setbtvalue(&o);
  return addk(fs, &o, &o);
}

static int nilK(FuncState *fs) {
  Value k, v;
  setnilvalue(&v);
  sethvalue(&k, fs->ls->h);
  return addk(fs, &k, &v);
}

#define MAXARG_sC_ (OFFSET_sC)
static int fitsC(Integer i) {
  return (l_castS2U(i) + OFFSET_sC <= cast_uint(MAXARG_C));
}

static int fitsBx(Integer i) {
  return (-OFFSET_sBx <= i && i <= MAXARG_Bx - OFFSET_sBx);
}

void cg_int(FuncState *fs, int reg, Integer i) {
  if (fitsBx(i))
    codeAsBx(fs, OP_LOADI, reg, cast_int(i));
  else
    codek(fs, reg, intK(fs, i));
}

static void cg_float(FuncState *fs, int reg, Number f) {
  Integer fi;
  if (vm_flttointns(f, &fi, F2Ieq) && fitsBx(fi))
    codeAsBx(fs, OP_LOADF, reg, cast_int(fi));
  else
    codek(fs, reg, numberK(fs, f));
}

static void const2exp(Value *v, expdesc *e) {
  switch (ttypetag(v)) {
    case V_INT:
      e->k = VKINT; e->u.ival = ivalue(v);
      break;
    case V_FLT:
      e->k = VKFLT; e->u.nval = fltvalue(v);
      break;
    case V_FALSE:
      e->k = VFALSE;
      break;
    case V_TRUE:
      e->k = VTRUE;
      break;
    case V_NIL:
      e->k = VNIL;
      break;
    case ctb(V_SHRSTR): case ctb(V_LNGSTR):
      e->k = VKSTR; e->u.strval = tsvalue(v);
      break;
    default: break;
  }
}

void cg_setreturns(FuncState *fs, expdesc *e, int nresults) {
  Instruction *pc = &getinstruction(fs, e);
  if (e->k == VCALL)
    SETARG_C(*pc, nresults + 1);
  else {
    SETARG_C(*pc, nresults + 1);
    SETARG_A(*pc, fs->freereg);
    cg_reserveregs(fs, 1);
  }
}

static void str2K(FuncState *fs, expdesc *e) {
  e->u.info = cg_stringK(fs, e->u.strval);
  e->k = VK;
}

void cg_setoneret(FuncState *fs, expdesc *e) {
  if (e->k == VCALL) {
    e->k = VNONRELOC;
    e->u.info = GETARG_A(getinstruction(fs, e));
  } else if (e->k == VVARARG) {
    SETARG_C(getinstruction(fs, e), 2);
    e->k = VRELOC;
  }
}

void cg_dischargevars(FuncState *fs, expdesc *e) {
  switch (e->k) {
    case VCONST: {
      const2exp(const2val(fs, e), e);
      break;
    }
    case VLOCAL: {
      e->u.info = e->u.var.ridx;
      e->k = VNONRELOC;
      break;
    }
    case VUPVAL: {
      e->u.info = cg_codeABC(fs, OP_GETUPVAL, 0, e->u.info, 0);
      e->k = VRELOC;
      break;
    }
    case VINDEXUP: {
      e->u.info = cg_codeABC(fs, OP_GETTABUP, 0, e->u.ind.t, e->u.ind.idx);
      e->k = VRELOC;
      break;
    }
    case VINDEXI: {
      freereg(fs, e->u.ind.t);
      e->u.info = cg_codeABC(fs, OP_GETI, 0, e->u.ind.t, e->u.ind.idx);
      e->k = VRELOC;
      break;
    }
    case VINDEXSTR: {
      freereg(fs, e->u.ind.t);
      e->u.info = cg_codeABC(fs, OP_GETFIELD, 0, e->u.ind.t, e->u.ind.idx);
      e->k = VRELOC;
      break;
    }
    case VINDEXED: {
      freeregs(fs, e->u.ind.t, e->u.ind.idx);
      e->u.info = cg_codeABC(fs, OP_GETTABLE, 0, e->u.ind.t, e->u.ind.idx);
      e->k = VRELOC;
      break;
    }
    case VVARARG: case VCALL: {
      cg_setoneret(fs, e);
      break;
    }
    default: break;
  }
}

static void discharge2reg(FuncState *fs, expdesc *e, int reg) {
  cg_dischargevars(fs, e);
  switch (e->k) {
    case VNIL: {
      cg_nil(fs, reg, 1);
      break;
    }
    case VFALSE: {
      cg_codeABC(fs, OP_LOADFALSE, reg, 0, 0);
      break;
    }
    case VTRUE: {
      cg_codeABC(fs, OP_LOADTRUE, reg, 0, 0);
      break;
    }
    case VKSTR: {
      str2K(fs, e);
    }  /* FALLTHROUGH */
    case VK: {
      codek(fs, reg, e->u.info);
      break;
    }
    case VKFLT: {
      cg_float(fs, reg, e->u.nval);
      break;
    }
    case VKINT: {
      cg_int(fs, reg, e->u.ival);
      break;
    }
    case VRELOC: {
      Instruction *pc = &getinstruction(fs, e);
      SETARG_A(*pc, reg);
      break;
    }
    case VNONRELOC: {
      if (reg != e->u.info)
        cg_codeABC(fs, OP_MOVE, reg, e->u.info, 0);
      break;
    }
    default: {
      return;  /* VJMP */
    }
  }
  e->u.info = reg;
  e->k = VNONRELOC;
}

static void discharge2anyreg(FuncState *fs, expdesc *e) {
  if (e->k != VNONRELOC) {
    cg_reserveregs(fs, 1);
    discharge2reg(fs, e, fs->freereg - 1);
  }
}

static int code_loadbool(FuncState *fs, int A, OpCode op) {
  cg_getlabel(fs);
  return cg_codeABC(fs, op, A, 0, 0);
}

static int need_value(FuncState *fs, int list) {
  for (; list != NO_JUMP; list = getjump(fs, list)) {
    Instruction i = *getjumpcontrol(fs, list);
    if (GET_OPCODE(i) != OP_TESTSET) return 1;
  }
  return 0;
}

static void exp2reg(FuncState *fs, expdesc *e, int reg) {
  discharge2reg(fs, e, reg);
  if (e->k == VJMP)
    cg_concat(fs, &e->t, e->u.info);
  if (hasjumps(e)) {
    int final;
    int p_f = NO_JUMP;
    int p_t = NO_JUMP;
    if (need_value(fs, e->t) || need_value(fs, e->f)) {
      int fj = (e->k == VJMP) ? NO_JUMP : cg_jump(fs);
      p_f = code_loadbool(fs, reg, OP_LFALSESKIP);
      p_t = code_loadbool(fs, reg, OP_LOADTRUE);
      cg_patchtohere(fs, fj);
    }
    final = cg_getlabel(fs);
    patchlistaux(fs, e->f, final, reg, p_f);
    patchlistaux(fs, e->t, final, reg, p_t);
  }
  e->f = e->t = NO_JUMP;
  e->u.info = reg;
  e->k = VNONRELOC;
}

void cg_exp2nextreg(FuncState *fs, expdesc *e) {
  cg_dischargevars(fs, e);
  freeexp(fs, e);
  cg_reserveregs(fs, 1);
  exp2reg(fs, e, fs->freereg - 1);
}

int cg_exp2anyreg(FuncState *fs, expdesc *e) {
  cg_dischargevars(fs, e);
  if (e->k == VNONRELOC) {
    if (!hasjumps(e))
      return e->u.info;
    if (e->u.info >= parser_nvarstack(fs)) {
      exp2reg(fs, e, e->u.info);
      return e->u.info;
    }
  }
  cg_exp2nextreg(fs, e);
  return e->u.info;
}

void cg_exp2anyregup(FuncState *fs, expdesc *e) {
  if (e->k != VUPVAL || hasjumps(e))
    cg_exp2anyreg(fs, e);
}

void cg_exp2val(FuncState *fs, expdesc *e) {
  if (e->k == VJMP || hasjumps(e))
    cg_exp2anyreg(fs, e);
  else
    cg_dischargevars(fs, e);
}

static int exp2K(FuncState *fs, expdesc *e) {
  if (!hasjumps(e)) {
    int info;
    switch (e->k) {
      case VTRUE: info = boolT(fs); break;
      case VFALSE: info = boolF(fs); break;
      case VNIL: info = nilK(fs); break;
      case VKINT: info = intK(fs, e->u.ival); break;
      case VKFLT: info = numberK(fs, e->u.nval); break;
      case VKSTR: info = cg_stringK(fs, e->u.strval); break;
      case VK: info = e->u.info; break;
      default: return 0;
    }
    if (info <= MAXINDEXRK) {
      e->k = VK;
      e->u.info = info;
      return 1;
    }
  }
  return 0;
}

static int exp2RK(FuncState *fs, expdesc *e) {
  if (exp2K(fs, e))
    return 1;
  else {
    cg_exp2anyreg(fs, e);
    return 0;
  }
}

static void codeABRK(FuncState *fs, OpCode o, int a, int b, expdesc *ec) {
  int k = exp2RK(fs, ec);
  cg_codeABCk(fs, o, a, b, ec->u.info, k);
}

void cg_storevar(FuncState *fs, expdesc *var, expdesc *ex) {
  switch (var->k) {
    case VLOCAL: {
      freeexp(fs, ex);
      exp2reg(fs, ex, var->u.var.ridx);
      return;
    }
    case VUPVAL: {
      int e = cg_exp2anyreg(fs, ex);
      cg_codeABC(fs, OP_SETUPVAL, e, var->u.info, 0);
      break;
    }
    case VINDEXUP: {
      codeABRK(fs, OP_SETTABUP, var->u.ind.t, var->u.ind.idx, ex);
      break;
    }
    case VINDEXI: {
      codeABRK(fs, OP_SETI, var->u.ind.t, var->u.ind.idx, ex);
      break;
    }
    case VINDEXSTR: {
      codeABRK(fs, OP_SETFIELD, var->u.ind.t, var->u.ind.idx, ex);
      break;
    }
    case VINDEXED: {
      codeABRK(fs, OP_SETTABLE, var->u.ind.t, var->u.ind.idx, ex);
      break;
    }
    default: break;
  }
  freeexp(fs, ex);
}

void cg_self(FuncState *fs, expdesc *e, expdesc *key) {
  int ereg;
  cg_exp2anyreg(fs, e);
  ereg = e->u.info;
  freeexp(fs, e);
  e->u.info = fs->freereg;
  e->k = VNONRELOC;
  cg_reserveregs(fs, 2);
  codeABRK(fs, OP_SELF, e->u.info, ereg, key);
  freeexp(fs, key);
}

static void negatecondition(FuncState *fs, expdesc *e) {
  Instruction *pc = getjumpcontrol(fs, e->u.info);
  SETARG_k(*pc, (GETARG_k(*pc) ^ 1));
}

static int jumponcond(FuncState *fs, expdesc *e, int cond) {
  if (e->k == VRELOC) {
    Instruction ie = getinstruction(fs, e);
    if (GET_OPCODE(ie) == OP_NOT) {
      removelastinstruction(fs);
      return condjump(fs, OP_TEST, GETARG_B(ie), 0, 0, !cond);
    }
  }
  discharge2anyreg(fs, e);
  freeexp(fs, e);
  return condjump(fs, OP_TESTSET, NO_REG, e->u.info, 0, cond);
}

void cg_goiftrue(FuncState *fs, expdesc *e) {
  int pc;
  cg_dischargevars(fs, e);
  switch (e->k) {
    case VJMP: {
      negatecondition(fs, e);
      pc = e->u.info;
      break;
    }
    case VK: case VKFLT: case VKINT: case VKSTR: case VTRUE: {
      pc = NO_JUMP;
      break;
    }
    default: {
      pc = jumponcond(fs, e, 0);
      break;
    }
  }
  cg_concat(fs, &e->f, pc);
  cg_patchtohere(fs, e->t);
  e->t = NO_JUMP;
}

void cg_goiffalse(FuncState *fs, expdesc *e) {
  int pc;
  cg_dischargevars(fs, e);
  switch (e->k) {
    case VJMP: {
      pc = e->u.info;
      break;
    }
    case VNIL: case VFALSE: {
      pc = NO_JUMP;
      break;
    }
    default: {
      pc = jumponcond(fs, e, 1);
      break;
    }
  }
  cg_concat(fs, &e->t, pc);
  cg_patchtohere(fs, e->f);
  e->f = NO_JUMP;
}

static void codenot(FuncState *fs, expdesc *e) {
  switch (e->k) {
    case VNIL: case VFALSE: {
      e->k = VTRUE;
      break;
    }
    case VK: case VKFLT: case VKINT: case VKSTR: case VTRUE: {
      e->k = VFALSE;
      break;
    }
    case VJMP: {
      negatecondition(fs, e);
      break;
    }
    case VRELOC:
    case VNONRELOC: {
      discharge2anyreg(fs, e);
      freeexp(fs, e);
      e->u.info = cg_codeABC(fs, OP_NOT, 0, e->u.info, 0);
      e->k = VRELOC;
      break;
    }
    default: break;
  }
  { int temp = e->f; e->f = e->t; e->t = temp; }
  removevalues(fs, e->f);
  removevalues(fs, e->t);
}

static int isKstr(FuncState *fs, expdesc *e) {
  return (e->k == VK && !hasjumps(e) && e->u.info <= MAXARG_B &&
          ttisshrstring(&fs->f->k[e->u.info]));
}

int cg_isKint(expdesc *e) {
  return (e->k == VKINT && !hasjumps(e));
}

static int isCint(expdesc *e) {
  return cg_isKint(e) && (l_castS2U(e->u.ival) <= l_castS2U(MAXARG_C));
}

static int isSCint(expdesc *e) {
  return cg_isKint(e) && fitsC(e->u.ival);
}

static int isSCnumber(expdesc *e, int *pi, int *isfloat) {
  Integer i;
  if (e->k == VKINT)
    i = e->u.ival;
  else if (e->k == VKFLT && vm_flttointns(e->u.nval, &i, F2Ieq))
    *isfloat = 1;
  else
    return 0;
  if (!hasjumps(e) && fitsC(i)) {
    *pi = cast_int(i) + OFFSET_sC;
    return 1;
  } else
    return 0;
}

void cg_indexed(FuncState *fs, expdesc *t, expdesc *k) {
  if (k->k == VKSTR)
    str2K(fs, k);
  if (t->k == VUPVAL && !isKstr(fs, k))
    cg_exp2anyreg(fs, t);
  t->ro = 0;
  t->gname = NULL;
  if (t->k == VUPVAL) {
    int temp = t->u.info;
    t->u.ind.t = (uint8_t)temp;
    t->u.ind.idx = (short)k->u.info;
    t->k = VINDEXUP;
  } else {
    t->u.ind.t = (uint8_t)((t->k == VLOCAL) ? t->u.var.ridx : t->u.info);
    if (isKstr(fs, k)) {
      t->u.ind.idx = (short)k->u.info;
      t->k = VINDEXSTR;
    } else if (isCint(k)) {
      t->u.ind.idx = (short)cast_int(k->u.ival);
      t->k = VINDEXI;
    } else {
      t->u.ind.idx = (short)cg_exp2anyreg(fs, k);
      t->k = VINDEXED;
    }
  }
}

/* ---- constant folding ---- */

static int validop(int op, Value *v1, Value *v2) {
  switch (op) {
    case OPR_BAND: case OPR_BOR: case OPR_BXOR:
    case OPR_SHL: case OPR_SHR: case OPR_BNOT: {
      Integer i;
      return (vm_tointegerns(v1, &i, F2Ieq) &&
              vm_tointegerns(v2, &i, F2Ieq));
    }
    case OPR_DIV: case OPR_IDIV: case OPR_MOD:
      return (nvalue(v2) != 0);
    default: return 1;
  }
}

static int constfolding(FuncState *fs, int op, expdesc *e1, const expdesc *e2) {
  Value v1, v2, res;
  if (!tonumeral(e1, &v1) || !tonumeral(e2, &v2) || !validop(op, &v1, &v2))
    return 0;
  obj_rawarith(fs->ls->L, op, &v1, &v2, &res);
  if (ttisinteger(&res)) {
    e1->k = VKINT;
    e1->u.ival = ivalue(&res);
  } else {
    Number n = fltvalue(&res);
    if (n != n || n == 0)
      return 0;
    e1->k = VKFLT;
    e1->u.nval = n;
  }
  return 1;
}

static OpCode binopr2op(BinOpr opr, BinOpr baser, OpCode base) {
  return (OpCode)((cast_int(opr) - cast_int(baser)) + cast_int(base));
}

static OpCode unopr2op(UnOpr opr) {
  return (OpCode)((cast_int(opr) - cast_int(OPR_MINUS)) + cast_int(OP_UNM));
}

static TMS binopr2TM(BinOpr opr) {
  return (TMS)((cast_int(opr) - cast_int(OPR_ADD_)) + cast_int(TM_ADD));
}

static void codeunexpval(FuncState *fs, OpCode op, expdesc *e, int line) {
  int r = cg_exp2anyreg(fs, e);
  freeexp(fs, e);
  e->u.info = cg_codeABC(fs, op, 0, r, 0);
  e->k = VRELOC;
  cg_fixline(fs, line);
}

static void finishbinexpval(FuncState *fs, expdesc *e1, expdesc *e2, OpCode op, int v2, int flip, int line, OpCode mmop, TMS event) {
  int v1 = cg_exp2anyreg(fs, e1);
  int pc = cg_codeABCk(fs, op, 0, v1, v2, 0);
  freeexps(fs, e1, e2);
  e1->u.info = pc;
  e1->k = VRELOC;
  cg_fixline(fs, line);
  cg_codeABCk(fs, mmop, v1, v2, event, flip);
  cg_fixline(fs, line);
}

static void codebinexpval(FuncState *fs, BinOpr opr, expdesc *e1, expdesc *e2, int line) {
  OpCode op = binopr2op(opr, OPR_ADD_, OP_ADD);
  int v2 = cg_exp2anyreg(fs, e2);
  finishbinexpval(fs, e1, e2, op, v2, 0, line, OP_MMBIN, binopr2TM(opr));
}

static void codebini(FuncState *fs, OpCode op, expdesc *e1, expdesc *e2, int flip, int line, TMS event) {
  int v2 = cast_int(e2->u.ival) + OFFSET_sC;
  finishbinexpval(fs, e1, e2, op, v2, flip, line, OP_MMBINI, event);
}

static void codebinK(FuncState *fs, BinOpr opr, expdesc *e1, expdesc *e2, int flip, int line) {
  TMS event = binopr2TM(opr);
  int v2 = e2->u.info;
  OpCode op = binopr2op(opr, OPR_ADD_, OP_ADDK);
  finishbinexpval(fs, e1, e2, op, v2, flip, line, OP_MMBINK, event);
}

static int finishbinexpneg(FuncState *fs, expdesc *e1, expdesc *e2, OpCode op, int line, TMS event) {
  if (!cg_isKint(e2))
    return 0;
  else {
    Integer i2 = e2->u.ival;
    if (!(fitsC(i2) && fitsC(-i2)))
      return 0;
    else {
      int v2 = cast_int(i2);
      finishbinexpval(fs, e1, e2, op, (-v2) + OFFSET_sC, 0, line, OP_MMBINI, event);
      SETARG_B(fs->f->code[fs->pc - 1], v2 + OFFSET_sC);
      return 1;
    }
  }
}

static void swapexps(expdesc *e1, expdesc *e2) {
  expdesc temp = *e1; *e1 = *e2; *e2 = temp;
}

static void codebinNoK(FuncState *fs, BinOpr opr, expdesc *e1, expdesc *e2, int flip, int line) {
  if (flip)
    swapexps(e1, e2);
  codebinexpval(fs, opr, e1, e2, line);
}

static void codearith(FuncState *fs, BinOpr opr, expdesc *e1, expdesc *e2, int flip, int line) {
  if (tonumeral(e2, NULL) && exp2K(fs, e2))
    codebinK(fs, opr, e1, e2, flip, line);
  else
    codebinNoK(fs, opr, e1, e2, flip, line);
}

static void codecommutative(FuncState *fs, BinOpr op, expdesc *e1, expdesc *e2, int line) {
  int flip = 0;
  if (tonumeral(e1, NULL)) {
    swapexps(e1, e2);
    flip = 1;
  }
  if (op == OPR_ADD_ && isSCint(e2))
    codebini(fs, OP_ADDI, e1, e2, flip, line, TM_ADD);
  else
    codearith(fs, op, e1, e2, flip, line);
}

static void codebitwise(FuncState *fs, BinOpr opr, expdesc *e1, expdesc *e2, int line) {
  int flip = 0;
  if (e1->k == VKINT) {
    swapexps(e1, e2);
    flip = 1;
  }
  if (e2->k == VKINT && exp2K(fs, e2))
    codebinK(fs, opr, e1, e2, flip, line);
  else
    codebinNoK(fs, opr, e1, e2, flip, line);
}

static void codeorder(FuncState *fs, BinOpr opr, expdesc *e1, expdesc *e2) {
  int r1, r2;
  int im;
  int isfloat = 0;
  OpCode op;
  if (isSCnumber(e2, &im, &isfloat)) {
    r1 = cg_exp2anyreg(fs, e1);
    r2 = im;
    op = binopr2op(opr, OPR_LT_, OP_LTI);
  } else if (isSCnumber(e1, &im, &isfloat)) {
    r1 = cg_exp2anyreg(fs, e2);
    r2 = im;
    op = binopr2op(opr, OPR_LT_, OP_GTI);
  } else {
    r1 = cg_exp2anyreg(fs, e1);
    r2 = cg_exp2anyreg(fs, e2);
    op = binopr2op(opr, OPR_LT_, OP_LT);
  }
  freeexps(fs, e1, e2);
  e1->u.info = condjump(fs, op, r1, r2, isfloat, 1);
  e1->k = VJMP;
}

static void codeeq(FuncState *fs, BinOpr opr, expdesc *e1, expdesc *e2) {
  int r1, r2;
  int im;
  int isfloat = 0;
  OpCode op;
  if (e1->k != VNONRELOC) {
    swapexps(e1, e2);
  }
  r1 = cg_exp2anyreg(fs, e1);
  if (isSCnumber(e2, &im, &isfloat)) {
    op = OP_EQI;
    r2 = im;
  } else if (exp2RK(fs, e2)) {
    op = OP_EQK;
    r2 = e2->u.info;
  } else {
    op = OP_EQ;
    r2 = cg_exp2anyreg(fs, e2);
  }
  freeexps(fs, e1, e2);
  e1->u.info = condjump(fs, op, r1, r2, isfloat, (opr == OPR_EQ_));
  e1->k = VJMP;
}

void cg_prefix(FuncState *fs, UnOpr opr, expdesc *e, int line) {
  static const expdesc ef = {VKINT, {0}, NO_JUMP, NO_JUMP, 0, NULL};
  cg_dischargevars(fs, e);
  switch (opr) {
    case OPR_MINUS: case OPR_BNOT_:
      if (constfolding(fs, (opr == OPR_MINUS) ? OPR_UNM : OPR_BNOT, e, &ef))
        break;
      /* FALLTHROUGH */
    case OPR_LEN_:
      codeunexpval(fs, unopr2op(opr), e, line);
      break;
    case OPR_NOT_: codenot(fs, e); break;
    default: break;
  }
}

void cg_infix(FuncState *fs, BinOpr op, expdesc *v) {
  cg_dischargevars(fs, v);
  switch (op) {
    case OPR_AND_: {
      cg_goiftrue(fs, v);
      break;
    }
    case OPR_OR_: {
      cg_goiffalse(fs, v);
      break;
    }
    case OPR_CONCAT_: {
      cg_exp2nextreg(fs, v);
      break;
    }
    case OPR_ADD_: case OPR_SUB_:
    case OPR_MUL_: case OPR_DIV_: case OPR_IDIV_:
    case OPR_MOD_: case OPR_POW_:
    case OPR_BAND_: case OPR_BOR_: case OPR_BXOR_:
    case OPR_SHL_: case OPR_SHR_: {
      if (!tonumeral(v, NULL))
        cg_exp2anyreg(fs, v);
      break;
    }
    case OPR_EQ_: case OPR_NE_: {
      if (!tonumeral(v, NULL))
        exp2RK(fs, v);
      break;
    }
    case OPR_LT_: case OPR_LE_:
    case OPR_GT_: case OPR_GE_: {
      int dummy, dummy2;
      if (!isSCnumber(v, &dummy, &dummy2))
        cg_exp2anyreg(fs, v);
      break;
    }
    default: break;
  }
}

static void codeconcat(FuncState *fs, expdesc *e1, expdesc *e2, int line) {
  Instruction *ie2 = previousinstruction(fs);
  if (GET_OPCODE(*ie2) == OP_CONCAT) {
    int n = GETARG_B(*ie2);
    freeexp(fs, e2);
    SETARG_A(*ie2, e1->u.info);
    SETARG_B(*ie2, n + 1);
  } else {
    cg_codeABC(fs, OP_CONCAT, e1->u.info, 2, 0);
    freeexp(fs, e2);
    cg_fixline(fs, line);
  }
}

void cg_posfix(FuncState *fs, BinOpr opr, expdesc *e1, expdesc *e2, int line) {
  cg_dischargevars(fs, e2);
  if (opr <= OPR_SHR_ && constfolding(fs, opr + OPR_ADD, e1, e2))
    return;
  switch (opr) {
    case OPR_AND_: {
      cg_concat(fs, &e2->f, e1->f);
      *e1 = *e2;
      break;
    }
    case OPR_OR_: {
      cg_concat(fs, &e2->t, e1->t);
      *e1 = *e2;
      break;
    }
    case OPR_CONCAT_: {
      cg_exp2nextreg(fs, e2);
      codeconcat(fs, e1, e2, line);
      break;
    }
    case OPR_ADD_: case OPR_MUL_: {
      codecommutative(fs, opr, e1, e2, line);
      break;
    }
    case OPR_SUB_: {
      if (finishbinexpneg(fs, e1, e2, OP_ADDI, line, TM_SUB))
        break;
      /* FALLTHROUGH */
    }
    case OPR_DIV_: case OPR_IDIV_: case OPR_MOD_: case OPR_POW_: {
      codearith(fs, opr, e1, e2, 0, line);
      break;
    }
    case OPR_BAND_: case OPR_BOR_: case OPR_BXOR_: {
      codebitwise(fs, opr, e1, e2, line);
      break;
    }
    case OPR_SHL_: {
      if (isSCint(e1)) {
        swapexps(e1, e2);
        codebini(fs, OP_SHLI, e1, e2, 1, line, TM_SHL);
      } else if (finishbinexpneg(fs, e1, e2, OP_SHRI, line, TM_SHL)) {
        /* coded as (r1 >> -I) */
      } else
        codebinexpval(fs, opr, e1, e2, line);
      break;
    }
    case OPR_SHR_: {
      if (isSCint(e2))
        codebini(fs, OP_SHRI, e1, e2, 0, line, TM_SHR);
      else
        codebinexpval(fs, opr, e1, e2, line);
      break;
    }
    case OPR_EQ_: case OPR_NE_: {
      codeeq(fs, opr, e1, e2);
      break;
    }
    case OPR_GT_: case OPR_GE_: {
      /* '(a > b)' <=> '(b < a)';  '(a >= b)' <=> '(b <= a)' */
      swapexps(e1, e2);
      opr = (BinOpr)((opr - OPR_GT_) + OPR_LT_);
    }  /* FALLTHROUGH */
    case OPR_LT_: case OPR_LE_: {
      codeorder(fs, opr, e1, e2);
      break;
    }
    default: break;
  }
}

void cg_fixline(FuncState *fs, int line) {
  fs->f->lineinfo[fs->pc - 1] = line;
  fs->previousline = line;
}

void cg_settablesize(FuncState *fs, int pc, int ra, int asize, int hsize) {
  Instruction *inst = &fs->f->code[pc];
  int rb = (hsize != 0) ? obj_ceillog2(hsize) + 1 : 0;
  int extra = asize / (MAXARG_C + 1);
  int rc = asize % (MAXARG_C + 1);
  int k = (extra > 0);
  *inst = CREATE_ABCk(OP_NEWTABLE, ra, rb, rc, k);
  *(inst + 1) = CREATE_Ax(OP_EXTRAARG, extra);
}

void cg_setlist(FuncState *fs, int base, int nelems, int tostore) {
  if (tostore == MULTRET)
    tostore = 0;
  if (nelems <= MAXARG_C)
    cg_codeABC(fs, OP_SETLIST, base, tostore, nelems);
  else {
    int extra = nelems / (MAXARG_C + 1);
    nelems %= (MAXARG_C + 1);
    cg_codeABCk(fs, OP_SETLIST, base, tostore, nelems, 1);
    codeextraarg(fs, extra);
  }
  fs->freereg = base + 1;
}

/* check whether a global variable is already defined: emits OP_CHKGLB */
void cg_codeglbcheck(FuncState *fs, expdesc *var, int nameidx) {
  expdesc copy = *var;
  int r;
  cg_exp2anyreg(fs, &copy);
  r = copy.u.info;
  freeexp(fs, &copy);
  cg_codeABx(fs, OP_CHKGLB, r, nameidx);
}

static int finaltarget(Instruction *code, int i) {
  int count;
  for (count = 0; count < 100; count++) {
    Instruction pc = code[i];
    if (GET_OPCODE(pc) != OP_JMP)
      break;
    else
      i += GETARG_sJ(pc) + 1;
  }
  return i;
}

void cg_finish(FuncState *fs) {
  int i;
  Proto *p = fs->f;
  for (i = 0; i < fs->pc; i++) {
    Instruction *pc = &p->code[i];
    switch (GET_OPCODE(*pc)) {
      case OP_RETURN0: case OP_RETURN1: {
        if (!(fs->needclose || p->is_vararg))
          break;
        SET_OPCODE(*pc, OP_RETURN);
      }  /* FALLTHROUGH */
      case OP_RETURN: case OP_TAILCALL: {
        if (fs->needclose)
          SETARG_k(*pc, 1);
        if (p->is_vararg)
          SETARG_C(*pc, p->numparams + 1);
        break;
      }
      case OP_JMP: {
        int target = finaltarget(p->code, i);
        fixjump(fs, i, target);
        break;
      }
      default: break;
    }
  }
}
