output.arguments:
{"command":"cd /workspace && cat > src/parser.c <<'EOF'
/*
 * parser.c - recursive descent parser producing bytecode
 */
#include <limits.h>
#include <stdlib.h>
#include <string.h>
#include "core.h"
#include "lexer.h"
#include "parser.h"
#include "api.h"

#define hasmultret(k) ((k) == VCALL || (k) == VVARARG)
#define eqstr_(a,b) ((a) == (b))

typedef struct BlockCnt {
  struct BlockCnt *previous;
  int firstlabel;
  int firstgoto;
  uint8_t nactvar;
  uint8_t upval;
  uint8_t isloop;
  uint8_t insidetbc;
} BlockCnt;

static void statement(LexState *ls);
static void expr(LexState *ls, expdesc *v);

static void error_expected(LexState *ls, int token) {
  lex_syntaxerror(ls, obj_pushfstring(ls->L, "%s expected", lex_token2str(ls, token)));
}

static void errorlimit(FuncState *fs, int limit, const char *what) {
  State *L = fs->ls->L;
  const char *msg;
  int line = fs->f->linedefined;
  const char *where = (line == 0) ? "main function" : obj_pushfstring(L, "function at line %d", line);
  msg = obj_pushfstring(L, "too many %s (limit is %d) in %s", what, limit, where);
  lex_syntaxerror(fs->ls, msg);
}

static void checklimit(FuncState *fs, int v, int l, const char *what) {
  if (v > l) errorlimit(fs, l, what);
}

static int testnext(LexState *ls, int c) {
  if (ls->t.token == c) {
    lex_next(ls);
    return 1;
  } else return 0;
}

static void check(LexState *ls, int c) {
  if (ls->t.token != c)
    error_expected(ls, c);
}

static void checknext(LexState *ls, int c) {
  check(ls, c);
  lex_next(ls);
}

#define check_condition(ls,c,msg) { if (!(c)) lex_syntaxerror(ls, msg); }

static void check_match(LexState *ls, int what, int who, int where) {
  if (unlikely(!testnext(ls, what))) {
    if (where == ls->linenumber)
      error_expected(ls, what);
    else {
      lex_syntaxerror(ls, obj_pushfstring(ls->L,
        "%s expected (to close %s at line %d)",
        lex_token2str(ls, what), lex_token2str(ls, who), where));
    }
  }
}

static TString *str_checkname(LexState *ls) {
  TString *ts;
  check(ls, TK_NAME);
  ts = ls->t.seminfo.ts;
  lex_next(ls);
  return ts;
}

static void init_exp(expdesc *e, expkind k, int i) {
  e->f = e->t = NO_JUMP;
  e->k = k;
  e->u.info = i;
  e->ro = 0;
  e->gname = NULL;
}

static void codestring(expdesc *e, TString *s) {
  e->f = e->t = NO_JUMP;
  e->k = VKSTR;
  e->u.strval = s;
  e->ro = 0;
  e->gname = NULL;
}

static void codename(LexState *ls, expdesc *e) {
  codestring(e, str_checkname(ls));
}

static int registerlocalvar(LexState *ls, FuncState *fs, TString *varname) {
  Proto *f = fs->f;
  int oldsize = f->sizelocvars;
  mem_growvec(ls->L, f->locvars, fs->ndebugvars, f->sizelocvars, LocVar, SHRT_MAX, "local variables");
  while (oldsize < f->sizelocvars)
    f->locvars[oldsize++].varname = NULL;
  f->locvars[fs->ndebugvars].varname = varname;
  f->locvars[fs->ndebugvars].startpc = fs->pc;
  return fs->ndebugvars++;
}

static int new_localvar(LexState *ls, TString *name) {
  State *L = ls->L;
  FuncState *fs = ls->fs;
  Dyndata *dyd = ls->dyd;
  Vardesc *var;
  checklimit(fs, dyd->actvar.n + 1 - fs->firstlocal, MAXVARS, "local variables");
  mem_growvec(L, dyd->actvar.arr, dyd->actvar.n + 1, dyd->actvar.size, Vardesc, USHRT_MAX, "local variables");
  var = &dyd->actvar.arr[dyd->actvar.n++];
  var->vd.kind = VDKREG;
  var->vd.name = name;
  return dyd->actvar.n - 1 - fs->firstlocal;
}

#define new_localvarliteral(ls,v) new_localvar(ls, lex_newstring(ls, "" v, (sizeof(v)/sizeof(char)) - 1))

static Vardesc *getlocalvardesc(FuncState *fs, int vidx) {
  return &fs->ls->dyd->actvar.arr[fs->firstlocal + vidx];
}

static int varhasreg(Vardesc *vd) {
  return vd->vd.kind <= RDKTOCLOSE;  /* regular, const, tbc locals occupy registers */
}

/* register level: number of registers used by the first nvar active variables */
static int reglevel(FuncState *fs, int nvar) {
  while (nvar-- > 0) {
    Vardesc *vd = getlocalvardesc(fs, nvar);
    if (varhasreg(vd))
      return vd->vd.ridx + 1;
  }
  return 0;
}

int parser_nvarstack(FuncState *fs) {
  return reglevel(fs, fs->nactvar);
}

static LocVar *localdebuginfo(FuncState *fs, int vidx) {
  Vardesc *vd = getlocalvardesc(fs, vidx);
  if (!varhasreg(vd))
    return NULL;
  else {
    int idx = vd->vd.pidx;
    return &fs->f->locvars[idx];
  }
}

static void init_var(FuncState *fs, expdesc *e, int vidx) {
  e->f = e->t = NO_JUMP;
  e->k = VLOCAL;
  e->u.var.vidx = (unsigned short)vidx;
  e->u.var.ridx = getlocalvardesc(fs, vidx)->vd.ridx;
  e->ro = 0;
  e->gname = NULL;
}

static void check_readonly(LexState *ls, expdesc *e) {
  FuncState *fs = ls->fs;
  TString *varname = NULL;
  switch (e->k) {
    case VCONST: {
      varname = ls->dyd->actvar.arr[e->u.info].vd.name;
      break;
    }
    case VLOCAL: {
      Vardesc *vardesc = getlocalvardesc(fs, e->u.var.vidx);
      if (vardesc->vd.kind != VDKREG)
        varname = vardesc->vd.name;
      break;
    }
    case VUPVAL: {
      Upvaldesc *up = &fs->f->upvalues[e->u.info];
      if (up->kind != VDKREG)
        varname = up->name;
      break;
    }
    case VINDEXUP: case VINDEXSTR: case VINDEXED: case VINDEXI: {
      if (e->ro) varname = e->gname;
      break;
    }
    default:
      return;
  }
  if (varname) {
    const char *msg = obj_pushfstring(ls->L, "attempt to assign to const variable '%s'", getstr(varname));
    cg_semerror(ls, msg);
  }
}

static void adjustlocalvars(LexState *ls, int nvars) {
  FuncState *fs = ls->fs;
  int reglevel_ = parser_nvarstack(fs);
  int i;
  for (i = 0; i < nvars; i++) {
    int vidx = fs->nactvar++;
    Vardesc *var = getlocalvardesc(fs, vidx);
    var->vd.ridx = (uint8_t)reglevel_++;
    var->vd.pidx = (short)registerlocalvar(ls, fs, var->vd.name);
  }
}

static void removevars(FuncState *fs, int tolevel) {
  fs->ls->dyd->actvar.n -= (fs->nactvar - tolevel);
  while (fs->nactvar > tolevel) {
    LocVar *var = localdebuginfo(fs, --fs->nactvar);
    if (var)
      var->endpc = fs->pc;
  }
}

static int searchupvalue(FuncState *fs, TString *name) {
  int i;
  Upvaldesc *up = fs->f->upvalues;
  for (i = 0; i < fs->nups; i++) {
    if (eqstr_(up[i].name, name)) return i;
  }
  return -1;
}

static Upvaldesc *allocupvalue(FuncState *fs) {
  Proto *f = fs->f;
  int oldsize = f->sizeupvalues;
  checklimit(fs, fs->nups + 1, MAXUPVAL, "upvalues");
  mem_growvec(fs->ls->L, f->upvalues, fs->nups, f->sizeupvalues, Upvaldesc, MAXUPVAL, "upvalues");
  while (oldsize < f->sizeupvalues)
    f->upvalues[oldsize++].name = NULL;
  return &f->upvalues[fs->nups++];
}

static int newupvalue(FuncState *fs, TString *name, expdesc *v) {
  Upvaldesc *up = allocupvalue(fs);
  FuncState *prev = fs->prev;
  if (v->k == VLOCAL) {
    up->instack = 1;
    up->idx = v->u.var.ridx;
    up->kind = getlocalvardesc(prev, v->u.var.vidx)->vd.kind;
  } else {
    up->instack = 0;
    up->idx = (uint8_t)v->u.info;
    up->kind = prev->f->upvalues[v->u.info].kind;
  }
  up->name = name;
  return fs->nups - 1;
}

/* search for a variable (local or declared global) in the current function;
   returns the kind found or -1 */
static int searchvar(FuncState *fs, TString *n, expdesc *var) {
  int i;
  for (i = cast_int(fs->nactvar) - 1; i >= 0; i--) {
    Vardesc *vd = getlocalvardesc(fs, i);
    if (vd->vd.kind >= GDKREG) {
      if (vd->vd.kind == GDKALL) continue;
      if (eqstr_(n, vd->vd.name)) {
        /* declared global */
        init_exp(var, VVOID, 0);
        var->ro = (vd->vd.kind == GDKCONST);
        var->gname = n;
        return vd->vd.kind;
      }
      continue;
    }
    if (eqstr_(n, vd->vd.name)) {
      if (vd->vd.kind == RDKCTC)
        init_exp(var, VCONST, fs->firstlocal + i);
      else
        init_var(fs, var, i);
      return var->k;
    }
  }
  return -1;
}

static void markupval(FuncState *fs, int level) {
  BlockCnt *bl = fs->bl;
  while (bl->nactvar > level)
    bl = bl->previous;
  bl->upval = 1;
  fs->needclose = 1;
}

static void marktobeclosed(FuncState *fs) {
  BlockCnt *bl = fs->bl;
  bl->upval = 1;
  bl->insidetbc = 1;
  fs->needclose = 1;
}

/* returns: VLOCAL/VUPVAL/VCONST set in var, or VVOID for global (var->ro set for const globals) */
static void singlevaraux(FuncState *fs, TString *n, expdesc *var, int base) {
  if (fs == NULL)
    init_exp(var, VVOID, 0);
  else {
    int v = searchvar(fs, n, var);
    if (v >= GDKREG) {
      /* declared global: treat as free name */
      var->k = VVOID;
      return;
    } else if (v >= 0) {
      if (v == VLOCAL && !base)
        markupval(fs, var->u.var.vidx);
    } else {
      int idx = searchupvalue(fs, n);
      if (idx < 0) {
        singlevaraux(fs->prev, n, var, 0);
        if (var->k == VLOCAL || var->k == VUPVAL)
          idx = newupvalue(fs, n, var);
        else
          return;  /* global or constant */
      }
      init_exp(var, VUPVAL, idx);
    }
  }
}

/* is there any active global declaration in scope? returns 0: none, 1: strict, 2: has '*' */
static int globaldeclmode(LexState *ls) {
  Dyndata *dyd = ls->dyd;
  int i;
  int mode = 0;
  for (i = dyd->actvar.n - 1; i >= 0; i--) {
    int kind = dyd->actvar.arr[i].vd.kind;
    if (kind == GDKALL) return 2;
    if (kind >= GDKREG) mode = 1;
  }
  return mode;
}

static int isdeclaredglobal(LexState *ls, TString *n, int *ro) {
  Dyndata *dyd = ls->dyd;
  int i;
  for (i = dyd->actvar.n - 1; i >= 0; i--) {
    Vardesc *vd = &dyd->actvar.arr[i];
    if (vd->vd.kind >= GDKREG && vd->vd.kind != GDKALL && eqstr_(vd->vd.name, n)) {
      *ro = (vd->vd.kind == GDKCONST);
      return 1;
    }
  }
  return 0;
}

static void singlevar(LexState *ls, expdesc *var) {
  TString *varname = str_checkname(ls);
  FuncState *fs = ls->fs;
  singlevaraux(fs, varname, var, 1);
  if (var->k == VVOID) {
    expdesc key;
    int ro = 0;
    int declared = isdeclaredglobal(ls, varname, &ro);
    if (!declared) {
      int mode = globaldeclmode(ls);
      if (mode == 1) {
        cg_semerror(ls, obj_pushfstring(ls->L, "variable '%s' not declared", getstr(varname)));
      }
    }
    singlevaraux(fs, ls->envn, var, 1);
    cg_exp2anyregup(fs, var);
    codestring(&key, varname);
    cg_indexed(fs, var, &key);
    var->ro = (uint8_t)ro;
    var->gname = varname;
  }
}

static void adjust_assign(LexState *ls, int nvars, int nexps, expdesc *e) {
  FuncState *fs = ls->fs;
  int needed = nvars - nexps;
  if (hasmultret(e->k)) {
    int extra = needed + 1;
    if (extra < 0) extra = 0;
    cg_setreturns(fs, e, extra);
  } else {
    if (e->k != VVOID)
      cg_exp2nextreg(fs, e);
    if (needed > 0)
      cg_nil(fs, fs->freereg, needed);
  }
  if (needed > 0)
    cg_reserveregs(fs, needed);
  else
    fs->freereg += needed;
}

static void enterlevel(LexState *ls) {
  State *L = ls->L;
  L->nCcalls++;
  if (L->nCcalls >= MAX_CCALLS) {
    if (L->nCcalls == MAX_CCALLS)
      err_runerror(L, "C stack overflow");
    else if (L->nCcalls >= (MAX_CCALLS / 10 * 11))
      do_throw(L, ST_ERRERR);
  }
}

#define leavelevel(ls) ((ls)->L->nCcalls--)

/* ---- goto / labels ---- */

static void jumpscopeerror(LexState *ls, Labeldesc *gt) {
  const char *varname = getstr(getlocalvardesc(ls->fs, gt->nactvar)->vd.name);
  const char *msg = "<goto %s> at line %d jumps into the scope of '%s'";
  msg = obj_pushfstring(ls->L, msg, getstr(gt->name), gt->line, varname);
  cg_semerror(ls, msg);
}

static void solvegoto(LexState *ls, int g, Labeldesc *label) {
  int i;
  Labellist *gl = &ls->dyd->gt;
  Labeldesc *gt = &gl->arr[g];
  if (unlikely(gt->nactvar < label->nactvar))
    jumpscopeerror(ls, gt);
  cg_patchlist(ls->fs, gt->pc, label->pc);
  for (i = g; i < gl->n - 1; i++)
    gl->arr[i] = gl->arr[i + 1];
  gl->n--;
}

static Labeldesc *findlabel(LexState *ls, TString *name) {
  int i;
  Dyndata *dyd = ls->dyd;
  for (i = ls->fs->firstlabel; i < dyd->label.n; i++) {
    Labeldesc *lb = &dyd->label.arr[i];
    if (eqstr_(lb->name, name))
      return lb;
  }
  return NULL;
}

static int newlabelentry(LexState *ls, Labellist *l, TString *name, int line, int pc) {
  int n = l->n;
  mem_growvec(ls->L, l->arr, n, l->size, Labeldesc, SHRT_MAX, "labels/gotos");
  l->arr[n].name = name;
  l->arr[n].line = line;
  l->arr[n].nactvar = ls->fs->nactvar;
  l->arr[n].close = 0;
  l->arr[n].pc = pc;
  l->n = n + 1;
  return n;
}

static int newgotoentry(LexState *ls, TString *name, int line, int pc) {
  return newlabelentry(ls, &ls->dyd->gt, name, line, pc);
}

static int solvegotos(LexState *ls, Labeldesc *lb) {
  Labellist *gl = &ls->dyd->gt;
  int i = ls->fs->bl->firstgoto;
  int needsclose = 0;
  while (i < gl->n) {
    if (eqstr_(gl->arr[i].name, lb->name)) {
      needsclose |= gl->arr[i].close;
      solvegoto(ls, i, lb);
    } else
      i++;
  }
  return needsclose;
}

static int createlabel(LexState *ls, TString *name, int line, int last) {
  FuncState *fs = ls->fs;
  Labellist *ll = &ls->dyd->label;
  int l = newlabelentry(ls, ll, name, line, cg_getlabel(fs));
  if (last) {
    ll->arr[l].nactvar = fs->bl->nactvar;
  }
  if (solvegotos(ls, &ll->arr[l])) {
    cg_codeABC(fs, OP_CLOSE, parser_nvarstack(fs), 0, 0);
    return 1;
  }
  return 0;
}

static void movegotosout(FuncState *fs, BlockCnt *bl) {
  int i;
  Labellist *gl = &fs->ls->dyd->gt;
  for (i = bl->firstgoto; i < gl->n; i++) {
    Labeldesc *gt = &gl->arr[i];
    if (reglevel(fs, gt->nactvar) > reglevel(fs, bl->nactvar))
      gt->close |= bl->upval;
    gt->nactvar = bl->nactvar;
  }
}

static void enterblock(FuncState *fs, BlockCnt *bl, uint8_t isloop) {
  bl->isloop = isloop;
  bl->nactvar = fs->nactvar;
  bl->firstlabel = fs->ls->dyd->label.n;
  bl->firstgoto = fs->ls->dyd->gt.n;
  bl->upval = 0;
  bl->insidetbc = (fs->bl != NULL && fs->bl->insidetbc);
  bl->previous = fs->bl;
  fs->bl = bl;
}

static void undefgoto(LexState *ls, Labeldesc *gt) {
  const char *msg;
  if (eqstr_(gt->name, str_new(ls->L, "break"))) {
    msg = "break outside a loop at line %d";
    msg = obj_pushfstring(ls->L, msg, gt->line);
  } else {
    msg = "no visible label '%s' for <goto> at line %d";
    msg = obj_pushfstring(ls->L, msg, getstr(gt->name), gt->line);
  }
  cg_semerror(ls, msg);
}

static void leaveblock(FuncState *fs) {
  BlockCnt *bl = fs->bl;
  LexState *ls = fs->ls;
  int hasclose = 0;
  int stklevel = reglevel(fs, bl->nactvar);
  removevars(fs, bl->nactvar);
  if (bl->isloop)
    hasclose = createlabel(ls, str_new(ls->L, "break"), 0, 0);
  if (!hasclose && bl->previous && bl->upval) {
    cg_codeABC(fs, OP_CLOSE, stklevel, 0, 0);
  }
  fs->freereg = (uint8_t)stklevel;
  ls->dyd->label.n = bl->firstlabel;
  fs->bl = bl->previous;
  if (bl->previous)
    movegotosout(fs, bl);
  else {
    if (bl->firstgoto < ls->dyd->gt.n)
      undefgoto(ls, &ls->dyd->gt.arr[bl->firstgoto]);
  }
}

/* ---- functions ---- */

static Proto *addprototype(LexState *ls) {
  Proto *clp;
  State *L = ls->L;
  FuncState *fs = ls->fs;
  Proto *f = fs->f;
  if (fs->np >= f->sizep) {
    int oldsize = f->sizep;
    mem_growvec(L, f->p, fs->np, f->sizep, Proto *, MAXARG_Bx, "functions");
    while (oldsize < f->sizep)
      f->p[oldsize++] = NULL;
  }
  f->p[fs->np++] = clp = proto_new(L);
  return clp;
}

static void codeclosure(LexState *ls, expdesc *v) {
  FuncState *fs = ls->fs->prev;
  init_exp(v, VRELOC, cg_codeABx(fs, OP_CLOSURE, 0, fs->np - 1));
  cg_exp2nextreg(fs, v);
}

static void open_func(LexState *ls, FuncState *fs, BlockCnt *bl) {
  Proto *f = fs->f;
  fs->prev = ls->fs;
  fs->ls = ls;
  ls->fs = fs;
  fs->pc = 0;
  fs->previousline = f->linedefined;
  fs->lasttarget = 0;
  fs->freereg = 0;
  fs->nk = 0;
  fs->np = 0;
  fs->nups = 0;
  fs->ndebugvars = 0;
  fs->nactvar = 0;
  fs->needclose = 0;
  fs->firstlocal = ls->dyd->actvar.n;
  fs->firstlabel = ls->dyd->label.n;
  fs->bl = NULL;
  f->source = ls->source;
  f->maxstacksize = 2;
  enterblock(fs, bl, 0);
}

static void close_func(LexState *ls) {
  State *L = ls->L;
  FuncState *fs = ls->fs;
  Proto *f = fs->f;
  cg_ret(fs, parser_nvarstack(fs), 0);
  leaveblock(fs);
  cg_finish(fs);
  f->code = (Instruction *)mem_shrinkvector(L, f->code, &f->sizecode, fs->pc, sizeof(Instruction));
  f->lineinfo = (int *)mem_shrinkvector(L, f->lineinfo, &f->sizelineinfo, fs->pc, sizeof(int));
  f->k = (Value *)mem_shrinkvector(L, f->k, &f->sizek, fs->nk, sizeof(Value));
  f->p = (Proto **)mem_shrinkvector(L, f->p, &f->sizep, fs->np, sizeof(Proto *));
  f->locvars = (LocVar *)mem_shrinkvector(L, f->locvars, &f->sizelocvars, fs->ndebugvars, sizeof(LocVar));
  f->upvalues = (Upvaldesc *)mem_shrinkvector(L, f->upvalues, &f->sizeupvalues, fs->nups, sizeof(Upvaldesc));
  ls->fs = fs->prev;
  gc_checkGC(L);
}

/* ---- grammar ---- */

static int block_follow(LexState *ls, int withuntil) {
  switch (ls->t.token) {
    case TK_ELSE: case TK_ELSEIF:
    case TK_END: case TK_EOS:
      return 1;
    case TK_UNTIL: return withuntil;
    default: return 0;
  }
}

static void statlist(LexState *ls) {
  while (!block_follow(ls, 1)) {
    if (ls->t.token == TK_RETURN) {
      statement(ls);
      return;
    }
    statement(ls);
  }
}

static void fieldsel(LexState *ls, expdesc *v) {
  FuncState *fs = ls->fs;
  expdesc key;
  cg_exp2anyregup(fs, v);
  lex_next(ls);
  codename(ls, &key);
  cg_indexed(fs, v, &key);
}

static void yindex(LexState *ls, expdesc *v) {
  lex_next(ls);
  expr(ls, v);
  cg_exp2val(ls->fs, v);
  checknext(ls, ']');
}

typedef struct ConsControl {
  expdesc v;
  expdesc *t;
  int nh;
  int na;
  int tostore;
} ConsControl;

static void recfield(LexState *ls, ConsControl *cc) {
  FuncState *fs = ls->fs;
  int reg = ls->fs->freereg;
  expdesc tab, key, val;
  if (ls->t.token == TK_NAME) {
    checklimit(fs, cc->nh, INT_MAX, "items in a constructor");
    codename(ls, &key);
  } else
    yindex(ls, &key);
  cc->nh++;
  checknext(ls, '=');
  tab = *cc->t;
  cg_indexed(fs, &tab, &key);
  expr(ls, &val);
  cg_storevar(fs, &tab, &val);
  fs->freereg = (uint8_t)reg;
}

static void closelistfield(FuncState *fs, ConsControl *cc) {
  if (cc->v.k == VVOID) return;
  cg_exp2nextreg(fs, &cc->v);
  cc->v.k = VVOID;
  if (cc->tostore == LFIELDS_PER_FLUSH) {
    cg_setlist(fs, cc->t->u.info, cc->na, cc->tostore);
    cc->na += cc->tostore;
    cc->tostore = 0;
  }
}

static void lastlistfield(FuncState *fs, ConsControl *cc) {
  if (cc->tostore == 0) return;
  if (hasmultret(cc->v.k)) {
    cg_setmultret(fs, &cc->v);
    cg_setlist(fs, cc->t->u.info, cc->na, MULTRET);
    cc->na--;
  } else {
    if (cc->v.k != VVOID)
      cg_exp2nextreg(fs, &cc->v);
    cg_setlist(fs, cc->t->u.info, cc->na, cc->tostore);
  }
  cc->na += cc->tostore;
}

static void listfield(LexState *ls, ConsControl *cc) {
  expr(ls, &cc->v);
  cc->tostore++;
}

static void field(LexState *ls, ConsControl *cc) {
  switch (ls->t.token) {
    case TK_NAME: {
      if (lex_lookahead(ls) != '=')
        listfield(ls, cc);
      else
        recfield(ls, cc);
      break;
    }
    case '[': {
      recfield(ls, cc);
      break;
    }
    default: {
      listfield(ls, cc);
      break;
    }
  }
}

static void constructor(LexState *ls, expdesc *t) {
  FuncState *fs = ls->fs;
  int line = ls->linenumber;
  int pc = cg_codeABC(fs, OP_NEWTABLE, 0, 0, 0);
  ConsControl cc;
  cg_code(fs, 0);  /* space for extra arg. */
  cc.na = cc.nh = cc.tostore = 0;
  cc.t = t;
  init_exp(t, VNONRELOC, fs->freereg);
  cg_reserveregs(fs, 1);
  init_exp(&cc.v, VVOID, 0);
  checknext(ls, '{');
  do {
    if (ls->t.token == '}') break;
    closelistfield(fs, &cc);
    field(ls, &cc);
  } while (testnext(ls, ',') || testnext(ls, ';'));
  check_match(ls, '}', '{', line);
  lastlistfield(fs, &cc);
  cg_settablesize(fs, pc, t->u.info, cc.na, cc.nh);
}

static void setvararg(FuncState *fs, int nparams) {
  fs->f->is_vararg = 1;
  cg_codeABC(fs, OP_VARARGPREP, nparams, 0, 0);
}

static void parlist(LexState *ls) {
  FuncState *fs = ls->fs;
  Proto *f = fs->f;
  int nparams = 0;
  int isvararg = 0;
  if (ls->t.token != ')') {
    do {
      switch (ls->t.token) {
        case TK_NAME: {
          new_localvar(ls, str_checkname(ls));
          nparams++;
          break;
        }
        case TK_DOTS: {
          lex_next(ls);
          isvararg = 1;
          break;
        }
        default: lex_syntaxerror(ls, "<name> or '...' expected");
      }
    } while (!isvararg && testnext(ls, ','));
  }
  adjustlocalvars(ls, nparams);
  f->numparams = cast_byte(fs->nactvar);
  if (isvararg)
    setvararg(fs, f->numparams);
  cg_reserveregs(fs, fs->nactvar);
}

static void body(LexState *ls, expdesc *e, int ismethod, int line) {
  FuncState new_fs;
  BlockCnt bl;
  new_fs.f = addprototype(ls);
  new_fs.f->linedefined = line;
  open_func(ls, &new_fs, &bl);
  checknext(ls, '(');
  if (ismethod) {
    new_localvarliteral(ls, "self");
    adjustlocalvars(ls, 1);
  }
  parlist(ls);
  checknext(ls, ')');
  statlist(ls);
  new_fs.f->lastlinedefined = ls->linenumber;
  check_match(ls, TK_END, TK_FUNCTION, line);
  codeclosure(ls, e);
  close_func(ls);
}

static int explist(LexState *ls, expdesc *v) {
  int n = 1;
  expr(ls, v);
  while (testnext(ls, ',')) {
    cg_exp2nextreg(ls->fs, v);
    expr(ls, v);
    n++;
  }
  return n;
}

static void funcargs(LexState *ls, expdesc *f, int line) {
  FuncState *fs = ls->fs;
  expdesc args;
  int base, nparams;
  switch (ls->t.token) {
    case '(': {
      lex_next(ls);
      if (ls->t.token == ')')
        args.k = VVOID;
      else {
        explist(ls, &args);
        if (hasmultret(args.k))
          cg_setmultret(fs, &args);
      }
      check_match(ls, ')', '(', line);
      break;
    }
    case '{': {
      constructor(ls, &args);
      break;
    }
    case TK_STRING: {
      codestring(&args, ls->t.seminfo.ts);
      lex_next(ls);
      break;
    }
    default: {
      lex_syntaxerror(ls, "function arguments expected");
    }
  }
  base = f->u.info;
  if (hasmultret(args.k))
    nparams = MULTRET;
  else {
    if (args.k != VVOID)
      cg_exp2nextreg(fs, &args);
    nparams = fs->freereg - (base + 1);
  }
  init_exp(f, VCALL, cg_codeABC(fs, OP_CALL, base, nparams + 1, 2));
  cg_fixline(fs, line);
  fs->freereg = (uint8_t)(base + 1);
}

static void primaryexp(LexState *ls, expdesc *v) {
  switch (ls->t.token) {
    case '(': {
      int line = ls->linenumber;
      lex_next(ls);
      expr(ls, v);
      check_match(ls, ')', '(', line);
      cg_dischargevars(ls->fs, v);
      return;
    }
    case TK_NAME: {
      singlevar(ls, v);
      return;
    }
    default: {
      lex_syntaxerror(ls, "unexpected symbol");
    }
  }
}

static void suffixedexp(LexState *ls, expdesc *v) {
  FuncState *fs = ls->fs;
  int line = ls->linenumber;
  primaryexp(ls, v);
  for (;;) {
    switch (ls->t.token) {
      case '.': {
        fieldsel(ls, v);
        break;
      }
      case '[': {
        expdesc key;
        cg_exp2anyregup(fs, v);
        yindex(ls, &key);
        cg_indexed(fs, v, &key);
        break;
      }
      case ':': {
        expdesc key;
        lex_next(ls);
        codename(ls, &key);
        cg_self(fs, v, &key);
        funcargs(ls, v, line);
        break;
      }
      case '(': case TK_STRING: case '{': {
        cg_exp2nextreg(fs, v);
        funcargs(ls, v, line);
        break;
      }
      default: return;
    }
  }
}

static void simpleexp(LexState *ls, expdesc *v) {
  switch (ls->t.token) {
    case TK_FLT: {
      init_exp(v, VKFLT, 0);
      v->u.nval = ls->t.seminfo.r;
      break;
    }
    case TK_INT: {
      init_exp(v, VKINT, 0);
      v->u.ival = ls->t.seminfo.i;
      break;
    }
    case TK_STRING: {
      codestring(v, ls->t.seminfo.ts);
      break;
    }
    case TK_NIL: {
      init_exp(v, VNIL, 0);
      break;
    }
    case TK_TRUE: {
      init_exp(v, VTRUE, 0);
      break;
    }
    case TK_FALSE: {
      init_exp(v, VFALSE, 0);
      break;
    }
    case TK_DOTS: {
      FuncState *fs = ls->fs;
      check_condition(ls, fs->f->is_vararg, "cannot use '...' outside a vararg function");
      init_exp(v, VVARARG, cg_codeABC(fs, OP_VARARG, 0, 0, 1));
      break;
    }
    case '{': {
      constructor(ls, v);
      return;
    }
    case TK_FUNCTION: {
      lex_next(ls);
      body(ls, v, 0, ls->linenumber);
      return;
    }
    default: {
      suffixedexp(ls, v);
      return;
    }
  }
  lex_next(ls);
}

static UnOpr getunopr(int op) {
  switch (op) {
    case TK_NOT: return OPR_NOT_;
    case '-': return OPR_MINUS;
    case '~': return OPR_BNOT_;
    case '#': return OPR_LEN_;
    default: return OPR_NOUNOPR;
  }
}

static BinOpr getbinopr(int op) {
  switch (op) {
    case '+': return OPR_ADD_;
    case '-': return OPR_SUB_;
    case '*': return OPR_MUL_;
    case '%': return OPR_MOD_;
    case '^': return OPR_POW_;
    case '/': return OPR_DIV_;
    case TK_IDIV: return OPR_IDIV_;
    case '&': return OPR_BAND_;
    case '|': return OPR_BOR_;
    case '~': return OPR_BXOR_;
    case TK_SHL: return OPR_SHL_;
    case TK_SHR: return OPR_SHR_;
    case TK_CONCAT: return OPR_CONCAT_;
    case TK_NE: return OPR_NE_;
    case TK_EQ: return OPR_EQ_;
    case '<': return OPR_LT_;
    case TK_LE: return OPR_LE_;
    case '>': return OPR_GT_;
    case TK_GE: return OPR_GE_;
    case TK_AND: return OPR_AND_;
    case TK_OR: return OPR_OR_;
    default: return OPR_NOBINOPR;
  }
}

static const struct {
  uint8_t left;
  uint8_t right;
} priority[] = {
   {10, 10}, {10, 10},           /* '+' '-' */
   {11, 11}, {11, 11},           /* '*' '%' */
   {14, 13},                  /* '^' (right associative) */
   {11, 11}, {11, 11},           /* '/' '//' */
   {6, 6}, {4, 4}, {5, 5},   /* '&' '|' '~' */
   {7, 7}, {7, 7},           /* '<<' '>>' */
   {9, 8},                   /* '..' (right associative) */
   {3, 3}, {3, 3}, {3, 3},   /* ==, <, <= */
   {3, 3}, {3, 3}, {3, 3},   /* ~=, >, >= */
   {2, 2}, {1, 1}            /* and, or */
};

#define UNARY_PRIORITY 12

static BinOpr subexpr(LexState *ls, expdesc *v, int limit) {
  BinOpr op;
  UnOpr uop;
  enterlevel(ls);
  uop = getunopr(ls->t.token);
  if (uop != OPR_NOUNOPR) {
    int line = ls->linenumber;
    lex_next(ls);
    subexpr(ls, v, UNARY_PRIORITY);
    cg_prefix(ls->fs, uop, v, line);
  } else simpleexp(ls, v);
  op = getbinopr(ls->t.token);
  while (op != OPR_NOBINOPR && priority[op].left > limit) {
    expdesc v2;
    BinOpr nextop;
    int line = ls->linenumber;
    lex_next(ls);
    cg_infix(ls->fs, op, v);
    nextop = subexpr(ls, &v2, priority[op].right);
    cg_posfix(ls->fs, op, v, &v2, line);
    op = nextop;
  }
  leavelevel(ls);
  return op;
}

static void expr(LexState *ls, expdesc *v) {
  subexpr(ls, v, 0);
}

/* ---- statements ---- */

static void block(LexState *ls) {
  FuncState *fs = ls->fs;
  BlockCnt bl;
  enterblock(fs, &bl, 0);
  statlist(ls);
  leaveblock(fs);
}

struct LHS_assign {
  struct LHS_assign *prev;
  expdesc v;
};

static void check_conflict(LexState *ls, struct LHS_assign *lh, expdesc *v) {
  FuncState *fs = ls->fs;
  int extra = fs->freereg;
  int conflict = 0;
  for (; lh; lh = lh->prev) {
    if (vkisindexed(lh->v.k)) {
      if (lh->v.k == VINDEXUP) {
        if (v->k == VUPVAL && lh->v.u.ind.t == v->u.info) {
          conflict = 1;
          lh->v.k = VINDEXSTR;
          lh->v.u.ind.t = (uint8_t)extra;
        }
      } else {
        if (v->k == VLOCAL && lh->v.u.ind.t == v->u.var.ridx) {
          conflict = 1;
          lh->v.u.ind.t = (uint8_t)extra;
        }
        if (lh->v.k == VINDEXED && v->k == VLOCAL &&
            lh->v.u.ind.idx == v->u.var.ridx) {
          conflict = 1;
          lh->v.u.ind.idx = (short)extra;
        }
      }
    }
  }
  if (conflict) {
    if (v->k == VLOCAL)
      cg_codeABC(fs, OP_MOVE, extra, v->u.var.ridx, 0);
    else
      cg_codeABC(fs, OP_GETUPVAL, extra, v->u.info, 0);
    cg_reserveregs(fs, 1);
  }
}

static void restassign(LexState *ls, struct LHS_assign *lh, int nvars) {
  expdesc e;
  check_condition(ls, vkisvar(lh->v.k), "syntax error");
  check_readonly(ls, &lh->v);
  if (testnext(ls, ',')) {
    struct LHS_assign nv;
    nv.prev = lh;
    suffixedexp(ls, &nv.v);
    if (!vkisindexed(nv.v.k))
      check_conflict(ls, lh, &nv.v);
    enterlevel(ls);
    restassign(ls, &nv, nvars + 1);
    leavelevel(ls);
  } else {
    int nexps;
    checknext(ls, '=');
    nexps = explist(ls, &e);
    if (nexps != nvars)
      adjust_assign(ls, nvars, nexps, &e);
    else {
      cg_setoneret(ls->fs, &e);
      cg_storevar(ls->fs, &lh->v, &e);
      return;
    }
  }
  init_exp(&e, VNONRELOC, ls->fs->freereg - 1);
  cg_storevar(ls->fs, &lh->v, &e);
}

static int cond(LexState *ls) {
  expdesc v;
  expr(ls, &v);
  if (v.k == VNIL) v.k = VFALSE;
  cg_goiftrue(ls->fs, &v);
  return v.f;
}

static void gotostat(LexState *ls) {
  FuncState *fs = ls->fs;
  int line = ls->linenumber;
  TString *name = str_checkname(ls);
  Labeldesc *lb = findlabel(ls, name);
  if (lb == NULL)
    newgotoentry(ls, name, line, cg_jump(fs));
  else {
    int lblevel = reglevel(fs, lb->nactvar);
    if (parser_nvarstack(fs) > lblevel)
      cg_codeABC(fs, OP_CLOSE, lblevel, 0, 0);
    cg_patchlist(fs, cg_jump(fs), lb->pc);
  }
}

static void breakstat(LexState *ls) {
  int line = ls->linenumber;
  BlockCnt *bl = ls->fs->bl;
  while (bl != NULL && !bl->isloop) bl = bl->previous;
  if (bl == NULL)
    lex_syntaxerror(ls, "break outside loop");
  lex_next(ls);
  newgotoentry(ls, str_new(ls->L, "break"), line, cg_jump(ls->fs));
}

static void checkrepeated(LexState *ls, TString *name) {
  Labeldesc *lb = findlabel(ls, name);
  if (unlikely(lb != NULL)) {
    const char *msg = "label '%s' already defined on line %d";
    msg = obj_pushfstring(ls->L, msg, getstr(name), lb->line);
    cg_semerror(ls, msg);
  }
}

static void labelstat(LexState *ls, TString *name, int line) {
  checknext(ls, TK_DBCOLON);
  while (ls->t.token == ';' || ls->t.token == TK_DBCOLON)
    statement(ls);
  checkrepeated(ls, name);
  createlabel(ls, name, line, block_follow(ls, 0));
}

static void whilestat(LexState *ls, int line) {
  FuncState *fs = ls->fs;
  int whileinit;
  int condexit;
  BlockCnt bl;
  lex_next(ls);
  whileinit = cg_getlabel(fs);
  condexit = cond(ls);
  enterblock(fs, &bl, 1);
  checknext(ls, TK_DO);
  block(ls);
  cg_jumpto(fs, whileinit);
  check_match(ls, TK_END, TK_WHILE, line);
  leaveblock(fs);
  cg_patchtohere(fs, condexit);
}

static void repeatstat(LexState *ls, int line) {
  int condexit;
  FuncState *fs = ls->fs;
  int repeat_init = cg_getlabel(fs);
  BlockCnt bl1, bl2;
  enterblock(fs, &bl1, 1);
  enterblock(fs, &bl2, 0);
  lex_next(ls);
  statlist(ls);
  check_match(ls, TK_UNTIL, TK_REPEAT, line);
  condexit = cond(ls);
  leaveblock(fs);
  if (bl2.upval) {
    int exit = cg_jump(fs);
    cg_patchtohere(fs, condexit);
    cg_codeABC(fs, OP_CLOSE, reglevel(fs, bl2.nactvar), 0, 0);
    condexit = cg_jump(fs);
    cg_patchtohere(fs, exit);
  }
  cg_patchlist(fs, condexit, repeat_init);
  leaveblock(fs);
}

static void exp1(LexState *ls) {
  expdesc e;
  expr(ls, &e);
  cg_exp2nextreg(ls->fs, &e);
}

static void fixforjump(FuncState *fs, int pc, int dest, int back) {
  Instruction *jmp = &fs->f->code[pc];
  int offset = dest - (pc + 1);
  if (back)
    offset = -offset;
  if (unlikely(offset > MAXARG_Bx))
    lex_syntaxerror(fs->ls, "control structure too long");
  SETARG_Bx(*jmp, offset);
}

static void forbody(LexState *ls, int base, int line, int nvars, int isgen) {
  static const OpCode forprep[2] = {OP_FORPREP, OP_TFORPREP};
  static const OpCode forloop[2] = {OP_FORLOOP, OP_TFORLOOP};
  BlockCnt bl;
  FuncState *fs = ls->fs;
  int prep, endfor;
  checknext(ls, TK_DO);
  prep = cg_codeABx(fs, forprep[isgen], base, 0);
  enterblock(fs, &bl, 0);
  adjustlocalvars(ls, nvars);
  cg_reserveregs(fs, nvars);
  block(ls);
  leaveblock(fs);
  fixforjump(fs, prep, cg_getlabel(fs), 0);
  if (isgen) {
    cg_codeABC(fs, OP_TFORCALL, base, 0, nvars);
    cg_fixline(fs, line);
  }
  endfor = cg_codeABx(fs, forloop[isgen], base, 0);
  fixforjump(fs, endfor, prep + 1, 1);
  cg_fixline(fs, line);
}

static void fornum(LexState *ls, TString *varname, int line) {
  FuncState *fs = ls->fs;
  int base = fs->freereg;
  new_localvarliteral(ls, "(for state)");
  new_localvarliteral(ls, "(for state)");
  new_localvarliteral(ls, "(for state)");
  new_localvar(ls, varname);
  getlocalvardesc(fs, fs->nactvar + 3)->vd.kind = RDKCONST;
  checknext(ls, '=');
  exp1(ls);
  checknext(ls, ',');
  exp1(ls);
  if (testnext(ls, ','))
    exp1(ls);
  else {
    cg_int(fs, fs->freereg, 1);
    cg_reserveregs(fs, 1);
  }
  adjustlocalvars(ls, 3);
  forbody(ls, base, line, 1, 0);
}

static void forlist(LexState *ls, TString *indexname) {
  FuncState *fs = ls->fs;
  expdesc e;
  int nvars = 5;
  int line;
  int base = fs->freereg;
  new_localvarliteral(ls, "(for state)");
  new_localvarliteral(ls, "(for state)");
  new_localvarliteral(ls, "(for state)");
  new_localvarliteral(ls, "(for state)");
  new_localvar(ls, indexname);
  getlocalvardesc(fs, fs->nactvar + 4)->vd.kind = RDKCONST;
  while (testnext(ls, ',')) {
    new_localvar(ls, str_checkname(ls));
    nvars++;
  }
  checknext(ls, TK_IN);
  line = ls->linenumber;
  adjust_assign(ls, 4, explist(ls, &e), &e);
  adjustlocalvars(ls, 4);
  marktobeclosed(fs);
  cg_checkstack(fs, 3);
  forbody(ls, base, line, nvars - 4, 1);
}

static void forstat(LexState *ls, int line) {
  FuncState *fs = ls->fs;
  TString *varname;
  BlockCnt bl;
  enterblock(fs, &bl, 1);
  lex_next(ls);
  varname = str_checkname(ls);
  switch (ls->t.token) {
    case '=': fornum(ls, varname, line); break;
    case ',': case TK_IN: forlist(ls, varname); break;
    default: lex_syntaxerror(ls, "'=' or 'in' expected");
  }
  check_match(ls, TK_END, TK_FOR, line);
  leaveblock(fs);
}

static void test_then_block(LexState *ls, int *escapelist) {
  BlockCnt bl;
  FuncState *fs = ls->fs;
  expdesc v;
  int jf;
  lex_next(ls);
  expr(ls, &v);
  checknext(ls, TK_THEN);
  if (ls->t.token == TK_BREAK) {
    int line = ls->linenumber;
    cg_goiffalse(ls->fs, &v);
    lex_next(ls);
    enterblock(fs, &bl, 0);
    newgotoentry(ls, str_new(ls->L, "break"), line, v.t);
    while (testnext(ls, ';')) {}
    if (block_follow(ls, 0)) {
      leaveblock(fs);
      return;
    } else
      jf = cg_jump(fs);
  } else {
    cg_goiftrue(ls->fs, &v);
    enterblock(fs, &bl, 0);
    jf = v.f;
  }
  statlist(ls);
  leaveblock(fs);
  if (ls->t.token == TK_ELSE || ls->t.token == TK_ELSEIF)
    cg_concat(fs, escapelist, cg_jump(fs));
  cg_patchtohere(fs, jf);
}

static void ifstat(LexState *ls, int line) {
  FuncState *fs = ls->fs;
  int escapelist = NO_JUMP;
  test_then_block(ls, &escapelist);
  while (ls->t.token == TK_ELSEIF)
    test_then_block(ls, &escapelist);
  if (testnext(ls, TK_ELSE))
    block(ls);
  check_match(ls, TK_END, TK_IF, line);
  cg_patchtohere(fs, escapelist);
}

static void localfunc(LexState *ls) {
  expdesc b;
  FuncState *fs = ls->fs;
  int fvar = fs->nactvar;
  new_localvar(ls, str_checkname(ls));
  adjustlocalvars(ls, 1);
  body(ls, &b, 0, ls->linenumber);
  localdebuginfo(fs, fvar)->startpc = fs->pc;
}

static int getlocalattribute(LexState *ls) {
  if (testnext(ls, '<')) {
    TString *ts = str_checkname(ls);
    const char *attr = getstr(ts);
    checknext(ls, '>');
    if (strcmp(attr, "const") == 0)
      return RDKCONST;
    else if (strcmp(attr, "close") == 0)
      return RDKTOCLOSE;
    else
      cg_semerror(ls, obj_pushfstring(ls->L, "unknown attribute '%s'", attr));
  }
  return VDKREG;
}

static void checktoclose(FuncState *fs, int level) {
  if (level != -1) {
    marktobeclosed(fs);
    cg_codeABC(fs, OP_TBC, reglevel(fs, level), 0, 0);
  }
}

static void localstat(LexState *ls) {
  FuncState *fs = ls->fs;
  int toclose = -1;
  Vardesc *var;
  int vidx, kind;
  int nvars = 0;
  int nexps;
  expdesc e;
  do {
    vidx = new_localvar(ls, str_checkname(ls));
    kind = getlocalattribute(ls);
    getlocalvardesc(fs, vidx)->vd.kind = (uint8_t)kind;
    if (kind == RDKTOCLOSE) {
      if (toclose != -1)
        cg_semerror(ls, "multiple to-be-closed variables in local list");
      toclose = fs->nactvar + nvars;
    }
    nvars++;
  } while (testnext(ls, ','));
  if (testnext(ls, '='))
    nexps = explist(ls, &e);
  else {
    e.k = VVOID;
    nexps = 0;
  }
  var = getlocalvardesc(fs, vidx);
  if (nvars == nexps &&
      var->vd.kind == RDKCONST &&
      cg_exp2const(fs, &e, &var->k)) {
    var->vd.kind = RDKCTC;
    adjustlocalvars(ls, nvars - 1);
    fs->nactvar++;
  } else {
    adjust_assign(ls, nvars, nexps, &e);
    adjustlocalvars(ls, nvars);
  }
  checktoclose(fs, toclose);
}

/* ---- 5.5 'global' declarations ---- */

static int newglobalvar(LexState *ls, TString *name, int kind) {
  State *L = ls->L;
  FuncState *fs = ls->fs;
  Dyndata *dyd = ls->dyd;
  Vardesc *var;
  checklimit(fs, dyd->actvar.n + 1 - fs->firstlocal, MAXVARS, "local variables");
  mem_growvec(L, dyd->actvar.arr, dyd->actvar.n + 1, dyd->actvar.size, Vardesc, USHRT_MAX, "local variables");
  var = &dyd->actvar.arr[dyd->actvar.n++];
  var->vd.kind = (uint8_t)kind;
  var->vd.name = name;
  var->vd.ridx = 0;
  var->vd.pidx = -1;
  fs->nactvar++;
  return dyd->actvar.n - 1 - fs->firstlocal;
}

static int getglobalattribute(LexState *ls) {
  if (testnext(ls, '<')) {
    TString *ts = str_checkname(ls);
    const char *attr = getstr(ts);
    checknext(ls, '>');
    if (strcmp(attr, "const") == 0)
      return GDKCONST;
    else if (strcmp(attr, "close") == 0)
      cg_semerror(ls, "global variables cannot be to-be-closed");
    else
      cg_semerror(ls, obj_pushfstring(ls->L, "unknown attribute '%s'", attr));
  }
  return GDKREG;
}

/* build expression for global variable 'name' (_ENV.name) */
static void globalvarexp(LexState *ls, TString *name, expdesc *var) {
  FuncState *fs = ls->fs;
  expdesc key;
  singlevaraux(fs, ls->envn, var, 1);
  cg_exp2anyregup(fs, var);
  codestring(&key, name);
  cg_indexed(fs, var, &key);
  var->gname = name;
}

static void globalfunc(LexState *ls, int line) {
  expdesc v, b;
  FuncState *fs = ls->fs;
  TString *name = str_checkname(ls);
  newglobalvar(ls, name, GDKREG);
  globalvarexp(ls, name, &v);
  cg_codeglbcheck(fs, &v, cg_stringK(fs, name));
  body(ls, &b, 0, line);
  check_readonly(ls, &v);
  cg_storevar(fs, &v, &b);
  cg_fixline(fs, line);
}

static void globalstat(LexState *ls, int line) {
  FuncState *fs = ls->fs;
  int defkind = GDKREG;
  TString *names[MAXVARS];
  int kinds[MAXVARS];
  int nvars = 0;
  int nexps;
  expdesc e;
  int i;
  UNUSED(line);
  if (ls->t.token == TK_FUNCTION) {
    lex_next(ls);
    globalfunc(ls, line);
    return;
  }
  if (ls->t.token == '*') {
    lex_next(ls);
    newglobalvar(ls, str_new(ls->L, "*"), GDKALL);
    return;
  }
  if (ls->t.token == '<')
    defkind = getglobalattribute(ls);
  do {
    TString *name;
    int kind;
    check(ls, TK_NAME);
    name = str_checkname(ls);
    kind = defkind;
    if (ls->t.token == '<')
      kind = getglobalattribute(ls);
    if (nvars >= MAXVARS) errorlimit(fs, MAXVARS, "global variables");
    names[nvars] = name;
    kinds[nvars] = kind;
    nvars++;
  } while (testnext(ls, ','));
  /* declare variables */
  for (i = 0; i < nvars; i++)
    newglobalvar(ls, names[i], kinds[i]);
  if (testnext(ls, '=')) {
    int base = fs->freereg;
    nexps = explist(ls, &e);
    adjust_assign(ls, nvars, nexps, &e);
    /* now values are in registers base .. base+nvars-1 */
    for (i = 0; i < nvars; i++) {
      expdesc var, val;
      globalvarexp(ls, names[i], &var);
      cg_codeglbcheck(fs, &var, cg_stringK(fs, names[i]));
      init_exp(&val, VNONRELOC, base + i);
      globalvarexp(ls, names[i], &var);
      cg_storevar(fs, &var, &val);
    }
    fs->freereg = (uint8_t)base;
  }
}

static int funcname(LexState *ls, expdesc *v) {
  int ismethod = 0;
  singlevar(ls, v);
  while (ls->t.token == '.')
    fieldsel(ls, v);
  if (ls->t.token == ':') {
    ismethod = 1;
    fieldsel(ls, v);
  }
  return ismethod;
}

static void funcstat(LexState *ls, int line) {
  int ismethod;
  expdesc v, b;
  lex_next(ls);
  ismethod = funcname(ls, &v);
  body(ls, &b, ismethod, line);
  check_readonly(ls, &v);
  cg_storevar(ls->fs, &v, &b);
  cg_fixline(ls->fs, line);
}

static void exprstat(LexState *ls) {
  FuncState *fs = ls->fs;
  struct LHS_assign v;
  suffixedexp(ls, &v.v);
  if (ls->t.token == '=' || ls->t.token == ',') {
    v.prev = NULL;
    restassign(ls, &v, 1);
  } else {
    Instruction *inst;
    check_condition(ls, v.v.k == VCALL, "syntax error");
    inst = &getinstruction(fs, &v.v);
    SETARG_C(*inst, 1);
  }
}

static void retstat(LexState *ls) {
  FuncState *fs = ls->fs;
  expdesc e;
  int nret;
  int first = parser_nvarstack(fs);
  if (block_follow(ls, 1) || ls->t.token == ';')
    nret = 0;
  else {
    nret = explist(ls, &e);
    if (hasmultret(e.k)) {
      cg_setmultret(fs, &e);
      if (e.k == VCALL && nret == 1 && !fs->bl->insidetbc) {
        SET_OPCODE(getinstruction(fs, &e), OP_TAILCALL);
      }
      nret = MULTRET;
    } else {
      if (nret == 1)
        first = cg_exp2anyreg(fs, &e);
      else {
        cg_exp2nextreg(fs, &e);
      }
    }
  }
  cg_ret(fs, first, nret);
  testnext(ls, ';');
}

static int isglobaldecl(LexState *ls) {
  /* current token is NAME "global"; decide whether it starts a declaration */
  int la;
  if (strcmp(getstr(ls->t.seminfo.ts), "global") != 0) return 0;
  la = lex_lookahead(ls);
  return (la == TK_NAME || la == '*' || la == TK_FUNCTION || la == '<');
}

static void statement(LexState *ls) {
  int line = ls->linenumber;
  enterlevel(ls);
  switch (ls->t.token) {
    case ';': {
      lex_next(ls);
      break;
    }
    case TK_IF: {
      ifstat(ls, line);
      break;
    }
    case TK_WHILE: {
      whilestat(ls, line);
      break;
    }
    case TK_DO: {
      lex_next(ls);
      block(ls);
      check_match(ls, TK_END, TK_DO, line);
      break;
    }
    case TK_FOR: {
      forstat(ls, line);
      break;
    }
    case TK_REPEAT: {
      repeatstat(ls, line);
      break;
    }
    case TK_FUNCTION: {
      funcstat(ls, line);
      break;
    }
    case TK_LOCAL: {
      lex_next(ls);
      if (testnext(ls, TK_FUNCTION))
        localfunc(ls);
      else
        localstat(ls);
      break;
    }
    case TK_DBCOLON: {
      lex_next(ls);
      labelstat(ls, str_checkname(ls), line);
      break;
    }
    case TK_RETURN: {
      lex_next(ls);
      retstat(ls);
      break;
    }
    case TK_BREAK: {
      breakstat(ls);
      break;
    }
    case TK_GOTO: {
      lex_next(ls);
      gotostat(ls);
      break;
    }
    case TK_NAME: {
      if (isglobaldecl(ls)) {
        lex_next(ls);
        globalstat(ls, line);
        break;
      }
      exprstat(ls);
      break;
    }
    default: {
      exprstat(ls);
      break;
    }
  }
  ls->fs->freereg = (uint8_t)parser_nvarstack(ls->fs);
  leavelevel(ls);
}

static void mainfunc(LexState *ls, FuncState *fs) {
  BlockCnt bl;
  Upvaldesc *env;
  open_func(ls, fs, &bl);
  setvararg(fs, 0);
  env = allocupvalue(fs);
  env->instack = 1;
  env->idx = 0;
  env->kind = VDKREG;
  env->name = ls->envn;
  lex_next(ls);
  statlist(ls);
  check(ls, TK_EOS);
  close_func(ls);
}

LClosure *parse_chunk(State *L, Zio *z, const char *name, int firstchar) {
  LexState lexstate;
  FuncState funcstate;
  Dyndata dyd;
  Mbuffer buff;
  LClosure *cl = lclosure_new(L, 1);
  setclLvalue(L->top, cl);
  do_inctop(L);
  lexstate.h = tbl_new(L);
  sethvalue(L->top, lexstate.h);
  do_inctop(L);
  funcstate.f = cl->p = proto_new(L);
  funcstate.f->source = str_new(L, name);
  lexstate.buff = &buff;
  buff.buffer = NULL; buff.n = 0; buff.buffsize = 0;
  memset(&dyd, 0, sizeof(dyd));
  lexstate.dyd = &dyd;
  dyd.actvar.n = dyd.gt.n = dyd.label.n = 0;
  lex_setinput(L, &lexstate, z, funcstate.f->source, firstchar);
  {
    /* protect the dynamic data: run parser, free on exit via normal path */
    mainfunc(&lexstate, &funcstate);
  }
  mem_free(L, buff.buffer, buff.buffsize);
  mem_freearray(L, dyd.actvar.arr, dyd.actvar.size);
  mem_freearray(L, dyd.gt.arr, dyd.gt.size);
  mem_freearray(L, dyd.label.arr, dyd.label.size);
  L->top--;  /* remove scanner's table */
  return cl;
}
EOF
echo ok"}

actions.command:
cd /workspace && cat > src/parser.c <<'EOF'
/*
 * parser.c - recursive descent parser producing bytecode
 */
#include <limits.h>
#include <stdlib.h>
#include <string.h>
#include "core.h"
#include "lexer.h"
#include "parser.h"
#include "api.h"

#define hasmultret(k) ((k) == VCALL || (k) == VVARARG)
#define eqstr_(a,b) ((a) == (b))

typedef struct BlockCnt {
  struct BlockCnt *previous;
  int firstlabel;
  int firstgoto;
  uint8_t nactvar;
  uint8_t upval;
  uint8_t isloop;
  uint8_t insidetbc;
} BlockCnt;

static void statement(LexState *ls);
static void expr(LexState *ls, expdesc *v);

static void error_expected(LexState *ls, int token) {
  lex_syntaxerror(ls, obj_pushfstring(ls->L, "%s expected", lex_token2str(ls, token)));
}

static void errorlimit(FuncState *fs, int limit, const char *what) {
  State *L = fs->ls->L;
  const char *msg;
  int line = fs->f->linedefined;
  const char *where = (line == 0) ? "main function" : obj_pushfstring(L, "function at line %d", line);
  msg = obj_pushfstring(L, "too many %s (limit is %d) in %s", what, limit, where);
  lex_syntaxerror(fs->ls, msg);
}

static void checklimit(FuncState *fs, int v, int l, const char *what) {
  if (v > l) errorlimit(fs, l, what);
}

static int testnext(LexState *ls, int c) {
  if (ls->t.token == c) {
    lex_next(ls);
    return 1;
  } else return 0;
}

static void check(LexState *ls, int c) {
  if (ls->t.token != c)
    error_expected(ls, c);
}

static void checknext(LexState *ls, int c) {
  check(ls, c);
  lex_next(ls);
}

#define check_condition(ls,c,msg) { if (!(c)) lex_syntaxerror(ls, msg); }

static void check_match(LexState *ls, int what, int who, int where) {
  if (unlikely(!testnext(ls, what))) {
    if (where == ls->linenumber)
      error_expected(ls, what);
    else {
      lex_syntaxerror(ls, obj_pushfstring(ls->L,
        "%s expected (to close %s at line %d)",
        lex_token2str(ls, what), lex_token2str(ls, who), where));
    }
  }
}

static TString *str_checkname(LexState *ls) {
  TString *ts;
  check(ls, TK_NAME);
  ts = ls->t.seminfo.ts;
  lex_next(ls);
  return ts;
}

static void init_exp(expdesc *e, expkind k, int i) {
  e->f = e->t = NO_JUMP;
  e->k = k;
  e->u.info = i;
  e->ro = 0;
  e->gname = NULL;
}

static void codestring(expdesc *e, TString *s) {
  e->f = e->t = NO_JUMP;
  e->k = VKSTR;
  e->u.strval = s;
  e->ro = 0;
  e->gname = NULL;
}

static void codename(LexState *ls, expdesc *e) {
  codestring(e, str_checkname(ls));
}

static int registerlocalvar(LexState *ls, FuncState *fs, TString *varname) {
  Proto *f = fs->f;
  int oldsize = f->sizelocvars;
  mem_growvec(ls->L, f->locvars, fs->ndebugvars, f->sizelocvars, LocVar, SHRT_MAX, "local variables");
  while (oldsize < f->sizelocvars)
    f->locvars[oldsize++].varname = NULL;
  f->locvars[fs->ndebugvars].varname = varname;
  f->locvars[fs->ndebugvars].startpc = fs->pc;
  return fs->ndebugvars++;
}

static int new_localvar(LexState *ls, TString *name) {
  State *L = ls->L;
  FuncState *fs = ls->fs;
  Dyndata *dyd = ls->dyd;
  Vardesc *var;
  checklimit(fs, dyd->actvar.n + 1 - fs->firstlocal, MAXVARS, "local variables");
  mem_growvec(L, dyd->actvar.arr, dyd->actvar.n + 1, dyd->actvar.size, Vardesc, USHRT_MAX, "local variables");
  var = &dyd->actvar.arr[dyd->actvar.n++];
  var->vd.kind = VDKREG;
  var->vd.name = name;
  return dyd->actvar.n - 1 - fs->firstlocal;
}

#define new_localvarliteral(ls,v) new_localvar(ls, lex_newstring(ls, "" v, (sizeof(v)/sizeof(char)) - 1))

static Vardesc *getlocalvardesc(FuncState *fs, int vidx) {
  return &fs->ls->dyd->actvar.arr[fs->firstlocal + vidx];
}

static int varhasreg(Vardesc *vd) {
  return vd->vd.kind <= RDKTOCLOSE;  /* regular, const, tbc locals occupy registers */
}

/* register level: number of registers used by the first nvar active variables */
static int reglevel(FuncState *fs, int nvar) {
  while (nvar-- > 0) {
    Vardesc *vd = getlocalvardesc(fs, nvar);
    if (varhasreg(vd))
      return vd->vd.ridx + 1;
  }
  return 0;
}

int parser_nvarstack(FuncState *fs) {
  return reglevel(fs, fs->nactvar);
}

static LocVar *localdebuginfo(FuncState *fs, int vidx) {
  Vardesc *vd = getlocalvardesc(fs, vidx);
  if (!varhasreg(vd))
    return NULL;
  else {
    int idx = vd->vd.pidx;
    return &fs->f->locvars[idx];
  }
}

static void init_var(FuncState *fs, expdesc *e, int vidx) {
  e->f = e->t = NO_JUMP;
  e->k = VLOCAL;
  e->u.var.vidx = (unsigned short)vidx;
  e->u.var.ridx = getlocalvardesc(fs, vidx)->vd.ridx;
  e->ro = 0;
  e->gname = NULL;
}

static void check_readonly(LexState *ls, expdesc *e) {
  FuncState *fs = ls->fs;
  TString *varname = NULL;
  switch (e->k) {
    case VCONST: {
      varname = ls->dyd->actvar.arr[e->u.info].vd.name;
      break;
    }
    case VLOCAL: {
      Vardesc *vardesc = getlocalvardesc(fs, e->u.var.vidx);
      if (vardesc->vd.kind != VDKREG)
        varname = vardesc->vd.name;
      break;
    }
    case VUPVAL: {
      Upvaldesc *up = &fs->f->upvalues[e->u.info];
      if (up->kind != VDKREG)
        varname = up->name;
      break;
    }
    case VINDEXUP: case VINDEXSTR: case VINDEXED: case VINDEXI: {
      if (e->ro) varname = e->gname;
      break;
    }
    default:
      return;
  }
  if (varname) {
    const char *msg = obj_pushfstring(ls->L, "attempt to assign to const variable '%s'", getstr(varname));
    cg_semerror(ls, msg);
  }
}

static void adjustlocalvars(LexState *ls, int nvars) {
  FuncState *fs = ls->fs;
  int reglevel_ = parser_nvarstack(fs);
  int i;
  for (i = 0; i < nvars; i++) {
    int vidx = fs->nactvar++;
    Vardesc *var = getlocalvardesc(fs, vidx);
    var->vd.ridx = (uint8_t)reglevel_++;
    var->vd.pidx = (short)registerlocalvar(ls, fs, var->vd.name);
  }
}

static void removevars(FuncState *fs, int tolevel) {
  fs->ls->dyd->actvar.n -= (fs->nactvar - tolevel);
  while (fs->nactvar > tolevel) {
    LocVar *var = localdebuginfo(fs, --fs->nactvar);
    if (var)
      var->endpc = fs->pc;
  }
}

static int searchupvalue(FuncState *fs, TString *name) {
  int i;
  Upvaldesc *up = fs->f->upvalues;
  for (i = 0; i < fs->nups; i++) {
    if (eqstr_(up[i].name, name)) return i;
  }
  return -1;
}

static Upvaldesc *allocupvalue(FuncState *fs) {
  Proto *f = fs->f;
  int oldsize = f->sizeupvalues;
  checklimit(fs, fs->nups + 1, MAXUPVAL, "upvalues");
  mem_growvec(fs->ls->L, f->upvalues, fs->nups, f->sizeupvalues, Upvaldesc, MAXUPVAL, "upvalues");
  while (oldsize < f->sizeupvalues)
    f->upvalues[oldsize++].name = NULL;
  return &f->upvalues[fs->nups++];
}

static int newupvalue(FuncState *fs, TString *name, expdesc *v) {
  Upvaldesc *up = allocupvalue(fs);
  FuncState *prev = fs->prev;
  if (v->k == VLOCAL) {
    up->instack = 1;
    up->idx = v->u.var.ridx;
    up->kind = getlocalvardesc(prev, v->u.var.vidx)->vd.kind;
  } else {
    up->instack = 0;
    up->idx = (uint8_t)v->u.info;
    up->kind = prev->f->upvalues[v->u.info].kind;
  }
  up->name = name;
  return fs->nups - 1;
}

/* search for a variable (local or declared global) in the current function;
   returns the kind found or -1 */
static int searchvar(FuncState *fs, TString *n, expdesc *var) {
  int i;
  for (i = cast_int(fs->nactvar) - 1; i >= 0; i--) {
    Vardesc *vd = getlocalvardesc(fs, i);
    if (vd->vd.kind >= GDKREG) {
      if (vd->vd.kind == GDKALL) continue;
      if (eqstr_(n, vd->vd.name)) {
        /* declared global */
        init_exp(var, VVOID, 0);
        var->ro = (vd->vd.kind == GDKCONST);
        var->gname = n;
        return vd->vd.kind;
      }
      continue;
    }
    if (eqstr_(n, vd->vd.name)) {
      if (vd->vd.kind == RDKCTC)
        init_exp(var, VCONST, fs->firstlocal + i);
      else
        init_var(fs, var, i);
      return var->k;
    }
  }
  return -1;
}

static void markupval(FuncState *fs, int level) {
  BlockCnt *bl = fs->bl;
  while (bl->nactvar > level)
    bl = bl->previous;
  bl->upval = 1;
  fs->needclose = 1;
}

static void marktobeclosed(FuncState *fs) {
  BlockCnt *bl = fs->bl;
  bl->upval = 1;
  bl->insidetbc = 1;
  fs->needclose = 1;
}

/* returns: VLOCAL/VUPVAL/VCONST set in var, or VVOID for global (var->ro set for const globals) */
static void singlevaraux(FuncState *fs, TString *n, expdesc *var, int base) {
  if (fs == NULL)
    init_exp(var, VVOID, 0);
  else {
    int v = searchvar(fs, n, var);
    if (v >= GDKREG) {
      /* declared global: treat as free name */
      var->k = VVOID;
      return;
    } else if (v >= 0) {
      if (v == VLOCAL && !base)
        markupval(fs, var->u.var.vidx);
    } else {
      int idx = searchupvalue(fs, n);
      if (idx < 0) {
        singlevaraux(fs->prev, n, var, 0);
        if (var->k == VLOCAL || var->k == VUPVAL)
          idx = newupvalue(fs, n, var);
        else
          return;  /* global or constant */
      }
      init_exp(var, VUPVAL, idx);
    }
  }
}

/* is there any active global declaration in scope? returns 0: none, 1: strict, 2: has '*' */
static int globaldeclmode(LexState *ls) {
  Dyndata *dyd = ls->dyd;
  int i;
  int mode = 0;
  for (i = dyd->actvar.n - 1; i >= 0; i--) {
    int kind = dyd->actvar.arr[i].vd.kind;
    if (kind == GDKALL) return 2;
    if (kind >= GDKREG) mode = 1;
  }
  return mode;
}

static int isdeclaredglobal(LexState *ls, TString *n, int *ro) {
  Dyndata *dyd = ls->dyd;
  int i;
  for (i = dyd->actvar.n - 1; i >= 0; i--) {
    Vardesc *vd = &dyd->actvar.arr[i];
    if (vd->vd.kind >= GDKREG && vd->vd.kind != GDKALL && eqstr_(vd->vd.name, n)) {
      *ro = (vd->vd.kind == GDKCONST);
      return 1;
    }
  }
  return 0;
}

static void singlevar(LexState *ls, expdesc *var) {
  TString *varname = str_checkname(ls);
  FuncState *fs = ls->fs;
  singlevaraux(fs, varname, var, 1);
  if (var->k == VVOID) {
    expdesc key;
    int ro = 0;
    int declared = isdeclaredglobal(ls, varname, &ro);
    if (!declared) {
      int mode = globaldeclmode(ls);
      if (mode == 1) {
        cg_semerror(ls, obj_pushfstring(ls->L, "variable '%s' not declared", getstr(varname)));
      }
    }
    singlevaraux(fs, ls->envn, var, 1);
    cg_exp2anyregup(fs, var);
    codestring(&key, varname);
    cg_indexed(fs, var, &key);
    var->ro = (uint8_t)ro;
    var->gname = varname;
  }
}

static void adjust_assign(LexState *ls, int nvars, int nexps, expdesc *e) {
  FuncState *fs = ls->fs;
  int needed = nvars - nexps;
  if (hasmultret(e->k)) {
    int extra = needed + 1;
    if (extra < 0) extra = 0;
    cg_setreturns(fs, e, extra);
  } else {
    if (e->k != VVOID)
      cg_exp2nextreg(fs, e);
    if (needed > 0)
      cg_nil(fs, fs->freereg, needed);
  }
  if (needed > 0)
    cg_reserveregs(fs, needed);
  else
    fs->freereg += needed;
}

static void enterlevel(LexState *ls) {
  State *L = ls->L;
  L->nCcalls++;
  if (L->nCcalls >= MAX_CCALLS) {
    if (L->nCcalls == MAX_CCALLS)
      err_runerror(L, "C stack overflow");
    else if (L->nCcalls >= (MAX_CCALLS / 10 * 11))
      do_throw(L, ST_ERRERR);
  }
}

#define leavelevel(ls) ((ls)->L->nCcalls--)

/* ---- goto / labels ---- */

static void jumpscopeerror(LexState *ls, Labeldesc *gt) {
  const char *varname = getstr(getlocalvardesc(ls->fs, gt->nactvar)->vd.name);
  const char *msg = "<goto %s> at line %d jumps into the scope of '%s'";
  msg = obj_pushfstring(ls->L, msg, getstr(gt->name), gt->line, varname);
  cg_semerror(ls, msg);
}

static void solvegoto(LexState *ls, int g, Labeldesc *label) {
  int i;
  Labellist *gl = &ls->dyd->gt;
  Labeldesc *gt = &gl->arr[g];
  if (unlikely(gt->nactvar < label->nactvar))
    jumpscopeerror(ls, gt);
  cg_patchlist(ls->fs, gt->pc, label->pc);
  for (i = g; i < gl->n - 1; i++)
    gl->arr[i] = gl->arr[i + 1];
  gl->n--;
}

static Labeldesc *findlabel(LexState *ls, TString *name) {
  int i;
  Dyndata *dyd = ls->dyd;
  for (i = ls->fs->firstlabel; i < dyd->label.n; i++) {
    Labeldesc *lb = &dyd->label.arr[i];
    if (eqstr_(lb->name, name))
      return lb;
  }
  return NULL;
}

static int newlabelentry(LexState *ls, Labellist *l, TString *name, int line, int pc) {
  int n = l->n;
  mem_growvec(ls->L, l->arr, n, l->size, Labeldesc, SHRT_MAX, "labels/gotos");
  l->arr[n].name = name;
  l->arr[n].line = line;
  l->arr[n].nactvar = ls->fs->nactvar;
  l->arr[n].close = 0;
  l->arr[n].pc = pc;
  l->n = n + 1;
  return n;
}

static int newgotoentry(LexState *ls, TString *name, int line, int pc) {
  return newlabelentry(ls, &ls->dyd->gt, name, line, pc);
}

static int solvegotos(LexState *ls, Labeldesc *lb) {
  Labellist *gl = &ls->dyd->gt;
  int i = ls->fs->bl->firstgoto;
  int needsclose = 0;
  while (i < gl->n) {
    if (eqstr_(gl->arr[i].name, lb->name)) {
      needsclose |= gl->arr[i].close;
      solvegoto(ls, i, lb);
    } else
      i++;
  }
  return needsclose;
}

static int createlabel(LexState *ls, TString *name, int line, int last) {
  FuncState *fs = ls->fs;
  Labellist *ll = &ls->dyd->label;
  int l = newlabelentry(ls, ll, name, line, cg_getlabel(fs));
  if (last) {
    ll->arr[l].nactvar = fs->bl->nactvar;
  }
  if (solvegotos(ls, &ll->arr[l])) {
    cg_codeABC(fs, OP_CLOSE, parser_nvarstack(fs), 0, 0);
    return 1;
  }
  return 0;
}

static void movegotosout(FuncState *fs, BlockCnt *bl) {
  int i;
  Labellist *gl = &fs->ls->dyd->gt;
  for (i = bl->firstgoto; i < gl->n; i++) {
    Labeldesc *gt = &gl->arr[i];
    if (reglevel(fs, gt->nactvar) > reglevel(fs, bl->nactvar))
      gt->close |= bl->upval;
    gt->nactvar = bl->nactvar;
  }
}

static void enterblock(FuncState *fs, BlockCnt *bl, uint8_t isloop) {
  bl->isloop = isloop;
  bl->nactvar = fs->nactvar;
  bl->firstlabel = fs->ls->dyd->label.n;
  bl->firstgoto = fs->ls->dyd->gt.n;
  bl->upval = 0;
  bl->insidetbc = (fs->bl != NULL && fs->bl->insidetbc);
  bl->previous = fs->bl;
  fs->bl = bl;
}

static void undefgoto(LexState *ls, Labeldesc *gt) {
  const char *msg;
  if (eqstr_(gt->name, str_new(ls->L, "break"))) {
    msg = "break outside a loop at line %d";
    msg = obj_pushfstring(ls->L, msg, gt->line);
  } else {
    msg = "no visible label '%s' for <goto> at line %d";
    msg = obj_pushfstring(ls->L, msg, getstr(gt->name), gt->line);
  }
  cg_semerror(ls, msg);
}

static void leaveblock(FuncState *fs) {
  BlockCnt *bl = fs->bl;
  LexState *ls = fs->ls;
  int hasclose = 0;
  int stklevel = reglevel(fs, bl->nactvar);
  removevars(fs, bl->nactvar);
  if (bl->isloop)
    hasclose = createlabel(ls, str_new(ls->L, "break"), 0, 0);
  if (!hasclose && bl->previous && bl->upval) {
    cg_codeABC(fs, OP_CLOSE, stklevel, 0, 0);
  }
  fs->freereg = (uint8_t)stklevel;
  ls->dyd->label.n = bl->firstlabel;
  fs->bl = bl->previous;
  if (bl->previous)
    movegotosout(fs, bl);
  else {
    if (bl->firstgoto < ls->dyd->gt.n)
      undefgoto(ls, &ls->dyd->gt.arr[bl->firstgoto]);
  }
}

/* ---- functions ---- */

static Proto *addprototype(LexState *ls) {
  Proto *clp;
  State *L = ls->L;
  FuncState *fs = ls->fs;
  Proto *f = fs->f;
  if (fs->np >= f->sizep) {
    int oldsize = f->sizep;
    mem_growvec(L, f->p, fs->np, f->sizep, Proto *, MAXARG_Bx, "functions");
    while (oldsize < f->sizep)
      f->p[oldsize++] = NULL;
  }
  f->p[fs->np++] = clp = proto_new(L);
  return clp;
}

static void codeclosure(LexState *ls, expdesc *v) {
  FuncState *fs = ls->fs->prev;
  init_exp(v, VRELOC, cg_codeABx(fs, OP_CLOSURE, 0, fs->np - 1));
  cg_exp2nextreg(fs, v);
}

static void open_func(LexState *ls, FuncState *fs, BlockCnt *bl) {
  Proto *f = fs->f;
  fs->prev = ls->fs;
  fs->ls = ls;
  ls->fs = fs;
  fs->pc = 0;
  fs->previousline = f->linedefined;
  fs->lasttarget = 0;
  fs->freereg = 0;
  fs->nk = 0;
  fs->np = 0;
  fs->nups = 0;
  fs->ndebugvars = 0;
  fs->nactvar = 0;
  fs->needclose = 0;
  fs->firstlocal = ls->dyd->actvar.n;
  fs->firstlabel = ls->dyd->label.n;
  fs->bl = NULL;
  f->source = ls->source;
  f->maxstacksize = 2;
  enterblock(fs, bl, 0);
}

static void close_func(LexState *ls) {
  State *L = ls->L;
  FuncState *fs = ls->fs;
  Proto *f = fs->f;
  cg_ret(fs, parser_nvarstack(fs), 0);
  leaveblock(fs);
  cg_finish(fs);
  f->code = (Instruction *)mem_shrinkvector(L, f->code, &f->sizecode, fs->pc, sizeof(Instruction));
  f->lineinfo = (int *)mem_shrinkvector(L, f->lineinfo, &f->sizelineinfo, fs->pc, sizeof(int));
  f->k = (Value *)mem_shrinkvector(L, f->k, &f->sizek, fs->nk, sizeof(Value));
  f->p = (Proto **)mem_shrinkvector(L, f->p, &f->sizep, fs->np, sizeof(Proto *));
  f->locvars = (LocVar *)mem_shrinkvector(L, f->locvars, &f->sizelocvars, fs->ndebugvars, sizeof(LocVar));
  f->upvalues = (Upvaldesc *)mem_shrinkvector(L, f->upvalues, &f->sizeupvalues, fs->nups, sizeof(Upvaldesc));
  ls->fs = fs->prev;
  gc_checkGC(L);
}

/* ---- grammar ---- */

static int block_follow(LexState *ls, int withuntil) {
  switch (ls->t.token) {
    case TK_ELSE: case TK_ELSEIF:
    case TK_END: case TK_EOS:
      return 1;
    case TK_UNTIL: return withuntil;
    default: return 0;
  }
}

static void statlist(LexState *ls) {
  while (!block_follow(ls, 1)) {
    if (ls->t.token == TK_RETURN) {
      statement(ls);
      return;
    }
    statement(ls);
  }
}

static void fieldsel(LexState *ls, expdesc *v) {
  FuncState *fs = ls->fs;
  expdesc key;
  cg_exp2anyregup(fs, v);
  lex_next(ls);
  codename(ls, &key);
  cg_indexed(fs, v, &key);
}

static void yindex(LexState *ls, expdesc *v) {
  lex_next(ls);
  expr(ls, v);
  cg_exp2val(ls->fs, v);
  checknext(ls, ']');
}

typedef struct ConsControl {
  expdesc v;
  expdesc *t;
  int nh;
  int na;
  int tostore;
} ConsControl;

static void recfield(LexState *ls, ConsControl *cc) {
  FuncState *fs = ls->fs;
  int reg = ls->fs->freereg;
  expdesc tab, key, val;
  if (ls->t.token == TK_NAME) {
    checklimit(fs, cc->nh, INT_MAX, "items in a constructor");
    codename(ls, &key);
  } else
    yindex(ls, &key);
  cc->nh++;
  checknext(ls, '=');
  tab = *cc->t;
  cg_indexed(fs, &tab, &key);
  expr(ls, &val);
  cg_storevar(fs, &tab, &val);
  fs->freereg = (uint8_t)reg;
}

static void closelistfield(FuncState *fs, ConsControl *cc) {
  if (cc->v.k == VVOID) return;
  cg_exp2nextreg(fs, &cc->v);
  cc->v.k = VVOID;
  if (cc->tostore == LFIELDS_PER_FLUSH) {
    cg_setlist(fs, cc->t->u.info, cc->na, cc->tostore);
    cc->na += cc->tostore;
    cc->tostore = 0;
  }
}

static void lastlistfield(FuncState *fs, ConsControl *cc) {
  if (cc->tostore == 0) return;
  if (hasmultret(cc->v.k)) {
    cg_setmultret(fs, &cc->v);
    cg_setlist(fs, cc->t->u.info, cc->na, MULTRET);
    cc->na--;
  } else {
    if (cc->v.k != VVOID)
      cg_exp2nextreg(fs, &cc->v);
    cg_setlist(fs, cc->t->u.info, cc->na, cc->tostore);
  }
  cc->na += cc->tostore;
}

static void listfield(LexState *ls, ConsControl *cc) {
  expr(ls, &cc->v);
  cc->tostore++;
}

static void field(LexState *ls, ConsControl *cc) {
  switch (ls->t.token) {
    case TK_NAME: {
      if (lex_lookahead(ls) != '=')
        listfield(ls, cc);
      else
        recfield(ls, cc);
      break;
    }
    case '[': {
      recfield(ls, cc);
      break;
    }
    default: {
      listfield(ls, cc);
      break;
    }
  }
}

static void constructor(LexState *ls, expdesc *t) {
  FuncState *fs = ls->fs;
  int line = ls->linenumber;
  int pc = cg_codeABC(fs, OP_NEWTABLE, 0, 0, 0);
  ConsControl cc;
  cg_code(fs, 0);  /* space for extra arg. */
  cc.na = cc.nh = cc.tostore = 0;
  cc.t = t;
  init_exp(t, VNONRELOC, fs->freereg);
  cg_reserveregs(fs, 1);
  init_exp(&cc.v, VVOID, 0);
  checknext(ls, '{');
  do {
    if (ls->t.token == '}') break;
    closelistfield(fs, &cc);
    field(ls, &cc);
  } while (testnext(ls, ',') || testnext(ls, ';'));
  check_match(ls, '}', '{', line);
  lastlistfield(fs, &cc);
  cg_settablesize(fs, pc, t->u.info, cc.na, cc.nh);
}

static void setvararg(FuncState *fs, int nparams) {
  fs->f->is_vararg = 1;
  cg_codeABC(fs, OP_VARARGPREP, nparams, 0, 0);
}

static void parlist(LexState *ls) {
  FuncState *fs = ls->fs;
  Proto *f = fs->f;
  int nparams = 0;
  int isvararg = 0;
  if (ls->t.token != ')') {
    do {
      switch (ls->t.token) {
        case TK_NAME: {
          new_localvar(ls, str_checkname(ls));
          nparams++;
          break;
        }
        case TK_DOTS: {
          lex_next(ls);
          isvararg = 1;
          break;
        }
        default: lex_syntaxerror(ls, "<name> or '...' expected");
      }
    } while (!isvararg && testnext(ls, ','));
  }
  adjustlocalvars(ls, nparams);
  f->numparams = cast_byte(fs->nactvar);
  if (isvararg)
    setvararg(fs, f->numparams);
  cg_reserveregs(fs, fs->nactvar);
}

static void body(LexState *ls, expdesc *e, int ismethod, int line) {
  FuncState new_fs;
  BlockCnt bl;
  new_fs.f = addprototype(ls);
  new_fs.f->linedefined = line;
  open_func(ls, &new_fs, &bl);
  checknext(ls, '(');
  if (ismethod) {
    new_localvarliteral(ls, "self");
    adjustlocalvars(ls, 1);
  }
  parlist(ls);
  checknext(ls, ')');
  statlist(ls);
  new_fs.f->lastlinedefined = ls->linenumber;
  check_match(ls, TK_END, TK_FUNCTION, line);
  codeclosure(ls, e);
  close_func(ls);
}

static int explist(LexState *ls, expdesc *v) {
  int n = 1;
  expr(ls, v);
  while (testnext(ls, ',')) {
    cg_exp2nextreg(ls->fs, v);
    expr(ls, v);
    n++;
  }
  return n;
}

static void funcargs(LexState *ls, expdesc *f, int line) {
  FuncState *fs = ls->fs;
  expdesc args;
  int base, nparams;
  switch (ls->t.token) {
    case '(': {
      lex_next(ls);
      if (ls->t.token == ')')
        args.k = VVOID;
      else {
        explist(ls, &args);
        if (hasmultret(args.k))
          cg_setmultret(fs, &args);
      }
      check_match(ls, ')', '(', line);
      break;
    }
    case '{': {
      constructor(ls, &args);
      break;
    }
    case TK_STRING: {
      codestring(&args, ls->t.seminfo.ts);
      lex_next(ls);
      break;
    }
    default: {
      lex_syntaxerror(ls, "function arguments expected");
    }
  }
  base = f->u.info;
  if (hasmultret(args.k))
    nparams = MULTRET;
  else {
    if (args.k != VVOID)
      cg_exp2nextreg(fs, &args);
    nparams = fs->freereg - (base + 1);
  }
  init_exp(f, VCALL, cg_codeABC(fs, OP_CALL, base, nparams + 1, 2));
  cg_fixline(fs, line);
  fs->freereg = (uint8_t)(base + 1);
}

static void primaryexp(LexState *ls, expdesc *v) {
  switch (ls->t.token) {
    case '(': {
      int line = ls->linenumber;
      lex_next(ls);
      expr(ls, v);
      check_match(ls, ')', '(', line);
      cg_dischargevars(ls->fs, v);
      return;
    }
    case TK_NAME: {
      singlevar(ls, v);
      return;
    }
    default: {
      lex_syntaxerror(ls, "unexpected symbol");
    }
  }
}

static void suffixedexp(LexState *ls, expdesc *v) {
  FuncState *fs = ls->fs;
  int line = ls->linenumber;
  primaryexp(ls, v);
  for (;;) {
    switch (ls->t.token) {
      case '.': {
        fieldsel(ls, v);
        break;
      }
      case '[': {
        expdesc key;
        cg_exp2anyregup(fs, v);
        yindex(ls, &key);
        cg_indexed(fs, v, &key);
        break;
      }
      case ':': {
        expdesc key;
        lex_next(ls);
        codename(ls, &key);
        cg_self(fs, v, &key);
        funcargs(ls, v, line);
        break;
      }
      case '(': case TK_STRING: case '{': {
        cg_exp2nextreg(fs, v);
        funcargs(ls, v, line);
        break;
      }
      default: return;
    }
  }
}

static void simpleexp(LexState *ls, expdesc *v) {
  switch (ls->t.token) {
    case TK_FLT: {
      init_exp(v, VKFLT, 0);
      v->u.nval = ls->t.seminfo.r;
      break;
    }
    case TK_INT: {
      init_exp(v, VKINT, 0);
      v->u.ival = ls->t.seminfo.i;
      break;
    }
    case TK_STRING: {
      codestring(v, ls->t.seminfo.ts);
      break;
    }
    case TK_NIL: {
      init_exp(v, VNIL, 0);
      break;
    }
    case TK_TRUE: {
      init_exp(v, VTRUE, 0);
      break;
    }
    case TK_FALSE: {
      init_exp(v, VFALSE, 0);
      break;
    }
    case TK_DOTS: {
      FuncState *fs = ls->fs;
      check_condition(ls, fs->f->is_vararg, "cannot use '...' outside a vararg function");
      init_exp(v, VVARARG, cg_codeABC(fs, OP_VARARG, 0, 0, 1));
      break;
    }
    case '{': {
      constructor(ls, v);
      return;
    }
    case TK_FUNCTION: {
      lex_next(ls);
      body(ls, v, 0, ls->linenumber);
      return;
    }
    default: {
      suffixedexp(ls, v);
      return;
    }
  }
  lex_next(ls);
}

static UnOpr getunopr(int op) {
  switch (op) {
    case TK_NOT: return OPR_NOT_;
    case '-': return OPR_MINUS;
    case '~': return OPR_BNOT_;
    case '#': return OPR_LEN_;
    default: return OPR_NOUNOPR;
  }
}

static BinOpr getbinopr(int op) {
  switch (op) {
    case '+': return OPR_ADD_;
    case '-': return OPR_SUB_;
    case '*': return OPR_MUL_;
    case '%': return OPR_MOD_;
    case '^': return OPR_POW_;
    case '/': return OPR_DIV_;
    case TK_IDIV: return OPR_IDIV_;
    case '&': return OPR_BAND_;
    case '|': return OPR_BOR_;
    case '~': return OPR_BXOR_;
    case TK_SHL: return OPR_SHL_;
    case TK_SHR: return OPR_SHR_;
    case TK_CONCAT: return OPR_CONCAT_;
    case TK_NE: return OPR_NE_;
    case TK_EQ: return OPR_EQ_;
    case '<': return OPR_LT_;
    case TK_LE: return OPR_LE_;
    case '>': return OPR_GT_;
    case TK_GE: return OPR_GE_;
    case TK_AND: return OPR_AND_;
    case TK_OR: return OPR_OR_;
    default: return OPR_NOBINOPR;
  }
}

static const struct {
  uint8_t left;
  uint8_t right;
} priority[] = {
   {10, 10}, {10, 10},           /* '+' '-' */
   {11, 11}, {11, 11},           /* '*' '%' */
   {14, 13},                  /* '^' (right associative) */
   {11, 11}, {11, 11},           /* '/' '//' */
   {6, 6}, {4, 4}, {5, 5},   /* '&' '|' '~' */
   {7, 7}, {7, 7},           /* '<<' '>>' */
   {9, 8},                   /* '..' (right associative) */
   {3, 3}, {3, 3}, {3, 3},   /* ==, <, <= */
   {3, 3}, {3, 3}, {3, 3},   /* ~=, >, >= */
   {2, 2}, {1, 1}            /* and, or */
};

#define UNARY_PRIORITY 12

static BinOpr subexpr(LexState *ls, expdesc *v, int limit) {
  BinOpr op;
  UnOpr uop;
  enterlevel(ls);
  uop = getunopr(ls->t.token);
  if (uop != OPR_NOUNOPR) {
    int line = ls->linenumber;
    lex_next(ls);
    subexpr(ls, v, UNARY_PRIORITY);
    cg_prefix(ls->fs, uop, v, line);
  } else simpleexp(ls, v);
  op = getbinopr(ls->t.token);
  while (op != OPR_NOBINOPR && priority[op].left > limit) {
    expdesc v2;
    BinOpr nextop;
    int line = ls->linenumber;
    lex_next(ls);
    cg_infix(ls->fs, op, v);
    nextop = subexpr(ls, &v2, priority[op].right);
    cg_posfix(ls->fs, op, v, &v2, line);
    op = nextop;
  }
  leavelevel(ls);
  return op;
}

static void expr(LexState *ls, expdesc *v) {
  subexpr(ls, v, 0);
}

/* ---- statements ---- */

static void block(LexState *ls) {
  FuncState *fs = ls->fs;
  BlockCnt bl;
  enterblock(fs, &bl, 0);
  statlist(ls);
  leaveblock(fs);
}

struct LHS_assign {
  struct LHS_assign *prev;
  expdesc v;
};

static void check_conflict(LexState *ls, struct LHS_assign *lh, expdesc *v) {
  FuncState *fs = ls->fs;
  int extra = fs->freereg;
  int conflict = 0;
  for (; lh; lh = lh->prev) {
    if (vkisindexed(lh->v.k)) {
      if (lh->v.k == VINDEXUP) {
        if (v->k == VUPVAL && lh->v.u.ind.t == v->u.info) {
          conflict = 1;
          lh->v.k = VINDEXSTR;
          lh->v.u.ind.t = (uint8_t)extra;
        }
      } else {
        if (v->k == VLOCAL && lh->v.u.ind.t == v->u.var.ridx) {
          conflict = 1;
          lh->v.u.ind.t = (uint8_t)extra;
        }
        if (lh->v.k == VINDEXED && v->k == VLOCAL &&
            lh->v.u.ind.idx == v->u.var.ridx) {
          conflict = 1;
          lh->v.u.ind.idx = (short)extra;
        }
      }
    }
  }
  if (conflict) {
    if (v->k == VLOCAL)
      cg_codeABC(fs, OP_MOVE, extra, v->u.var.ridx, 0);
    else
      cg_codeABC(fs, OP_GETUPVAL, extra, v->u.info, 0);
    cg_reserveregs(fs, 1);
  }
}

static void restassign(LexState *ls, struct LHS_assign *lh, int nvars) {
  expdesc e;
  check_condition(ls, vkisvar(lh->v.k), "syntax error");
  check_readonly(ls, &lh->v);
  if (testnext(ls, ',')) {
    struct LHS_assign nv;
    nv.prev = lh;
    suffixedexp(ls, &nv.v);
    if (!vkisindexed(nv.v.k))
      check_conflict(ls, lh, &nv.v);
    enterlevel(ls);
    restassign(ls, &nv, nvars + 1);
    leavelevel(ls);
  } else {
    int nexps;
    checknext(ls, '=');
    nexps = explist(ls, &e);
    if (nexps != nvars)
      adjust_assign(ls, nvars, nexps, &e);
    else {
      cg_setoneret(ls->fs, &e);
      cg_storevar(ls->fs, &lh->v, &e);
      return;
    }
  }
  init_exp(&e, VNONRELOC, ls->fs->freereg - 1);
  cg_storevar(ls->fs, &lh->v, &e);
}

static int cond(LexState *ls) {
  expdesc v;
  expr(ls, &v);
  if (v.k == VNIL) v.k = VFALSE;
  cg_goiftrue(ls->fs, &v);
  return v.f;
}

static void gotostat(LexState *ls) {
  FuncState *fs = ls->fs;
  int line = ls->linenumber;
  TString *name = str_checkname(ls);
  Labeldesc *lb = findlabel(ls, name);
  if (lb == NULL)
    newgotoentry(ls, name, line, cg_jump(fs));
  else {
    int lblevel = reglevel(fs, lb->nactvar);
    if (parser_nvarstack(fs) > lblevel)
      cg_codeABC(fs, OP_CLOSE, lblevel, 0, 0);
    cg_patchlist(fs, cg_jump(fs), lb->pc);
  }
}

static void breakstat(LexState *ls) {
  int line = ls->linenumber;
  BlockCnt *bl = ls->fs->bl;
  while (bl != NULL && !bl->isloop) bl = bl->previous;
  if (bl == NULL)
    lex_syntaxerror(ls, "break outside loop");
  lex_next(ls);
  newgotoentry(ls, str_new(ls->L, "break"), line, cg_jump(ls->fs));
}

static void checkrepeated(LexState *ls, TString *name) {
  Labeldesc *lb = findlabel(ls, name);
  if (unlikely(lb != NULL)) {
    const char *msg = "label '%s' already defined on line %d";
    msg = obj_pushfstring(ls->L, msg, getstr(name), lb->line);
    cg_semerror(ls, msg);
  }
}

static void labelstat(LexState *ls, TString *name, int line) {
  checknext(ls, TK_DBCOLON);
  while (ls->t.token == ';' || ls->t.token == TK_DBCOLON)
    statement(ls);
  checkrepeated(ls, name);
  createlabel(ls, name, line, block_follow(ls, 0));
}

static void whilestat(LexState *ls, int line) {
  FuncState *fs = ls->fs;
  int whileinit;
  int condexit;
  BlockCnt bl;
  lex_next(ls);
  whileinit = cg_getlabel(fs);
  condexit = cond(ls);
  enterblock(fs, &bl, 1);
  checknext(ls, TK_DO);
  block(ls);
  cg_jumpto(fs, whileinit);
  check_match(ls, TK_END, TK_WHILE, line);
  leaveblock(fs);
  cg_patchtohere(fs, condexit);
}

static void repeatstat(LexState *ls, int line) {
  int condexit;
  FuncState *fs = ls->fs;
  int repeat_init = cg_getlabel(fs);
  BlockCnt bl1, bl2;
  enterblock(fs, &bl1, 1);
  enterblock(fs, &bl2, 0);
  lex_next(ls);
  statlist(ls);
  check_match(ls, TK_UNTIL, TK_REPEAT, line);
  condexit = cond(ls);
  leaveblock(fs);
  if (bl2.upval) {
    int exit = cg_jump(fs);
    cg_patchtohere(fs, condexit);
    cg_codeABC(fs, OP_CLOSE, reglevel(fs, bl2.nactvar), 0, 0);
    condexit = cg_jump(fs);
    cg_patchtohere(fs, exit);
  }
  cg_patchlist(fs, condexit, repeat_init);
  leaveblock(fs);
}

static void exp1(LexState *ls) {
  expdesc e;
  expr(ls, &e);
  cg_exp2nextreg(ls->fs, &e);
}

static void fixforjump(FuncState *fs, int pc, int dest, int back) {
  Instruction *jmp = &fs->f->code[pc];
  int offset = dest - (pc + 1);
  if (back)
    offset = -offset;
  if (unlikely(offset > MAXARG_Bx))
    lex_syntaxerror(fs->ls, "control structure too long");
  SETARG_Bx(*jmp, offset);
}

static void forbody(LexState *ls, int base, int line, int nvars, int isgen) {
  static const OpCode forprep[2] = {OP_FORPREP, OP_TFORPREP};
  static const OpCode forloop[2] = {OP_FORLOOP, OP_TFORLOOP};
  BlockCnt bl;
  FuncState *fs = ls->fs;
  int prep, endfor;
  checknext(ls, TK_DO);
  prep = cg_codeABx(fs, forprep[isgen], base, 0);
  enterblock(fs, &bl, 0);
  adjustlocalvars(ls, nvars);
  cg_reserveregs(fs, nvars);
  block(ls);
  leaveblock(fs);
  fixforjump(fs, prep, cg_getlabel(fs), 0);
  if (isgen) {
    cg_codeABC(fs, OP_TFORCALL, base, 0, nvars);
    cg_fixline(fs, line);
  }
  endfor = cg_codeABx(fs, forloop[isgen], base, 0);
  fixforjump(fs, endfor, prep + 1, 1);
  cg_fixline(fs, line);
}

static void fornum(LexState *ls, TString *varname, int line) {
  FuncState *fs = ls->fs;
  int base = fs->freereg;
  new_localvarliteral(ls, "(for state)");
  new_localvarliteral(ls, "(for state)");
  new_localvarliteral(ls, "(for state)");
  new_localvar(ls, varname);
  getlocalvardesc(fs, fs->nactvar + 3)->vd.kind = RDKCONST;
  checknext(ls, '=');
  exp1(ls);
  checknext(ls, ',');
  exp1(ls);
  if (testnext(ls, ','))
    exp1(ls);
  else {
    cg_int(fs, fs->freereg, 1);
    cg_reserveregs(fs, 1);
  }
  adjustlocalvars(ls, 3);
  forbody(ls, base, line, 1, 0);
}

static void forlist(LexState *ls, TString *indexname) {
  FuncState *fs = ls->fs;
  expdesc e;
  int nvars = 5;
  int line;
  int base = fs->freereg;
  new_localvarliteral(ls, "(for state)");
  new_localvarliteral(ls, "(for state)");
  new_localvarliteral(ls, "(for state)");
  new_localvarliteral(ls, "(for state)");
  new_localvar(ls, indexname);
  getlocalvardesc(fs, fs->nactvar + 4)->vd.kind = RDKCONST;
  while (testnext(ls, ',')) {
    new_localvar(ls, str_checkname(ls));
    nvars++;
  }
  checknext(ls, TK_IN);
  line = ls->linenumber;
  adjust_assign(ls, 4, explist(ls, &e), &e);
  adjustlocalvars(ls, 4);
  marktobeclosed(fs);
  cg_checkstack(fs, 3);
  forbody(ls, base, line, nvars - 4, 1);
}

static void forstat(LexState *ls, int line) {
  FuncState *fs = ls->fs;
  TString *varname;
  BlockCnt bl;
  enterblock(fs, &bl, 1);
  lex_next(ls);
  varname = str_checkname(ls);
  switch (ls->t.token) {
    case '=': fornum(ls, varname, line); break;
    case ',': case TK_IN: forlist(ls, varname); break;
    default: lex_syntaxerror(ls, "'=' or 'in' expected");
  }
  check_match(ls, TK_END, TK_FOR, line);
  leaveblock(fs);
}

static void test_then_block(LexState *ls, int *escapelist) {
  BlockCnt bl;
  FuncState *fs = ls->fs;
  expdesc v;
  int jf;
  lex_next(ls);
  expr(ls, &v);
  checknext(ls, TK_THEN);
  if (ls->t.token == TK_BREAK) {
    int line = ls->linenumber;
    cg_goiffalse(ls->fs, &v);
    lex_next(ls);
    enterblock(fs, &bl, 0);
    newgotoentry(ls, str_new(ls->L, "break"), line, v.t);
    while (testnext(ls, ';')) {}
    if (block_follow(ls, 0)) {
      leaveblock(fs);
      return;
    } else
      jf = cg_jump(fs);
  } else {
    cg_goiftrue(ls->fs, &v);
    enterblock(fs, &bl, 0);
    jf = v.f;
  }
  statlist(ls);
  leaveblock(fs);
  if (ls->t.token == TK_ELSE || ls->t.token == TK_ELSEIF)
    cg_concat(fs, escapelist, cg_jump(fs));
  cg_patchtohere(fs, jf);
}

static void ifstat(LexState *ls, int line) {
  FuncState *fs = ls->fs;
  int escapelist = NO_JUMP;
  test_then_block(ls, &escapelist);
  while (ls->t.token == TK_ELSEIF)
    test_then_block(ls, &escapelist);
  if (testnext(ls, TK_ELSE))
    block(ls);
  check_match(ls, TK_END, TK_IF, line);
  cg_patchtohere(fs, escapelist);
}

static void localfunc(LexState *ls) {
  expdesc b;
  FuncState *fs = ls->fs;
  int fvar = fs->nactvar;
  new_localvar(ls, str_checkname(ls));
  adjustlocalvars(ls, 1);
  body(ls, &b, 0, ls->linenumber);
  localdebuginfo(fs, fvar)->startpc = fs->pc;
}

static int getlocalattribute(LexState *ls) {
  if (testnext(ls, '<')) {
    TString *ts = str_checkname(ls);
    const char *attr = getstr(ts);
    checknext(ls, '>');
    if (strcmp(attr, "const") == 0)
      return RDKCONST;
    else if (strcmp(attr, "close") == 0)
      return RDKTOCLOSE;
    else
      cg_semerror(ls, obj_pushfstring(ls->L, "unknown attribute '%s'", attr));
  }
  return VDKREG;
}

static void checktoclose(FuncState *fs, int level) {
  if (level != -1) {
    marktobeclosed(fs);
    cg_codeABC(fs, OP_TBC, reglevel(fs, level), 0, 0);
  }
}

static void localstat(LexState *ls) {
  FuncState *fs = ls->fs;
  int toclose = -1;
  Vardesc *var;
  int vidx, kind;
  int nvars = 0;
  int nexps;
  expdesc e;
  do {
    vidx = new_localvar(ls, str_checkname(ls));
    kind = getlocalattribute(ls);
    getlocalvardesc(fs, vidx)->vd.kind = (uint8_t)kind;
    if (kind == RDKTOCLOSE) {
      if (toclose != -1)
        cg_semerror(ls, "multiple to-be-closed variables in local list");
      toclose = fs->nactvar + nvars;
    }
    nvars++;
  } while (testnext(ls, ','));
  if (testnext(ls, '='))
    nexps = explist(ls, &e);
  else {
    e.k = VVOID;
    nexps = 0;
  }
  var = getlocalvardesc(fs, vidx);
  if (nvars == nexps &&
      var->vd.kind == RDKCONST &&
      cg_exp2const(fs, &e, &var->k)) {
    var->vd.kind = RDKCTC;
    adjustlocalvars(ls, nvars - 1);
    fs->nactvar++;
  } else {
    adjust_assign(ls, nvars, nexps, &e);
    adjustlocalvars(ls, nvars);
  }
  checktoclose(fs, toclose);
}

/* ---- 5.5 'global' declarations ---- */

static int newglobalvar(LexState *ls, TString *name, int kind) {
  State *L = ls->L;
  FuncState *fs = ls->fs;
  Dyndata *dyd = ls->dyd;
  Vardesc *var;
  checklimit(fs, dyd->actvar.n + 1 - fs->firstlocal, MAXVARS, "local variables");
  mem_growvec(L, dyd->actvar.arr, dyd->actvar.n + 1, dyd->actvar.size, Vardesc, USHRT_MAX, "local variables");
  var = &dyd->actvar.arr[dyd->actvar.n++];
  var->vd.kind = (uint8_t)kind;
  var->vd.name = name;
  var->vd.ridx = 0;
  var->vd.pidx = -1;
  fs->nactvar++;
  return dyd->actvar.n - 1 - fs->firstlocal;
}

static int getglobalattribute(LexState *ls) {
  if (testnext(ls, '<')) {
    TString *ts = str_checkname(ls);
    const char *attr = getstr(ts);
    checknext(ls, '>');
    if (strcmp(attr, "const") == 0)
      return GDKCONST;
    else if (strcmp(attr, "close") == 0)
      cg_semerror(ls, "global variables cannot be to-be-closed");
    else
      cg_semerror(ls, obj_pushfstring(ls->L, "unknown attribute '%s'", attr));
  }
  return GDKREG;
}

/* build expression for global variable 'name' (_ENV.name) */
static void globalvarexp(LexState *ls, TString *name, expdesc *var) {
  FuncState *fs = ls->fs;
  expdesc key;
  singlevaraux(fs, ls->envn, var, 1);
  cg_exp2anyregup(fs, var);
  codestring(&key, name);
  cg_indexed(fs, var, &key);
  var->gname = name;
}

static void globalfunc(LexState *ls, int line) {
  expdesc v, b;
  FuncState *fs = ls->fs;
  TString *name = str_checkname(ls);
  newglobalvar(ls, name, GDKREG);
  globalvarexp(ls, name, &v);
  cg_codeglbcheck(fs, &v, cg_stringK(fs, name));
  body(ls, &b, 0, line);
  check_readonly(ls, &v);
  cg_storevar(fs, &v, &b);
  cg_fixline(fs, line);
}

static void globalstat(LexState *ls, int line) {
  FuncState *fs = ls->fs;
  int defkind = GDKREG;
  TString *names[MAXVARS];
  int kinds[MAXVARS];
  int nvars = 0;
  int nexps;
  expdesc e;
  int i;
  UNUSED(line);
  if (ls->t.token == TK_FUNCTION) {
    lex_next(ls);
    globalfunc(ls, line);
    return;
  }
  if (ls->t.token == '*') {
    lex_next(ls);
    newglobalvar(ls, str_new(ls->L, "*"), GDKALL);
    return;
  }
  if (ls->t.token == '<')
    defkind = getglobalattribute(ls);
  do {
    TString *name;
    int kind;
    check(ls, TK_NAME);
    name = str_checkname(ls);
    kind = defkind;
    if (ls->t.token == '<')
      kind = getglobalattribute(ls);
    if (nvars >= MAXVARS) errorlimit(fs, MAXVARS, "global variables");
    names[nvars] = name;
    kinds[nvars] = kind;
    nvars++;
  } while (testnext(ls, ','));
  /* declare variables */
  for (i = 0; i < nvars; i++)
    newglobalvar(ls, names[i], kinds[i]);
  if (testnext(ls, '=')) {
    int base = fs->freereg;
    nexps = explist(ls, &e);
    adjust_assign(ls, nvars, nexps, &e);
    /* now values are in registers base .. base+nvars-1 */
    for (i = 0; i < nvars; i++) {
      expdesc var, val;
      globalvarexp(ls, names[i], &var);
      cg_codeglbcheck(fs, &var, cg_stringK(fs, names[i]));
      init_exp(&val, VNONRELOC, base + i);
      globalvarexp(ls, names[i], &var);
      cg_storevar(fs, &var, &val);
    }
    fs->freereg = (uint8_t)base;
  }
}

static int funcname(LexState *ls, expdesc *v) {
  int ismethod = 0;
  singlevar(ls, v);
  while (ls->t.token == '.')
    fieldsel(ls, v);
  if (ls->t.token == ':') {
    ismethod = 1;
    fieldsel(ls, v);
  }
  return ismethod;
}

static void funcstat(LexState *ls, int line) {
  int ismethod;
  expdesc v, b;
  lex_next(ls);
  ismethod = funcname(ls, &v);
  body(ls, &b, ismethod, line);
  check_readonly(ls, &v);
  cg_storevar(ls->fs, &v, &b);
  cg_fixline(ls->fs, line);
}

static void exprstat(LexState *ls) {
  FuncState *fs = ls->fs;
  struct LHS_assign v;
  suffixedexp(ls, &v.v);
  if (ls->t.token == '=' || ls->t.token == ',') {
    v.prev = NULL;
    restassign(ls, &v, 1);
  } else {
    Instruction *inst;
    check_condition(ls, v.v.k == VCALL, "syntax error");
    inst = &getinstruction(fs, &v.v);
    SETARG_C(*inst, 1);
  }
}

static void retstat(LexState *ls) {
  FuncState *fs = ls->fs;
  expdesc e;
  int nret;
  int first = parser_nvarstack(fs);
  if (block_follow(ls, 1) || ls->t.token == ';')
    nret = 0;
  else {
    nret = explist(ls, &e);
    if (hasmultret(e.k)) {
      cg_setmultret(fs, &e);
      if (e.k == VCALL && nret == 1 && !fs->bl->insidetbc) {
        SET_OPCODE(getinstruction(fs, &e), OP_TAILCALL);
      }
      nret = MULTRET;
    } else {
      if (nret == 1)
        first = cg_exp2anyreg(fs, &e);
      else {
        cg_exp2nextreg(fs, &e);
      }
    }
  }
  cg_ret(fs, first, nret);
  testnext(ls, ';');
}

static int isglobaldecl(LexState *ls) {
  /* current token is NAME "global"; decide whether it starts a declaration */
  int la;
  if (strcmp(getstr(ls->t.seminfo.ts), "global") != 0) return 0;
  la = lex_lookahead(ls);
  return (la == TK_NAME || la == '*' || la == TK_FUNCTION || la == '<');
}

static void statement(LexState *ls) {
  int line = ls->linenumber;
  enterlevel(ls);
  switch (ls->t.token) {
    case ';': {
      lex_next(ls);
      break;
    }
    case TK_IF: {
      ifstat(ls, line);
      break;
    }
    case TK_WHILE: {
      whilestat(ls, line);
      break;
    }
    case TK_DO: {
      lex_next(ls);
      block(ls);
      check_match(ls, TK_END, TK_DO, line);
      break;
    }
    case TK_FOR: {
      forstat(ls, line);
      break;
    }
    case TK_REPEAT: {
      repeatstat(ls, line);
      break;
    }
    case TK_FUNCTION: {
      funcstat(ls, line);
      break;
    }
    case TK_LOCAL: {
      lex_next(ls);
      if (testnext(ls, TK_FUNCTION))
        localfunc(ls);
      else
        localstat(ls);
      break;
    }
    case TK_DBCOLON: {
      lex_next(ls);
      labelstat(ls, str_checkname(ls), line);
      break;
    }
    case TK_RETURN: {
      lex_next(ls);
      retstat(ls);
      break;
    }
    case TK_BREAK: {
      breakstat(ls);
      break;
    }
    case TK_GOTO: {
      lex_next(ls);
      gotostat(ls);
      break;
    }
    case TK_NAME: {
      if (isglobaldecl(ls)) {
        lex_next(ls);
        globalstat(ls, line);
        break;
      }
      exprstat(ls);
      break;
    }
    default: {
      exprstat(ls);
      break;
    }
  }
  ls->fs->freereg = (uint8_t)parser_nvarstack(ls->fs);
  leavelevel(ls);
}

static void mainfunc(LexState *ls, FuncState *fs) {
  BlockCnt bl;
  Upvaldesc *env;
  open_func(ls, fs, &bl);
  setvararg(fs, 0);
  env = allocupvalue(fs);
  env->instack = 1;
  env->idx = 0;
  env->kind = VDKREG;
  env->name = ls->envn;
  lex_next(ls);
  statlist(ls);
  check(ls, TK_EOS);
  close_func(ls);
}

LClosure *parse_chunk(State *L, Zio *z, const char *name, int firstchar) {
  LexState lexstate;
  FuncState funcstate;
  Dyndata dyd;
  Mbuffer buff;
  LClosure *cl = lclosure_new(L, 1);
  setclLvalue(L->top, cl);
  do_inctop(L);
  lexstate.h = tbl_new(L);
  sethvalue(L->top, lexstate.h);
  do_inctop(L);
  funcstate.f = cl->p = proto_new(L);
  funcstate.f->source = str_new(L, name);
  lexstate.buff = &buff;
  buff.buffer = NULL; buff.n = 0; buff.buffsize = 0;
  memset(&dyd, 0, sizeof(dyd));
  lexstate.dyd = &dyd;
  dyd.actvar.n = dyd.gt.n = dyd.label.n = 0;
  lex_setinput(L, &lexstate, z, funcstate.f->source, firstchar);
  {
    /* protect the dynamic data: run parser, free on exit via normal path */
    mainfunc(&lexstate, &funcstate);
  }
  mem_free(L, buff.buffer, buff.buffsize);
  mem_freearray(L, dyd.actvar.arr, dyd.actvar.size);
  mem_freearray(L, dyd.gt.arr, dyd.gt.size);
  mem_freearray(L, dyd.label.arr, dyd.label.size);
  L->top--;  /* remove scanner's table */
  return cl;
}
EOF
echo ok

