/*
 * debug.c - debug information, runtime error messages, tracebacks
 */
#include <stdlib.h>
#include <stdio.h>
#include <stdarg.h>
#include "core.h"
#include "opcodes.h"
#include "api.h"

#define ci_func(ci) (clLvalue((ci)->func))

static int currentpc(CallInfo *ci) {
  return cast_int(ci->u.l.savedpc - ci_func(ci)->p->code) - 1;
}

int dbg_getfuncline(const Proto *f, int pc) {
  if (f->lineinfo == NULL || pc < 0 || pc >= f->sizelineinfo) return -1;
  return f->lineinfo[pc];
}

int dbg_currentline(CallInfo *ci) {
  return dbg_getfuncline(ci_func(ci)->p, currentpc(ci));
}

const char *dbg_getlocalname(const Proto *f, int local_number, int pc) {
  int i;
  for (i = 0; i < f->sizelocvars && f->locvars[i].startpc <= pc; i++) {
    if (pc < f->locvars[i].endpc) {
      local_number--;
      if (local_number == 0)
        return getstr(f->locvars[i].varname);
    }
  }
  return NULL;
}

static const char *upvalname(const Proto *p, int uv) {
  TString *s = p->upvalues[uv].name;
  if (s == NULL) return "?";
  else return getstr(s);
}

static const char *findvararg(CallInfo *ci, int n, StkId *pos) {
  if (clLvalue(ci->func)->p->is_vararg) {
    int nextra = ci->u.l.nextraargs;
    if (n >= -nextra) {
      *pos = ci->func - nextra - (n + 1);
      return "(vararg)";
    }
  }
  return NULL;
}

const char *dbg_findlocal(State *L, CallInfo *ci, int n, StkId *pos) {
  StkId base = ci->func + 1;
  const char *name = NULL;
  if (isLua(ci)) {
    if (n < 0)
      return findvararg(ci, n, pos);
    else
      name = dbg_getlocalname(ci_func(ci)->p, n, currentpc(ci));
  }
  if (name == NULL) {
    StkId limit = (ci == L->ci) ? L->top : ci->next->func;
    if (limit - base >= n && n > 0)
      name = isLua(ci) ? "(temporary)" : "(C temporary)";
    else
      return NULL;
  }
  if (pos) *pos = base + (n - 1);
  return name;
}

/* ---- symbolic execution ---- */

static int filterpc(int pc, int jmptarget) {
  if (pc < jmptarget)
    return -1;
  else return pc;
}

static int findsetreg(const Proto *p, int lastpc, int reg) {
  int pc;
  int setreg = -1;
  int jmptarget = 0;
  if (testMMMode(GET_OPCODE(p->code[lastpc])))
    lastpc--;
  for (pc = 0; pc < lastpc; pc++) {
    Instruction i = p->code[pc];
    OpCode op = GET_OPCODE(i);
    int a = GETARG_A(i);
    int change;
    switch (op) {
      case OP_LOADNIL: {
        int b = GETARG_B(i);
        change = (a <= reg && reg <= a + b);
        break;
      }
      case OP_TFORCALL: {
        change = (reg >= a + 2);
        break;
      }
      case OP_CALL:
      case OP_TAILCALL: {
        change = (reg >= a);
        break;
      }
      case OP_JMP: {
        int b = GETARG_sJ(i);
        int dest = pc + 1 + b;
        if (dest <= lastpc && dest > jmptarget)
          jmptarget = dest;
        change = 0;
        break;
      }
      default:
        change = (testAMode(op) && reg == a);
        break;
    }
    if (change)
      setreg = filterpc(pc, jmptarget);
  }
  return setreg;
}

static const char *kname(const Proto *p, int index, const char **name) {
  Value *kvalue = &p->k[index];
  if (ttisstring(kvalue)) {
    *name = getstr(tsvalue(kvalue));
    return "constant";
  } else {
    *name = "?";
    return NULL;
  }
}

static const char *basicgetobjname(const Proto *p, int *ppc, int reg, const char **name) {
  int pc = *ppc;
  *name = dbg_getlocalname(p, reg + 1, pc);
  if (*name)
    return "local";
  *ppc = pc = findsetreg(p, pc, reg);
  if (pc != -1) {
    Instruction i = p->code[pc];
    OpCode op = GET_OPCODE(i);
    switch (op) {
      case OP_MOVE: {
        int b = GETARG_B(i);
        if (b < GETARG_A(i))
          return basicgetobjname(p, ppc, b, name);
        break;
      }
      case OP_GETUPVAL: {
        *name = upvalname(p, GETARG_B(i));
        return "upvalue";
      }
      case OP_LOADK: return kname(p, GETARG_Bx(i), name);
      case OP_LOADKX: return kname(p, GETARG_Ax(p->code[pc + 1]), name);
      default: break;
    }
  }
  return NULL;
}

static void rname(const Proto *p, int pc, int c, const char **name) {
  const char *what = basicgetobjname(p, &pc, c, name);
  if (!(what && *what == 'c'))
    *name = "?";
}

static void rkname(const Proto *p, int pc, Instruction i, const char **name) {
  int c = GETARG_C(i);
  if (GETARG_k(i))
    kname(p, c, name);
  else
    rname(p, pc, c, name);
}

static const char *isEnv(const Proto *p, int pc, Instruction i, int isup) {
  int t = GETARG_B(i);
  const char *name;
  if (isup)
    name = upvalname(p, t);
  else
    basicgetobjname(p, &pc, t, &name);
  return (name && strcmp(name, "_ENV") == 0) ? "global" : "field";
}

static const char *getobjname(const Proto *p, int lastpc, int reg, const char **name) {
  const char *kind = basicgetobjname(p, &lastpc, reg, name);
  if (kind != NULL)
    return kind;
  else if (lastpc != -1) {
    Instruction i = p->code[lastpc];
    OpCode op = GET_OPCODE(i);
    switch (op) {
      case OP_GETTABUP: {
        int k = GETARG_C(i);
        kname(p, k, name);
        return isEnv(p, lastpc, i, 1);
      }
      case OP_GETTABLE: {
        int k = GETARG_C(i);
        rname(p, lastpc, k, name);
        return isEnv(p, lastpc, i, 0);
      }
      case OP_GETI: {
        *name = "integer index";
        return "field";
      }
      case OP_GETFIELD: {
        int k = GETARG_C(i);
        kname(p, k, name);
        return isEnv(p, lastpc, i, 0);
      }
      case OP_SELF: {
        rkname(p, lastpc, i, name);
        return "method";
      }
      default: break;
    }
  }
  return NULL;
}

static const char *funcnamefromcode(State *L, const Proto *p, int pc, const char **name) {
  TMS tm = (TMS)0;
  Instruction i = p->code[pc];
  switch (GET_OPCODE(i)) {
    case OP_CALL:
    case OP_TAILCALL:
      return getobjname(p, pc, GETARG_A(i), name);
    case OP_TFORCALL: {
      *name = "for iterator";
      return "for iterator";
    }
    case OP_SELF: case OP_GETTABUP: case OP_GETTABLE:
    case OP_GETI: case OP_GETFIELD:
      tm = TM_INDEX;
      break;
    case OP_SETTABUP: case OP_SETTABLE: case OP_SETI: case OP_SETFIELD:
      tm = TM_NEWINDEX;
      break;
    case OP_MMBIN: case OP_MMBINI: case OP_MMBINK: {
      tm = (TMS)GETARG_C(i);
      break;
    }
    case OP_UNM: tm = TM_UNM; break;
    case OP_BNOT: tm = TM_BNOT; break;
    case OP_LEN: tm = TM_LEN; break;
    case OP_CONCAT: tm = TM_CONCAT; break;
    case OP_EQ: tm = TM_EQ; break;
    case OP_LT: case OP_LTI: case OP_GTI: tm = TM_LT; break;
    case OP_LE: case OP_LEI: case OP_GEI: tm = TM_LE; break;
    case OP_CLOSE: case OP_RETURN: tm = TM_CLOSE; break;
    default:
      return NULL;
  }
  *name = getstr(G(L)->tmname[tm]) + 2;
  return "metamethod";
}

const char *dbg_funcnamefromcall(State *L, CallInfo *ci, const char **name) {
  if (ci->callstatus & CIST_HOOKED) {
    *name = "?";
    return "hook";
  } else if (ci->callstatus & CIST_FIN) {
    *name = "__gc";
    return "metamethod";
  } else if (isLua(ci))
    return funcnamefromcode(L, ci_func(ci)->p, currentpc(ci), name);
  else
    return NULL;
}

static const char *getfuncname(State *L, CallInfo *ci, const char **name) {
  if (ci != NULL && !(ci->callstatus & CIST_TAIL) && ci->previous != NULL)
    return dbg_funcnamefromcall(L, ci->previous, name);
  else return NULL;
}

/* ---- getinfo ---- */

static void funcinfo(DebugInfo *ar, const Value *func) {
  if (!ttisLclosure(func)) {
    ar->source = "=[C]";
    ar->srclen = 4;
    ar->linedefined = -1;
    ar->lastlinedefined = -1;
    ar->what = "C";
  } else {
    const Proto *p = clLvalue(func)->p;
    if (p->source) {
      ar->source = getstr(p->source);
      ar->srclen = tsslen(p->source);
    } else {
      ar->source = "=?";
      ar->srclen = 2;
    }
    ar->linedefined = p->linedefined;
    ar->lastlinedefined = p->lastlinedefined;
    ar->what = (ar->linedefined == 0) ? "main" : "Lua";
  }
  obj_chunkid(ar->short_src, ar->source, ar->srclen);
}

static void collectvalidlines(State *L, const Value *f) {
  if (!ttisLclosure(f)) {
    setnilvalue(L->top);
    do_inctop(L);
  } else {
    int i;
    const Proto *p = clLvalue(f)->p;
    Table *t = tbl_new(L);
    Value v;
    sethvalue(L->top, t);
    do_inctop(L);
    setbtvalue(&v);
    for (i = 0; i < p->sizelineinfo; i++) {
      if (!(p->is_vararg && i == 0))
        tbl_setint(L, t, p->lineinfo[i], &v);
    }
  }
}

static int auxgetinfo(State *L, const char *what, DebugInfo *ar, const Value *f, CallInfo *ci) {
  int status = 1;
  for (; *what; what++) {
    switch (*what) {
      case 'S': {
        funcinfo(ar, f);
        break;
      }
      case 'l': {
        ar->currentline = (ci && isLua(ci)) ? dbg_currentline(ci) : -1;
        break;
      }
      case 'u': {
        if (ttisLclosure(f)) {
          ar->nups = clLvalue(f)->nupvalues;
          ar->isvararg = clLvalue(f)->p->is_vararg;
          ar->nparams = clLvalue(f)->p->numparams;
        } else {
          ar->nups = ttisCclosure(f) ? clCvalue(f)->nupvalues : 0;
          ar->isvararg = 1;
          ar->nparams = 0;
        }
        break;
      }
      case 't': {
        ar->istailcall = (ci) ? (ci->callstatus & CIST_TAIL) != 0 : 0;
        break;
      }
      case 'n': {
        ar->namewhat = getfuncname(L, ci, &ar->name);
        if (ar->namewhat == NULL) {
          ar->namewhat = "";
          ar->name = NULL;
        }
        break;
      }
      case 'r': {
        ar->ftransfer = ar->ntransfer = 0;
        break;
      }
      case 'L':
      case 'f':
        break;
      default: status = 0;
    }
  }
  return status;
}

int dbg_getinfo(State *L, const char *what, DebugInfo *ar) {
  int status;
  const Value *func;
  CallInfo *ci;
  if (*what == '>') {
    ci = NULL;
    func = L->top - 1;
    what++;
    L->top--;
  } else {
    ci = ar->i_ci;
    func = ci->func;
  }
  status = auxgetinfo(L, what, ar, func, ci);
  if (strchr(what, 'f')) {
    setobj(L->top, func);
    do_inctop(L);
  }
  if (strchr(what, 'L'))
    collectvalidlines(L, func);
  return status;
}

int dbg_getstack(State *L, int level, DebugInfo *ar) {
  int status;
  CallInfo *ci;
  if (level < 0) return 0;
  for (ci = L->ci; level > 0 && ci != &L->base_ci; ci = ci->previous)
    level--;
  if (level == 0 && ci != &L->base_ci) {
    status = 1;
    ar->i_ci = ci;
  } else status = 0;
  return status;
}

/* ---- error messages ---- */

static const char *formatvarinfo(State *L, const char *kind, const char *name) {
  if (kind == NULL)
    return "";
  else
    return obj_pushfstring(L, " (%s '%s')", kind, name);
}

static int isinstack(CallInfo *ci, const Value *o) {
  StkId base = ci->func + 1;
  ptrdiff_t i = o - base;
  return (0 <= i && i < (ci->top - base) && base + i == o);
}

static const char *getupvalname(CallInfo *ci, const Value *o, const char **name) {
  LClosure *c = ci_func(ci);
  int i;
  for (i = 0; i < c->nupvalues; i++) {
    if (c->upvals[i]->v == o) {
      *name = upvalname(c->p, i);
      return "upvalue";
    }
  }
  return NULL;
}

static const char *varinfo(State *L, const Value *o) {
  CallInfo *ci = L->ci;
  const char *name = NULL;
  const char *kind = NULL;
  if (isLua(ci)) {
    kind = getupvalname(ci, o, &name);
    if (!kind && isinstack(ci, o))
      kind = getobjname(ci_func(ci)->p, currentpc(ci), cast_int(o - (ci->func + 1)), &name);
  }
  return formatvarinfo(L, kind, name);
}

static void typeerror(State *L, const Value *o, const char *op, const char *extra) {
  const char *t = tm_objtypename(L, o);
  err_runerror(L, "attempt to %s a %s value%s", op, t, extra);
}

void err_typeerror(State *L, const Value *o, const char *op) {
  typeerror(L, o, op, varinfo(L, o));
}

void err_callerror(State *L, const Value *o) {
  CallInfo *ci = L->ci;
  const char *name = NULL;
  const char *kind = NULL;
  const char *extra;
  if (isLua(ci)) kind = dbg_funcnamefromcall(L, ci, &name);
  if (kind != NULL)
    extra = formatvarinfo(L, kind, name);
  else
    extra = varinfo(L, o);
  typeerror(L, o, "call", extra);
}

void err_forerror(State *L, const Value *o, const char *what) {
  err_runerror(L, "bad 'for' %s (number expected, got %s)", what, tm_objtypename(L, o));
}

void err_concaterror(State *L, const Value *p1, const Value *p2) {
  if (ttisstring(p1) || cvt2str(p1)) p1 = p2;
  err_typeerror(L, p1, "concatenate");
}

void err_opinterror(State *L, const Value *p1, const Value *p2, const char *msg) {
  if (!ttisnumber(p1))
    p2 = p1;
  err_typeerror(L, p2, msg);
}

void err_tointerror(State *L, const Value *p1, const Value *p2) {
  Integer temp;
  if (!vm_tointegerns(p1, &temp, F2Ieq))
    p2 = p1;
  err_runerror(L, "number%s has no integer representation", varinfo(L, p2));
}

void err_ordererror(State *L, const Value *p1, const Value *p2) {
  const char *t1 = tm_objtypename(L, p1);
  const char *t2 = tm_objtypename(L, p2);
  if (strcmp(t1, t2) == 0)
    err_runerror(L, "attempt to compare two %s values", t1);
  else
    err_runerror(L, "attempt to compare %s with %s", t1, t2);
}

const char *err_addinfo(State *L, const char *msg, TString *src, int line) {
  char buff[IDSIZE];
  if (src)
    obj_chunkid(buff, getstr(src), tsslen(src));
  else {
    buff[0] = '?'; buff[1] = '\0';
  }
  return obj_pushfstring(L, "%s:%d: %s", buff, line, msg);
}

void err_errormsg(State *L) {
  if (L->errfunc != 0) {
    StkId errfunc = restorestack(L, L->errfunc);
    setobj(L->top, L->top - 1);
    setobj(L->top - 1, errfunc);
    L->top++;
    do_callnoyield(L, L->top - 2, 1);
  }
  do_throw(L, ST_ERRRUN);
}

void err_runerror(State *L, const char *fmt, ...) {
  CallInfo *ci = L->ci;
  const char *msg;
  va_list argp;
  gc_checkGC(L);
  va_start(argp, fmt);
  msg = obj_pushvfstring(L, fmt, argp);
  va_end(argp);
  if (isLua(ci)) {
    err_addinfo(L, msg, ci_func(ci)->p->source, dbg_currentline(ci));
    setobj(L->top - 2, L->top - 1);
    L->top--;
  }
  err_errormsg(L);
}

/* ---- traceback ---- */

#define LEVELS1 10
#define LEVELS2 11

static int lastlevel(State *L) {
  DebugInfo ar;
  int li = 1, le = 1;
  while (dbg_getstack(L, le, &ar)) { li = le; le *= 2; }
  while (li < le) {
    int m = (li + le) / 2;
    if (dbg_getstack(L, m, &ar)) li = m + 1;
    else le = m;
  }
  return le - 1;
}

/* search package.loaded for a global name of the function at top of L */
static int pushglobalfuncname(State *L, DebugInfo *ar) {
  int top = api_gettop(L);
  api_getinfo(L, "f", ar);  /* push function */
  api_getfield(L, REGISTRYINDEX, "_LOADED");
  if (!api_istable(L, -1)) {
    api_settop(L, top);
    return 0;
  }
  /* iterate over loaded modules */
  api_pushnil(L);
  while (api_next(L, -2)) {
    /* stack: func, loaded, modname, modtable */
    if (api_istable(L, -1) && api_type(L, -2) == T_STRING) {
      api_pushnil(L);
      while (api_next(L, -2)) {
        /* func, loaded, modname, modtable, key, value */
        if (api_rawequal(L, -1, top + 1) && api_type(L, -2) == T_STRING) {
          const char *modname = api_tostring(L, -4);
          const char *fname = api_tostring(L, -2);
          if (strcmp(modname, "_G") == 0)
            api_pushstring(L, fname);
          else
            api_pushfstring(L, "%s.%s", modname, fname);
          api_copy(L, -1, top + 1);
          api_settop(L, top + 1);
          return 1;
        }
        api_pop(L, 1);
      }
    }
    api_pop(L, 1);
  }
  api_settop(L, top);
  return 0;
}

static void pushfuncname(State *L, DebugInfo *ar) {
  if (*ar->namewhat != '\0')
    api_pushfstring(L, "%s '%s'", ar->namewhat, ar->name);
  else if (*ar->what == 'm')
    api_pushliteral(L, "main chunk");
  else if (pushglobalfuncname(L, ar)) {
    api_pushfstring(L, "function '%s'", api_tostring(L, -1));
    api_remove(L, -2);
  } else if (*ar->what != 'C')
    api_pushfstring(L, "function <%s:%d>", ar->short_src, ar->linedefined);
  else
    api_pushliteral(L, "?");
}

void dbg_traceback(State *L, State *L1, const char *msg, int level) {
  Buffer b;
  DebugInfo ar;
  int last = lastlevel(L1);
  int limit2show = (last - level > LEVELS1 + LEVELS2) ? LEVELS1 : -1;
  aux_buffinit(L, &b);
  if (msg) {
    aux_addstring(&b, msg);
    aux_addchar(&b, '\n');
  }
  aux_addstring(&b, "stack traceback:");
  while (dbg_getstack(L1, level++, &ar)) {
    if (limit2show-- == 0) {
      int n = last - level - LEVELS2 + 1;
      api_pushfstring(L, "\n\t...\t(skipping %d levels)", n);
      aux_addvalue(&b);
      level += n;
    } else {
      api_getinfo(L1, "Slnt", &ar);
      if (ar.currentline <= 0)
        api_pushfstring(L, "\n\t%s: in ", ar.short_src);
      else
        api_pushfstring(L, "\n\t%s:%d: in ", ar.short_src, ar.currentline);
      aux_addvalue(&b);
      pushfuncname(L, &ar);
      aux_addvalue(&b);
      if (ar.istailcall)
        aux_addstring(&b, "\n\t(...tail calls...)");
    }
  }
  aux_pushresult(&b);
}
EOF
echo ok"}

actions.command:
cd /workspace && cat > src/debug.c <<'EOF'
/*
 * debug.c - debug information, runtime error messages, tracebacks
 */
#include <stdlib.h>
#include <stdio.h>
#include <stdarg.h>
#include "core.h"
#include "opcodes.h"
#include "api.h"

#define ci_func(ci) (clLvalue((ci)->func))

static int currentpc(CallInfo *ci) {
  return cast_int(ci->u.l.savedpc - ci_func(ci)->p->code) - 1;
}

int dbg_getfuncline(const Proto *f, int pc) {
  if (f->lineinfo == NULL || pc < 0 || pc >= f->sizelineinfo) return -1;
  return f->lineinfo[pc];
}

int dbg_currentline(CallInfo *ci) {
  return dbg_getfuncline(ci_func(ci)->p, currentpc(ci));
}

const char *dbg_getlocalname(const Proto *f, int local_number, int pc) {
  int i;
  for (i = 0; i < f->sizelocvars && f->locvars[i].startpc <= pc; i++) {
    if (pc < f->locvars[i].endpc) {
      local_number--;
      if (local_number == 0)
        return getstr(f->locvars[i].varname);
    }
  }
  return NULL;
}

static const char *upvalname(const Proto *p, int uv) {
  TString *s = p->upvalues[uv].name;
  if (s == NULL) return "?";
  else return getstr(s);
}

static const char *findvararg(CallInfo *ci, int n, StkId *pos) {
  if (clLvalue(ci->func)->p->is_vararg) {
    int nextra = ci->u.l.nextraargs;
    if (n >= -nextra) {
      *pos = ci->func - nextra - (n + 1);
      return "(vararg)";
    }
  }
  return NULL;
}

const char *dbg_findlocal(State *L, CallInfo *ci, int n, StkId *pos) {
  StkId base = ci->func + 1;
  const char *name = NULL;
  if (isLua(ci)) {
    if (n < 0)
      return findvararg(ci, n, pos);
    else
      name = dbg_getlocalname(ci_func(ci)->p, n, currentpc(ci));
  }
  if (name == NULL) {
    StkId limit = (ci == L->ci) ? L->top : ci->next->func;
    if (limit - base >= n && n > 0)
      name = isLua(ci) ? "(temporary)" : "(C temporary)";
    else
      return NULL;
  }
  if (pos) *pos = base + (n - 1);
  return name;
}

/* ---- symbolic execution ---- */

static int filterpc(int pc, int jmptarget) {
  if (pc < jmptarget)
    return -1;
  else return pc;
}

static int findsetreg(const Proto *p, int lastpc, int reg) {
  int pc;
  int setreg = -1;
  int jmptarget = 0;
  if (testMMMode(GET_OPCODE(p->code[lastpc])))
    lastpc--;
  for (pc = 0; pc < lastpc; pc++) {
    Instruction i = p->code[pc];
    OpCode op = GET_OPCODE(i);
    int a = GETARG_A(i);
    int change;
    switch (op) {
      case OP_LOADNIL: {
        int b = GETARG_B(i);
        change = (a <= reg && reg <= a + b);
        break;
      }
      case OP_TFORCALL: {
        change = (reg >= a + 2);
        break;
      }
      case OP_CALL:
      case OP_TAILCALL: {
        change = (reg >= a);
        break;
      }
      case OP_JMP: {
        int b = GETARG_sJ(i);
        int dest = pc + 1 + b;
        if (dest <= lastpc && dest > jmptarget)
          jmptarget = dest;
        change = 0;
        break;
      }
      default:
        change = (testAMode(op) && reg == a);
        break;
    }
    if (change)
      setreg = filterpc(pc, jmptarget);
  }
  return setreg;
}

static const char *kname(const Proto *p, int index, const char **name) {
  Value *kvalue = &p->k[index];
  if (ttisstring(kvalue)) {
    *name = getstr(tsvalue(kvalue));
    return "constant";
  } else {
    *name = "?";
    return NULL;
  }
}

static const char *basicgetobjname(const Proto *p, int *ppc, int reg, const char **name) {
  int pc = *ppc;
  *name = dbg_getlocalname(p, reg + 1, pc);
  if (*name)
    return "local";
  *ppc = pc = findsetreg(p, pc, reg);
  if (pc != -1) {
    Instruction i = p->code[pc];
    OpCode op = GET_OPCODE(i);
    switch (op) {
      case OP_MOVE: {
        int b = GETARG_B(i);
        if (b < GETARG_A(i))
          return basicgetobjname(p, ppc, b, name);
        break;
      }
      case OP_GETUPVAL: {
        *name = upvalname(p, GETARG_B(i));
        return "upvalue";
      }
      case OP_LOADK: return kname(p, GETARG_Bx(i), name);
      case OP_LOADKX: return kname(p, GETARG_Ax(p->code[pc + 1]), name);
      default: break;
    }
  }
  return NULL;
}

static void rname(const Proto *p, int pc, int c, const char **name) {
  const char *what = basicgetobjname(p, &pc, c, name);
  if (!(what && *what == 'c'))
    *name = "?";
}

static void rkname(const Proto *p, int pc, Instruction i, const char **name) {
  int c = GETARG_C(i);
  if (GETARG_k(i))
    kname(p, c, name);
  else
    rname(p, pc, c, name);
}

static const char *isEnv(const Proto *p, int pc, Instruction i, int isup) {
  int t = GETARG_B(i);
  const char *name;
  if (isup)
    name = upvalname(p, t);
  else
    basicgetobjname(p, &pc, t, &name);
  return (name && strcmp(name, "_ENV") == 0) ? "global" : "field";
}

static const char *getobjname(const Proto *p, int lastpc, int reg, const char **name) {
  const char *kind = basicgetobjname(p, &lastpc, reg, name);
  if (kind != NULL)
    return kind;
  else if (lastpc != -1) {
    Instruction i = p->code[lastpc];
    OpCode op = GET_OPCODE(i);
    switch (op) {
      case OP_GETTABUP: {
        int k = GETARG_C(i);
        kname(p, k, name);
        return isEnv(p, lastpc, i, 1);
      }
      case OP_GETTABLE: {
        int k = GETARG_C(i);
        rname(p, lastpc, k, name);
        return isEnv(p, lastpc, i, 0);
      }
      case OP_GETI: {
        *name = "integer index";
        return "field";
      }
      case OP_GETFIELD: {
        int k = GETARG_C(i);
        kname(p, k, name);
        return isEnv(p, lastpc, i, 0);
      }
      case OP_SELF: {
        rkname(p, lastpc, i, name);
        return "method";
      }
      default: break;
    }
  }
  return NULL;
}

static const char *funcnamefromcode(State *L, const Proto *p, int pc, const char **name) {
  TMS tm = (TMS)0;
  Instruction i = p->code[pc];
  switch (GET_OPCODE(i)) {
    case OP_CALL:
    case OP_TAILCALL:
      return getobjname(p, pc, GETARG_A(i), name);
    case OP_TFORCALL: {
      *name = "for iterator";
      return "for iterator";
    }
    case OP_SELF: case OP_GETTABUP: case OP_GETTABLE:
    case OP_GETI: case OP_GETFIELD:
      tm = TM_INDEX;
      break;
    case OP_SETTABUP: case OP_SETTABLE: case OP_SETI: case OP_SETFIELD:
      tm = TM_NEWINDEX;
      break;
    case OP_MMBIN: case OP_MMBINI: case OP_MMBINK: {
      tm = (TMS)GETARG_C(i);
      break;
    }
    case OP_UNM: tm = TM_UNM; break;
    case OP_BNOT: tm = TM_BNOT; break;
    case OP_LEN: tm = TM_LEN; break;
    case OP_CONCAT: tm = TM_CONCAT; break;
    case OP_EQ: tm = TM_EQ; break;
    case OP_LT: case OP_LTI: case OP_GTI: tm = TM_LT; break;
    case OP_LE: case OP_LEI: case OP_GEI: tm = TM_LE; break;
    case OP_CLOSE: case OP_RETURN: tm = TM_CLOSE; break;
    default:
      return NULL;
  }
  *name = getstr(G(L)->tmname[tm]) + 2;
  return "metamethod";
}

const char *dbg_funcnamefromcall(State *L, CallInfo *ci, const char **name) {
  if (ci->callstatus & CIST_HOOKED) {
    *name = "?";
    return "hook";
  } else if (ci->callstatus & CIST_FIN) {
    *name = "__gc";
    return "metamethod";
  } else if (isLua(ci))
    return funcnamefromcode(L, ci_func(ci)->p, currentpc(ci), name);
  else
    return NULL;
}

static const char *getfuncname(State *L, CallInfo *ci, const char **name) {
  if (ci != NULL && !(ci->callstatus & CIST_TAIL) && ci->previous != NULL)
    return dbg_funcnamefromcall(L, ci->previous, name);
  else return NULL;
}

/* ---- getinfo ---- */

static void funcinfo(DebugInfo *ar, const Value *func) {
  if (!ttisLclosure(func)) {
    ar->source = "=[C]";
    ar->srclen = 4;
    ar->linedefined = -1;
    ar->lastlinedefined = -1;
    ar->what = "C";
  } else {
    const Proto *p = clLvalue(func)->p;
    if (p->source) {
      ar->source = getstr(p->source);
      ar->srclen = tsslen(p->source);
    } else {
      ar->source = "=?";
      ar->srclen = 2;
    }
    ar->linedefined = p->linedefined;
    ar->lastlinedefined = p->lastlinedefined;
    ar->what = (ar->linedefined == 0) ? "main" : "Lua";
  }
  obj_chunkid(ar->short_src, ar->source, ar->srclen);
}

static void collectvalidlines(State *L, const Value *f) {
  if (!ttisLclosure(f)) {
    setnilvalue(L->top);
    do_inctop(L);
  } else {
    int i;
    const Proto *p = clLvalue(f)->p;
    Table *t = tbl_new(L);
    Value v;
    sethvalue(L->top, t);
    do_inctop(L);
    setbtvalue(&v);
    for (i = 0; i < p->sizelineinfo; i++) {
      if (!(p->is_vararg && i == 0))
        tbl_setint(L, t, p->lineinfo[i], &v);
    }
  }
}

static int auxgetinfo(State *L, const char *what, DebugInfo *ar, const Value *f, CallInfo *ci) {
  int status = 1;
  for (; *what; what++) {
    switch (*what) {
      case 'S': {
        funcinfo(ar, f);
        break;
      }
      case 'l': {
        ar->currentline = (ci && isLua(ci)) ? dbg_currentline(ci) : -1;
        break;
      }
      case 'u': {
        if (ttisLclosure(f)) {
          ar->nups = clLvalue(f)->nupvalues;
          ar->isvararg = clLvalue(f)->p->is_vararg;
          ar->nparams = clLvalue(f)->p->numparams;
        } else {
          ar->nups = ttisCclosure(f) ? clCvalue(f)->nupvalues : 0;
          ar->isvararg = 1;
          ar->nparams = 0;
        }
        break;
      }
      case 't': {
        ar->istailcall = (ci) ? (ci->callstatus & CIST_TAIL) != 0 : 0;
        break;
      }
      case 'n': {
        ar->namewhat = getfuncname(L, ci, &ar->name);
        if (ar->namewhat == NULL) {
          ar->namewhat = "";
          ar->name = NULL;
        }
        break;
      }
      case 'r': {
        ar->ftransfer = ar->ntransfer = 0;
        break;
      }
      case 'L':
      case 'f':
        break;
      default: status = 0;
    }
  }
  return status;
}

int dbg_getinfo(State *L, const char *what, DebugInfo *ar) {
  int status;
  const Value *func;
  CallInfo *ci;
  if (*what == '>') {
    ci = NULL;
    func = L->top - 1;
    what++;
    L->top--;
  } else {
    ci = ar->i_ci;
    func = ci->func;
  }
  status = auxgetinfo(L, what, ar, func, ci);
  if (strchr(what, 'f')) {
    setobj(L->top, func);
    do_inctop(L);
  }
  if (strchr(what, 'L'))
    collectvalidlines(L, func);
  return status;
}

int dbg_getstack(State *L, int level, DebugInfo *ar) {
  int status;
  CallInfo *ci;
  if (level < 0) return 0;
  for (ci = L->ci; level > 0 && ci != &L->base_ci; ci = ci->previous)
    level--;
  if (level == 0 && ci != &L->base_ci) {
    status = 1;
    ar->i_ci = ci;
  } else status = 0;
  return status;
}

/* ---- error messages ---- */

static const char *formatvarinfo(State *L, const char *kind, const char *name) {
  if (kind == NULL)
    return "";
  else
    return obj_pushfstring(L, " (%s '%s')", kind, name);
}

static int isinstack(CallInfo *ci, const Value *o) {
  StkId base = ci->func + 1;
  ptrdiff_t i = o - base;
  return (0 <= i && i < (ci->top - base) && base + i == o);
}

static const char *getupvalname(CallInfo *ci, const Value *o, const char **name) {
  LClosure *c = ci_func(ci);
  int i;
  for (i = 0; i < c->nupvalues; i++) {
    if (c->upvals[i]->v == o) {
      *name = upvalname(c->p, i);
      return "upvalue";
    }
  }
  return NULL;
}

static const char *varinfo(State *L, const Value *o) {
  CallInfo *ci = L->ci;
  const char *name = NULL;
  const char *kind = NULL;
  if (isLua(ci)) {
    kind = getupvalname(ci, o, &name);
    if (!kind && isinstack(ci, o))
      kind = getobjname(ci_func(ci)->p, currentpc(ci), cast_int(o - (ci->func + 1)), &name);
  }
  return formatvarinfo(L, kind, name);
}

static void typeerror(State *L, const Value *o, const char *op, const char *extra) {
  const char *t = tm_objtypename(L, o);
  err_runerror(L, "attempt to %s a %s value%s", op, t, extra);
}

void err_typeerror(State *L, const Value *o, const char *op) {
  typeerror(L, o, op, varinfo(L, o));
}

void err_callerror(State *L, const Value *o) {
  CallInfo *ci = L->ci;
  const char *name = NULL;
  const char *kind = NULL;
  const char *extra;
  if (isLua(ci)) kind = dbg_funcnamefromcall(L, ci, &name);
  if (kind != NULL)
    extra = formatvarinfo(L, kind, name);
  else
    extra = varinfo(L, o);
  typeerror(L, o, "call", extra);
}

void err_forerror(State *L, const Value *o, const char *what) {
  err_runerror(L, "bad 'for' %s (number expected, got %s)", what, tm_objtypename(L, o));
}

void err_concaterror(State *L, const Value *p1, const Value *p2) {
  if (ttisstring(p1) || cvt2str(p1)) p1 = p2;
  err_typeerror(L, p1, "concatenate");
}

void err_opinterror(State *L, const Value *p1, const Value *p2, const char *msg) {
  if (!ttisnumber(p1))
    p2 = p1;
  err_typeerror(L, p2, msg);
}

void err_tointerror(State *L, const Value *p1, const Value *p2) {
  Integer temp;
  if (!vm_tointegerns(p1, &temp, F2Ieq))
    p2 = p1;
  err_runerror(L, "number%s has no integer representation", varinfo(L, p2));
}

void err_ordererror(State *L, const Value *p1, const Value *p2) {
  const char *t1 = tm_objtypename(L, p1);
  const char *t2 = tm_objtypename(L, p2);
  if (strcmp(t1, t2) == 0)
    err_runerror(L, "attempt to compare two %s values", t1);
  else
    err_runerror(L, "attempt to compare %s with %s", t1, t2);
}

const char *err_addinfo(State *L, const char *msg, TString *src, int line) {
  char buff[IDSIZE];
  if (src)
    obj_chunkid(buff, getstr(src), tsslen(src));
  else {
    buff[0] = '?'; buff[1] = '\0';
  }
  return obj_pushfstring(L, "%s:%d: %s", buff, line, msg);
}

void err_errormsg(State *L) {
  if (L->errfunc != 0) {
    StkId errfunc = restorestack(L, L->errfunc);
    setobj(L->top, L->top - 1);
    setobj(L->top - 1, errfunc);
    L->top++;
    do_callnoyield(L, L->top - 2, 1);
  }
  do_throw(L, ST_ERRRUN);
}

void err_runerror(State *L, const char *fmt, ...) {
  CallInfo *ci = L->ci;
  const char *msg;
  va_list argp;
  gc_checkGC(L);
  va_start(argp, fmt);
  msg = obj_pushvfstring(L, fmt, argp);
  va_end(argp);
  if (isLua(ci)) {
    err_addinfo(L, msg, ci_func(ci)->p->source, dbg_currentline(ci));
    setobj(L->top - 2, L->top - 1);
    L->top--;
  }
  err_errormsg(L);
}

/* ---- traceback ---- */

#define LEVELS1 10
#define LEVELS2 11

static int lastlevel(State *L) {
  DebugInfo ar;
  int li = 1, le = 1;
  while (dbg_getstack(L, le, &ar)) { li = le; le *= 2; }
  while (li < le) {
    int m = (li + le) / 2;
    if (dbg_getstack(L, m, &ar)) li = m + 1;
    else le = m;
  }
  return le - 1;
}

/* search package.loaded for a global name of the function at top of L */
static int pushglobalfuncname(State *L, DebugInfo *ar) {
  int top = api_gettop(L);
  api_getinfo(L, "f", ar);  /* push function */
  api_getfield(L, REGISTRYINDEX, "_LOADED");
  if (!api_istable(L, -1)) {
    api_settop(L, top);
    return 0;
  }
  /* iterate over loaded modules */
  api_pushnil(L);
  while (api_next(L, -2)) {
    /* stack: func, loaded, modname, modtable */
    if (api_istable(L, -1) && api_type(L, -2) == T_STRING) {
      api_pushnil(L);
      while (api_next(L, -2)) {
        /* func, loaded, modname, modtable, key, value */
        if (api_rawequal(L, -1, top + 1) && api_type(L, -2) == T_STRING) {
          const char *modname = api_tostring(L, -4);
          const char *fname = api_tostring(L, -2);
          if (strcmp(modname, "_G") == 0)
            api_pushstring(L, fname);
          else
            api_pushfstring(L, "%s.%s", modname, fname);
          api_copy(L, -1, top + 1);
          api_settop(L, top + 1);
          return 1;
        }
        api_pop(L, 1);
      }
    }
    api_pop(L, 1);
  }
  api_settop(L, top);
  return 0;
}

static void pushfuncname(State *L, DebugInfo *ar) {
  if (*ar->namewhat != '\0')
    api_pushfstring(L, "%s '%s'", ar->namewhat, ar->name);
  else if (*ar->what == 'm')
    api_pushliteral(L, "main chunk");
  else if (pushglobalfuncname(L, ar)) {
    api_pushfstring(L, "function '%s'", api_tostring(L, -1));
    api_remove(L, -2);
  } else if (*ar->what != 'C')
    api_pushfstring(L, "function <%s:%d>", ar->short_src, ar->linedefined);
  else
    api_pushliteral(L, "?");
}

void dbg_traceback(State *L, State *L1, const char *msg, int level) {
  Buffer b;
  DebugInfo ar;
  int last = lastlevel(L1);
  int limit2show = (last - level > LEVELS1 + LEVELS2) ? LEVELS1 : -1;
  aux_buffinit(L, &b);
  if (msg) {
    aux_addstring(&b, msg);
    aux_addchar(&b, '\n');
  }
  aux_addstring(&b, "stack traceback:");
  while (dbg_getstack(L1, level++, &ar)) {
    if (limit2show-- == 0) {
      int n = last - level - LEVELS2 + 1;
      api_pushfstring(L, "\n\t...\t(skipping %d levels)", n);
      aux_addvalue(&b);
      level += n;
    } else {
      api_getinfo(L1, "Slnt", &ar);
      if (ar.currentline <= 0)
        api_pushfstring(L, "\n\t%s: in ", ar.short_src);
      else
        api_pushfstring(L, "\n\t%s:%d: in ", ar.short_src, ar.currentline);
      aux_addvalue(&b);
      pushfuncname(L, &ar);
      aux_addvalue(&b);
      if (ar.istailcall)
        aux_addstring(&b, "\n\t(...tail calls...)");
    }
  }
  aux_pushresult(&b);
}
