/*
 * api.c - stack-based interface used by libraries
 */
#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include "core.h"
#include "api.h"

#define isvalid(L, o) (!ttisnil(o) || o != &G(L)->nilvalue)
#define ispseudo(i) ((i) <= REGISTRYINDEX)
#define isupvalue(i) ((i) < REGISTRYINDEX)

Value *api_index2value(State *L, int idx) {
  CallInfo *ci = L->ci;
  if (idx > 0) {
    StkId o = ci->func + idx;
    if (o >= L->top) return &G(L)->nilvalue;
    else return o;
  } else if (!ispseudo(idx)) {
    return L->top + idx;
  } else if (idx == REGISTRYINDEX)
    return &G(L)->l_registry;
  else {
    idx = REGISTRYINDEX - idx;
    if (ttisCclosure(ci->func)) {
      CClosure *func = clCvalue(ci->func);
      return (idx <= func->nupvalues) ? &func->upvalue[idx - 1] : &G(L)->nilvalue;
    } else {
      return &G(L)->nilvalue;
    }
  }
}

static StkId index2stack(State *L, int idx) {
  CallInfo *ci = L->ci;
  if (idx > 0) {
    return ci->func + idx;
  } else {
    return L->top + idx;
  }
}

int api_checkstack(State *L, int n) {
  int res;
  CallInfo *ci = L->ci;
  if (L->stack_last - L->top > n)
    res = 1;
  else {
    int inuse = cast_int(L->top - L->stack) + EXTRA_SLOTS;
    if (inuse > MAXSTACK_SLOTS - n)
      res = 0;
    else {
      do_growstack(L, n, 0);
      res = 1;
    }
  }
  if (res && ci->top < L->top + n)
    ci->top = L->top + n;
  return res;
}

void api_xmove(State *from, State *to, int n) {
  int i;
  if (from == to) return;
  from->top -= n;
  for (i = 0; i < n; i++) {
    setobj(to->top, from->top + i);
    to->top++;
  }
}

int api_absindex(State *L, int idx) {
  return (idx > 0 || ispseudo(idx)) ? idx : cast_int(L->top - L->ci->func) + idx;
}

int api_gettop(State *L) {
  return cast_int(L->top - (L->ci->func + 1));
}

void api_settop(State *L, int idx) {
  CallInfo *ci = L->ci;
  StkId func = ci->func;
  ptrdiff_t diff;
  if (idx >= 0) {
    diff = ((func + 1) + idx) - L->top;
    for (; diff > 0; diff--)
      setnilvalue(L->top++);
  } else {
    diff = idx + 1;
  }
  {
    StkId newtop = L->top + diff;
    if (diff < 0 && L->ntbc > 0 && L->tbc[L->ntbc - 1] >= savestack(L, newtop)) {
      func_close(L, newtop, CLOSEKTOP, 0);
    }
    L->top = newtop;
  }
}

void api_closeslot(State *L, int idx) {
  StkId level = index2stack(L, idx);
  func_close(L, level, CLOSEKTOP, 0);
  setnilvalue(level);
}

static void reverse(State *L, StkId from, StkId to) {
  for (; from < to; from++, to--) {
    Value temp;
    setobj(&temp, from);
    setobj(from, to);
    setobj(to, &temp);
  }
}

void api_rotate(State *L, int idx, int n) {
  StkId p, t, m;
  t = L->top - 1;
  p = index2stack(L, idx);
  m = (n >= 0 ? t - n : p - n - 1);
  reverse(L, p, m);
  reverse(L, m + 1, t);
  reverse(L, p, t);
}

void api_copy(State *L, int fromidx, int toidx) {
  Value *fr, *to;
  fr = api_index2value(L, fromidx);
  to = api_index2value(L, toidx);
  setobj(to, fr);
}

void api_pushvalue(State *L, int idx) {
  setobj(L->top, api_index2value(L, idx));
  do_inctop(L);
}

/* ---- access ---- */

int api_type(State *L, int idx) {
  const Value *o = api_index2value(L, idx);
  return (isvalid(L, o) ? ttype(o) : T_NONE);
}

const char *api_typename(State *L, int t) {
  UNUSED(L);
  return ttypename(t);
}

int api_iscfunction(State *L, int idx) {
  const Value *o = api_index2value(L, idx);
  return (ttislcf(o) || (ttisCclosure(o)));
}

int api_isinteger(State *L, int idx) {
  const Value *o = api_index2value(L, idx);
  return ttisinteger(o);
}

int api_isnumber(State *L, int idx) {
  Number n;
  const Value *o = api_index2value(L, idx);
  return tonumber(o, &n);
}

int api_isstring(State *L, int idx) {
  const Value *o = api_index2value(L, idx);
  return (ttisstring(o) || cvt2str(o));
}

int api_isuserdata(State *L, int idx) {
  const Value *o = api_index2value(L, idx);
  return (ttisfulluserdata(o) || ttislightuserdata(o));
}

int api_rawequal(State *L, int index1, int index2) {
  const Value *o1 = api_index2value(L, index1);
  const Value *o2 = api_index2value(L, index2);
  return (isvalid(L, o1) && isvalid(L, o2)) ? vm_rawequalobj(o1, o2) : 0;
}

void api_arith(State *L, int op) {
  if (op == OPR_UNM || op == OPR_BNOT) {
    setobj(L->top, L->top - 1);
    do_inctop(L);
  }
  obj_arith(L, op, L->top - 2, L->top - 1, L->top - 2);
  L->top--;
}

int api_compare(State *L, int index1, int index2, int op) {
  const Value *o1;
  const Value *o2;
  int i = 0;
  o1 = api_index2value(L, index1);
  o2 = api_index2value(L, index2);
  if (isvalid(L, o1) && isvalid(L, o2)) {
    switch (op) {
      case OPEQ: i = vm_equalobj(L, o1, o2); break;
      case OPLT: i = vm_lessthan(L, o1, o2); break;
      case OPLE: i = vm_lessequal(L, o1, o2); break;
      default: break;
    }
  }
  return i;
}

size_t api_stringtonumber(State *L, const char *s) {
  size_t sz = obj_str2num(s, L->top);
  if (sz != 0)
    do_inctop(L);
  return sz;
}

Number api_tonumberx(State *L, int idx, int *pisnum) {
  Number n = 0;
  const Value *o = api_index2value(L, idx);
  int isnum = tonumber(o, &n);
  if (pisnum)
    *pisnum = isnum;
  return n;
}

Integer api_tointegerx(State *L, int idx, int *pisnum) {
  Integer res = 0;
  const Value *o = api_index2value(L, idx);
  int isnum = tointeger(o, &res);
  if (pisnum)
    *pisnum = isnum;
  return res;
}

int api_toboolean(State *L, int idx) {
  const Value *o = api_index2value(L, idx);
  return !l_isfalse(o);
}

const char *api_tolstring(State *L, int idx, size_t *len) {
  Value *o;
  o = api_index2value(L, idx);
  if (!ttisstring(o)) {
    if (!cvt2str(o)) {
      if (len != NULL) *len = 0;
      return NULL;
    }
    obj_tostring(L, o);
    gc_checkGC(L);
    o = api_index2value(L, idx);
  }
  if (len != NULL)
    *len = vslen(o);
  return svalue(o);
}

UInteger api_rawlen(State *L, int idx) {
  const Value *o = api_index2value(L, idx);
  switch (ttypetag(o)) {
    case ctb(V_SHRSTR): return tsvalue(o)->shrlen;
    case ctb(V_LNGSTR): return tsvalue(o)->u.lnglen;
    case ctb(V_USERDATA): return uvalue(o)->len;
    case ctb(V_TABLE): return tbl_getn(hvalue(o));
    default: return 0;
  }
}

CFunction api_tocfunction(State *L, int idx) {
  const Value *o = api_index2value(L, idx);
  if (ttislcf(o)) return fvalue(o);
  else if (ttisCclosure(o))
    return clCvalue(o)->f;
  else return NULL;
}

static void *touserdata(const Value *o) {
  switch (ttype(o)) {
    case T_USERDATA: return uvalue(o)->mem;
    case T_LIGHTUD: return pvalue(o);
    default: return NULL;
  }
}

void *api_touserdata(State *L, int idx) {
  const Value *o = api_index2value(L, idx);
  return touserdata(o);
}

State *api_tothread(State *L, int idx) {
  const Value *o = api_index2value(L, idx);
  return (!ttisthread(o)) ? NULL : thvalue(o);
}

const void *api_topointer(State *L, int idx) {
  const Value *o = api_index2value(L, idx);
  switch (ttypetag(o)) {
    case V_LCF: return (void *)(size_t)fvalue(o);
    case ctb(V_USERDATA): case V_LIGHTUD:
      return touserdata(o);
    default: {
      if (iscollectable(o))
        return gcvalue(o);
      else
        return NULL;
    }
  }
}

/* ---- push ---- */

void api_pushnil(State *L) {
  setnilvalue(L->top);
  do_inctop(L);
}

void api_pushnumber(State *L, Number n) {
  setfltvalue(L->top, n);
  do_inctop(L);
}

void api_pushinteger(State *L, Integer n) {
  setivalue(L->top, n);
  do_inctop(L);
}

const char *api_pushlstring(State *L, const char *s, size_t len) {
  TString *ts;
  ts = (len == 0) ? str_new(L, "") : str_newlstr(L, s, len);
  setsvalue(L->top, ts);
  do_inctop(L);
  gc_checkGC(L);
  return getstr(ts);
}

const char *api_pushstring(State *L, const char *s) {
  if (s == NULL)
    setnilvalue(L->top);
  else {
    TString *ts;
    ts = str_new(L, s);
    setsvalue(L->top, ts);
    s = getstr(ts);
  }
  do_inctop(L);
  gc_checkGC(L);
  return s;
}

const char *api_pushvfstring(State *L, const char *fmt, va_list argp) {
  const char *ret;
  ret = obj_pushvfstring(L, fmt, argp);
  gc_checkGC(L);
  return ret;
}

const char *api_pushfstring(State *L, const char *fmt, ...) {
  const char *ret;
  va_list argp;
  va_start(argp, fmt);
  ret = obj_pushvfstring(L, fmt, argp);
  va_end(argp);
  gc_checkGC(L);
  return ret;
}

void api_pushcclosure(State *L, CFunction fn, int n) {
  if (n == 0) {
    setfvalue(L->top, fn);
    do_inctop(L);
  } else {
    CClosure *cl;
    cl = cclosure_new(L, n);
    cl->f = fn;
    L->top -= n;
    while (n--) {
      setobj(&cl->upvalue[n], L->top + n);
    }
    setclCvalue(L->top, cl);
    do_inctop(L);
    gc_checkGC(L);
  }
}

void api_pushboolean(State *L, int b) {
  if (b) setbtvalue(L->top);
  else setbfvalue(L->top);
  do_inctop(L);
}

void api_pushlightuserdata(State *L, void *p) {
  setpvalue(L->top, p);
  do_inctop(L);
}

int api_pushthread(State *L) {
  setthvalue(L->top, L);
  do_inctop(L);
  return (G(L)->mainthread == L);
}

/* ---- get ---- */

static int auxgetstr(State *L, const Value *t, const char *k) {
  const Value *slot;
  TString *str = str_new(L, k);
  if (ttistable(t) && !isempty(slot = tbl_getstr(hvalue(t), str))) {
    setobj(L->top, slot);
    do_inctop(L);
  } else {
    setsvalue(L->top, str);
    do_inctop(L);
    vm_finishget(L, t, L->top - 1, L->top - 1, ttistable(t) ? slot : NULL);
  }
  return ttype(L->top - 1);
}

#define getGtable(L) (tbl_getint(hvalue(&G(L)->l_registry), RIDX_GLOBALS))

int api_getglobal(State *L, const char *name) {
  const Value *G_ = getGtable(L);
  return auxgetstr(L, G_, name);
}

int api_gettable(State *L, int idx) {
  const Value *slot;
  Value *t;
  t = api_index2value(L, idx);
  if (ttistable(t) && !isempty(slot = tbl_get(hvalue(t), L->top - 1))) {
    setobj(L->top - 1, slot);
  } else
    vm_finishget(L, t, L->top - 1, L->top - 1, ttistable(t) ? slot : NULL);
  return ttype(L->top - 1);
}

int api_getfield(State *L, int idx, const char *k) {
  return auxgetstr(L, api_index2value(L, idx), k);
}

int api_geti(State *L, int idx, Integer n) {
  Value *t;
  const Value *slot;
  t = api_index2value(L, idx);
  if (ttistable(t) && !isempty(slot = tbl_getint(hvalue(t), n))) {
    setobj(L->top, slot);
  } else {
    Value aux;
    setivalue(&aux, n);
    vm_finishget(L, t, &aux, L->top, ttistable(t) ? slot : NULL);
  }
  do_inctop(L);
  return ttype(L->top - 1);
}

static int finishrawget(State *L, const Value *val) {
  if (isempty(val))
    setnilvalue(L->top);
  else
    setobj(L->top, val);
  do_inctop(L);
  return ttype(L->top - 1);
}

static Table *gettable(State *L, int idx) {
  Value *t = api_index2value(L, idx);
  return hvalue(t);
}

int api_rawget(State *L, int idx) {
  Table *t;
  const Value *val;
  t = gettable(L, idx);
  val = tbl_get(t, L->top - 1);
  L->top--;
  return finishrawget(L, val);
}

int api_rawgeti(State *L, int idx, Integer n) {
  Table *t;
  t = gettable(L, idx);
  return finishrawget(L, tbl_getint(t, n));
}

int api_rawgetp(State *L, int idx, const void *p) {
  Table *t;
  Value k;
  t = gettable(L, idx);
  setpvalue(&k, (void *)p);
  return finishrawget(L, tbl_get(t, &k));
}

void api_createtable(State *L, int narray, int nrec) {
  Table *t;
  t = tbl_new(L);
  sethvalue(L->top, t);
  do_inctop(L);
  if (narray > 0 || nrec > 0)
    tbl_resize(L, t, narray, nrec);
  gc_checkGC(L);
}

int api_getmetatable(State *L, int objindex) {
  const Value *obj;
  Table *mt;
  int res = 0;
  obj = api_index2value(L, objindex);
  switch (ttype(obj)) {
    case T_TABLE: mt = hvalue(obj)->metatable; break;
    case T_USERDATA: mt = uvalue(obj)->metatable; break;
    default: mt = G(L)->mt[ttype(obj)]; break;
  }
  if (mt != NULL) {
    sethvalue(L->top, mt);
    do_inctop(L);
    res = 1;
  }
  return res;
}

int api_getiuservalue(State *L, int idx, int n) {
  Value *o;
  int t;
  o = api_index2value(L, idx);
  if (n <= 0 || n > uvalue(o)->nuvalue) {
    setnilvalue(L->top);
    t = T_NONE;
  } else {
    setobj(L->top, &uvalue(o)->uv[n - 1]);
    t = ttype(L->top);
  }
  do_inctop(L);
  return t;
}

/* ---- set ---- */

static void auxsetstr(State *L, const Value *t, const char *k) {
  const Value *slot;
  TString *str = str_new(L, k);
  if (ttistable(t) && !isempty(slot = tbl_getstr(hvalue(t), str))) {
    setobj((Value *)slot, L->top - 1);
    invalidateTMcache(hvalue(t));
    L->top--;
  } else {
    setsvalue(L->top, str);
    do_inctop(L);
    vm_finishset(L, t, L->top - 1, L->top - 2, ttistable(t) ? slot : NULL);
    L->top -= 2;
  }
}

void api_setglobal(State *L, const char *name) {
  const Value *G_ = getGtable(L);
  auxsetstr(L, G_, name);
}

void api_settable(State *L, int idx) {
  Value *t;
  const Value *slot;
  t = api_index2value(L, idx);
  if (ttistable(t) && !isempty(slot = tbl_get(hvalue(t), L->top - 2))) {
    setobj((Value *)slot, L->top - 1);
    invalidateTMcache(hvalue(t));
  } else
    vm_finishset(L, t, L->top - 2, L->top - 1, ttistable(t) ? slot : NULL);
  L->top -= 2;
}

void api_setfield(State *L, int idx, const char *k) {
  auxsetstr(L, api_index2value(L, idx), k);
}

void api_seti(State *L, int idx, Integer n) {
  Value *t;
  const Value *slot;
  t = api_index2value(L, idx);
  if (ttistable(t) && !isempty(slot = tbl_getint(hvalue(t), n))) {
    setobj((Value *)slot, L->top - 1);
    invalidateTMcache(hvalue(t));
  } else {
    Value aux;
    setivalue(&aux, n);
    vm_finishset(L, t, &aux, L->top - 1, ttistable(t) ? slot : NULL);
  }
  L->top--;
}

static void aux_rawset(State *L, int idx, Value *key, int n) {
  Table *t;
  t = gettable(L, idx);
  tbl_set(L, t, key, L->top - 1);
  invalidateTMcache(t);
  L->top -= n;
}

void api_rawset(State *L, int idx) {
  aux_rawset(L, idx, L->top - 2, 2);
}

void api_rawsetp(State *L, int idx, const void *p) {
  Value k;
  setpvalue(&k, (void *)p);
  aux_rawset(L, idx, &k, 1);
}

void api_rawseti(State *L, int idx, Integer n) {
  Table *t;
  t = gettable(L, idx);
  tbl_setint(L, t, n, L->top - 1);
  L->top--;
}

int api_setmetatable(State *L, int objindex) {
  Value *obj;
  Table *mt;
  obj = api_index2value(L, objindex);
  if (ttisnil(L->top - 1))
    mt = NULL;
  else {
    mt = hvalue(L->top - 1);
  }
  switch (ttype(obj)) {
    case T_TABLE: {
      hvalue(obj)->metatable = mt;
      if (mt) gc_checkfinalizer(L, gcvalue(obj), mt);
      break;
    }
    case T_USERDATA: {
      uvalue(obj)->metatable = mt;
      if (mt) gc_checkfinalizer(L, gcvalue(obj), mt);
      break;
    }
    default: {
      G(L)->mt[ttype(obj)] = mt;
      break;
    }
  }
  L->top--;
  return 1;
}

int api_setiuservalue(State *L, int idx, int n) {
  Value *o;
  int res;
  o = api_index2value(L, idx);
  if (!((unsigned)n - 1u < (unsigned)uvalue(o)->nuvalue))
    res = 0;
  else {
    setobj(&uvalue(o)->uv[n - 1], L->top - 1);
    res = 1;
  }
  L->top--;
  return res;
}

/* ---- calls ---- */

void api_call(State *L, int nargs, int nresults) {
  StkId func;
  func = L->top - (nargs + 1);
  do_call(L, func, nresults);
  if (nresults == MULTRET && L->ci->top < L->top)
    L->ci->top = L->top;
}

struct CallS {
  StkId func;
  int nresults;
};

static void f_call(State *L, void *ud) {
  struct CallS *c = (struct CallS *)ud;
  do_callnoyield(L, c->func, c->nresults);
}

int api_pcall(State *L, int nargs, int nresults, int errfunc) {
  struct CallS c;
  int status;
  ptrdiff_t func;
  if (errfunc == 0)
    func = 0;
  else {
    StkId o = index2stack(L, errfunc);
    func = savestack(L, o);
  }
  c.func = L->top - (nargs + 1);
  c.nresults = nresults;
  status = do_pcall(L, f_call, &c, savestack(L, c.func), func);
  if (nresults == MULTRET && L->ci->top < L->top)
    L->ci->top = L->top;
  return status;
}

int api_load(State *L, Reader reader, void *data, const char *chunkname, const char *mode) {
  Zio z;
  int status;
  if (!chunkname) chunkname = "?";
  zio_init(L, &z, reader, data);
  status = do_protectedparser_z(L, &z, chunkname, mode);
  if (status == ST_OK) {
    LClosure *f = clLvalue(L->top - 1);
    if (f->nupvalues >= 1) {
      /* get global table from registry */
      const Value *gt = getGtable(L);
      setobj(f->upvals[0]->v, gt);
    }
  }
  return status;
}

int api_dump(State *L, int (*writer)(State *, const void *, size_t, void *), void *data, int strip) {
  int status;
  Value *o;
  o = L->top - 1;
  if (ttisLclosure(o))
    status = dump_proto(L, clLvalue(o)->p, writer, data, strip);
  else
    status = 1;
  return status;
}

int api_status(State *L) {
  return L->status;
}

/* ---- gc ---- */

int api_gc(State *L, int what, ...) {
  va_list argp;
  int res = 0;
  GlobalState *g = G(L);
  va_start(argp, what);
  switch (what) {
    case GCSTOP: {
      g->gcstopped |= 1;
      break;
    }
    case GCRESTART: {
      g->gcstopped &= ~1;
      g->gcthreshold = g->totalbytes;
      break;
    }
    case GCCOLLECT: {
      gc_fullcollect(L, 0);
      break;
    }
    case GCCOUNT: {
      res = cast_int(g->totalbytes >> 10);
      break;
    }
    case GCCOUNTB: {
      res = cast_int(g->totalbytes & 0x3ff);
      break;
    }
    case GCSTEP: {
      int oldstp = g->gcstopped;
      g->gcstopped &= ~1;
      gc_fullcollect(L, 0);
      g->gcstopped = oldstp;
      res = 1;
      break;
    }
    case GCSETPAUSE: {
      int data = va_arg(argp, int);
      res = g->gcpause;
      g->gcpause = data;
      break;
    }
    case GCSETSTEPMUL: {
      int data = va_arg(argp, int);
      res = g->gcstepmul;
      g->gcstepmul = data;
      break;
    }
    case GCISRUNNING: {
      res = !(g->gcstopped & 1);
      break;
    }
    case GCGEN: {
      res = g->gckind ? GCGEN : GCINC;
      g->gckind = 1;
      break;
    }
    case GCINC: {
      res = g->gckind ? GCGEN : GCINC;
      g->gckind = 0;
      break;
    }
    default: res = -1;
  }
  va_end(argp);
  return res;
}

/* ---- misc ---- */

int api_error(State *L) {
  Value *errobj;
  errobj = L->top - 1;
  if (ttisshrstring(errobj) && tsvalue(errobj) == G(L)->memerrmsg)
    do_throw(L, ST_ERRMEM);
  else
    err_errormsg(L);
  return 0;
}

int api_next(State *L, int idx) {
  Table *t;
  int more;
  t = gettable(L, idx);
  more = tbl_next(L, t, L->top - 1);
  if (more) {
    do_inctop(L);
  } else
    L->top -= 1;
  return more;
}

void api_toclose(State *L, int idx) {
  StkId o = index2stack(L, idx);
  upval_newtbc(L, o);
}

void api_concat(State *L, int n) {
  if (n > 0)
    vm_concat(L, n);
  else {
    setsvalue(L->top, str_newlstr(L, "", 0));
    do_inctop(L);
  }
  gc_checkGC(L);
}

void api_len(State *L, int idx) {
  Value *t;
  t = api_index2value(L, idx);
  vm_objlen(L, L->top, t);
  do_inctop(L);
}

void *api_newuserdatauv(State *L, size_t size, int nuvalue) {
  Udata *u;
  u = udata_new(L, size, nuvalue);
  setuvalue(L->top, u);
  do_inctop(L);
  gc_checkGC(L);
  return u->mem;
}

static const char *aux_upvalue(Value *fi, int n, Value **val, GCHeader **owner) {
  switch (ttypetag(fi)) {
    case ctb(V_CCL): {
      CClosure *f = clCvalue(fi);
      if (!((unsigned)n - 1u < (unsigned)f->nupvalues))
        return NULL;
      *val = &f->upvalue[n - 1];
      if (owner) *owner = (GCHeader *)f;
      return "";
    }
    case ctb(V_LCL): {
      LClosure *f = clLvalue(fi);
      TString *name;
      Proto *p = f->p;
      if (!((unsigned)n - 1u < (unsigned)p->sizeupvalues))
        return NULL;
      *val = f->upvals[n - 1]->v;
      if (owner) *owner = (GCHeader *)f->upvals[n - 1];
      name = p->upvalues[n - 1].name;
      return (name == NULL) ? "(no name)" : getstr(name);
    }
    default: return NULL;
  }
}

const char *api_getupvalue(State *L, int funcindex, int n) {
  const char *name;
  Value *val = NULL;
  name = aux_upvalue(api_index2value(L, funcindex), n, &val, NULL);
  if (name) {
    setobj(L->top, val);
    do_inctop(L);
  }
  return name;
}

const char *api_setupvalue(State *L, int funcindex, int n) {
  const char *name;
  Value *val = NULL;
  GCHeader *owner = NULL;
  Value *fi;
  fi = api_index2value(L, funcindex);
  name = aux_upvalue(fi, n, &val, &owner);
  if (name) {
    L->top--;
    setobj(val, L->top);
  }
  return name;
}

static UpVal **getupvalref(State *L, int fidx, int n, LClosure **pf) {
  static UpVal *const nullup = NULL;
  LClosure *f;
  Value *fi = api_index2value(L, fidx);
  f = clLvalue(fi);
  if (pf) *pf = f;
  if (1 <= n && n <= f->p->sizeupvalues)
    return &f->upvals[n - 1];
  else
    return (UpVal **)&nullup;
}

void *api_upvalueid(State *L, int fidx, int n) {
  Value *fi = api_index2value(L, fidx);
  switch (ttypetag(fi)) {
    case ctb(V_LCL): {
      return *getupvalref(L, fidx, n, NULL);
    }
    case ctb(V_CCL): {
      CClosure *f = clCvalue(fi);
      if (1 <= n && n <= f->nupvalues)
        return &f->upvalue[n - 1];
      return NULL;
    }
    default: return NULL;
  }
}

void api_upvaluejoin(State *L, int fidx1, int n1, int fidx2, int n2) {
  LClosure *f1;
  UpVal **up1 = getupvalref(L, fidx1, n1, &f1);
  UpVal **up2 = getupvalref(L, fidx2, n2, NULL);
  *up1 = *up2;
}

void api_setwarnf(State *L, void (*f)(void *, const char *, int), void *ud) {
  G(L)->ud_warn = ud;
  G(L)->warnf = f;
}

void api_warning(State *L, const char *msg, int tocont) {
  warn_message(L, msg, tocont);
}

/* ---- debug ---- */

int api_getstack(State *L, int level, DebugInfo *ar) {
  return dbg_getstack(L, level, ar);
}

int api_getinfo(State *L, const char *what, DebugInfo *ar) {
  return dbg_getinfo(L, what, ar);
}

const char *api_getlocal(State *L, const DebugInfo *ar, int n) {
  const char *name;
  if (ar == NULL) {
    if (!ttisLclosure(L->top - 1))
      name = NULL;
    else
      name = dbg_getlocalname(clLvalue(L->top - 1)->p, n, 0);
  } else {
    StkId pos = NULL;
    name = dbg_findlocal(L, ar->i_ci, n, &pos);
    if (name) {
      setobj(L->top, pos);
      do_inctop(L);
    }
  }
  return name;
}

const char *api_setlocal(State *L, const DebugInfo *ar, int n) {
  StkId pos = NULL;
  const char *name;
  name = dbg_findlocal(L, ar->i_ci, n, &pos);
  if (name) {
    setobj(pos, L->top - 1);
    L->top--;
  }
  return name;
}

/* ---- coroutine API ---- */

int api_yield(State *L, int nresults) {
  return co_yield(L, nresults);
}

int api_resume(State *L, State *from, int narg, int *nres) {
  return co_resume(L, from, narg, nres);
}

int api_isyieldable(State *L) {
  return co_isyieldable(L);
}

int api_closethread(State *L, State *from) {
  return co_close(from, L);
}

/* ---- warnings ---- */

void warn_message(State *L, const char *msg, int tocont) {
  GlobalState *g = G(L);
  if (g->warnf)
    g->warnf(g->ud_warn, msg, tocont);
}

void warn_error(State *L, const char *where) {
  Value *errobj = L->top - 1;
  const char *msg = (ttisstring(errobj)) ? svalue(errobj) : "error object is not a string";
  warn_message(L, "error in ", 1);
  warn_message(L, where, 1);
  warn_message(L, " (", 1);
  warn_message(L, msg, 1);
  warn_message(L, ")", 0);
}
