cd /workspace && cat > src/api.c <<'EOF'
/*
 * api.c - stack-based interface used by libraries
 */
#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include "core.h"
#include "api.h"

#define isvalid(L, o) (!ttisnil(o) || o != &G(L)->nilvalue)
#define ispseudo(i) ((i) <= REGISTRYINDEX)
#define isupvalue(i) ((i) < REGISTRYINDEX)

Value *api_index2value(State *L, int idx) {
  CallInfo *ci = L->ci;
  if (idx > 0) {
    StkId o = ci->func + idx;
    if (o >= L->top) return &G(L)->nilvalue;
    else return o;
  } else if (!ispseudo(idx)) {
    return L->top + idx;
  } else if (idx == REGISTRYINDEX)
    return &G(L)->l_registry;
  else {
    idx = REGISTRYINDEX - idx;
    if (ttisCclosure(ci->func)) {
      CClosure *func = clCvalue(ci->func);
      return (idx <= func->nupvalues) ? &func->upvalue[idx - 1] : &G(L)->nilvalue;
    } else {
      return &G(L)->nilvalue;
    }
  }
}

static StkId index2stack(State *L, int idx) {
  CallInfo *ci = L->ci;
  if (idx > 0) {
    return ci->func + idx;
  } else {
    return L->top + idx;
  }
}

int api_checkstack(State *L, int n) {
  int res;
  CallInfo *ci = L->ci;
  if (L->stack_last - L->top > n)
    res = 1;
  else {
    int inuse = cast_int(L->top - L->stack) + EXTRA_SLOTS;
    if (inuse > MAXSTACK_SLOTS - n)
      res = 0;
    else {
      do_growstack(L, n, 0);
      res = 1;
    }
  }
  if (res && ci->top < L->top + n)
    ci->top = L->top + n;
  return res;
}

void api_xmove(State *from, State *to, int n) {
  int i;
  if (from == to) return;
  from->top -= n;
  for (i = 0; i < n; i++) {
    setobj(to->top, from->top + i);
    to->top++;
  }
}

int api_absindex(State *L, int idx) {
  return (idx > 0 || ispseudo(idx)) ? idx : cast_int(L->top - L->ci->func) + idx;
}

int api_gettop(State *L) {
  return cast_int(L->top - (L->ci->func + 1));
}

void api_settop(State *L, int idx) {
  CallInfo *ci = L->ci;
  StkId func = ci->func;
  ptrdiff_t diff;
  if (idx >= 0) {
    diff = ((func + 1) + idx) - L->top;
    for (; diff > 0; diff--)
      setnilvalue(L->top++);
  } else {
    diff = idx + 1;
  }
  {
    StkId newtop = L->top + diff;
    if (diff < 0 && L->ntbc > 0 && L->tbc[L->ntbc - 1] >= savestack(L, newtop)) {
      func_close(L, newtop, CLOSEKTOP, 0);
    }
    L->top = newtop;
  }
}

void api_closeslot(State *L, int idx) {
  StkId level = index2stack(L, idx);
  func_close(L, level, CLOSEKTOP, 0);
  setnilvalue(level);
}

static void reverse(State *L, StkId from, StkId to) {
  for (; from < to; from++, to--) {
    Value temp;
    setobj(&temp, from);
    setobj(from, to);
    setobj(to, &temp);
  }
}

void api_rotate(State *L, int idx, int n) {
  StkId p, t, m;
  t = L->top - 1;
  p = index2stack(L, idx);
  m = (n >= 0 ? t - n : p - n - 1);
  reverse(L, p, m);
  reverse(L, m + 1, t);
  reverse(L, p, t);
}

void api_copy(State *L, int fromidx, int toidx) {
  Value *fr, *to;
  fr = api_index2value(L, fromidx);
  to = api_index2value(L, toidx);
  setobj(to, fr);
}

void api_pushvalue(State *L, int idx) {
  setobj(L->top, api_index2value(L, idx));
  do_inctop(L);
}

/* ---- access ---- */

int api_type(State *L, int idx) {
  const Value *o = api_index2value(L, idx);
  return (isvalid(L, o) ? ttype(o) : T_NONE);
}

const char *api_typename(State *L, int t) {
  UNUSED(L);
  return ttypename(t);
}

int api_iscfunction(State *L, int idx) {
  const Value *o = api_index2value(L, idx);
  return (ttislcf(o) || (ttisCclosure(o)));
}

int api_isinteger(State *L, int idx) {
  const Value *o = api_index2value(L, idx);
  return ttisinteger(o);
}

int api_isnumber(State *L, int idx) {
  Number n;
  const Value *o = api_index2value(L, idx);
  return tonumber(o, &n);
}

int api_isstring(State *L, int idx) {
  const Value *o = api_index2value(L, idx);
  return (ttisstring(o) || cvt2str(o));
}

int api_isuserdata(State *L, int idx) {
  const Value *o = api_index2value(L, idx);
  return (ttisfulluserdata(o) || ttislightuserdata(o));
}

int api_rawequal(State *L, int index1, int index2) {
  const Value *o1 = api_index2value(L, index1);
  const Value *o2 = api_index2value(L, index2);
  return (isvalid(L, o1) && isvalid(L, o2)) ? vm_rawequalobj(o1, o2) : 0;
}

void api_arith(State *L, int op) {
  if (op == OPR_UNM || op == OPR_BNOT) {
    setobj(L->top, L->top - 1);
    do_inctop(L);
  }
  obj_arith(L, op, L->top - 2, L->top - 1, L->top - 2);
  L->top--;
}

int api_compare(State *L, int index1, int index2, int op) {
  const Value *o1;
  const Value *o2;
  int i = 0;
  o1 = api_index2value(L, index1);
  o2 = api_index2value(L, index2);
  if (isvalid(L, o1) && isvalid(L, o2)) {
    switch (op) {
      case OPEQ: i = vm_equalobj(L, o1, o2); break;
      case OPLT: i = vm_lessthan(L, o1, o2); break;
      case OPLE: i = vm_lessequal(L, o1, o2); break;
      default: break;
    }
  }
  return i;
}

size_t api_stringtonumber(State *L, const char *s) {
  size_t sz = obj_str2num(s, L->top);
  if (sz != 0)
    do_inctop(L);
  return sz;
}

Number api_tonumberx(State *L, int idx, int *pisnum) {
  Number n = 0;
  const Value *o = api_index2value(L, idx);
  int isnum = tonumber(o, &n);
  if (pisnum)
    *pisnum = isnum;
  return n;
}

