    cl = cclosure_new(L, n);
    cl->f = fn;
    L->top -= n;
    while (n--) {
      setobj(&cl->upvalue[n], L->top + n);
    }
    setclCvalue(L->top, cl);
    do_inctop(L);
    gc_checkGC(L);
  }
