void api_call(State *L, int nargs, int nresults) {
  StkId func;
  func = L->top - (nargs + 1);
  do_call(L, func, nresults);
  if (nresults == MULTRET && L->ci->top < L->top)
    L->ci->top = L->top;
}

struct CallS {
  StkId func;
  int nresults;
};

static void f_call(State *L, void *ud) {
  struct CallS *c = (struct CallS *)ud;
  do_callnoyield(L, c->func, c->nresults);
}

int api_pcall(State *L, int nargs, int nresults, int errfunc) {
  struct CallS c;
  int status;
  ptrdiff_t func;
  if (errfunc == 0)
    func = 0;
  else {
    StkId o = index2stack(L, errfunc);
    func = savestack(L, o);
  }
  c.func = L->top - (nargs + 1);
  c.nresults = nresults;
  status = do_pcall(L, f_call, &c, savestack(L, c.func), func);
  if (nresults == MULTRET && L->ci->top < L->top)
    L->ci->top = L->top;
  return status;
}

int api_load(State *L, Reader reader, void *data, const char *chunkname, const char *mode) {
  Zio z;
  int status;
  if (!chunkname) chunkname = "?";
  zio_init(L, &z, reader, data);
  status = do_protectedparser_z(L, &z, chunkname, mode);
  if (status == ST_OK) {
    LClosure *f = clLvalue(L->top - 1);
    if (f->nupvalues >= 1) {
      /* get global table from registry */
      const Value *gt = getGtable(L);
      setobj(f->upvals[0]->v, gt);
    }
  }
  return status;
}

