/* ---- gc ---- */

int api_gc(State *L, int what, ...) {
  va_list argp;
  int res = 0;
  GlobalState *g = G(L);
  va_start(argp, what);
  switch (what) {
    case GCSTOP: {
      g->gcstopped |= 1;
      break;
    }
    case GCRESTART: {
      g->gcstopped &= ~1;
      g->gcthreshold = g->totalbytes;
      break;
    }
    case GCCOLLECT: {
      gc_fullcollect(L, 0);
      break;
    }
    case GCCOUNT: {
      res = cast_int(g->totalbytes >> 10);
      break;
    }
    case GCCOUNTB: {
      res = cast_int(g->totalbytes & 0x3ff);
      break;
    }
    case GCSTEP: {
      int oldstp = g->gcstopped;
      g->gcstopped &= ~1;
      gc_fullcollect(L, 0);
      g->gcstopped = oldstp;
      res = 1;
      break;
    }
    case GCSETPAUSE: {
      int data = va_arg(argp, int);
      res = g->gcpause;
      g->gcpause = data;
      break;
    }
    case GCSETSTEPMUL: {
      int data = va_arg(argp, int);
      res = g->gcstepmul;
      g->gcstepmul = data;
      break;
    }
    case GCISRUNNING: {
      res = !(g->gcstopped & 1);
      break;
    }
    case GCGEN: {
      res = g->gckind ? GCGEN : GCINC;
      g->gckind = 1;
      break;
    }
    case GCINC: {
      res = g->gckind ? GCGEN : GCINC;
      g->gckind = 0;
      break;
    }
    default: res = -1;
  }
  va_end(argp);
  return res;
}

