static const char *aux_upvalue(Value *fi, int n, Value **val, GCHeader **owner) {
  switch (ttypetag(fi)) {
    case ctb(V_CCL): {
      CClosure *f = clCvalue(fi);
      if (!((unsigned)n - 1u < (unsigned)f->nupvalues))
        return NULL;
      *val = &f->upvalue[n - 1];
      if (owner) *owner = (GCHeader *)f;
      return "";
    }
    case ctb(V_LCL): {
      LClosure *f = clLvalue(fi);
      TString *name;
      Proto *p = f->p;
      if (!((unsigned)n - 1u < (unsigned)p->sizeupvalues))
        return NULL;
      *val = f->upvals[n - 1]->v;
      if (owner) *owner = (GCHeader *)f->upvals[n - 1];
      name = p->upvalues[n - 1].name;
      return (name == NULL) ? "(no name)" : getstr(name);
    }
    default: return NULL;
  }
}

const char *api_getupvalue(State *L, int funcindex, int n) {
