 */
#include <errno.h>
#include <stdarg.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include "core.h"
#include "api.h"

#define LEVELS1 10
#define LEVELS2 11

/* ---- error reporting ---- */

static int pushglobalfuncname(State *L, DebugInfo *ar) {
  int top = api_gettop(L);
  api_getinfo(L, "f", ar);
  api_getfield(L, REGISTRYINDEX, "_LOADED");
  if (!api_istable(L, -1)) { api_settop(L, top); return 0; }
  api_pushnil(L);
  while (api_next(L, -2)) {
    if (api_istable(L, -1) && api_type(L, -2) == T_STRING) {
      api_pushnil(L);
      while (api_next(L, -2)) {
        if (api_rawequal(L, -1, top + 1) && api_type(L, -2) == T_STRING) {
          const char *modname = api_tostring(L, -4);
          const char *fname = api_tostring(L, -2);
          if (strcmp(modname, "_G") == 0)
            api_pushstring(L, fname);
          else
            api_pushfstring(L, "%s.%s", modname, fname);
          api_copy(L, -1, top + 1);
          api_settop(L, top + 1);
          return 1;
        }
        api_pop(L, 1);
      }
    }
    api_pop(L, 1);
  }
  api_settop(L, top);
  return 0;
}

int aux_argerror(State *L, int arg, const char *extramsg) {
  DebugInfo ar;
  if (!api_getstack(L, 0, &ar))
    return aux_error(L, "bad argument #%d (%s)", arg, extramsg);
  api_getinfo(L, "n", &ar);
  if (strcmp(ar.namewhat, "method") == 0) {
    arg--;
    if (arg == 0)
      return aux_error(L, "calling '%s' on bad self (%s)", ar.name, extramsg);
  }
  if (ar.name == NULL)
    ar.name = (pushglobalfuncname(L, &ar)) ? api_tostring(L, -1) : "?";
  return aux_error(L, "bad argument #%d to '%s' (%s)", arg, ar.name, extramsg);
}

int aux_typeerror(State *L, int arg, const char *tname) {
  const char *msg;
  const char *typearg;
  if (aux_getmetafield(L, arg, "__name") == T_STRING)
    typearg = api_tostring(L, -1);
  else if (api_type(L, arg) == T_LIGHTUD)
    typearg = "light userdata";
  else
    typearg = aux_typename(L, arg);
  msg = api_pushfstring(L, "%s expected, got %s", tname, typearg);
  return aux_argerror(L, arg, msg);
}

static void tag_error(State *L, int arg, int tag) {
  aux_typeerror(L, arg, api_typename(L, tag));
}

void aux_where(State *L, int level) {
  DebugInfo ar;
  if (api_getstack(L, level, &ar)) {
    api_getinfo(L, "Sl", &ar);
    if (ar.currentline > 0) {
      api_pushfstring(L, "%s:%d: ", ar.short_src, ar.currentline);
      return;
    }
  }
  api_pushfstring(L, "");
}

int aux_error(State *L, const char *fmt, ...) {
  va_list argp;
  va_start(argp, fmt);
  aux_where(L, 1);
  api_pushvfstring(L, fmt, argp);
  va_end(argp);
  api_concat(L, 2);
  return api_error(L);
}

int aux_fileresult(State *L, int stat, const char *fname) {
  int en = errno;
  if (stat) {
    api_pushboolean(L, 1);
    return 1;
  } else {
    const char *msg;
    aux_pushfail(L);
    msg = (en != 0) ? strerror(en) : "(no extra info)";
    if (fname)
      api_pushfstring(L, "%s: %s", fname, msg);
    else
      api_pushstring(L, msg);
    api_pushinteger(L, en);
    return 3;
  }
}

#include <sys/wait.h>

int aux_execresult(State *L, int stat) {
  if (stat != 0 && errno != 0)
    return aux_fileresult(L, 0, NULL);
  else {
    const char *what = "exit";
    if (WIFEXITED(stat)) stat = WEXITSTATUS(stat);
    else if (WIFSIGNALED(stat)) { stat = WTERMSIG(stat); what = "signal"; }
    if (*what == 'e' && stat == 0)
      api_pushboolean(L, 1);
    else
      aux_pushfail(L);
    api_pushstring(L, what);
    api_pushinteger(L, stat);
    return 3;
  }
}

/* ---- userdata ---- */

int aux_newmetatable(State *L, const char *tname) {
  if (aux_getmetatable(L, tname) != T_NIL)
    return 0;
  api_pop(L, 1);
  api_createtable(L, 0, 2);
  api_pushstring(L, tname);
  api_setfield(L, -2, "__name");
  api_pushvalue(L, -1);
  api_setfield(L, REGISTRYINDEX, tname);
  return 1;
}

void aux_setmetatable(State *L, const char *tname) {
  aux_getmetatable(L, tname);
  api_setmetatable(L, -2);
}

void *aux_testudata(State *L, int ud, const char *tname) {
  void *p = api_touserdata(L, ud);
  if (p != NULL) {
    if (api_getmetatable(L, ud)) {
      aux_getmetatable(L, tname);
      if (!api_rawequal(L, -1, -2))
        p = NULL;
      api_pop(L, 2);
      return p;
    }
  }
  return NULL;
}

void *aux_checkudata(State *L, int ud, const char *tname) {
  void *p = aux_testudata(L, ud, tname);
  aux_argexpected(L, p != NULL, ud, tname);
  return p;
}

/* ---- argument checks ---- */

int aux_checkoption(State *L, int arg, const char *def, const char *const lst[]) {
  const char *name = (def) ? aux_optstring(L, arg, def) : aux_checkstring(L, arg);
  int i;
  for (i = 0; lst[i]; i++)
    if (strcmp(lst[i], name) == 0)
      return i;
  return aux_argerror(L, arg, api_pushfstring(L, "invalid option '%s'", name));
}

void aux_checkstack(State *L, int space, const char *msg) {
  if (!api_checkstack(L, space)) {
    if (msg)
      aux_error(L, "stack overflow (%s)", msg);
    else
      aux_error(L, "stack overflow");
  }
}

void aux_checktype(State *L, int arg, int t) {
  if (api_type(L, arg) != t)
    tag_error(L, arg, t);
}

void aux_checkany(State *L, int arg) {
  if (api_type(L, arg) == T_NONE)
    aux_argerror(L, arg, "value expected");
}

const char *aux_checklstring(State *L, int arg, size_t *len) {
  const char *s = api_tolstring(L, arg, len);
  if (!s) tag_error(L, arg, T_STRING);
  return s;
}

const char *aux_optlstring(State *L, int arg, const char *def, size_t *len) {
  if (api_isnoneornil(L, arg)) {
    if (len)
      *len = (def ? strlen(def) : 0);
    return def;
  } else return aux_checklstring(L, arg, len);
}

Number aux_checknumber(State *L, int arg) {
  int isnum;
  Number d = api_tonumberx(L, arg, &isnum);
  if (!isnum)
    tag_error(L, arg, T_NUMBER);
  return d;
}

Number aux_optnumber(State *L, int arg, Number def) {
  return aux_opt(L, aux_checknumber, arg, def);
}

static void interror(State *L, int arg) {
  if (api_isnumber(L, arg))
    aux_argerror(L, arg, "number has no integer representation");
  else
    tag_error(L, arg, T_NUMBER);
}

Integer aux_checkinteger(State *L, int arg) {
  int isnum;
  Integer d = api_tointegerx(L, arg, &isnum);
  if (!isnum) {
    interror(L, arg);
  }
  return d;
}

Integer aux_optinteger(State *L, int arg, Integer def) {
  return aux_opt(L, aux_checkinteger, arg, def);
}

/* ---- buffers ---- */

typedef struct UBox {
  void *box;
  size_t bsize;
} UBox;

static void *resizebox(State *L, int idx, size_t newsize) {
  UBox *box = (UBox *)api_touserdata(L, idx);
  void *temp = realloc(box->box, newsize);
  if (temp == NULL && newsize > 0) {
    api_pushliteral(L, "not enough memory");
    api_error(L);
  }
  box->box = temp;
  box->bsize = newsize;
  return temp;
}

static int boxgc(State *L) {
  resizebox(L, 1, 0);
  return 0;
}

static const Reg boxmt[] = {
  {"__gc", boxgc},
  {"__close", boxgc},
  {NULL, NULL}
};

static void newbox(State *L) {
  UBox *box = (UBox *)api_newuserdatauv(L, sizeof(UBox), 0);
  box->box = NULL;
  box->bsize = 0;
  if (aux_newmetatable(L, "_UBOX*"))
    aux_setfuncs(L, boxmt, 0);
  api_setmetatable(L, -2);
}

#define buffonstack(B) ((B)->b != (B)->u.init)

#define checkbufferlevel(B,idx) ((void)0)

static size_t newbuffsize(Buffer *B, size_t sz) {
  size_t newsize = (B->size / 2) * 3;
  if (MAX_SIZET - sz < B->n)
    aux_error(B->L, "buffer too large");
  if (newsize < B->n + sz)
    newsize = B->n + sz;
  return newsize;
}

static char *prepbuffsize(Buffer *B, size_t sz, int boxidx) {
  checkbufferlevel(B, boxidx);
  if (B->size - B->n >= sz)
    return B->b + B->n;
  else {
    State *L = B->L;
    char *newbuff;
    size_t newsize = newbuffsize(B, sz);
    if (buffonstack(B))
      newbuff = (char *)resizebox(L, boxidx, newsize);
    else {
      api_remove(L, boxidx);
      newbox(L);
      api_insert(L, boxidx);
      api_toclose(L, boxidx);
      newbuff = (char *)resizebox(L, boxidx, newsize);
      memcpy(newbuff, B->b, B->n * sizeof(char));
    }
    B->b = newbuff;
    B->size = newsize;
    return newbuff + B->n;
  }
}

char *aux_prepbuffsize(Buffer *B, size_t sz) {
  return prepbuffsize(B, sz, -1);
}

void aux_addlstring(Buffer *B, const char *s, size_t l) {
  if (l > 0) {
    char *b = prepbuffsize(B, l, -1);
    memcpy(b, s, l * sizeof(char));
    aux_addsize(B, l);
  }
}

void aux_addstring(Buffer *B, const char *s) {
  aux_addlstring(B, s, strlen(s));
}

void aux_pushresult(Buffer *B) {
  State *L = B->L;
  checkbufferlevel(B, -1);
  api_pushlstring(L, B->b, B->n);
  if (buffonstack(B))
    api_closeslot(L, -2);
  api_remove(L, -2);
}

void aux_pushresultsize(Buffer *B, size_t sz) {
  aux_addsize(B, sz);
  aux_pushresult(B);
}

void aux_addvalue(Buffer *B) {
  State *L = B->L;
  size_t len;
  const char *s = api_tolstring(L, -1, &len);
  char *b = prepbuffsize(B, len, -2);
  memcpy(b, s, len * sizeof(char));
  aux_addsize(B, len);
  api_pop(L, 1);
}

void aux_buffinit(State *L, Buffer *B) {
  B->L = L;
  B->b = B->u.init;
  B->n = 0;
  B->size = sizeof(B->u.init);
  api_pushlightuserdata(L, (void *)B);
}

char *aux_buffinitsize(State *L, Buffer *B, size_t sz) {
  aux_buffinit(L, B);
  return prepbuffsize(B, sz, -1);
}

/* ---- references ---- */

#define freelist (REFNIL - 1)

int aux_ref(State *L, int t) {
  int ref;
  if (api_isnil(L, -1)) {
    api_pop(L, 1);
    return REFNIL;
  }
  t = api_absindex(L, t);
  if (api_rawgeti(L, t, freelist) == T_NIL) {
    ref = 0;
    api_pushinteger(L, 0);
    api_rawseti(L, t, freelist);
  } else {
    ref = (int)api_tointeger(L, -1);
  }
  api_pop(L, 1);
  if (ref != 0) {
    api_rawgeti(L, t, ref);
    api_rawseti(L, t, freelist);
  } else
    ref = (int)api_rawlen(L, t) + 1;
  api_rawseti(L, t, ref);
  return ref;
}

void aux_unref(State *L, int t, int ref) {
  if (ref >= 0) {
    t = api_absindex(L, t);
    api_rawgeti(L, t, freelist);
    api_rawseti(L, t, ref);
    api_pushinteger(L, ref);
    api_rawseti(L, t, freelist);
  }
}

/* ---- load functions ---- */

typedef struct LoadF {
  int n;
  FILE *f;
  char buff[BUFSIZ];
} LoadF;

static const char *getF(State *L, void *ud, size_t *size) {
  LoadF *lf = (LoadF *)ud;
  UNUSED(L);
  if (lf->n > 0) {
    *size = lf->n;
    lf->n = 0;
  } else {
    if (feof(lf->f)) return NULL;
    *size = fread(lf->buff, 1, sizeof(lf->buff), lf->f);
  }
  return lf->buff;
}

static int errfile(State *L, const char *what, int fnameindex) {
  int err = errno;
  const char *filename = api_tostring(L, fnameindex) + 1;
  if (err != 0)
    api_pushfstring(L, "cannot %s %s: %s", what, filename, strerror(err));
  else
    api_pushfstring(L, "cannot %s %s", what, filename);
  api_remove(L, fnameindex);
  return ST_ERRRUN + 10;  /* LUA_ERRFILE */
}

static int skipBOM(FILE *f) {
  int c = getc(f);
  if (c == 0xEF && getc(f) == 0xBB && getc(f) == 0xBF)
    return getc(f);
  else
    return c;
}

static int skipcomment(FILE *f, int *cp) {
  int c = *cp = skipBOM(f);
  if (c == '#') {
    do {
      c = getc(f);
    } while (c != EOF && c != '\n');
    *cp = getc(f);
    return 1;
  } else
    return 0;
}

int aux_loadfilex(State *L, const char *filename, const char *mode) {
  LoadF lf;
  int status, readstatus;
  int c;
  int fnameindex = api_gettop(L) + 1;
  if (filename == NULL) {
    api_pushliteral(L, "=stdin");
    lf.f = stdin;
  } else {
    api_pushfstring(L, "@%s", filename);
    errno = 0;
    lf.f = fopen(filename, "r");
    if (lf.f == NULL) return errfile(L, "open", fnameindex);
  }
  lf.n = 0;
  if (skipcomment(lf.f, &c))
    lf.buff[lf.n++] = '\n';
  if (c == 0x1B && filename != NULL) {
    lf.n = 0;
    lf.f = freopen(filename, "rb", lf.f);
    if (lf.f == NULL) return errfile(L, "reopen", fnameindex);
    skipcomment(lf.f, &c);
  }
  if (c != EOF)
    lf.buff[lf.n++] = (char)c;
  errno = 0;
  status = api_load(L, getF, &lf, api_tostring(L, -1), mode);
  readstatus = ferror(lf.f);
  if (filename) fclose(lf.f);
  if (readstatus) {
    api_settop(L, fnameindex);
    return errfile(L, "read", fnameindex);
  }
  api_remove(L, fnameindex);
  return status;
}

typedef struct LoadS {
  const char *s;
  size_t size;
} LoadS;

static const char *getS(State *L, void *ud, size_t *size) {
  LoadS *ls = (LoadS *)ud;
  UNUSED(L);
  if (ls->size == 0) return NULL;
  *size = ls->size;
  ls->size = 0;
  return ls->s;
}

int aux_loadbufferx(State *L, const char *buff, size_t size, const char *name, const char *mode) {
  LoadS ls;
  ls.s = buff;
  ls.size = size;
  return api_load(L, getS, &ls, name, mode);
}

int aux_loadstring(State *L, const char *s) {
  return aux_loadbuffer(L, s, strlen(s), s);
}

/* ---- misc ---- */

int aux_getmetafield(State *L, int obj, const char *event) {
  if (!api_getmetatable(L, obj))
    return T_NIL;
  else {
    int tt;
    api_pushstring(L, event);
    tt = api_rawget(L, -2);
    if (tt == T_NIL)
      api_pop(L, 2);
    else
      api_remove(L, -2);
    return tt;
  }
}

int aux_callmeta(State *L, int obj, const char *event) {
  obj = api_absindex(L, obj);
  if (aux_getmetafield(L, obj, event) == T_NIL)
    return 0;
  api_pushvalue(L, obj);
  api_call(L, 1, 1);
  return 1;
}

Integer aux_len(State *L, int idx) {
  Integer l;
  int isnum;
  api_len(L, idx);
  l = api_tointegerx(L, -1, &isnum);
  if (!isnum)
    aux_error(L, "object length is not an integer");
  api_pop(L, 1);
  return l;
}

const char *aux_tolstring(State *L, int idx, size_t *len) {
  idx = api_absindex(L, idx);
  if (aux_callmeta(L, idx, "__tostring")) {
    if (!api_isstring(L, -1))
      aux_error(L, "'__tostring' must return a string");
  } else {
    switch (api_type(L, idx)) {
      case T_NUMBER: {
        if (api_isinteger(L, idx))
          api_pushfstring(L, "%I", (long long)api_tointeger(L, idx));
        else
          api_pushfstring(L, "%f", api_tonumber(L, idx));
        break;
      }
      case T_STRING:
        api_pushvalue(L, idx);
        break;
      case T_BOOLEAN:
        api_pushstring(L, (api_toboolean(L, idx) ? "true" : "false"));
        break;
      case T_NIL:
        api_pushliteral(L, "nil");
        break;
      default: {
        int tt = aux_getmetafield(L, idx, "__name");
        const char *kind = (tt == T_STRING) ? api_tostring(L, -1) : aux_typename(L, idx);
        api_pushfstring(L, "%s: %p", kind, api_topointer(L, idx));
        if (tt != T_NIL)
          api_remove(L, -2);
        break;
      }
    }
  }
  return api_tolstring(L, -1, len);
}

void aux_setfuncs(State *L, const Reg *l, int nup) {
  for (; l->name != NULL; l++) {
    if (l->func == NULL)
      api_pushboolean(L, 0);
    else {
      int i;
      for (i = 0; i < nup; i++)
        api_pushvalue(L, -nup);
      api_pushcclosure(L, l->func, nup);
    }
    api_setfield(L, -(nup + 2), l->name);
  }
  api_pop(L, nup);
}

int aux_getsubtable(State *L, int idx, const char *fname) {
  if (api_getfield(L, idx, fname) == T_TABLE)
    return 1;
  else {
    api_pop(L, 1);
    idx = api_absindex(L, idx);
    api_newtable(L);
    api_pushvalue(L, -1);
    api_setfield(L, idx, fname);
    return 0;
  }
}

void aux_requiref(State *L, const char *modname, CFunction openf, int glb) {
  aux_getsubtable(L, REGISTRYINDEX, "_LOADED");
  api_getfield(L, -1, modname);
  if (!api_toboolean(L, -1)) {
    api_pop(L, 1);
    api_pushcfunction(L, openf);
    api_pushstring(L, modname);
    api_call(L, 1, 1);
    api_pushvalue(L, -1);
    api_setfield(L, -3, modname);
  }
  api_remove(L, -2);
  if (glb) {
    api_pushvalue(L, -1);
    api_setglobal(L, modname);
  }
}

void aux_addgsub(Buffer *b, const char *s, const char *p, const char *r) {
  const char *wild;
  size_t l = strlen(p);
  while ((wild = strstr(s, p)) != NULL) {
    aux_addlstring(b, s, wild - s);
    aux_addstring(b, r);
    s = wild + l;
  }
  aux_addstring(b, s);
}

const char *aux_gsub(State *L, const char *s, const char *p, const char *r) {
  Buffer b;
  aux_buffinit(L, &b);
  aux_addgsub(&b, s, p, r);
  aux_pushresult(&b);
  return api_tostring(L, -1);
}

void aux_traceback(State *L, State *L1, const char *msg, int level) {
  dbg_traceback(L, L1, msg, level);
}

void aux_checkversion(State *L) { UNUSED(L); }
EOF
echo ok"}

