/*
 * aux.c - auxiliary functions for building libraries
 */
#include <errno.h>
#include <stdarg.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include "core.h"
#include "api.h"

#define LEVELS1 10
#define LEVELS2 11

/* ---- error reporting ---- */

static int pushglobalfuncname(State *L, DebugInfo *ar) {
  int top = api_gettop(L);
  api_getinfo(L, "f", ar);
  api_getfield(L, REGISTRYINDEX, "_LOADED");
  if (!api_istable(L, -1)) { api_settop(L, top); return 0; }
  api_pushnil(L);
  while (api_next(L, -2)) {
    if (api_istable(L, -1) && api_type(L, -2) == T_STRING) {
      api_pushnil(L);
      while (api_next(L, -2)) {
        if (api_rawequal(L, -1, top + 1) && api_type(L, -2) == T_STRING) {
          const char *modname = api_tostring(L, -4);
          const char *fname = api_tostring(L, -2);
          if (strcmp(modname, "_G") == 0)
            api_pushstring(L, fname);
          else
            api_pushfstring(L, "%s.%s", modname, fname);
          api_copy(L, -1, top + 1);
          api_settop(L, top + 1);
          return 1;
        }
        api_pop(L, 1);
      }
    }
    api_pop(L, 1);
  }
  api_settop(L, top);
  return 0;
}

int aux_argerror(State *L, int arg, const char *extramsg) {
  DebugInfo ar;
  if (!api_getstack(L, 0, &ar))
    return aux_error(L, "bad argument #%d (%s)", arg, extramsg);
  api_getinfo(L, "n", &ar);
  if (strcmp(ar.namewhat, "method") == 0) {
    arg--;
    if (arg == 0)
      return aux_error(L, "calling '%s' on bad self (%s)", ar.name, extramsg);
  }
  if (ar.name == NULL)
    ar.name = (pushglobalfuncname(L, &ar)) ? api_tostring(L, -1) : "?";
  return aux_error(L, "bad argument #%d to '%s' (%s)", arg, ar.name, extramsg);
}

int aux_typeerror(State *L, int arg, const char *tname) {
  const char *msg;
  const char *typearg;
  if (aux_getmetafield(L, arg, "__name") == T_STRING)
    typearg = api_tostring(L, -1);
  else if (api_type(L, arg) == T_LIGHTUD)
    typearg = "light userdata";
  else
    typearg = aux_typename(L, arg);
  msg = api_pushfstring(L, "%s expected, got %s", tname, typearg);
  return aux_argerror(L, arg, msg);
}

static void tag_error(State *L, int arg, int tag) {
