}

void aux_where(State *L, int level) {
  DebugInfo ar;
  if (api_getstack(L, level, &ar)) {
    api_getinfo(L, "Sl", &ar);
    if (ar.currentline > 0) {
      api_pushfstring(L, "%s:%d: ", ar.short_src, ar.currentline);
      return;
    }
  }
  api_pushfstring(L, "");
}

int aux_error(State *L, const char *fmt, ...) {
  va_list argp;
  va_start(argp, fmt);
  aux_where(L, 1);
  api_pushvfstring(L, fmt, argp);
  va_end(argp);
  api_concat(L, 2);
  return api_error(L);
}

int aux_fileresult(State *L, int stat, const char *fname) {
  int en = errno;
  if (stat) {
    api_pushboolean(L, 1);
    return 1;
  } else {
    const char *msg;
    aux_pushfail(L);
    msg = (en != 0) ? strerror(en) : "(no extra info)";
    if (fname)
      api_pushfstring(L, "%s: %s", fname, msg);
    else
      api_pushstring(L, msg);
    api_pushinteger(L, en);
    return 3;
  }
}

#include <sys/wait.h>

int aux_execresult(State *L, int stat) {
  if (stat != 0 && errno != 0)
    return aux_fileresult(L, 0, NULL);
  else {
    const char *what = "exit";
    if (WIFEXITED(stat)) stat = WEXITSTATUS(stat);
    else if (WIFSIGNALED(stat)) { stat = WTERMSIG(stat); what = "signal"; }
    if (*what == 'e' && stat == 0)
      api_pushboolean(L, 1);
    else
      aux_pushfail(L);
    api_pushstring(L, what);
    api_pushinteger(L, stat);
    return 3;
  }
}

