/* ---- buffers ---- */

typedef struct UBox {
  void *box;
  size_t bsize;
} UBox;

static void *resizebox(State *L, int idx, size_t newsize) {
  UBox *box = (UBox *)api_touserdata(L, idx);
  void *temp = realloc(box->box, newsize);
  if (temp == NULL && newsize > 0) {
    api_pushliteral(L, "not enough memory");
    api_error(L);
  }
  box->box = temp;
  box->bsize = newsize;
  return temp;
}

static int boxgc(State *L) {
  resizebox(L, 1, 0);
  return 0;
}

static const Reg boxmt[] = {
  {"__gc", boxgc},
  {"__close", boxgc},
  {NULL, NULL}
};

static void newbox(State *L) {
  UBox *box = (UBox *)api_newuserdatauv(L, sizeof(UBox), 0);
  box->box = NULL;
  box->bsize = 0;
  if (aux_newmetatable(L, "_UBOX*"))
    aux_setfuncs(L, boxmt, 0);
  api_setmetatable(L, -2);
}

#define buffonstack(B) ((B)->b != (B)->u.init)

#define checkbufferlevel(B,idx) ((void)0)

static size_t newbuffsize(Buffer *B, size_t sz) {
  size_t newsize = (B->size / 2) * 3;
  if (MAX_SIZET - sz < B->n)
    aux_error(B->L, "buffer too large");
  if (newsize < B->n + sz)
    newsize = B->n + sz;
  return newsize;
}

static char *prepbuffsize(Buffer *B, size_t sz, int boxidx) {
  checkbufferlevel(B, boxidx);
  if (B->size - B->n >= sz)
    return B->b + B->n;
  else {
    State *L = B->L;
    char *newbuff;
    size_t newsize = newbuffsize(B, sz);
    if (buffonstack(B))
      newbuff = (char *)resizebox(L, boxidx, newsize);
    else {
      api_remove(L, boxidx);
      newbox(L);
      api_insert(L, boxidx);
      api_toclose(L, boxidx);
      newbuff = (char *)resizebox(L, boxidx, newsize);
      memcpy(newbuff, B->b, B->n * sizeof(char));
    }
    B->b = newbuff;
    B->size = newsize;
    return newbuff + B->n;
  }
}

char *aux_prepbuffsize(Buffer *B, size_t sz) {
  return prepbuffsize(B, sz, -1);
}

void aux_addlstring(Buffer *B, const char *s, size_t l) {
  if (l > 0) {
    char *b = prepbuffsize(B, l, -1);
    memcpy(b, s, l * sizeof(char));
    aux_addsize(B, l);
  }
}

void aux_addstring(Buffer *B, const char *s) {
  aux_addlstring(B, s, strlen(s));
}

void aux_pushresult(Buffer *B) {
  State *L = B->L;
  checkbufferlevel(B, -1);
  api_pushlstring(L, B->b, B->n);
  if (buffonstack(B))
    api_closeslot(L, -2);
  api_remove(L, -2);
}

void aux_pushresultsize(Buffer *B, size_t sz) {
  aux_addsize(B, sz);
  aux_pushresult(B);
}

void aux_addvalue(Buffer *B) {
  State *L = B->L;
  size_t len;
  const char *s = api_tolstring(L, -1, &len);
  char *b = prepbuffsize(B, len, -2);
  memcpy(b, s, len * sizeof(char));
  aux_addsize(B, len);
  api_pop(L, 1);
}

void aux_buffinit(State *L, Buffer *B) {
  B->L = L;
  B->b = B->u.init;
  B->n = 0;
  B->size = sizeof(B->u.init);
  api_pushlightuserdata(L, (void *)B);
}

char *aux_buffinitsize(State *L, Buffer *B, size_t sz) {
  aux_buffinit(L, B);
  return prepbuffsize(B, sz, -1);
}

/* ---- references ---- */

#define freelist (REFNIL - 1)

int aux_ref(State *L, int t) {
  int ref;
  if (api_isnil(L, -1)) {
    api_pop(L, 1);
    return REFNIL;
  }
  t = api_absindex(L, t);
  if (api_rawgeti(L, t, freelist) == T_NIL) {
    ref = 0;
    api_pushinteger(L, 0);
    api_rawseti(L, t, freelist);
  } else {
    ref = (int)api_tointeger(L, -1);
  }
  api_pop(L, 1);
  if (ref != 0) {
    api_rawgeti(L, t, ref);
    api_rawseti(L, t, freelist);
  } else
    ref = (int)api_rawlen(L, t) + 1;
  api_rawseti(L, t, ref);
  return ref;
}

void aux_unref(State *L, int t, int ref) {
  if (ref >= 0) {
    t = api_absindex(L, t);
    api_rawgeti(L, t, freelist);
    api_rawseti(L, t, ref);
    api_pushinteger(L, ref);
    api_rawseti(L, t, freelist);
  }
}

/* ---- load functions ---- */

typedef struct LoadF {
  int n;
  FILE *f;
  char buff[BUFSIZ];
} LoadF;

static const char *getF(State *L, void *ud, size_t *size) {
  LoadF *lf = (LoadF *)ud;
  UNUSED(L);
  if (lf->n > 0) {
    *size = lf->n;
    lf->n = 0;
  } else {
    if (feof(lf->f)) return NULL;
    *size = fread(lf->buff, 1, sizeof(lf->buff), lf->f);
  }
  return lf->buff;
}

static int errfile(State *L, const char *what, int fnameindex) {
  int err = errno;
  const char *filename = api_tostring(L, fnameindex) + 1;
  if (err != 0)
    api_pushfstring(L, "cannot %s %s: %s", what, filename, strerror(err));
  else
    api_pushfstring(L, "cannot %s %s", what, filename);
  api_remove(L, fnameindex);
  return ST_ERRRUN + 10;  /* LUA_ERRFILE */
}

static int skipBOM(FILE *f) {
  int c = getc(f);
  if (c == 0xEF && getc(f) == 0xBB && getc(f) == 0xBF)
    return getc(f);
  else
    return c;
}

static int skipcomment(FILE *f, int *cp) {
  int c = *cp = skipBOM(f);
  if (c == '#') {
    do {
      c = getc(f);
    } while (c != EOF && c != '\n');
    *cp = getc(f);
    return 1;
  } else
    return 0;
}

int aux_loadfilex(State *L, const char *filename, const char *mode) {
  LoadF lf;
  int status, readstatus;
  int c;
  int fnameindex = api_gettop(L) + 1;
  if (filename == NULL) {
    api_pushliteral(L, "=stdin");
    lf.f = stdin;
  } else {
    api_pushfstring(L, "@%s", filename);
    errno = 0;
    lf.f = fopen(filename, "r");
    if (lf.f == NULL) return errfile(L, "open", fnameindex);
  }
  lf.n = 0;
  if (skipcomment(lf.f, &c))
    lf.buff[lf.n++] = '\n';
  if (c == 0x1B && filename != NULL) {
    lf.n = 0;
    lf.f = freopen(filename, "rb", lf.f);
    if (lf.f == NULL) return errfile(L, "reopen", fnameindex);
    skipcomment(lf.f, &c);
  }
  if (c != EOF)
    lf.buff[lf.n++] = (char)c;
  errno = 0;
  status = api_load(L, getF, &lf, api_tostring(L, -1), mode);
  readstatus = ferror(lf.f);
  if (filename) fclose(lf.f);
  if (readstatus) {
    api_settop(L, fnameindex);
    return errfile(L, "read", fnameindex);
  }
  api_remove(L, fnameindex);
  return status;
}

typedef struct LoadS {
  const char *s;
  size_t size;
} LoadS;

static const char *getS(State *L, void *ud, size_t *size) {
  LoadS *ls = (LoadS *)ud;
  UNUSED(L);
  if (ls->size == 0) return NULL;
  *size = ls->size;
  ls->size = 0;
  return ls->s;
}

int aux_loadbufferx(State *L, const char *buff, size_t size, const char *name, const char *mode) {
  LoadS ls;
  ls.s = buff;
  ls.size = size;
  return api_load(L, getS, &ls, name, mode);
}

int aux_loadstring(State *L, const char *s) {
  return aux_loadbuffer(L, s, strlen(s), s);
}

