int aux_getmetafield(State *L, int obj, const char *event) {
  if (!api_getmetatable(L, obj))
    return T_NIL;
  else {
    int tt;
    api_pushstring(L, event);
    tt = api_rawget(L, -2);
    if (tt == T_NIL)
      api_pop(L, 2);
    else
      api_remove(L, -2);
    return tt;
  }
}

int aux_callmeta(State *L, int obj, const char *event) {
  obj = api_absindex(L, obj);
  if (aux_getmetafield(L, obj, event) == T_NIL)
    return 0;
  api_pushvalue(L, obj);
  api_call(L, 1, 1);
  return 1;
}

Integer aux_len(State *L, int idx) {
  Integer l;
  int isnum;
  api_len(L, idx);
  l = api_tointegerx(L, -1, &isnum);
  if (!isnum)
    aux_error(L, "object length is not an integer");
  api_pop(L, 1);
  return l;
}

const char *aux_tolstring(State *L, int idx, size_t *len) {
  idx = api_absindex(L, idx);
  if (aux_callmeta(L, idx, "__tostring")) {
    if (!api_isstring(L, -1))
      aux_error(L, "'__tostring' must return a string");
  } else {
    switch (api_type(L, idx)) {
      case T_NUMBER: {
        if (api_isinteger(L, idx))
          api_pushfstring(L, "%I", (long long)api_tointeger(L, idx));
        else
          api_pushfstring(L, "%f", api_tonumber(L, idx));
        break;
      }
      case T_STRING:
        api_pushvalue(L, idx);
        break;
      case T_BOOLEAN:
        api_pushstring(L, (api_toboolean(L, idx) ? "true" : "false"));
        break;
      case T_NIL:
        api_pushliteral(L, "nil");
        break;
      default: {
        int tt = aux_getmetafield(L, idx, "__name");
        const char *kind = (tt == T_STRING) ? api_tostring(L, -1) : aux_typename(L, idx);
        api_pushfstring(L, "%s: %p", kind, api_topointer(L, idx));
        if (tt != T_NIL)
          api_remove(L, -2);
        break;
      }
    }
  }
  return api_tolstring(L, -1, len);
}

void aux_setfuncs(State *L, const Reg *l, int nup) {
  for (; l->name != NULL; l++) {
    if (l->func == NULL)
      api_pushboolean(L, 0);
    else {
      int i;
      for (i = 0; i < nup; i++)
        api_pushvalue(L, -nup);
      api_pushcclosure(L, l->func, nup);
    }
    api_setfield(L, -(nup + 2), l->name);
  }
  api_pop(L, nup);
}

int aux_getsubtable(State *L, int idx, const char *fname) {
  if (api_getfield(L, idx, fname) == T_TABLE)
    return 1;
  else {
    api_pop(L, 1);
    idx = api_absindex(L, idx);
    api_newtable(L);
    api_pushvalue(L, -1);
    api_setfield(L, idx, fname);
    return 0;
  }
}

void aux_requiref(State *L, const char *modname, CFunction openf, int glb) {
  aux_getsubtable(L, REGISTRYINDEX, "_LOADED");
  api_getfield(L, -1, modname);
  if (!api_toboolean(L, -1)) {
    api_pop(L, 1);
    api_pushcfunction(L, openf);
    api_pushstring(L, modname);
    api_call(L, 1, 1);
    api_pushvalue(L, -1);
    api_setfield(L, -3, modname);
  }
  api_remove(L, -2);
  if (glb) {
    api_pushvalue(L, -1);
    api_setglobal(L, modname);
  }
}

void aux_addgsub(Buffer *b, const char *s, const char *p, const char *r) {
  const char *wild;
  size_t l = strlen(p);
  while ((wild = strstr(s, p)) != NULL) {
    aux_addlstring(b, s, wild - s);
    aux_addstring(b, r);
    s = wild + l;
  }
  aux_addstring(b, s);
}

