#define SPACECHARS " \f\n\r\t\v"

static const char *b_str2int(const char *s, int base, Integer *pn) {
  UInteger n = 0;
  int neg = 0;
  s += strspn(s, SPACECHARS);
  if (*s == '-') { s++; neg = 1; }
  else if (*s == '+') s++;
  if (!isalnum((unsigned char)*s))
    return NULL;
  do {
    int digit = (isdigit((unsigned char)*s)) ? *s - '0'
                   : (toupper((unsigned char)*s) - 'A') + 10;
    if (digit >= base) return NULL;
    n = n * base + digit;
    s++;
  } while (isalnum((unsigned char)*s));
  s += strspn(s, SPACECHARS);
  *pn = (Integer)((neg) ? (0u - n) : n);
  return s;
}

static int luaB_tonumber(State *L) {
  if (api_isnoneornil(L, 2)) {
    if (api_type(L, 1) == T_NUMBER) {
      api_settop(L, 1);
      return 1;
    } else {
      size_t l;
      const char *s = api_tolstring(L, 1, &l);
      if (s != NULL && api_stringtonumber(L, s) == l + 1)
        return 1;
      aux_checkany(L, 1);
    }
  } else {
    size_t l;
    const char *s;
    Integer n = 0;
    Integer base = aux_checkinteger(L, 2);
    aux_checktype(L, 1, T_STRING);
    s = api_tolstring(L, 1, &l);
    aux_argcheck(L, 2 <= base && base <= 36, 2, "base out of range");
    if (b_str2int(s, (int)base, &n) == s + l) {
      api_pushinteger(L, n);
      return 1;
    }
  }
  aux_pushfail(L);
  return 1;
}

