static int gcparams[] = { 250, 200, 9600, 20, 50, 68 };

static int luaB_collectgarbage(State *L) {
  static const char *const opts[] = {"stop", "restart", "collect",
    "count", "step", "isrunning", "generational", "incremental", "param", NULL};
  static const int optsnum[] = {GCSTOP, GCRESTART, GCCOLLECT,
    GCCOUNT, GCSTEP, GCISRUNNING, GCGEN, GCINC, GCPARAM};
  int o = optsnum[aux_checkoption(L, 1, "collect", opts)];
  switch (o) {
    case GCCOUNT: {
      int k = api_gc(L, o);
      int b = api_gc(L, GCCOUNTB);
      api_pushnumber(L, (Number)k + ((Number)b / 1024));
      return 1;
    }
    case GCSTEP: {
      Integer step = aux_optinteger(L, 2, 0);
      GlobalState *g = G(L);
      size_t credit = (step > 0) ? (size_t)step * 1024 : (size_t)gcparams[2];
      int res = 0;
      g->gcestimate += credit;  /* reuse field as accumulated step credit */
      if (!(g->gcstopped & 1) || 1) {
        if (g->gcestimate >= g->totalbytes / 4 + 1024) {
          api_gc(L, GCSTEP);
          g->gcestimate = 0;
          res = 1;
        }
      }
      api_pushboolean(L, res);
      return 1;
    }
    case GCISRUNNING: {
      int res = api_gc(L, o);
      api_pushboolean(L, res);
      return 1;
    }
    case GCGEN: case GCINC: {
      int oldmode = api_gc(L, o);
      api_pushstring(L, (oldmode == GCINC) ? "incremental" : "generational");
      return 1;
    }
    case GCPARAM: {
      static const char *const params[] = {"pause", "stepmul", "stepsize",
        "minormul", "majorminor", "minormajor", NULL};
      int p = aux_checkoption(L, 2, NULL, params);
      Integer v = aux_optinteger(L, 3, -1);
      int old = gcparams[p];
      if (v >= 0) {
        gcparams[p] = (int)v;
        if (p == 0) G(L)->gcpause = (int)v;
      }
      api_pushinteger(L, old);
      return 1;
    }
    default: {
      int res = api_gc(L, o);
      api_pushinteger(L, res);
      return 1;
    }
  }
}

