/*
 * lib_table.c - table library
 */
#include <limits.h>
#include <stddef.h>
#include <string.h>
#include <time.h>
#include "core.h"
#include "api.h"

#define TAB_R 1
#define TAB_W 2
#define TAB_L 4
#define TAB_RW (TAB_R | TAB_W)

#define aux_getn(L,n,w) (checktab(L, n, (w) | TAB_L), aux_len(L, n))

static int checkfield(State *L, const char *key, int n) {
  api_pushstring(L, key);
  return (api_rawget(L, -n) != T_NIL);
}

static void checktab(State *L, int arg, int what) {
  if (api_type(L, arg) != T_TABLE) {
    int n = 1;
    if (api_getmetatable(L, arg) &&
        (!(what & TAB_R) || checkfield(L, "__index", ++n)) &&
        (!(what & TAB_W) || checkfield(L, "__newindex", ++n)) &&
        (!(what & TAB_L) || checkfield(L, "__len", ++n))) {
      api_pop(L, n);
    } else
      aux_checktype(L, arg, T_TABLE);
  }
}

static int tcreate(State *L) {
  Integer sizeseq = aux_checkinteger(L, 1);
  Integer sizerest = aux_optinteger(L, 2, 0);
  aux_argcheck(L, 0 <= sizeseq && sizeseq < INT_MAX, 1, "out of range");
  aux_argcheck(L, 0 <= sizerest && sizerest < INT_MAX, 2, "out of range");
  api_createtable(L, (int)sizeseq, (int)sizerest);
  return 1;
}

static int tinsert(State *L) {
  Integer pos;
  Integer e = aux_getn(L, 1, TAB_RW);
  e = e + 1;
  switch (api_gettop(L)) {
    case 2: {
      pos = e;
      break;
    }
    case 3: {
      Integer i;
      pos = aux_checkinteger(L, 2);
      aux_argcheck(L, (UInteger)pos - 1u < (UInteger)e, 2, "position out of bounds");
      for (i = e; i > pos; i--) {
        api_geti(L, 1, i - 1);
        api_seti(L, 1, i);
      }
      break;
    }
    default: {
      return aux_error(L, "wrong number of arguments to 'insert'");
    }
  }
  api_seti(L, 1, pos);
  return 0;
}

static int tremove(State *L) {
  Integer size = aux_getn(L, 1, TAB_RW);
  Integer pos = aux_optinteger(L, 2, size);
  if (pos != size)
    aux_argcheck(L, (UInteger)pos - 1u <= (UInteger)size, 2, "position out of bounds");
  api_geti(L, 1, pos);
  for (; pos < size; pos++) {
    api_geti(L, 1, pos + 1);
    api_seti(L, 1, pos);
  }
  api_pushnil(L);
  api_seti(L, 1, pos);
  return 1;
}

static int tmove(State *L) {
  Integer f = aux_checkinteger(L, 2);
  Integer e = aux_checkinteger(L, 3);
  Integer t = aux_checkinteger(L, 4);
  int tt = !api_isnoneornil(L, 5) ? 5 : 1;
  checktab(L, 1, TAB_R);
  checktab(L, tt, TAB_W);
  if (e >= f) {
    Integer n, i;
    aux_argcheck(L, f > 0 || e < INT64_MAX + f, 3, "too many elements to move");
    n = e - f + 1;
    aux_argcheck(L, t <= INT64_MAX - n + 1, 4, "destination wrap around");
    if (t > e || t <= f || (tt != 1 && !api_compare(L, 1, tt, OPEQ))) {
      for (i = 0; i < n; i++) {
        api_geti(L, 1, f + i);
        api_seti(L, tt, t + i);
      }
    } else {
      for (i = n - 1; i >= 0; i--) {
        api_geti(L, 1, f + i);
        api_seti(L, tt, t + i);
      }
    }
  }
  api_pushvalue(L, tt);
  return 1;
}

static void addfield(State *L, Buffer *b, Integer i) {
  api_geti(L, 1, i);
  if (unlikely(!api_isstring(L, -1)))
    aux_error(L, "invalid value (%s) at index %I in table for 'concat'",
              aux_typename(L, -1), (long long)i);
  aux_addvalue(b);
}

static int tconcat(State *L) {
  Buffer b;
  Integer last = aux_getn(L, 1, TAB_R);
  size_t lsep;
  const char *sep = aux_optlstring(L, 2, "", &lsep);
  Integer i = aux_optinteger(L, 3, 1);
  last = aux_optinteger(L, 4, last);
  aux_buffinit(L, &b);
  for (; i < last; i++) {
    addfield(L, &b, i);
    aux_addlstring(&b, sep, lsep);
  }
  if (i == last)
    addfield(L, &b, i);
  aux_pushresult(&b);
  return 1;
}

static int tpack(State *L) {
  int i;
  int n = api_gettop(L);
  api_createtable(L, n, 1);
  api_insert(L, 1);
  for (i = n; i >= 1; i--)
    api_seti(L, 1, i);
  api_pushinteger(L, n);
  api_setfield(L, 1, "n");
  return 1;
}

static int tunpack(State *L) {
  UInteger n;
  Integer i = aux_optinteger(L, 2, 1);
  Integer e = aux_opt(L, aux_checkinteger, 3, aux_len(L, 1));
  if (i > e) return 0;
  n = (UInteger)e - i;
  if (unlikely(n >= (unsigned int)INT_MAX || !api_checkstack(L, (int)(++n))))
    return aux_error(L, "too many results to unpack");
  for (; i < e; i++) {
    api_geti(L, 1, i);
  }
  api_geti(L, 1, e);
  return (int)n;
}

/* ---- sort ---- */

typedef unsigned int IdxT;
#define RANLIMIT 100u

static unsigned int l_randomizePivot(void) {
  clock_t c = clock();
  time_t t = time(NULL);
  unsigned int buff[4];
  unsigned int i, rnd = 0;
  memcpy(buff, &c, sizeof(c) < sizeof(buff) ? sizeof(c) : sizeof(buff));
  if (sizeof(c) + sizeof(t) <= sizeof(buff))
    memcpy(buff + sizeof(c) / sizeof(unsigned int), &t, sizeof(t));
  for (i = 0; i < 4; i++) rnd += buff[i];
  return rnd;
}

static void set2(State *L, IdxT i, IdxT j) {
  api_seti(L, 1, i);
  api_seti(L, 1, j);
}

static int sort_comp(State *L, int a, int b) {
  if (api_isnil(L, 2))
    return api_compare(L, a, b, OPLT);
  else {
    int res;
    api_pushvalue(L, 2);
    api_pushvalue(L, a - 1);
    api_pushvalue(L, b - 2);
    api_call(L, 2, 1);
    res = api_toboolean(L, -1);
    api_pop(L, 1);
    return res;
  }
}

static IdxT partition(State *L, IdxT lo, IdxT up) {
  IdxT i = lo;
  IdxT j = up - 1;
  for (;;) {
    while (api_geti(L, 1, ++i), sort_comp(L, -1, -2)) {
      if (unlikely(i == up - 1))
        aux_error(L, "invalid order function for sorting");
      api_pop(L, 1);
    }
    while (api_geti(L, 1, --j), sort_comp(L, -3, -1)) {
      if (unlikely(j < i))
        aux_error(L, "invalid order function for sorting");
      api_pop(L, 1);
    }
    if (j < i) {
      api_pop(L, 1);
      set2(L, up - 1, i);
      return i;
    }
    set2(L, i, j);
  }
}

static IdxT choosePivot(IdxT lo, IdxT up, unsigned int rnd) {
  IdxT r4 = (up - lo) / 4;
  IdxT p = rnd % (r4 * 2) + (lo + r4);
  return p;
}

static void auxsort(State *L, IdxT lo, IdxT up, unsigned int rnd) {
  while (lo < up) {
    IdxT p;
    IdxT n;
    api_geti(L, 1, lo);
    api_geti(L, 1, up);
    if (sort_comp(L, -1, -2))
      set2(L, lo, up);
    else
      api_pop(L, 2);
    if (up - lo == 1)
      break;
    if (up - lo < RANLIMIT || rnd == 0)
      p = (lo + up) / 2;
    else
      p = choosePivot(lo, up, rnd);
    api_geti(L, 1, p);
    api_geti(L, 1, lo);
    if (sort_comp(L, -2, -1))
      set2(L, p, lo);
    else {
      api_pop(L, 1);
      api_geti(L, 1, up);
      if (sort_comp(L, -1, -2))
        set2(L, p, up);
      else
        api_pop(L, 2);
    }
    if (up - lo == 2)
      break;
    api_geti(L, 1, p);
    api_pushvalue(L, -1);
    api_geti(L, 1, up - 1);
    set2(L, p, up - 1);
    p = partition(L, lo, up);
    if (p - lo < up - p) {
      auxsort(L, lo, p - 1, rnd);
      n = p - lo;
      lo = p + 1;
    } else {
      auxsort(L, p + 1, up, rnd);
      n = up - p;
      up = p - 1;
    }
    if ((up - lo) / 128 > n)
      rnd = l_randomizePivot();
  }
}

static int sort(State *L) {
  Integer n = aux_getn(L, 1, TAB_RW);
  if (n > 1) {
    aux_argcheck(L, n < INT_MAX, 1, "array too big");
    if (!api_isnoneornil(L, 2))
      aux_checktype(L, 2, T_FUNCTION);
    api_settop(L, 2);
    auxsort(L, 1, (IdxT)n, 0);
  }
  return 0;
}

static const Reg tab_funcs[] = {
  {"concat", tconcat},
  {"create", tcreate},
  {"insert", tinsert},
  {"pack", tpack},
  {"unpack", tunpack},
  {"remove", tremove},
  {"move", tmove},
  {"sort", sort},
  {NULL, NULL}
};

int open_table(State *L) {
  aux_newlib(L, tab_funcs);
  return 1;
}
