      for (i = 0; i < n; i++) {
        api_geti(L, 1, f + i);
        api_seti(L, tt, t + i);
      }
    } else {
      for (i = n - 1; i >= 0; i--) {
        api_geti(L, 1, f + i);
        api_seti(L, tt, t + i);
      }
    }
  }
  api_pushvalue(L, tt);
