/* ---- pseudo-random generator (xoshiro256**) ---- */

typedef uint64_t Rand64;

static Rand64 rotl(Rand64 x, int n) {
  return (x << n) | (x >> (64 - n));
}

static Rand64 nextrand(Rand64 *state) {
  Rand64 state0 = state[0];
  Rand64 state1 = state[1];
  Rand64 state2 = state[2] ^ state0;
  Rand64 state3 = state[3] ^ state1;
  Rand64 res = rotl(state1 * 5, 7) * 9;
  state1 <<= 17;
  state[0] = state0 ^ state3;
  state[1] = state0 ^ state2;
  state[2] = state2 ^ state1;
  state[3] = rotl(state3, 45);
  return res;
}

#define FIGS 53
#define shift64_FIG (64 - FIGS)
#define twotomin53 (0.5 / ((Rand64)1 << (FIGS - 1)))

static Number I2d(Rand64 x) {
  return (Number)(x >> shift64_FIG) * twotomin53;
}

typedef struct {
  Rand64 s[4];
} RanState;

static UInteger project(UInteger ran, UInteger n, RanState *state) {
  if ((n & (n + 1)) == 0)
    return ran & n;
  else {
    UInteger lim = n;
    lim |= (lim >> 1);
    lim |= (lim >> 2);
    lim |= (lim >> 4);
    lim |= (lim >> 8);
    lim |= (lim >> 16);
    lim |= (lim >> 32);
    while ((ran &= lim) > n)
      ran = nextrand(state->s);
    return ran;
  }
}

static int math_random(State *L) {
  Integer low, up;
  UInteger p;
  RanState *g = (RanState *)api_touserdata(L, api_upvalueindex(1));
  Rand64 rv = nextrand(g->s);
  switch (api_gettop(L)) {
    case 0: {
      api_pushnumber(L, I2d(rv));
      return 1;
    }
    case 1: {
      low = 1;
      up = aux_checkinteger(L, 1);
      if (up == 0) {
        api_pushinteger(L, (Integer)rv);
        return 1;
      }
      break;
    }
    case 2: {
      low = aux_checkinteger(L, 1);
      up = aux_checkinteger(L, 2);
      break;
    }
    default: return aux_error(L, "wrong number of arguments");
  }
  aux_argcheck(L, low <= up, 1, "interval is empty");
  p = project((UInteger)rv, (UInteger)up - (UInteger)low, g);
  api_pushinteger(L, (Integer)(p + (UInteger)low));
  return 1;
}

