  int i;
  state[0] = (Rand64)n1;
  state[1] = (Rand64)0xff;
  state[2] = (Rand64)n2;
  state[3] = (Rand64)0;
  for (i = 0; i < 16; i++)
    nextrand(state);
  api_pushinteger(L, (Integer)n1);
  api_pushinteger(L, (Integer)n2);
}

