static UInteger project(UInteger ran, UInteger n, RanState *state) {
  if ((n & (n + 1)) == 0)
    return ran & n;
  else {
    UInteger lim = n;
    lim |= (lim >> 1);
    lim |= (lim >> 2);
    lim |= (lim >> 4);
    lim |= (lim >> 8);
    lim |= (lim >> 16);
    lim |= (lim >> 32);
    while ((ran &= lim) > n)
      ran = nextrand(state->s);
