static const char *matchbalance(MatchState *ms, const char *s, const char *p) {
  if (unlikely(p >= ms->p_end - 1))
    aux_error(ms->L, "malformed pattern (missing arguments to '%%b')");
  if (*s != *p) return NULL;
  else {
