static void push_onecapture(MatchState *ms, int i, const char *s, const char *e) {
  const char *cap;
  ptrdiff_t l = get_onecapture(ms, i, s, e, &cap);
  if (l != CAP_POSITION)
    api_pushlstring(ms->L, cap, l);
}

static int push_captures(MatchState *ms, const char *s, const char *e) {
  int i;
  int nlevels = (ms->level == 0 && s) ? 1 : ms->level;
  aux_checkstack(ms->L, nlevels, "too many captures");
  for (i = 0; i < nlevels; i++)
    push_onecapture(ms, i, s, e);
  return nlevels;
}

static int nospecials(const char *p, size_t l) {
  size_t upto = 0;
  do {
    if (strpbrk(p + upto, SPECIALS))
      return 0;
    upto += strlen(p + upto) + 1;
  } while (upto <= l);
  return 1;
}

static void prepstate(MatchState *ms, State *L, const char *s, size_t ls, const char *p, size_t lp) {
  ms->L = L;
  ms->matchdepth = MAXCCALLS_;
  ms->src_init = s;
  ms->src_end = s + ls;
  ms->p_end = p + lp;
}

static void reprepstate(MatchState *ms) {
  ms->level = 0;
}

static int str_find_aux(State *L, int find) {
  size_t ls, lp;
  const char *s = aux_checklstring(L, 1, &ls);
  const char *p = aux_checklstring(L, 2, &lp);
  size_t init = posrelatI(aux_optinteger(L, 3, 1), ls) - 1;
  if (init > ls) {
    aux_pushfail(L);
    return 1;
  }
  if (find && (api_toboolean(L, 4) || nospecials(p, lp))) {
    const char *s2 = lmemfind(s + init, ls - init, p, lp);
    if (s2) {
      api_pushinteger(L, (s2 - s) + 1);
      api_pushinteger(L, (s2 - s) + lp);
      return 2;
    }
  } else {
    MatchState ms;
    const char *s1 = s + init;
    int anchor = (*p == '^');
    if (anchor) {
      p++; lp--;
    }
    prepstate(&ms, L, s, ls, p, lp);
    do {
      const char *res;
      reprepstate(&ms);
      if ((res = match(&ms, s1, p)) != NULL) {
        if (find) {
          api_pushinteger(L, (s1 - s) + 1);
          api_pushinteger(L, res - s);
          return push_captures(&ms, NULL, 0) + 2;
        } else
          return push_captures(&ms, s1, res);
      }
    } while (s1++ < ms.src_end && !anchor);
  }
  aux_pushfail(L);
  return 1;
}

static int str_find(State *L) { return str_find_aux(L, 1); }
static int str_match(State *L) { return str_find_aux(L, 0); }

typedef struct GMatchState {
  const char *src;
  const char *p;
  const char *lastmatch;
  MatchState ms;
} GMatchState;

static int gmatch_aux(State *L) {
  GMatchState *gm = (GMatchState *)api_touserdata(L, api_upvalueindex(3));
  const char *src;
  gm->ms.L = L;
  for (src = gm->src; src <= gm->ms.src_end; src++) {
    const char *e;
    reprepstate(&gm->ms);
    if ((e = match(&gm->ms, src, gm->p)) != NULL && e != gm->lastmatch) {
      gm->src = gm->lastmatch = e;
      return push_captures(&gm->ms, src, e);
    }
  }
  return 0;
}

static int gmatch(State *L) {
  size_t ls, lp;
  const char *s = aux_checklstring(L, 1, &ls);
  const char *p = aux_checklstring(L, 2, &lp);
  size_t init = posrelatI(aux_optinteger(L, 3, 1), ls) - 1;
  GMatchState *gm;
  api_settop(L, 2);
  gm = (GMatchState *)api_newuserdatauv(L, sizeof(GMatchState), 0);
  if (init > ls)
    init = ls + 1;
  prepstate(&gm->ms, L, s, ls, p, lp);
  gm->src = s + init; gm->p = p; gm->lastmatch = NULL;
  api_pushcclosure(L, gmatch_aux, 3);
  return 1;
}

static void add_s(MatchState *ms, Buffer *b, const char *s, const char *e) {
  size_t l;
  State *L = ms->L;
  const char *news = api_tolstring(L, 3, &l);
  const char *p;
  while ((p = (char *)memchr(news, L_ESC, l)) != NULL) {
    aux_addlstring(b, news, p - news);
    p++;
    if (*p == L_ESC)
      aux_addchar(b, *p);
    else if (*p == '0')
      aux_addlstring(b, s, e - s);
    else if (isdigit(uchar(*p))) {
      const char *cap;
      ptrdiff_t resl = get_onecapture(ms, *p - '1', s, e, &cap);
      if (resl == CAP_POSITION)
        aux_addvalue(b);
      else
        aux_addlstring(b, cap, resl);
    } else
      aux_error(L, "invalid use of '%c' in replacement string", L_ESC);
    l -= p + 1 - news;
    news = p + 1;
  }
  aux_addlstring(b, news, l);
}

static int add_value(MatchState *ms, Buffer *b, const char *s, const char *e, int tr) {
  State *L = ms->L;
  switch (tr) {
    case T_FUNCTION: {
      int n;
      api_pushvalue(L, 3);
      n = push_captures(ms, s, e);
      api_call(L, n, 1);
      break;
    }
    case T_TABLE: {
      push_onecapture(ms, 0, s, e);
      api_gettable(L, 3);
      break;
    }
    default: {
      add_s(ms, b, s, e);
      return 1;
    }
  }
  if (!api_toboolean(L, -1)) {
    api_pop(L, 1);
    aux_addlstring(b, s, e - s);
    return 0;
  } else if (unlikely(!api_isstring(L, -1)))
    return aux_error(L, "invalid replacement value (a %s)", aux_typename(L, -1));
  else {
    aux_addvalue(b);
    return 1;
  }
}

static int str_gsub(State *L) {
  size_t srcl, lp;
  const char *src = aux_checklstring(L, 1, &srcl);
  const char *p = aux_checklstring(L, 2, &lp);
  const char *lastmatch = NULL;
  int tr = api_type(L, 3);
  Integer max_s = aux_optinteger(L, 4, (Integer)srcl + 1);
  int anchor = (*p == '^');
  Integer n = 0;
  int changed = 0;
  MatchState ms;
  Buffer b;
  aux_argexpected(L, tr == T_NUMBER || tr == T_STRING ||
                   tr == T_FUNCTION || tr == T_TABLE, 3,
                      "string/function/table");
  aux_buffinit(L, &b);
  if (anchor) {
    p++; lp--;
  }
  prepstate(&ms, L, src, srcl, p, lp);
  while (n < max_s) {
    const char *e;
    reprepstate(&ms);
    if ((e = match(&ms, src, p)) != NULL && e != lastmatch) {
      n++;
      changed = add_value(&ms, &b, src, e, tr) | changed;
      src = lastmatch = e;
    } else if (src < ms.src_end)
      aux_addchar(&b, *src++);
    else break;
    if (anchor) break;
  }
  if (!changed)
    api_pushvalue(L, 1);
  else {
    aux_addlstring(&b, src, ms.src_end - src);
    aux_pushresult(&b);
  }
  api_pushinteger(L, n);
  return 2;
}

/* ---- format ---- */

#define L_FMTFLAGSF "-+ #0"
#define L_FMTFLAGSX "-#0"
#define L_FMTFLAGSI "-+ 0"
#define L_FMTFLAGSU "-0"
#define L_FMTFLAGSC "-"
#define MAX_ITEMF (110 + DBL_MAX_10_EXP)
#define MAX_ITEM 120
#define MAX_FORMAT 32

static void addquoted(Buffer *b, const char *s, size_t len) {
  aux_addchar(b, '"');
  while (len--) {
    if (*s == '"' || *s == '\\' || *s == '\n') {
      aux_addchar(b, '\\');
      aux_addchar(b, *s);
    } else if (iscntrl(uchar(*s))) {
      char buff[10];
      if (!isdigit(uchar(*(s + 1))))
        snprintf(buff, sizeof(buff), "\\%d", (int)uchar(*s));
      else
        snprintf(buff, sizeof(buff), "\\%03d", (int)uchar(*s));
      aux_addstring(b, buff);
    } else
      aux_addchar(b, *s);
    s++;
  }
  aux_addchar(b, '"');
}

static int quotefloat(State *L, char *buff, Number n) {
  if (n == (Number)HUGE_VAL)
    return snprintf(buff, MAX_ITEM, "1e9999");
  else if (n == -(Number)HUGE_VAL)
    return snprintf(buff, MAX_ITEM, "-1e9999");
  else if (n != n)
    return snprintf(buff, MAX_ITEM, "(0/0)");
  else {
    int nb = snprintf(buff, MAX_ITEM, "%a", n);
    if (memchr(buff, '.', nb) == NULL) {
      char point = localeconv()->decimal_point[0];
      char *ppoint = (char *)memchr(buff, point, nb);
      if (ppoint) *ppoint = '.';
    }
    return nb;
  }
}

static void addliteral(State *L, Buffer *b, int arg) {
  switch (api_type(L, arg)) {
    case T_STRING: {
      size_t len;
      const char *s = api_tolstring(L, arg, &len);
      addquoted(b, s, len);
      break;
    }
    case T_NUMBER: {
      char *buff = aux_prepbuffsize(b, MAX_ITEM);
      int nb;
      if (!api_isinteger(L, arg))
        nb = quotefloat(L, buff, api_tonumber(L, arg));
      else {
        Integer n = api_tointeger(L, arg);
        const char *format = (n == INT64_MIN) ? "0x%llx" : "%lld";
        nb = snprintf(buff, MAX_ITEM, format, (long long)n);
      }
      aux_addsize(b, nb);
      break;
    }
    case T_NIL: case T_BOOLEAN: {
      aux_tolstring(L, arg, NULL);
      aux_addvalue(b);
      break;
    }
    default: {
      aux_argerror(L, arg, "value has no literal form");
    }
  }
}

static const char *get2digits(const char *s) {
  if (isdigit(uchar(*s))) {
    s++;
    if (isdigit(uchar(*s))) s++;
  }
  return s;
}

static void checkformat(State *L, const char *form, const char *flags, int precision) {
  const char *spec = form + 1;
  spec += strspn(spec, flags);
  if (*spec != '0') {
    spec = get2digits(spec);
    if (*spec == '.' && precision) {
      spec++;
      spec = get2digits(spec);
    }
  }
  if (!isalpha(uchar(*spec)))
    aux_error(L, "invalid conversion specification: '%s'", form);
}

static const char *getformat(State *L, const char *strfrmt, char *form) {
  size_t len = strspn(strfrmt, L_FMTFLAGSF "123456789");
  len++;
  if (len >= MAX_FORMAT - 10)
    aux_error(L, "invalid format string to 'format'");
  *(form++) = '%';
  memcpy(form, strfrmt, len * sizeof(char));
  *(form + len) = '\0';
  return strfrmt + len - 1;
}

static void addlenmod(char *form, const char *lenmod) {
  size_t l = strlen(form);
  size_t lm = strlen(lenmod);
  char spec = form[l - 1];
  strcpy(form + l - 1, lenmod);
  form[l + lm - 1] = spec;
  form[l + lm] = '\0';
}

static int str_format(State *L) {
  int top = api_gettop(L);
  int arg = 1;
  size_t sfl;
  const char *strfrmt = aux_checklstring(L, arg, &sfl);
  const char *strfrmt_end = strfrmt + sfl;
  const char *flags;
  Buffer b;
  aux_buffinit(L, &b);
  while (strfrmt < strfrmt_end) {
    if (*strfrmt != L_ESC)
      aux_addchar(&b, *strfrmt++);
    else if (*++strfrmt == L_ESC)
      aux_addchar(&b, *strfrmt++);
    else {
      char form[MAX_FORMAT];
      int maxitem = MAX_ITEM;
      char *buff = aux_prepbuffsize(&b, maxitem);
      int nb = 0;
      if (++arg > top)
        return aux_argerror(L, arg, "no value");
      strfrmt = getformat(L, strfrmt, form);
      switch (*strfrmt++) {
        case 'c': {
          checkformat(L, form, L_FMTFLAGSC, 0);
          nb = snprintf(buff, maxitem, form, (int)aux_checkinteger(L, arg));
          break;
        }
        case 'd': case 'i':
          flags = L_FMTFLAGSI;
          goto intcase;
        case 'u':
          flags = L_FMTFLAGSU;
          goto intcase;
        case 'o': case 'x': case 'X':
          flags = L_FMTFLAGSX;
         intcase: {
          Integer n = aux_checkinteger(L, arg);
          checkformat(L, form, flags, 1);
          addlenmod(form, "ll");
          nb = snprintf(buff, maxitem, form, (long long)n);
          break;
        }
        case 'a': case 'A':
          checkformat(L, form, L_FMTFLAGSF, 1);
          addlenmod(form, "");
          nb = snprintf(buff, maxitem, form, (double)aux_checknumber(L, arg));
          break;
        case 'f': case 'F': case 'e': case 'E': case 'g': case 'G': {
          Number n = aux_checknumber(L, arg);
          checkformat(L, form, L_FMTFLAGSF, 1);
          if (*(strfrmt - 1) == 'f' || *(strfrmt - 1) == 'F') {
            maxitem = MAX_ITEMF;
            buff = aux_prepbuffsize(&b, maxitem);
          }
          addlenmod(form, "");
          nb = snprintf(buff, maxitem, form, (double)n);
          break;
        }
        case 'p': {
          const void *p = api_topointer(L, arg);
          checkformat(L, form, L_FMTFLAGSC, 0);
          if (p == NULL) {
            p = "(null)";
            form[strlen(form) - 1] = 's';
          }
          nb = snprintf(buff, maxitem, form, p);
          break;
        }
        case 'q': {
          if (form[2] != '\0')
            return aux_error(L, "specifier '%%q' cannot have modifiers");
          addliteral(L, &b, arg);
          break;
        }
        case 's': {
          size_t l;
          const char *s = aux_tolstring(L, arg, &l);
          if (form[2] == '\0')
            aux_addvalue(&b);
          else {
            aux_argcheck(L, l == strlen(s), arg, "string contains zeros");
            checkformat(L, form, L_FMTFLAGSC, 1);
            if (strchr(form, '.') == NULL && l >= 100) {
              aux_addvalue(&b);
            } else {
              nb = snprintf(buff, maxitem, form, s);
              api_pop(L, 1);
            }
          }
          break;
        }
        default: {
          return aux_error(L, "invalid conversion '%s' to 'format'", form);
        }
      }
      aux_addsize(&b, nb);
    }
  }
  aux_pushresult(&b);
  return 1;
}

/* ---- pack / unpack ---- */

#define MAXINTSIZE 16
#define NB 8
#define MC ((1 << NB) - 1)
#define SZINT ((int)sizeof(Integer))
#define MAXALIGN 8

static const union {
  int dummy;
  char little;
} nativeendian = {1};

typedef struct Header {
  State *L;
  int islittle;
  int maxalign;
} Header;

typedef enum KOption {
  Kint, Kuint, Kfloat, Knumber, Kdouble, Kchar, Kstring, Kzstr, Kpadding, Kpaddalign, Knop
} KOption;

static int digit(int c) { return '0' <= c && c <= '9'; }

static int getnum(const char **fmt, int df) {
  if (!digit(**fmt))
    return df;
  else {
    int a = 0;
    do {
      a = a * 10 + (*((*fmt)++) - '0');
    } while (digit(**fmt) && a <= ((int)MAXSIZE_ - 9) / 10);
    return a;
  }
}

static int getnumlimit(Header *h, const char **fmt, int df) {
  int sz = getnum(fmt, df);
  if (unlikely(sz > MAXINTSIZE || sz <= 0))
    return aux_error(h->L, "integral size (%d) out of limits [1,%d]", sz, MAXINTSIZE);
  return sz;
}

static void initheader(State *L, Header *h) {
  h->L = L;
  h->islittle = nativeendian.little;
  h->maxalign = 1;
}

static KOption getoption(Header *h, const char **fmt, int *size) {
  int opt = *((*fmt)++);
  *size = 0;
  switch (opt) {
    case 'b': *size = sizeof(char); return Kint;
    case 'B': *size = sizeof(char); return Kuint;
    case 'h': *size = sizeof(short); return Kint;
    case 'H': *size = sizeof(short); return Kuint;
    case 'l': *size = sizeof(long); return Kint;
    case 'L': *size = sizeof(long); return Kuint;
    case 'j': *size = sizeof(Integer); return Kint;
    case 'J': *size = sizeof(Integer); return Kuint;
    case 'T': *size = sizeof(size_t); return Kuint;
    case 'f': *size = sizeof(float); return Kfloat;
    case 'n': *size = sizeof(Number); return Knumber;
    case 'd': *size = sizeof(double); return Kdouble;
    case 'i': *size = getnumlimit(h, fmt, sizeof(int)); return Kint;
    case 'I': *size = getnumlimit(h, fmt, sizeof(int)); return Kuint;
    case 's': *size = getnumlimit(h, fmt, sizeof(size_t)); return Kstring;
    case 'c':
      *size = getnum(fmt, -1);
      if (unlikely(*size == -1))
        aux_error(h->L, "missing size for format option 'c'");
      return Kchar;
    case 'z': return Kzstr;
    case 'x': *size = 1; return Kpadding;
    case 'X': return Kpaddalign;
    case ' ': break;
    case '<': h->islittle = 1; break;
    case '>': h->islittle = 0; break;
    case '=': h->islittle = nativeendian.little; break;
    case '!': {
      const int maxalign = offsetof(struct { char c; union { double d; void *p; Integer i; Number n; } u; }, u);
      h->maxalign = getnumlimit(h, fmt, maxalign);
      break;
    }
    default: aux_error(h->L, "invalid format option '%c'", opt);
  }
  return Knop;
}

static KOption getdetails(Header *h, size_t totalsize, const char **fmt, int *psize, int *ntoalign) {
  KOption opt = getoption(h, fmt, psize);
  int align = *psize;
  if (opt == Kpaddalign) {
    if (**fmt == '\0' || getoption(h, fmt, &align) == Kchar || align == 0)
      aux_argerror(h->L, 1, "invalid next option for option 'X'");
  }
  if (align <= 1 || opt == Kchar)
    *ntoalign = 0;
  else {
    if (align > h->maxalign)
      align = h->maxalign;
    if (unlikely((align & (align - 1)) != 0))
      aux_argerror(h->L, 1, "format asks for alignment not power of 2");
    *ntoalign = (align - (int)(totalsize & (align - 1))) & (align - 1);
  }
  return opt;
}

static void packint(Buffer *b, UInteger n, int islittle, int size, int neg) {
  char *buff = aux_prepbuffsize(b, size);
  int i;
  buff[islittle ? 0 : size - 1] = (char)(n & MC);
  for (i = 1; i < size; i++) {
    n >>= NB;
    buff[islittle ? i : size - 1 - i] = (char)(n & MC);
  }
  if (neg && size > SZINT) {
    for (i = SZINT; i < size; i++)
      buff[islittle ? i : size - 1 - i] = (char)MC;
  }
  aux_addsize(b, size);
}

static void copywithendian(char *dest, const char *src, int size, int islittle) {
  if (islittle == nativeendian.little)
    memcpy(dest, src, size);
  else {
    dest += size - 1;
    while (size-- != 0)
      *(dest--) = *(src++);
  }
}

static int str_pack(State *L) {
  Buffer b;
  Header h;
  const char *fmt = aux_checkstring(L, 1);
  int arg = 1;
  size_t totalsize = 0;
  initheader(L, &h);
  api_pushnil(L);
  aux_buffinit(L, &b);
  while (*fmt != '\0') {
    int size, ntoalign;
    KOption opt = getdetails(&h, totalsize, &fmt, &size, &ntoalign);
    totalsize += ntoalign + size;
    while (ntoalign-- > 0)
      aux_addchar(&b, 0);
    arg++;
    switch (opt) {
      case Kint: {
        Integer n = aux_checkinteger(L, arg);
        if (size < SZINT) {
          Integer lim = (Integer)1 << ((size * NB) - 1);
          aux_argcheck(L, -lim <= n && n < lim, arg, "integer overflow");
        }
        packint(&b, (UInteger)n, h.islittle, size, (n < 0));
        break;
      }
      case Kuint: {
        Integer n = aux_checkinteger(L, arg);
        if (size < SZINT)
          aux_argcheck(L, (UInteger)n < ((UInteger)1 << (size * NB)), arg, "unsigned overflow");
        packint(&b, (UInteger)n, h.islittle, size, 0);
        break;
      }
      case Kfloat: {
        float f = (float)aux_checknumber(L, arg);
        char *buff = aux_prepbuffsize(&b, sizeof(f));
        copywithendian(buff, (char *)&f, sizeof(f), h.islittle);
        aux_addsize(&b, size);
        break;
      }
      case Knumber: {
        Number f = aux_checknumber(L, arg);
        char *buff = aux_prepbuffsize(&b, sizeof(f));
        copywithendian(buff, (char *)&f, sizeof(f), h.islittle);
        aux_addsize(&b, size);
        break;
      }
      case Kdouble: {
        double f = (double)aux_checknumber(L, arg);
        char *buff = aux_prepbuffsize(&b, sizeof(f));
        copywithendian(buff, (char *)&f, sizeof(f), h.islittle);
        aux_addsize(&b, size);
        break;
      }
      case Kchar: {
        size_t len;
        const char *s = aux_checklstring(L, arg, &len);
        aux_argcheck(L, len <= (size_t)size, arg, "string longer than given size");
        aux_addlstring(&b, s, len);
        while (len++ < (size_t)size)
          aux_addchar(&b, 0);
        break;
      }
      case Kstring: {
        size_t len;
        const char *s = aux_checklstring(L, arg, &len);
        aux_argcheck(L, size >= (int)sizeof(size_t) || len < ((size_t)1 << (size * NB)), arg, "string length does not fit in given size");
        packint(&b, (UInteger)len, h.islittle, size, 0);
        aux_addlstring(&b, s, len);
        totalsize += len;
        break;
      }
      case Kzstr: {
        size_t len;
        const char *s = aux_checklstring(L, arg, &len);
        aux_argcheck(L, strlen(s) == len, arg, "string contains zeros");
        aux_addlstring(&b, s, len);
        aux_addchar(&b, '\0');
        totalsize += len + 1;
        break;
      }
      case Kpadding: aux_addchar(&b, 0);  /* FALLTHROUGH */
      case Kpaddalign: case Knop:
        arg--;
        break;
    }
  }
  aux_pushresult(&b);
  return 1;
}

static int str_packsize(State *L) {
  Header h;
  const char *fmt = aux_checkstring(L, 1);
  size_t totalsize = 0;
  initheader(L, &h);
  while (*fmt != '\0') {
    int size, ntoalign;
    KOption opt = getdetails(&h, totalsize, &fmt, &size, &ntoalign);
    aux_argcheck(L, opt != Kstring && opt != Kzstr, 1, "variable-length format");
    size += ntoalign;
    aux_argcheck(L, totalsize <= MAXSIZE_ - size, 1, "format result too large");
    totalsize += size;
  }
  api_pushinteger(L, (Integer)totalsize);
  return 1;
}

static Integer unpackint(State *L, const char *str, int islittle, int size, int issigned) {
  UInteger res = 0;
  int i;
  int limit = (size <= SZINT) ? size : SZINT;
  for (i = limit - 1; i >= 0; i--) {
    res <<= NB;
    res |= (UInteger)(unsigned char)str[islittle ? i : size - 1 - i];
  }
  if (size < SZINT) {
    if (issigned) {
      UInteger mask = (UInteger)1 << (size * NB - 1);
      res = ((res ^ mask) - mask);
    }
  } else if (size > SZINT) {
    int mask = (!issigned || (Integer)res >= 0) ? 0 : MC;
    for (i = limit; i < size; i++) {
      if (unlikely((unsigned char)str[islittle ? i : size - 1 - i] != mask))
        aux_error(L, "%d-byte integer does not fit into Lua Integer", size);
    }
  }
  return (Integer)res;
}

static int str_unpack(State *L) {
  Header h;
  const char *fmt = aux_checkstring(L, 1);
  size_t ld;
  const char *data = aux_checklstring(L, 2, &ld);
  size_t pos = posrelatI(aux_optinteger(L, 3, 1), ld) - 1;
  int n = 0;
  aux_argcheck(L, pos <= ld, 3, "initial position out of string");
  initheader(L, &h);
  while (*fmt != '\0') {
    int size, ntoalign;
    KOption opt = getdetails(&h, pos, &fmt, &size, &ntoalign);
    aux_argcheck(L, (size_t)ntoalign + size <= ld - pos, 2, "data string too short");
    pos += ntoalign;
    aux_checkstack(L, 2, "too many results");
    n++;
    switch (opt) {
      case Kint:
      case Kuint: {
        Integer res = unpackint(L, data + pos, h.islittle, size, (opt == Kint));
        api_pushinteger(L, res);
        break;
      }
      case Kfloat: {
        float f;
        copywithendian((char *)&f, data + pos, sizeof(f), h.islittle);
        api_pushnumber(L, (Number)f);
        break;
      }
      case Knumber: {
        Number f;
        copywithendian((char *)&f, data + pos, sizeof(f), h.islittle);
        api_pushnumber(L, f);
        break;
      }
      case Kdouble: {
        double f;
        copywithendian((char *)&f, data + pos, sizeof(f), h.islittle);
        api_pushnumber(L, (Number)f);
        break;
      }
      case Kchar: {
        api_pushlstring(L, data + pos, size);
        break;
      }
      case Kstring: {
        size_t len = (size_t)unpackint(L, data + pos, h.islittle, size, 0);
        aux_argcheck(L, len <= ld - pos - size, 2, "data string too short");
        api_pushlstring(L, data + pos + size, len);
        pos += len;
        break;
      }
      case Kzstr: {
        size_t len = strlen(data + pos);
        aux_argcheck(L, pos + len < ld, 2, "unfinished string for format 'z'");
        api_pushlstring(L, data + pos, len);
        pos += len + 1;
        break;
      }
      case Kpaddalign: case Kpadding: case Knop:
        n--;
        break;
    }
    pos += size;
  }
  api_pushinteger(L, pos + 1);
  return n + 1;
}

static const Reg strlib[] = {
  {"byte", str_byte},
  {"char", str_char},
  {"dump", str_dump},
  {"find", str_find},
  {"format", str_format},
  {"gmatch", gmatch},
  {"gsub", str_gsub},
  {"len", str_len},
  {"lower", str_lower},
  {"match", str_match},
  {"rep", str_rep},
  {"reverse", str_reverse},
  {"sub", str_sub},
  {"upper", str_upper},
  {"pack", str_pack},
  {"packsize", str_packsize},
  {"unpack", str_unpack},
  {NULL, NULL}
};

static void createmetatable(State *L) {
  aux_newlibtable(L, stringmetamethods);
  aux_setfuncs(L, stringmetamethods, 0);
  api_pushliteral(L, "");
  api_pushvalue(L, -2);
  api_setmetatable(L, -2);
  api_pop(L, 1);
  api_pushvalue(L, -2);
  api_setfield(L, -2, "__index");
  api_pop(L, 1);
}

int open_string(State *L) {
  aux_newlib(L, strlib);
  createmetatable(L);
  return 1;
}
