#define MAXSIZE_ ((size_t)(INT64_MAX))
#define uchar(c) ((unsigned char)(c))

static int str_len(State *L) {
  size_t l;
  aux_checklstring(L, 1, &l);
  api_pushinteger(L, (Integer)l);
  return 1;
}

static size_t posrelatI(Integer pos, size_t len) {
  if (pos > 0)
    return (size_t)pos;
  else if (pos == 0)
    return 1;
  else if (pos < -(Integer)len)
    return 1;
  else return len + (size_t)pos + 1;
}

static size_t getendpos(State *L, int arg, Integer def, size_t len) {
  Integer pos = aux_optinteger(L, arg, def);
  if (pos > (Integer)len)
    return len;
  else if (pos >= 0)
    return (size_t)pos;
  else if (pos < -(Integer)len)
    return 0;
  else return len + (size_t)pos + 1;
}

static int str_sub(State *L) {
  size_t l;
  const char *s = aux_checklstring(L, 1, &l);
  size_t start = posrelatI(aux_checkinteger(L, 2), l);
  size_t end = getendpos(L, 3, -1, l);
  if (start <= end)
    api_pushlstring(L, s + start - 1, (end - start) + 1);
  else api_pushliteral(L, "");
  return 1;
}

static int str_reverse(State *L) {
  size_t l, i;
  Buffer b;
  const char *s = aux_checklstring(L, 1, &l);
  char *p = aux_buffinitsize(L, &b, l);
  for (i = 0; i < l; i++)
    p[i] = s[l - i - 1];
  aux_pushresultsize(&b, l);
  return 1;
}

static int str_lower(State *L) {
  size_t l;
  size_t i;
  Buffer b;
  const char *s = aux_checklstring(L, 1, &l);
  char *p = aux_buffinitsize(L, &b, l);
  for (i = 0; i < l; i++)
    p[i] = tolower(uchar(s[i]));
  aux_pushresultsize(&b, l);
  return 1;
}

static int str_upper(State *L) {
  size_t l;
  size_t i;
  Buffer b;
  const char *s = aux_checklstring(L, 1, &l);
  char *p = aux_buffinitsize(L, &b, l);
  for (i = 0; i < l; i++)
    p[i] = toupper(uchar(s[i]));
  aux_pushresultsize(&b, l);
  return 1;
}

static int str_rep(State *L) {
  size_t l, lsep;
  const char *s = aux_checklstring(L, 1, &l);
  Integer n = aux_checkinteger(L, 2);
  const char *sep = aux_optlstring(L, 3, "", &lsep);
  if (n <= 0)
    api_pushliteral(L, "");
  else if (l + lsep < l || l + lsep > MAXSIZE_ / n)
    return aux_error(L, "resulting string too large");
  else {
    size_t totallen = (size_t)n * l + (size_t)(n - 1) * lsep;
    Buffer b;
    char *p = aux_buffinitsize(L, &b, totallen);
    while (n-- > 1) {
      memcpy(p, s, l * sizeof(char)); p += l;
      if (lsep > 0) {
        memcpy(p, sep, lsep * sizeof(char));
        p += lsep;
      }
    }
    memcpy(p, s, l * sizeof(char));
    aux_pushresultsize(&b, totallen);
  }
  return 1;
}

static int str_byte(State *L) {
  size_t l;
  const char *s = aux_checklstring(L, 1, &l);
  Integer pi = aux_optinteger(L, 2, 1);
  size_t posi = posrelatI(pi, l);
  size_t pose = getendpos(L, 3, pi, l);
  int n, i;
  if (posi > pose) return 0;
  if (unlikely(pose - posi >= (size_t)INT_MAX))
    return aux_error(L, "string slice too long");
  n = (int)(pose - posi) + 1;
  aux_checkstack(L, n, "string slice too long");
  for (i = 0; i < n; i++)
    api_pushinteger(L, uchar(s[posi + i - 1]));
  return n;
}

static int str_char(State *L) {
  int n = api_gettop(L);
  int i;
  Buffer b;
  char *p = aux_buffinitsize(L, &b, n);
  for (i = 1; i <= n; i++) {
    UInteger c = (UInteger)aux_checkinteger(L, i);
    aux_argcheck(L, c <= (UInteger)UCHAR_MAX, i, "value out of range");
    p[i - 1] = uchar((unsigned char)c);
  }
  aux_pushresultsize(&b, n);
  return 1;
}

struct str_Writer {
  int init;
  Buffer B;
};

static int writer(State *L, const void *b, size_t size, void *ud) {
  struct str_Writer *state = (struct str_Writer *)ud;
  if (!state->init) {
    state->init = 1;
    aux_buffinit(L, &state->B);
  }
  aux_addlstring(&state->B, (const char *)b, size);
  return 0;
}

static int str_dump(State *L) {
  struct str_Writer state;
  int strip = api_toboolean(L, 2);
  aux_checktype(L, 1, T_FUNCTION);
  api_settop(L, 1);
  state.init = 0;
  if (unlikely(api_dump(L, writer, &state, strip) != 0))
    return aux_error(L, "unable to dump given function");
  aux_pushresult(&state.B);
  return 1;
}

/* ---- metamethods for strings (arithmetic) ---- */

static int tonum(State *L, int arg) {
  if (api_type(L, arg) == T_NUMBER) {
    api_pushvalue(L, arg);
    return 1;
  } else {
    size_t len;
    const char *s = api_tolstring(L, arg, &len);
    return (s != NULL && api_stringtonumber(L, s) == len + 1);
  }
}

static void trymt(State *L, const char *mtname) {
  api_settop(L, 2);
  if (likely(api_type(L, 2) == T_STRING || !aux_getmetafield(L, 2, mtname)))
    aux_error(L, "attempt to %s a '%s' with a '%s'", mtname + 2,
              aux_typename(L, -2), aux_typename(L, -1));
  api_insert(L, -3);
  api_call(L, 2, 1);
}

static int arith(State *L, int op, const char *mtname) {
  if (tonum(L, 1) && tonum(L, 2))
    api_arith(L, op);
  else
    trymt(L, mtname);
  return 1;
}

static int arith_add(State *L) { return arith(L, OPR_ADD, "__add"); }
static int arith_sub(State *L) { return arith(L, OPR_SUB, "__sub"); }
static int arith_mul(State *L) { return arith(L, OPR_MUL, "__mul"); }
static int arith_mod(State *L) { return arith(L, OPR_MOD, "__mod"); }
static int arith_pow(State *L) { return arith(L, OPR_POW, "__pow"); }
static int arith_div(State *L) { return arith(L, OPR_DIV, "__div"); }
static int arith_idiv(State *L) { return arith(L, OPR_IDIV, "__idiv"); }
