      case Kzstr: {
        size_t len = strlen(data + pos);
        aux_argcheck(L, pos + len < ld, 2, "unfinished string for format 'z'");
        api_pushlstring(L, data + pos, len);
        pos += len + 1;
        break;
      }
      case Kpaddalign: case Kpadding: case Knop:
        n--;
        break;
    }
    pos += size;
  }
  api_pushinteger(L, pos + 1);
  return n + 1;
}

