static const char *checkoption(State *L, const char *conv, ptrdiff_t convlen, char *buff) {
  const char *option = LUA_STRFTIMEOPTIONS;
  int oplen = 1;
  for (; *option != '\0' && oplen <= convlen; option += oplen) {
    if (*option == '|')
      oplen++;
    else if (memcmp(conv, option, oplen) == 0) {
      memcpy(buff, conv, oplen);
      buff[oplen] = '\0';
      return conv + oplen;
    }
  }
  aux_argerror(L, 1, api_pushfstring(L, "invalid conversion specifier '%%%s'", conv));
  return conv;
}

static time_t l_checktime(State *L, int arg) {
  Integer t = aux_checkinteger(L, arg);
  return (time_t)t;
}

#define SIZETIMEFMT 250

static int os_date(State *L) {
  size_t slen;
  const char *s = aux_optlstring(L, 1, "%c", &slen);
  time_t t = aux_opt(L, l_checktime, 2, time(NULL));
  const char *se = s + slen;
  struct tm tmr, *stm;
  if (*s == '!') {
    stm = gmtime_r(&t, &tmr);
    s++;
  } else
    stm = localtime_r(&t, &tmr);
  if (stm == NULL)
    return aux_error(L, "date result cannot be represented in this installation");
  if (strcmp(s, "*t") == 0) {
    api_createtable(L, 0, 9);
    setallfields(L, stm);
  } else {
    char cc[4];
    Buffer b;
    cc[0] = '%';
    aux_buffinit(L, &b);
    while (s < se) {
      if (*s != '%')
        aux_addchar(&b, *s++);
      else {
        size_t reslen;
        char *buff = aux_prepbuffsize(&b, SIZETIMEFMT);
        s++;
        s = checkoption(L, s, se - s, cc + 1);
        reslen = strftime(buff, SIZETIMEFMT, cc, stm);
        aux_addsize(&b, reslen);
      }
    }
    aux_pushresult(&b);
  }
  return 1;
}

static int os_time(State *L) {
  time_t t;
  if (api_isnoneornil(L, 1))
    t = time(NULL);
  else {
    struct tm ts;
    aux_checktype(L, 1, T_TABLE);
    api_settop(L, 1);
    ts.tm_year = getfield(L, "year", -1, 1900);
    ts.tm_mon = getfield(L, "month", -1, 1);
    ts.tm_mday = getfield(L, "day", -1, 0);
    ts.tm_hour = getfield(L, "hour", 12, 0);
    ts.tm_min = getfield(L, "min", 0, 0);
    ts.tm_sec = getfield(L, "sec", 0, 0);
    ts.tm_isdst = getboolfield(L, "isdst");
    t = mktime(&ts);
    setallfields(L, &ts);
  }
  if (t == (time_t)(-1))
    return aux_error(L, "time result cannot be represented in this installation");
  api_pushinteger(L, (Integer)t);
  return 1;
}

static int os_difftime(State *L) {
  time_t t1 = l_checktime(L, 1);
  time_t t2 = l_checktime(L, 2);
  api_pushnumber(L, (Number)difftime(t1, t2));
  return 1;
}

static int os_setlocale(State *L) {
  static const int cat[] = {LC_ALL, LC_COLLATE, LC_CTYPE, LC_MONETARY, LC_NUMERIC, LC_TIME};
  static const char *const catnames[] = {"all", "collate", "ctype", "monetary", "numeric", "time", NULL};
  const char *l = aux_optstring(L, 1, NULL);
  int op = aux_checkoption(L, 2, "all", catnames);
  api_pushstring(L, setlocale(cat[op], l));
  return 1;
}

static int os_exit(State *L) {
  int status;
  if (api_isboolean(L, 1))
    status = (api_toboolean(L, 1) ? EXIT_SUCCESS : EXIT_FAILURE);
  else
    status = (int)aux_optinteger(L, 1, EXIT_SUCCESS);
  if (api_toboolean(L, 2))
    state_close(L);
  if (L) exit(status);
  return 0;
}

static const Reg syslib[] = {
  {"clock", os_clock},
  {"date", os_date},
  {"difftime", os_difftime},
  {"execute", os_execute},
  {"exit", os_exit},
  {"getenv", os_getenv},
  {"remove", os_remove},
  {"rename", os_rename},
  {"setlocale", os_setlocale},
  {"time", os_time},
  {"tmpname", os_tmpname},
  {NULL, NULL}
};

int open_os(State *L) {
  aux_newlib(L, syslib);
  return 1;
}
