static int io_readline(State *L);

#define MAXARGLINE 250

static void aux_lines(State *L, int toclose) {
  int n = api_gettop(L) - 1;
  aux_argcheck(L, n <= MAXARGLINE, MAXARGLINE + 2, "too many arguments");
  api_pushvalue(L, 1);
  api_pushinteger(L, n);
  api_pushboolean(L, toclose);
  api_rotate(L, 2, 3);
  api_pushcclosure(L, io_readline, 3 + n);
}

static int f_lines(State *L) {
  tofile(L);
  aux_lines(L, 0);
  return 1;
}

static int io_lines(State *L) {
  int toclose;
  if (api_isnone(L, 1)) api_pushnil(L);
  if (api_isnil(L, 1)) {
    api_getfield(L, REGISTRYINDEX, IO_INPUT);
    api_replace(L, 1);
    tofile(L);
    toclose = 0;
  } else {
    const char *filename = aux_checkstring(L, 1);
    opencheckfile(L, filename, "r");
    api_replace(L, 1);
    toclose = 1;
  }
  aux_lines(L, toclose);
  if (toclose) {
    api_pushnil(L);
    api_pushnil(L);
    api_pushvalue(L, 1);
    return 4;
  } else
    return 1;
}

/* ---- read ---- */

#define L_MAXLENNUM 200

typedef struct {
  FILE *f;
  int c;
  int n;
  char buff[L_MAXLENNUM + 1];
} RN;

static int nextc(RN *rn) {
  if (unlikely(rn->n >= L_MAXLENNUM)) {
    rn->buff[0] = '\0';
    return 0;
  } else {
    rn->buff[rn->n++] = (char)rn->c;
    rn->c = getc(rn->f);
    return 1;
  }
}

static int test2(RN *rn, const char *set) {
  if (rn->c == set[0] || rn->c == set[1])
    return nextc(rn);
  else return 0;
}

static int readdigits(RN *rn, int hex) {
  int count = 0;
  while ((hex ? isxdigit(rn->c) : isdigit(rn->c)) && nextc(rn))
    count++;
  return count;
}

static int read_number(State *L, FILE *f) {
  RN rn;
  int count = 0;
  int hex = 0;
  char decp[2];
  rn.f = f; rn.n = 0;
  decp[0] = localeconv()->decimal_point[0];
  decp[1] = '.';
  do { rn.c = getc(rn.f); } while (isspace(rn.c));
  test2(&rn, "-+");
  if (test2(&rn, "00")) {
    if (test2(&rn, "xX")) hex = 1;
    else count = 1;
  }
  count += readdigits(&rn, hex);
  if (test2(&rn, decp))
    count += readdigits(&rn, hex);
  if (count > 0 && test2(&rn, (hex ? "pP" : "eE"))) {
    test2(&rn, "-+");
    readdigits(&rn, 0);
  }
  ungetc(rn.c, rn.f);
  rn.buff[rn.n] = '\0';
  if (likely(api_stringtonumber(L, rn.buff)))
    return 1;
  else {
    api_pushnil(L);
    return 0;
  }
}

static int test_eof(State *L, FILE *f) {
  int c = getc(f);
  ungetc(c, f);
  api_pushliteral(L, "");
  return (c != EOF);
}

static int read_line(State *L, FILE *f, int chop) {
  Buffer b;
  int c;
  aux_buffinit(L, &b);
  do {
    char *buff = aux_prepbuffer(&b);
    int i = 0;
    while (i < 1024 && (c = getc(f)) != EOF && c != '\n')
      buff[i++] = (char)c;
    aux_addsize(&b, i);
  } while (c != EOF && c != '\n');
  if (!chop && c == '\n')
    aux_addchar(&b, (char)c);
  aux_pushresult(&b);
  return (c == '\n' || api_rawlen(L, -1) > 0);
}

static void read_all(State *L, FILE *f) {
  size_t nr;
  Buffer b;
  aux_buffinit(L, &b);
  do {
    char *p = aux_prepbuffsize(&b, 1024);
    nr = fread(p, sizeof(char), 1024, f);
    aux_addsize(&b, nr);
  } while (nr == 1024);
  aux_pushresult(&b);
}

static int read_chars(State *L, FILE *f, size_t n) {
  size_t nr;
  char *p;
  Buffer b;
  aux_buffinit(L, &b);
  p = aux_prepbuffsize(&b, n);
  nr = fread(p, sizeof(char), n, f);
  aux_addsize(&b, nr);
  aux_pushresult(&b);
  return (nr > 0);
}

static int g_read(State *L, FILE *f, int first) {
  int nargs = api_gettop(L) - 1;
  int n, success;
  clearerr(f);
  errno = 0;
  if (nargs == 0) {
    success = read_line(L, f, 1);
    n = first + 1;
  } else {
    aux_checkstack(L, nargs + LUA_MINSTACK, "too many arguments");
    success = 1;
    for (n = first; nargs-- && success; n++) {
      if (api_type(L, n) == T_NUMBER) {
        size_t l = (size_t)aux_checkinteger(L, n);
        success = (l == 0) ? test_eof(L, f) : read_chars(L, f, l);
      } else {
        const char *p = aux_checkstring(L, n);
        if (*p == '*') p++;
        switch (*p) {
          case 'n':
            success = read_number(L, f);
            break;
          case 'l':
            success = read_line(L, f, 1);
            break;
          case 'L':
            success = read_line(L, f, 0);
            break;
          case 'a':
            read_all(L, f);
            success = 1;
            break;
          default:
            return aux_argerror(L, n, "invalid format");
        }
      }
    }
  }
  if (ferror(f))
    return aux_fileresult(L, 0, NULL);
  if (!success) {
    api_pop(L, 1);
    aux_pushfail(L);
  }
  return n - first;
}

