/*
 * lib_utf8.c - UTF-8 library
 */
#include <limits.h>
#include <stdlib.h>
#include <string.h>
#include "core.h"
#include "api.h"

#define MAXUNICODE 0x10FFFFu
#define MAXUTF 0x7FFFFFFFu
#define iscont(c) (((c) & 0xC0) == 0x80)
#define iscontp(p) iscont(*(p))

typedef unsigned int utfint;

static Integer u_posrelat(Integer pos, size_t len) {
  if (pos >= 0) return pos;
  else if (0u - (size_t)pos > len) return 0;
  else return (Integer)len + pos + 1;
}

static const char *utf8_decode(const char *s, utfint *val, int strict) {
  static const utfint limits[] = {~(utfint)0, 0x80, 0x800, 0x10000u, 0x200000u, 0x4000000u};
  unsigned int c = (unsigned char)s[0];
  utfint res = 0;
  if (c < 0x80)
    res = c;
  else {
    int count = 0;
    for (; c & 0x40; c <<= 1) {
      unsigned int cc = (unsigned char)s[++count];
      if (!iscont(cc))
        return NULL;
      res = (res << 6) | (cc & 0x3F);
    }
    res |= ((utfint)(c & 0x7F) << (count * 5));
    if (count > 5 || res > MAXUTF || res < limits[count])
      return NULL;
    s += count;
  }
  if (strict) {
    if (res > MAXUNICODE || (0xD800u <= res && res <= 0xDFFFu))
      return NULL;
  }
  if (val) *val = res;
  return s + 1;
}

static int utflen(State *L) {
  Integer n = 0;
  size_t len;
  const char *s = aux_checklstring(L, 1, &len);
  Integer posi = u_posrelat(aux_optinteger(L, 2, 1), len);
  Integer posj = u_posrelat(aux_optinteger(L, 3, -1), len);
  int lax = api_toboolean(L, 4);
  aux_argcheck(L, 1 <= posi && --posi <= (Integer)len, 2, "initial position out of bounds");
  aux_argcheck(L, --posj < (Integer)len, 3, "final position out of bounds");
  while (posi <= posj) {
    const char *s1 = utf8_decode(s + posi, NULL, !lax);
    if (s1 == NULL) {
      aux_pushfail(L);
      api_pushinteger(L, posi + 1);
      return 2;
    }
    posi = s1 - s;
    n++;
  }
  api_pushinteger(L, n);
  return 1;
}

static int codepoint(State *L) {
  size_t len;
  const char *s = aux_checklstring(L, 1, &len);
  Integer posi = u_posrelat(aux_optinteger(L, 2, 1), len);
  Integer pose = u_posrelat(aux_optinteger(L, 3, posi), len);
  int lax = api_toboolean(L, 4);
  int n;
  const char *se;
  aux_argcheck(L, posi >= 1, 2, "out of bounds");
  aux_argcheck(L, pose <= (Integer)len, 3, "out of bounds");
  if (posi > pose) return 0;
  if (pose - posi >= INT_MAX)
    return aux_error(L, "string slice too long");
  n = (int)(pose - posi) + 1;
  aux_checkstack(L, n, "string slice too long");
  n = 0;
  se = s + pose;
  for (s += posi - 1; s < se;) {
    utfint code;
    s = utf8_decode(s, &code, !lax);
    if (s == NULL)
      return aux_error(L, "invalid UTF-8 code");
    api_pushinteger(L, code);
    n++;
  }
  return n;
}

static void pushutfchar(State *L, int arg) {
  UInteger code = (UInteger)aux_checkinteger(L, arg);
  aux_argcheck(L, code <= MAXUTF, arg, "value out of range");
  api_pushfstring(L, "%U", (long)code);
}

static int utfchar(State *L) {
  int n = api_gettop(L);
  if (n == 1)
    pushutfchar(L, 1);
  else {
    int i;
    Buffer b;
    aux_buffinit(L, &b);
    for (i = 1; i <= n; i++) {
      pushutfchar(L, i);
      aux_addvalue(&b);
    }
    aux_pushresult(&b);
  }
  return 1;
}

static int byteoffset(State *L) {
  size_t len;
  const char *s = aux_checklstring(L, 1, &len);
  Integer n = aux_checkinteger(L, 2);
  Integer posi = (n >= 0) ? 1 : (Integer)len + 1;
  posi = u_posrelat(aux_optinteger(L, 3, posi), len);
  aux_argcheck(L, 1 <= posi && --posi <= (Integer)len, 3, "position out of bounds");
  if (n == 0) {
    while (posi > 0 && iscontp(s + posi)) posi--;
  } else {
    if (iscontp(s + posi))
      return aux_error(L, "initial position is a continuation byte");
    if (n < 0) {
      while (n < 0 && posi > 0) {
        do {
          posi--;
        } while (posi > 0 && iscontp(s + posi));
        n++;
      }
    } else {
      n--;
      while (n > 0 && posi < (Integer)len) {
        do {
          posi++;
        } while (iscontp(s + posi));
        n--;
      }
    }
  }
  if (n == 0) {
    api_pushinteger(L, posi + 1);
    /* 5.5 also returns end of character */
    {
      Integer pose = posi;
      if (posi < (Integer)len) {
        do { pose++; } while (iscontp(s + pose));
      }
      api_pushinteger(L, pose);
    }
    return 2;
  } else {
    aux_pushfail(L);
    return 1;
  }
}

static int iter_aux(State *L, int strict) {
  size_t len;
  const char *s = aux_checklstring(L, 1, &len);
  UInteger n = (UInteger)api_tointeger(L, 2);
  if (n < len) {
    while (iscontp(s + n)) n++;
  }
  if (n >= len)
    return 0;
  else {
    utfint code;
    const char *next = utf8_decode(s + n, &code, strict);
    if (next == NULL || iscontp(next))
      return aux_error(L, "invalid UTF-8 code");
    api_pushinteger(L, n + 1);
    api_pushinteger(L, code);
    return 2;
  }
}

static int iter_auxstrict(State *L) { return iter_aux(L, 1); }
static int iter_auxlax(State *L) { return iter_aux(L, 0); }

static int iter_codes(State *L) {
  int lax = api_toboolean(L, 2);
  const char *s = aux_checkstring(L, 1);
  aux_argcheck(L, !iscontp(s), 1, "invalid UTF-8 code");
  api_pushcfunction(L, lax ? iter_auxlax : iter_auxstrict);
  api_pushvalue(L, 1);
  api_pushinteger(L, 0);
  return 3;
}

#define UTF8PATT "[\0-\x7F\xC2-\xFD][\x80-\xBF]*"

static const Reg funcs[] = {
  {"offset", byteoffset},
  {"codepoint", codepoint},
  {"char", utfchar},
  {"len", utflen},
  {"codes", iter_codes},
  {"charpattern", NULL},
  {NULL, NULL}
};

int open_utf8(State *L) {
  aux_newlib(L, funcs);
  api_pushlstring(L, UTF8PATT, sizeof(UTF8PATT) / sizeof(char) - 1);
  api_setfield(L, -2, "charpattern");
  return 1;
}
