static State *getthread(State *L, int *arg) {
  if (api_isthread(L, 1)) {
    *arg = 1;
    return api_tothread(L, 1);
  } else {
    *arg = 0;
    return L;
  }
}

static void settabss(State *L, const char *k, const char *v) {
  api_pushstring(L, v);
  api_setfield(L, -2, k);
}

static void settabsi(State *L, const char *k, int v) {
  api_pushinteger(L, v);
  api_setfield(L, -2, k);
}

static void settabsb(State *L, const char *k, int v) {
  api_pushboolean(L, v);
  api_setfield(L, -2, k);
}

static void treatstackoption(State *L, State *L1, const char *fname) {
  if (L == L1)
    api_rotate(L, -2, 1);
  else
    api_xmove(L1, L, 1);
  api_setfield(L, -2, fname);
}

static int db_getinfo(State *L) {
  DebugInfo ar;
  int arg;
  State *L1 = getthread(L, &arg);
  const char *options = aux_optstring(L, arg + 2, "flnSrtu");
  checkstack(L, L1, 3);
  aux_argcheck(L, options[0] != '>', arg + 2, "invalid option '>'");
  if (api_isfunction(L, arg + 1)) {
    options = api_pushfstring(L, ">%s", options);
    api_pushvalue(L, arg + 1);
    api_xmove(L, L1, 1);
  } else {
    if (!api_getstack(L1, (int)aux_checkinteger(L, arg + 1), &ar)) {
      aux_pushfail(L);
      return 1;
    }
  }
  if (!api_getinfo(L1, options, &ar))
    return aux_argerror(L, arg + 2, "invalid option");
  api_newtable(L);
  if (strchr(options, 'S')) {
    api_pushlstring(L, ar.source, ar.srclen);
    api_setfield(L, -2, "source");
    settabss(L, "short_src", ar.short_src);
    settabsi(L, "linedefined", ar.linedefined);
    settabsi(L, "lastlinedefined", ar.lastlinedefined);
    settabss(L, "what", ar.what);
  }
  if (strchr(options, 'l'))
    settabsi(L, "currentline", ar.currentline);
  if (strchr(options, 'u')) {
    settabsi(L, "nups", ar.nups);
    settabsi(L, "nparams", ar.nparams);
    settabsb(L, "isvararg", ar.isvararg);
  }
  if (strchr(options, 'n')) {
    settabss(L, "name", ar.name);
    settabss(L, "namewhat", ar.namewhat);
  }
  if (strchr(options, 'r')) {
    settabsi(L, "ftransfer", ar.ftransfer);
    settabsi(L, "ntransfer", ar.ntransfer);
  }
  if (strchr(options, 't'))
    settabsb(L, "istailcall", ar.istailcall);
  if (strchr(options, 'L'))
    treatstackoption(L, L1, "activelines");
  if (strchr(options, 'f'))
    treatstackoption(L, L1, "func");
  return 1;
}

static int db_getlocal(State *L) {
  int arg;
  State *L1 = getthread(L, &arg);
  int nvar = (int)aux_checkinteger(L, arg + 2);
  if (api_isfunction(L, arg + 1)) {
    api_pushvalue(L, arg + 1);
    api_pushstring(L, api_getlocal(L, NULL, nvar));
    return 1;
  } else {
    DebugInfo ar;
    const char *name;
    int level = (int)aux_checkinteger(L, arg + 1);
    if (unlikely(!api_getstack(L1, level, &ar)))
      return aux_argerror(L, arg + 1, "level out of range");
    checkstack(L, L1, 1);
    name = api_getlocal(L1, &ar, nvar);
    if (name) {
      api_xmove(L1, L, 1);
      api_pushstring(L, name);
      api_rotate(L, -2, 1);
      return 2;
    } else {
      aux_pushfail(L);
      return 1;
    }
  }
}

static int db_setlocal(State *L) {
  int arg;
  const char *name;
  State *L1 = getthread(L, &arg);
  DebugInfo ar;
  int level = (int)aux_checkinteger(L, arg + 1);
  int nvar = (int)aux_checkinteger(L, arg + 2);
  if (unlikely(!api_getstack(L1, level, &ar)))
    return aux_argerror(L, arg + 1, "level out of range");
  aux_checkany(L, arg + 3);
  api_settop(L, arg + 3);
  checkstack(L, L1, 1);
  api_xmove(L, L1, 1);
  name = api_setlocal(L1, &ar, nvar);
  if (name == NULL)
    api_pop(L1, 1);
  api_pushstring(L, name);
  return 1;
}

static int auxupvalue(State *L, int get) {
  const char *name;
  int n = (int)aux_checkinteger(L, 2);
  aux_checktype(L, 1, T_FUNCTION);
  name = get ? api_getupvalue(L, 1, n) : api_setupvalue(L, 1, n);
  if (name == NULL) return 0;
  api_pushstring(L, name);
  api_insert(L, -(get + 1));
  return get + 1;
}

static int db_getupvalue(State *L) {
  return auxupvalue(L, 1);
}

static int db_setupvalue(State *L) {
