  aux_checktype(L, argf, T_FUNCTION);
  id = api_upvalueid(L, argf, nup);
  if (pnup) {
    aux_argcheck(L, id != NULL, argnup, "invalid upvalue index");
    *pnup = nup;
  }
  return id;
