  checkupval(L, 1, 2, &n1);
  checkupval(L, 3, 4, &n2);
  aux_argcheck(L, !api_iscfunction(L, 1), 1, "Lua function expected");
  aux_argcheck(L, !api_iscfunction(L, 3), 3, "Lua function expected");
  api_upvaluejoin(L, 1, n1, 3, n2);
