static int db_sethook(State *L) {
  int arg;
  State *L1 = getthread(L, &arg);
  UNUSED(L1);
  if (api_isnoneornil(L, arg + 1)) {
    api_settop(L, arg + 1);
  } else {
    aux_checkstring(L, arg + 2);
    aux_checktype(L, arg + 1, T_FUNCTION);
  }
  /* hooks are accepted but not invoked */
  if (!aux_getsubtable(L, REGISTRYINDEX, HOOKKEY)) {
    api_pushliteral(L, "k");
    api_setfield(L, -2, "__mode");
    api_pushvalue(L, -1);
    api_setmetatable(L, -2);
  }
  api_pushvalue(L, arg + 1);
  api_rawsetp(L, -2, L1);
  api_pop(L, 1);
  return 0;
}

static int db_gethook(State *L) {
  int arg;
  State *L1 = getthread(L, &arg);
  if (api_getfield(L, REGISTRYINDEX, HOOKKEY) == T_NIL) {
    api_pop(L, 1);
    aux_pushfail(L);
    return 1;
  }
  api_rawgetp(L, -1, L1);
  if (api_isnil(L, -1)) {
    api_pop(L, 2);
    aux_pushfail(L);
    return 1;
  }
  api_remove(L, -2);
  api_pushstring(L, "");
  api_pushinteger(L, 0);
  return 3;
}

static int db_debug(State *L) {
  for (;;) {
    char buffer[250];
    fprintf(stderr, "%s", "lua_debug> ");
    fflush(stderr);
    if (fgets(buffer, sizeof(buffer), stdin) == NULL ||
