cat > src/dump.c <<'EOF'
/*
 * dump.c - save and load precompiled chunks (own binary format)
 */
#include <stdlib.h>
#include <string.h>
#include "core.h"
#include "api.h"

#define SIGNATURE "\x1bLua"
#define FORMAT_VERSION 0x55
#define FORMAT_BYTE 0x01
#define DATA_MAGIC "\x19\x93\r\n\x1a\n"

typedef struct DumpState {
  State *L;
  int (*writer)(State *, const void *, size_t, void *);
  void *data;
  int strip;
  int status;
} DumpState;

static void dumpBlock(DumpState *D, const void *b, size_t size) {
  if (D->status == 0 && size > 0)
    D->status = (*D->writer)(D->L, b, size, D->data);
}

static void dumpByte(DumpState *D, int y) {
  uint8_t x = (uint8_t)y;
  dumpBlock(D, &x, 1);
}

static void dumpInt(DumpState *D, int x) {
  dumpBlock(D, &x, sizeof(int));
}

static void dumpSize(DumpState *D, size_t x) {
  dumpBlock(D, &x, sizeof(size_t));
}

static void dumpInteger(DumpState *D, Integer x) {
  dumpBlock(D, &x, sizeof(Integer));
}

static void dumpNumber(DumpState *D, Number x) {
  dumpBlock(D, &x, sizeof(Number));
}

static void dumpString(DumpState *D, const TString *s) {
  if (s == NULL)
    dumpSize(D, 0);
  else {
    size_t size = tsslen(s);
    const char *str = getstr(s);
    dumpSize(D, size + 1);
    dumpBlock(D, str, size);
  }
}

static void dumpFunction(DumpState *D, const Proto *f, TString *psource);

static void dumpCode(DumpState *D, const Proto *f) {
  dumpInt(D, f->sizecode);
  dumpBlock(D, f->code, (size_t)f->sizecode * sizeof(Instruction));
}

static void dumpConstants(DumpState *D, const Proto *f) {
  int i;
  int n = f->sizek;
  dumpInt(D, n);
  for (i = 0; i < n; i++) {
    const Value *o = &f->k[i];
    int tt = ttypetag(o);
    dumpByte(D, tt);
    switch (tt) {
      case V_FLT: dumpNumber(D, fltvalue(o)); break;
      case V_INT: dumpInteger(D, ivalue(o)); break;
      case ctb(V_SHRSTR): case ctb(V_LNGSTR): dumpString(D, tsvalue(o)); break;
      default: break;
    }
  }
}

static void dumpProtos(DumpState *D, const Proto *f) {
  int i;
  int n = f->sizep;
  dumpInt(D, n);
  for (i = 0; i < n; i++)
    dumpFunction(D, f->p[i], f->source);
}

static void dumpUpvalues(DumpState *D, const Proto *f) {
  int i, n = f->sizeupvalues;
  dumpInt(D, n);
  for (i = 0; i < n; i++) {
    dumpByte(D, f->upvalues[i].instack);
    dumpByte(D, f->upvalues[i].idx);
    dumpByte(D, f->upvalues[i].kind);
  }
}

static void dumpDebug(DumpState *D, const Proto *f) {
  int i, n;
  n = (D->strip) ? 0 : f->sizelineinfo;
  dumpInt(D, n);
  dumpBlock(D, f->lineinfo, (size_t)n * sizeof(int));
  n = (D->strip) ? 0 : f->sizelocvars;
  dumpInt(D, n);
  for (i = 0; i < n; i++) {
    dumpString(D, f->locvars[i].varname);
    dumpInt(D, f->locvars[i].startpc);
    dumpInt(D, f->locvars[i].endpc);
  }
  n = (D->strip) ? 0 : f->sizeupvalues;
  dumpInt(D, n);
  for (i = 0; i < n; i++)
    dumpString(D, f->upvalues[i].name);
}

static void dumpFunction(DumpState *D, const Proto *f, TString *psource) {
  if (D->strip || f->source == psource)
    dumpString(D, NULL);
  else
    dumpString(D, f->source);
  dumpInt(D, f->linedefined);
  dumpInt(D, f->lastlinedefined);
  dumpByte(D, f->numparams);
  dumpByte(D, f->is_vararg);
  dumpByte(D, f->maxstacksize);
  dumpCode(D, f);
  dumpConstants(D, f);
  dumpUpvalues(D, f);
  dumpProtos(D, f);
  dumpDebug(D, f);
}

static void dumpHeader(DumpState *D) {
  dumpBlock(D, SIGNATURE, 4);
  dumpByte(D, FORMAT_VERSION);
  dumpByte(D, FORMAT_BYTE);
  dumpBlock(D, DATA_MAGIC, 6);
  dumpByte(D, sizeof(Instruction));
  dumpByte(D, sizeof(Integer));
  dumpByte(D, sizeof(Number));
  dumpInteger(D, 0x5678);
  dumpNumber(D, 370.5);
}

int dump_proto(State *L, const Proto *f, int (*w)(State *, const void *, size_t, void *), void *data, int strip) {
  DumpState D;
  D.L = L;
  D.writer = w;
  D.data = data;
  D.strip = strip;
  D.status = 0;
  dumpHeader(&D);
  dumpByte(&D, f->sizeupvalues);
  dumpFunction(&D, f, NULL);
  return D.status;
}

/* ---- undump ---- */

typedef struct LoadState {
  State *L;
  Zio *Z;
  const char *name;
} LoadState;

static void error(LoadState *S, const char *why) {
  obj_pushfstring(S->L, "%s: bad binary format (%s)", S->name, why);
  do_throw(S->L, ST_ERRSYNTAX);
}

static void loadBlock(LoadState *S, void *b, size_t size) {
  if (zio_read(S->Z, b, size) != 0)
    error(S, "truncated chunk");
}

static uint8_t loadByte(LoadState *S) {
  int b = zgetc(S->Z);
  if (b == EOZ)
    error(S, "truncated chunk");
  return (uint8_t)b;
}

static int loadInt(LoadState *S) {
  int x;
  loadBlock(S, &x, sizeof(int));
  return x;
}

static size_t loadSize(LoadState *S) {
  size_t x;
  loadBlock(S, &x, sizeof(size_t));
  return x;
}

static Number loadNumber(LoadState *S) {
  Number x;
  loadBlock(S, &x, sizeof(Number));
  return x;
}

static Integer loadInteger(LoadState *S) {
  Integer x;
  loadBlock(S, &x, sizeof(Integer));
  return x;
}

static TString *loadStringN(LoadState *S, Proto *p) {
  State *L = S->L;
  TString *ts;
  size_t size = loadSize(S);
  if (size == 0)
    return NULL;
  else if (--size <= MAXSHORTLEN) {
    char buff[MAXSHORTLEN];
    loadBlock(S, buff, size);
    ts = str_newlstr(L, buff, size);
  } else {
    ts = str_createlng(L, size);
    setsvalue(L->top, ts);
    do_inctop(L);
    loadBlock(S, getstr(ts), size);
    L->top--;
  }
  UNUSED(p);
  return ts;
}

static TString *loadString(LoadState *S, Proto *p) {
  TString *st = loadStringN(S, p);
  if (st == NULL)
    error(S, "bad format for constant string");
  return st;
}

static void loadFunction(LoadState *S, Proto *f, TString *psource);

static void loadCode(LoadState *S, Proto *f) {
  int n = loadInt(S);
  if (n < 0) error(S, "bad code size");
  f->code = mem_newvector(S->L, n, Instruction);
  f->sizecode = n;
  loadBlock(S, f->code, (size_t)n * sizeof(Instruction));
}

static void loadConstants(LoadState *S, Proto *f) {
  int i;
  int n = loadInt(S);
  if (n < 0) error(S, "bad constants size");
  f->k = mem_newvector(S->L, n, Value);
  f->sizek = n;
  for (i = 0; i < n; i++)
    setnilvalue(&f->k[i]);
  for (i = 0; i < n; i++) {
    Value *o = &f->k[i];
    int t = loadByte(S);
    switch (t) {
      case V_NIL: setnilvalue(o); break;
      case V_FALSE: setbfvalue(o); break;
      case V_TRUE: setbtvalue(o); break;
      case V_FLT: setfltvalue(o, loadNumber(S)); break;
      case V_INT: setivalue(o, loadInteger(S)); break;
      case ctb(V_SHRSTR): case ctb(V_LNGSTR):
        setsvalue(o, loadString(S, f));
        break;
      default: error(S, "bad constant type");
    }
  }
}

static void loadProtos(LoadState *S, Proto *f) {
  int i;
  int n = loadInt(S);
  if (n < 0) error(S, "bad protos size");
  f->p = mem_newvector(S->L, n, Proto *);
  f->sizep = n;
  for (i = 0; i < n; i++)
    f->p[i] = NULL;
  for (i = 0; i < n; i++) {
    f->p[i] = proto_new(S->L);
    loadFunction(S, f->p[i], f->source);
  }
}

static void loadUpvalues(LoadState *S, Proto *f) {
  int i, n;
  n = loadInt(S);
  if (n < 0) error(S, "bad upvalues size");
  f->upvalues = mem_newvector(S->L, n, Upvaldesc);
  f->sizeupvalues = n;
  for (i = 0; i < n; i++)
    f->upvalues[i].name = NULL;
  for (i = 0; i < n; i++) {
    f->upvalues[i].instack = loadByte(S);
    f->upvalues[i].idx = loadByte(S);
    f->upvalues[i].kind = loadByte(S);
  }
}

static void loadDebug(LoadState *S, Proto *f) {
  int i, n;
  n = loadInt(S);
  if (n < 0) error(S, "bad lineinfo size");
  f->lineinfo = mem_newvector(S->L, n, int);
  f->sizelineinfo = n;
  loadBlock(S, f->lineinfo, (size_t)n * sizeof(int));
  n = loadInt(S);
  if (n < 0) error(S, "bad locvars size");
  f->locvars = mem_newvector(S->L, n, LocVar);
  f->sizelocvars = n;
  for (i = 0; i < n; i++)
    f->locvars[i].varname = NULL;
  for (i = 0; i < n; i++) {
    f->locvars[i].varname = loadStringN(S, f);
    f->locvars[i].startpc = loadInt(S);
    f->locvars[i].endpc = loadInt(S);
  }
  n = loadInt(S);
  if (n < 0 || n > f->sizeupvalues) error(S, "bad upvalue names size");
  for (i = 0; i < n; i++)
    f->upvalues[i].name = loadStringN(S, f);
}

static void loadFunction(LoadState *S, Proto *f, TString *psource) {
  f->source = loadStringN(S, f);
  if (f->source == NULL)
    f->source = psource;
  f->linedefined = loadInt(S);
  f->lastlinedefined = loadInt(S);
  f->numparams = loadByte(S);
  f->is_vararg = loadByte(S);
  f->maxstacksize = loadByte(S);
  loadCode(S, f);
  loadConstants(S, f);
  loadUpvalues(S, f);
  loadProtos(S, f);
  loadDebug(S, f);
}

static void checkliteral(LoadState *S, const char *s, const char *msg) {
  char buff[12];
  size_t len = strlen(s);
  loadBlock(S, buff, len);
  if (memcmp(s, buff, len) != 0)
    error(S, msg);
}

static void fchecksize(LoadState *S, size_t size, const char *tname) {
  if (loadByte(S) != size)
    error(S, obj_pushfstring(S->L, "%s size mismatch", tname));
}

static void checkHeader(LoadState *S) {
  checkliteral(S, &SIGNATURE[1], "not a binary chunk");
  if (loadByte(S) != FORMAT_VERSION)
    error(S, "version mismatch");
  if (loadByte(S) != FORMAT_BYTE)
    error(S, "format mismatch");
  checkliteral(S, DATA_MAGIC, "corrupted chunk");
  fchecksize(S, sizeof(Instruction), "Instruction");
  fchecksize(S, sizeof(Integer), "lua_Integer");
  fchecksize(S, sizeof(Number), "lua_Number");
  if (loadInteger(S) != 0x5678)
    error(S, "integer format mismatch");
  if (loadNumber(S) != 370.5)
    error(S, "float format mismatch");
}

LClosure *undump_chunk(State *L, Zio *Z, const char *name) {
  LoadState S;
  LClosure *cl;
  if (*name == '@' || *name == '=')
    S.name = name + 1;
  else if (*name == '\x1b')
    S.name = "binary string";
  else
    S.name = name;
  S.L = L;
  S.Z = Z;
  checkHeader(&S);
  cl = lclosure_new(L, loadByte(&S));
  setclLvalue(L->top, cl);
  do_inctop(L);
  cl->p = proto_new(L);
  loadFunction(&S, cl->p, NULL);
  lclosure_initupvals(L, cl);
  return cl;
}
EOF
