#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include "core.h"
#include "api.h"

#define LUA_PATH_SEP ";"
#define LUA_PATH_MARK "?"
#define LUA_EXEC_DIR "!"
#define LUA_IGMARK "-"
#define LUA_DIRSEP "/"
#define LUA_LSUBSEP LUA_DIRSEP
#define LUA_CSUBSEP LUA_DIRSEP
#define LUA_VDIR "5.5"
#define LUA_ROOT "/usr/local/"
#define LUA_LDIR LUA_ROOT "share/lua/" LUA_VDIR "/"
#define LUA_CDIR LUA_ROOT "lib/lua/" LUA_VDIR "/"
#define LUA_PATH_DEFAULT \
  LUA_LDIR"?.lua;" LUA_LDIR"?/init.lua;" \
  LUA_CDIR"?.lua;" LUA_CDIR"?/init.lua;" \
  "./?.lua;" "./?/init.lua"
#define LUA_CPATH_DEFAULT \
  LUA_CDIR"?.so;" LUA_CDIR"loadall.so;" "./?.so"
#define LUA_PATH_VAR "LUA_PATH"
#define LUA_CPATH_VAR "LUA_CPATH"
#define LUA_VERSUFFIX "_" "5_5"
#define AUXMARK "\1"
#define LUA_LOADED_TABLE "_LOADED"
#define LUA_PRELOAD_TABLE "_PRELOAD"
#define LIBPREFIX "LOADLIB: "

static int noenv_(State *L) {
  int b;
  api_getfield(L, REGISTRYINDEX, "LUA_NOENV");
  b = api_toboolean(L, -1);
  api_pop(L, 1);
  return b;
}

static int lookforfunc(State *L, const char *path, const char *sym) {
  UNUSED(path); UNUSED(sym);
  api_pushliteral(L, "dynamic libraries not enabled; check your Lua installation");
  return 1;  /* ERRLIB */
}

static int ll_loadlib(State *L) {
  const char *path = aux_checkstring(L, 1);
  const char *init = aux_checkstring(L, 2);
  int stat = lookforfunc(L, path, init);
  if (likely(stat == 0))
    return 1;
  else {
    aux_pushfail(L);
    api_insert(L, -2);
    api_pushstring(L, (stat == 1) ? "open" : "init");
    return 3;
  }
}

static int readable(const char *filename) {
  FILE *f = fopen(filename, "r");
  if (f == NULL) return 0;
  fclose(f);
  return 1;
}

static const char *getnextfilename(char **path, char *end) {
  char *sep;
  char *name = *path;
  if (name == end)
    return NULL;
  else if (*name == '\0') {
    *name = *LUA_PATH_SEP;
    name++;
  }
  sep = strchr(name, *LUA_PATH_SEP);
  if (sep == NULL)
    sep = end;
  *sep = '\0';
  *path = sep;
  return name;
}

static void pusherrornotfound(State *L, const char *path) {
  Buffer b;
  aux_buffinit(L, &b);
  aux_addstring(&b, "no file '");
  aux_addgsub(&b, path, LUA_PATH_SEP, "'\n\tno file '");
  aux_addstring(&b, "'");
  aux_pushresult(&b);
}

static const char *searchpath(State *L, const char *name, const char *path, const char *sep, const char *dirsep) {
  Buffer buff;
  char *pathname;
  char *endpathname;
  const char *filename;
  if (*sep != '\0' && strchr(name, *sep) != NULL)
    name = aux_gsub(L, name, sep, dirsep);
  aux_buffinit(L, &buff);
  aux_addgsub(&buff, path, LUA_PATH_MARK, name);
  aux_addchar(&buff, '\0');
  pathname = aux_buffaddr(&buff);
  endpathname = pathname + aux_bufflen(&buff) - 1;
  while ((filename = getnextfilename(&pathname, endpathname)) != NULL) {
    if (readable(filename))
      return api_pushstring(L, filename);
  }
  aux_pushresult(&buff);
  pusherrornotfound(L, api_tostring(L, -1));
  return NULL;
}

static int ll_searchpath(State *L) {
  const char *f = searchpath(L, aux_checkstring(L, 1),
                                aux_checkstring(L, 2),
                                aux_optstring(L, 3, "."),
                                aux_optstring(L, 4, LUA_DIRSEP));
  if (f != NULL) return 1;
  else {
    aux_pushfail(L);
    api_insert(L, -2);
    return 2;
  }
}

static const char *findfile(State *L, const char *name, const char *pname, const char *dirsep) {
  const char *path;
  api_getfield(L, api_upvalueindex(1), pname);
  path = api_tostring(L, -1);
  if (unlikely(path == NULL))
    aux_error(L, "'package.%s' must be a string", pname);
  return searchpath(L, name, path, ".", dirsep);
}

static int checkload(State *L, int stat, const char *filename) {
  if (likely(stat)) {
    api_pushstring(L, filename);
    return 2;
  } else
    return aux_error(L, "error loading module '%s' from file '%s':\n\t%s",
                        api_tostring(L, 1), filename, api_tostring(L, -1));
}

static int searcher_Lua(State *L) {
  const char *filename;
  const char *name = aux_checkstring(L, 1);
  filename = findfile(L, name, "path", LUA_LSUBSEP);
  if (filename == NULL) return 1;
  return checkload(L, (aux_loadfile(L, filename) == ST_OK), filename);
}

static int searcher_C(State *L) {
  const char *name = aux_checkstring(L, 1);
  const char *filename = findfile(L, name, "cpath", LUA_CSUBSEP);
  if (filename == NULL) return 1;
  api_pushliteral(L, "dynamic libraries not enabled; check your Lua installation");
  return aux_error(L, "error loading module '%s' from file '%s':\n\t%s", name, filename, api_tostring(L, -1));
}

static int searcher_Croot(State *L) {
  const char *filename;
  const char *name = aux_checkstring(L, 1);
  const char *p = strchr(name, '.');
  if (p == NULL) return 0;
  api_pushlstring(L, name, p - name);
  filename = findfile(L, api_tostring(L, -1), "cpath", LUA_CSUBSEP);
  if (filename == NULL) return 1;
  api_pushliteral(L, "dynamic libraries not enabled; check your Lua installation");
  return aux_error(L, "error loading module '%s' from file '%s':\n\t%s", name, filename, api_tostring(L, -1));
}

static int searcher_preload(State *L) {
  const char *name = aux_checkstring(L, 1);
  api_getfield(L, REGISTRYINDEX, LUA_PRELOAD_TABLE);
  if (api_getfield(L, -1, name) == T_NIL) {
    api_pushfstring(L, "no field package.preload['%s']", name);
    return 1;
  } else {
    api_pushliteral(L, ":preload:");
    return 2;
  }
}

static void findloader(State *L, const char *name) {
  int i;
  Buffer msg;
  if (unlikely(api_getfield(L, api_upvalueindex(1), "searchers") != T_TABLE))
    aux_error(L, "'package.searchers' must be a table");
  aux_buffinit(L, &msg);
  for (i = 1; ; i++) {
    aux_addstring(&msg, "\n\t");
    if (unlikely(api_rawgeti(L, 3, i) == T_NIL)) {
      api_pop(L, 1);
      aux_buffsub(&msg, 2);
      aux_pushresult(&msg);
      aux_error(L, "module '%s' not found:%s", name, api_tostring(L, -1));
    }
    api_pushstring(L, name);
    api_call(L, 1, 2);
    if (api_isfunction(L, -2))
      return;
    else if (api_isstring(L, -2)) {
      api_pop(L, 1);
      aux_addvalue(&msg);
    } else {
      api_pop(L, 2);
      aux_buffsub(&msg, 2);
    }
  }
}

static int ll_require(State *L) {
  const char *name = aux_checkstring(L, 1);
  api_settop(L, 1);
  api_getfield(L, REGISTRYINDEX, LUA_LOADED_TABLE);
  api_getfield(L, 2, name);
  if (api_toboolean(L, -1))
    return 1;
  api_pop(L, 1);
  findloader(L, name);
  api_rotate(L, -2, 1);
  api_pushvalue(L, 1);
  api_pushvalue(L, -3);
  api_call(L, 2, 1);
  if (!api_isnil(L, -1))
    api_setfield(L, 2, name);
  else
    api_pop(L, 1);
  if (api_getfield(L, 2, name) == T_NIL) {
    api_pushboolean(L, 1);
    api_copy(L, -1, -2);
    api_setfield(L, 2, name);
  }
  api_rotate(L, -2, 1);
  return 2;
}

static void setpath(State *L, const char *fieldname, const char *envname, const char *dft) {
  const char *dftmark;
  const char *nver = api_pushfstring(L, "%s%s", envname, LUA_VERSUFFIX);
  const char *path = getenv(nver);
  if (path == NULL)
    path = getenv(envname);
  if (path == NULL || noenv_(L))
    api_pushstring(L, dft);
  else if ((dftmark = strstr(path, LUA_PATH_SEP LUA_PATH_SEP)) == NULL)
    api_pushstring(L, path);
  else {
    size_t len = strlen(path);
    Buffer b;
    aux_buffinit(L, &b);
    if (path < dftmark) {
      aux_addlstring(&b, path, dftmark - path);
      aux_addchar(&b, *LUA_PATH_SEP);
    }
    aux_addstring(&b, dft);
    if (dftmark < path + len - 2) {
      aux_addchar(&b, *LUA_PATH_SEP);
      aux_addlstring(&b, dftmark + 2, (path + len - 2) - dftmark);
    }
    aux_pushresult(&b);
  }
  api_setfield(L, -3, fieldname);
  api_pop(L, 1);
}

static const Reg pk_funcs[] = {
  {"loadlib", ll_loadlib},
  {"searchpath", ll_searchpath},
  {"preload", NULL},
  {"cpath", NULL},
  {"path", NULL},
  {"searchers", NULL},
  {"loaded", NULL},
  {NULL, NULL}
};

static const Reg ll_funcs[] = {
  {"require", ll_require},
  {NULL, NULL}
};

static void createsearcherstable(State *L) {
  static const CFunction searchers[] = {searcher_preload, searcher_Lua, searcher_C, searcher_Croot, NULL};
  int i;
  api_createtable(L, sizeof(searchers) / sizeof(searchers[0]) - 1, 0);
  for (i = 0; searchers[i] != NULL; i++) {
    api_pushvalue(L, -2);
    api_pushcclosure(L, searchers[i], 1);
    api_rawseti(L, -2, i + 1);
  }
  api_setfield(L, -2, "searchers");
}

int open_package(State *L) {
  aux_newlib(L, pk_funcs);
  createsearcherstable(L);
  setpath(L, "path", LUA_PATH_VAR, LUA_PATH_DEFAULT);
  setpath(L, "cpath", LUA_CPATH_VAR, LUA_CPATH_DEFAULT);
  api_pushliteral(L, LUA_DIRSEP "\n" LUA_PATH_SEP "\n" LUA_PATH_MARK "\n" LUA_EXEC_DIR "\n" LUA_IGMARK "\n");
  api_setfield(L, -2, "config");
  aux_getsubtable(L, REGISTRYINDEX, LUA_LOADED_TABLE);
  api_setfield(L, -2, "loaded");
  aux_getsubtable(L, REGISTRYINDEX, LUA_PRELOAD_TABLE);
  api_setfield(L, -2, "preload");
  api_pushglobaltable(L);
  api_pushvalue(L, -2);
  aux_setfuncs(L, ll_funcs, 1);
  api_pop(L, 1);
  return 1;
}

/* ---- library initialization ---- */

static const Reg loadedlibs[] = {
  {"_G", open_base},
  {"package", open_package},
  {"coroutine", open_coroutine},
  {"table", open_table},
  {"io", open_io},
  {"os", open_os},
  {"string", open_string},
  {"math", open_math},
  {"utf8", open_utf8},
  {"debug", open_debug},
  {NULL, NULL}
};

void open_libs(State *L) {
  const Reg *lib;
  for (lib = loadedlibs; lib->func; lib++) {
    aux_requiref(L, lib->name, lib->func, 1);
    api_pop(L, 1);
  }
}
