  }
  return 1;
}

static int handle_luainit(State *L) {
  const char *name = "=" LUA_INITVARVERSION;
  const char *init = getenv(name + 1);
  if (init == NULL) {
    name = "=" LUA_INIT_VAR;
    init = getenv(name + 1);
  }
  if (init == NULL) return ST_OK;
  else if (init[0] == '@')
    return dofile(L, init + 1);
  else
    return dostring(L, init, name);
}

/* ---- REPL ---- */

static int stdin_is_tty(void) {
  return isatty(0);
}

static const char *get_prompt(State *L, int firstline) {
  if (api_getglobal(L, firstline ? "_PROMPT" : "_PROMPT2") == T_NIL)
    return (firstline ? LUA_PROMPT : LUA_PROMPT2);
  else {
    const char *p = aux_tolstring(L, -1, NULL);
    api_remove(L, -2);
    return p;
  }
}

#define EOFMARK "<eof>"
#define marklen (sizeof(EOFMARK)/sizeof(char) - 1)

static int incomplete(State *L, int status) {
  if (status == ST_ERRSYNTAX) {
    size_t lmsg;
    const char *msg = api_tolstring(L, -1, &lmsg);
    if (lmsg >= marklen && strcmp(msg + lmsg - marklen, EOFMARK) == 0)
      return 1;
  }
  return 0;
}

static int readline_(State *L, char *b, const char *prmt) {
  size_t l;
  int tty = stdin_is_tty();
  fputs(prmt, stdout);
  fflush(stdout);
  if (fgets(b, LUA_MAXINPUT, stdin) == NULL) {
    return 0;
  }
  l = strlen(b);
  if (!tty) {
    /* echo the line, like readline does when input is not a terminal */
    fwrite(b, 1, l, stdout);
    if (l == 0 || b[l - 1] != '\n') fputs("\n", stdout);
    fflush(stdout);
  }
  UNUSED(L);
  return 1;
}

static int pushline(State *L, int firstline) {
  char buffer[LUA_MAXINPUT];
  char *b = buffer;
  size_t l;
  const char *prmt = get_prompt(L, firstline);
  int readstatus = readline_(L, b, prmt);
  if (readstatus == 0)
    return 0;
  api_pop(L, 1);
  l = strlen(b);
  if (l > 0 && b[l - 1] == '\n')
    b[--l] = '\0';
  api_pushlstring(L, b, l);
  return 1;
}

static int addreturn(State *L) {
  const char *line = api_tostring(L, -1);
  const char *retline = api_pushfstring(L, "return %s;", line);
  int status = aux_loadbuffer(L, retline, strlen(retline), "=stdin");
  if (status == ST_OK) {
    api_remove(L, -2);
  } else
    api_pop(L, 2);
  return status;
}

static void checklocal(const char *line) {
  static const size_t szloc = sizeof("local") - 1;
  static const char space[] = " \t";
  line += strspn(line, space);
  if (strncmp(line, "local", szloc) == 0 &&
      strchr(space, *(line + szloc)) != NULL) {
    fprintf(stderr, "warning: locals do not survive across lines in interactive mode\n");
    fflush(stderr);
  }
}

static int multiline(State *L) {
  size_t len;
  const char *line = api_tolstring(L, 1, &len);
  checklocal(line);
  for (;;) {
    int status = aux_loadbuffer(L, line, len, "=stdin");
    if (!incomplete(L, status) || !pushline(L, 0)) {
      return status;
    }
    api_remove(L, -2);
    api_pushliteral(L, "\n");
    api_insert(L, -2);
    api_concat(L, 3);
    line = api_tolstring(L, 1, &len);
  }
}

static int loadline(State *L) {
  int status;
  api_settop(L, 0);
  if (!pushline(L, 1))
    return -1;
  if ((status = addreturn(L)) != ST_OK)
    status = multiline(L);
  api_remove(L, 1);
  return status;
}

static void l_print(State *L) {
  int n = api_gettop(L);
  if (n > 0) {
    aux_checkstack(L, LUA_MINSTACK, "too many results to print");
    api_getglobal(L, "print");
    api_insert(L, 1);
    if (api_pcall(L, n, 0, 0) != ST_OK)
      l_message(progname, api_pushfstring(L, "error calling 'print' (%s)", api_tostring(L, -1)));
  }
}

static void doREPL(State *L) {
  int status;
  const char *oldprogname = progname;
  progname = NULL;
  while ((status = loadline(L)) != -1) {
    if (status == ST_OK)
      status = docall(L, 0, MULTRET);
    if (status == ST_OK) l_print(L);
    else report(L, status);
  }
  api_settop(L, 0);
  fwrite("\n", sizeof(char), 1, stdout);
  fflush(stdout);
  progname = oldprogname;
}

static int pmain(State *L) {
  int argc = (int)api_tointeger(L, 1);
  char **argv = (char **)api_touserdata(L, 2);
  int script;
  int args = collectargs(argv, &script);
  int optlim = (script > 0) ? script : argc;
  aux_checkversion(L);
  if (args == has_error) {
    print_usage(argv[script]);
    return 0;
  }
  if (args & has_v)
    print_version();
  if (args & has_E) {
    api_pushboolean(L, 1);
    api_setfield(L, REGISTRYINDEX, "LUA_NOENV");
  }
  open_libs(L);
  createargtable(L, argv, argc, script);
  api_gc(L, GCRESTART);
  api_gc(L, GCGEN, 0, 0);
  if (!(args & has_E)) {
    if (handle_luainit(L) != ST_OK)
      return 0;
  }
  if (!runargs(L, argv, optlim))
    return 0;
  if (script > 0) {
    if (handle_script(L, argv + script) != ST_OK)
      return 0;
  }
  if (args & has_i)
    doREPL(L);
  else if (script < 1 && !(args & (has_e | has_v))) {
    if (stdin_is_tty()) {
      print_version();
      doREPL(L);
    } else dofile(L, NULL);
  }
  api_pushboolean(L, 1);
  return 1;
}

static void warnfoff(void *ud, const char *message, int tocont);
static void warnfon(void *ud, const char *message, int tocont);
static void warnfcont(void *ud, const char *message, int tocont);

static int checkcontrol(State *L, const char *message, int tocont) {
  if (tocont || *(message++) != '@')
    return 0;
  else {
    if (strcmp(message, "off") == 0)
      api_setwarnf(L, warnfoff, L);
    else if (strcmp(message, "on") == 0)
      api_setwarnf(L, warnfon, L);
    return 1;
  }
}

static void warnfoff(void *ud, const char *message, int tocont) {
  checkcontrol((State *)ud, message, tocont);
}

static void warnfcont(void *ud, const char *message, int tocont) {
  State *L = (State *)ud;
  fprintf(stderr, "%s", message);
  if (tocont)
    api_setwarnf(L, warnfcont, L);
  else {
    fprintf(stderr, "%s", "\n");
    fflush(stderr);
    api_setwarnf(L, warnfon, L);
  }
}

static void warnfon(void *ud, const char *message, int tocont) {
  if (checkcontrol((State *)ud, message, tocont))
    return;
  fprintf(stderr, "%s", "Lua warning: ");
  warnfcont(ud, message, tocont);
}

int main(int argc, char **argv) {
  int status, result;
  State *L = state_new();
  if (L == NULL) {
    l_message(argv[0], "cannot create state: not enough memory");
    return EXIT_FAILURE;
  }
  api_setwarnf(L, warnfoff, L);
  api_gc(L, GCSTOP);
  api_pushcfunction(L, &pmain);
  api_pushinteger(L, argc);
  api_pushlightuserdata(L, argv);
  status = api_pcall(L, 2, 1, 0);
  result = api_toboolean(L, -1);
  report(L, status);
  state_close(L);
  return (result && status == ST_OK) ? EXIT_SUCCESS : EXIT_FAILURE;
}
